import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessResponses = new Counter('business_responses');
const businessFailures = new Counter('business_failures');
const businessFailureRate = new Rate('business_failure_rate');
const orderCommitted = new Counter('orders_committed');
const cartCreated = new Counter('carts_created');
const loginSuccess = new Counter('logins_success');
const csrfExtracted = new Counter('csrf_extracted');
const challengeCompleted = new Counter('challenges_completed');
const reservationReady = new Counter('reservations_ready');
const recoveryPerformed = new Counter('recoveries_performed');
const renewPerformed = new Counter('renews_performed');
const retry412 = new Counter('retry_412');
const retry429 = new Counter('retry_429');

const USER_COUNT = 2;
const ITERATIONS_PER_USER = 2;

// Profile flags
const PROFILES = [
  { login_csrf: true },
  { login_csrf: true, html_layout: 1, reverse_catalog: true }
];

function getProfile(vuId) {
  return PROFILES[(vuId - 1) % PROFILES.length];
}

function extractCsrfFromHtml(html) {
  // Match input[name=csrf] with various attribute orders and quoting
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["'][^>]*>/i,
    /<input[^>]*name=["']csrf["'][^>]*>/i
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match) {
      if (match[1]) return match[1];
      // If no value attribute, try to find value in the same tag
      const tagMatch = match[0].match(/value=["']([^"']+)["']/i);
      if (tagMatch) return tagMatch[1];
    }
  }

  // Try to find any input with name=csrf and extract value
  const allInputs = html.match(/<input[^>]*>/gi) || [];
  for (const input of allInputs) {
    if (/name=["']csrf["']/i.test(input)) {
      const valueMatch = input.match(/value=["']([^"']+)["']/i);
      if (valueMatch) return valueMatch[1];
    }
  }

  return null;
}

function extractChallengeAction(html) {
  const formMatch = html.match(/<form[^>]*action=["']([^"']+)["'][^>]*>/i);
  if (formMatch) return formMatch[1];

  const actionMatch = html.match(/action=["']([^"']*challenges[^"']*)["']/i);
  if (actionMatch) return actionMatch[1];

  return null;
}

function extractChallengeInput(html) {
  const inputMatch = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  if (inputMatch) {
    const valueMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
    if (valueMatch) return valueMatch[1];
  }
  return null;
}

function extractGrantIdFromLocation(html) {
  const match = html.match(/grant_id["']?\s*[:=]\s*["']([^"']+)["']/i);
  if (match) return match[1];

  const jsonMatch = html.match(/\{[^}]*"grant_id"\s*:\s*"([^"]+)"[^}]*\}/);
  if (jsonMatch) return jsonMatch[1];

  return null;
}

function extractCsrfFromJson(json) {
  if (json && json.csrf) return json.csrf;
  return null;
}

function extractNextFromJson(json) {
  if (json && json.next !== undefined) return json.next;
  return null;
}

function extractProductsFromCatalog(json) {
  if (json && json.data && json.data.products) return json.data.products;
  return [];
}

function extractProductFromPage(json) {
  if (json && json.data && json.data.product) return json.data.product;
  if (json && json.product) return json.product;
  return null;
}

function extractNextFromPage(json) {
  if (json && json.next !== undefined) return json.next;
  return null;
}

function extractCartId(json) {
  if (json && json.id) return json.id;
  return null;
}

function extractEtag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  return etag || null;
}

function extractReservationStatusUrl(json) {
  if (json && json.status_url) return json.status_url;
  return null;
}

function extractReservationStatus(json) {
  if (json && json.status) return json.status;
  return null;
}

function extractReservationId(json) {
  if (json && json.reservation_id) return json.reservation_id;
  return null;
}

function extractOrderId(json) {
  if (json && json.id) return json.id;
  return null;
}

function extractAccepted(json) {
  if (json && json.accepted !== undefined) return json.accepted;
  return null;
}

function extractErrorCode(json) {
  if (json && json.error) return json.error;
  return null;
}

function extractLocation(headers) {
  return headers['Location'] || headers['location'] || null;
}

function makeIdempotencyKey(cartId) {
  return `idem-${cartId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

function getUsername(vuId) {
  return `bench-${vuId}`;
}

function getPassword() {
  return 'bench';
}

function login(vuId, profile) {
  const username = getUsername(vuId);
  const password = getPassword();

  // Step 1: GET login form to get CSRF
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  if (formRes.status !== 200) {
    return { success: false, error: `login form status ${formRes.status}` };
  }

  const csrf = extractCsrfFromHtml(formRes.body);
  if (!csrf) {
    return { success: false, error: 'no csrf found in login form' };
  }
  csrfExtracted.add(1);

  // Step 2: POST login
  const loginPayload = JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  });

  const loginRes = http.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'login' }
  });

  // Handle 302 redirect
  if (loginRes.status === 302) {
    const location = extractLocation(loginRes.headers);
    if (location) {
      const redirectRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_redirect' }
      });
      if (redirectRes.status !== 200) {
        return { success: false, error: `login redirect status ${redirectRes.status}` };
      }
      const redirectCsrf = extractCsrfFromJson(redirectRes.json());
      const redirectUser = redirectRes.json().user;
      if (redirectCsrf) {
        loginSuccess.add(1);
        return { success: true, csrf: redirectCsrf, user: redirectUser };
      }
      return { success: false, error: 'no csrf in redirect response' };
    }
    return { success: false, error: '302 without location' };
  }

  if (loginRes.status === 200) {
    const json = loginRes.json();
    const newCsrf = extractCsrfFromJson(json);
    if (newCsrf) {
      loginSuccess.add(1);
      return { success: true, csrf: newCsrf, user: json.user };
    }
    return { success: false, error: 'no csrf in login response' };
  }

  return { success: false, error: `login status ${loginRes.status}` };
}

function getCatalog(profile) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    tags: { name: 'catalog' }
  });

  if (res.status !== 200) {
    return { success: false, error: `catalog status ${res.status}` };
  }

  const json = res.json();
  const products = extractProductsFromCatalog(json);
  const next = extractNextFromJson(json);

  if (products.length > 0) {
    return { success: true, products: products, next: next };
  }

  return { success: false, error: 'no products in catalog' };
}

function getCatalogPage(profile, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = http.get(url, {
    tags: { name: 'catalog_page' }
  });

  if (res.status !== 200) {
    return { success: false, error: `catalog page status ${res.status}` };
  }

  const json = res.json();
  const product = extractProductFromPage(json);
  const next = extractNextFromPage(json);

  return { success: true, product: product, next: next };
}

function selectProduct(profile) {
  const catalogRes = getCatalog(profile);
  if (!catalogRes.success) {
    return { success: false, error: catalogRes.error };
  }

  let products = catalogRes.products;
  let next = catalogRes.next;
  let pagesTraversed = 0;

  // If reverse_catalog, reverse the products array
  if (profile.reverse_catalog) {
    products = products.slice().reverse();
  }

  // Try to find a product with in-stock variant
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          return { success: true, productId: product.id, variantId: variant.id };
        }
      }
    }
  }

  // Traverse pages if needed
  while (next && pagesTraversed < 3) {
    const pageRes = getCatalogPage(profile, next);
    if (!pageRes.success) {
      return { success: false, error: pageRes.error };
    }

    pagesTraversed++;

    if (pageRes.product) {
      const product = pageRes.product;
      if (product.variants && product.variants.length > 0) {
        for (const variant of product.variants) {
          if (variant.in_stock) {
            return { success: true, productId: product.id, variantId: variant.id };
          }
        }
      }
    }

    next = pageRes.next;
  }

  return { success: false, error: 'no in-stock product found' };
}

function createCart(csrf, productId, variantId, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };

  if (grantId) {
    payload.grant_id = grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_cart' }
  });

  if (res.status === 201) {
    const json = res.json();
    const cartId = extractCartId(json);
    const newCsrf = extractCsrfFromJson(json);
    const etag = extractEtag(res.headers);

    if (cartId) {
      cartCreated.add(1);
      return {
        success: true,
        cartId: cartId,
        csrf: newCsrf || csrf,
        etag: etag
      };
    }
    return { success: false, error: 'no cart id in response' };
  }

  return { success: false, error: `create cart status ${res.status}`, status: res.status };
}

function getCart(cartId, csrf) {
  const res = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'get_cart' }
  });

  if (res.status === 200) {
    const etag = extractEtag(res.headers);
    return { success: true, etag: etag };
  }

  return { success: false, error: `get cart status ${res.status}`, status: res.status };
}

function patchCart(cartId, csrf, etag, quantity) {
  const payload = JSON.stringify({ quantity: quantity });

  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'patch_cart' }
  });

  if (res.status === 200 || res.status === 204) {
    const newCsrf = extractCsrfFromJson(res.json());
    const newEtag = extractEtag(res.headers);
    return {
      success: true,
      csrf: newCsrf || csrf,
      etag: newEtag || etag
    };
  }

  if (res.status === 412) {
    return { success: false, error: '412', status: 412 };
  }

  return { success: false, error: `patch cart status ${res.status}`, status: res.status };
}

function getChallengeForm(csrf) {
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'challenge_form' }
  });

  if (res.status !== 200) {
    return { success: false, error: `challenge form status ${res.status}` };
  }

  const action = extractChallengeAction(res.body);
  const challengeValue = extractChallengeInput(res.body);

  if (!action || !challengeValue) {
    return { success: false, error: 'no challenge action or input found' };
  }

  return { success: true, action: action, challenge: challengeValue };
}

function postChallenge(action, challenge, csrf) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const payload = JSON.stringify({ challenge: challenge });

  const res = http.post(url, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'post_challenge' }
  });

  if (res.status === 302) {
    const location = extractLocation(res.headers);
    if (location) {
      const redirectRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        headers: {
          'X-CSRF-Token': csrf
        },
        tags: { name: 'challenge_redirect' }
      });

      if (redirectRes.status === 200) {
        const json = redirectRes.json();
        const grantId = json.grant_id;
        const newCsrf = extractCsrfFromJson(json);

        if (grantId) {
          challengeCompleted.add(1);
          return { success: true, grantId: grantId, csrf: newCsrf || csrf };
        }
        return { success: false, error: 'no grant_id in challenge response' };
      }
      return { success: false, error: `challenge redirect status ${redirectRes.status}` };
    }
    return { success: false, error: 'challenge 302 without location' };
  }

  if (res.status === 200) {
    const json = res.json();
    const grantId = json.grant_id;
    const newCsrf = extractCsrfFromJson(json);

    if (grantId) {
      challengeCompleted.add(1);
      return { success: true, grantId: grantId, csrf: newCsrf || csrf };
    }
    return { success: false, error: 'no grant_id in challenge response' };
  }

  return { success: false, error: `challenge status ${res.status}` };
}

function createReservation(cartId, csrf) {
  const payload = JSON.stringify({ cart_id: cartId });

  const res = http.post(`${BASE_URL}/v2/reservations`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_reservation' }
  });

  if (res.status === 202) {
    const json = res.json();
    const statusUrl = extractReservationStatusUrl(json);
    const newCsrf = extractCsrfFromJson(json);

    if (statusUrl) {
      return { success: true, statusUrl: statusUrl, csrf: newCsrf || csrf };
    }
    return { success: false, error: 'no status_url in reservation response' };
  }

  return { success: false, error: `reservation status ${res.status}`, status: res.status };
}

function pollReservation(statusUrl, csrf) {
  const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;

  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      sleep(0.05); // at least 50ms apart
    }

    const res = http.get(url, {
      headers: {
        'X-CSRF-Token': csrf
      },
      tags: { name: 'poll_reservation' }
    });

    if (res.status === 200) {
      const json = res.json();
      const status = extractReservationStatus(json);
      const reservationId = extractReservationId(json);
      const newCsrf = extractCsrfFromJson(json);

      if (status === 'ready' && reservationId) {
        reservationReady.add(1);
        return { success: true, reservationId: reservationId, csrf: newCsrf || csrf };
      }

      if (status === 'failed') {
        return { success: false, error: 'reservation failed' };
      }

      // pending - continue polling
      csrf = newCsrf || csrf;
    } else {
      return { success: false, error: `poll reservation status ${res.status}` };
    }
  }

  return { success: false, error: 'reservation polling timeout' };
}

function createOrder(cartId, csrf, reservationId, etag, idempotencyKey) {
  const payload = {
    cart_id: cartId
  };

  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };

  if (etag) {
    headers['If-Match'] = etag;
  }

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'create_order' }
  });

  if (res.status === 201) {
    const json = res.json();
    const accepted = extractAccepted(json);
    const orderId = extractOrderId(json);
    const newCsrf = extractCsrfFromJson(json);

    if (accepted === true && orderId) {
      orderCommitted.add(1);
      return { success: true, orderId: orderId, csrf: newCsrf || csrf };
    }

    if (accepted === false) {
      return { success: false, error: 'order accepted:false', businessFailure: true };
    }

    return { success: false, error: 'no order id or accepted flag' };
  }

  if (res.status === 200) {
    const json = res.json();
    const accepted = extractAccepted(json);

    if (accepted === false) {
      return { success: false, error: 'order accepted:false', businessFailure: true };
    }
  }

  return { success: false, error: `create order status ${res.status}`, status: res.status };
}

function renewSession(csrf) {
  const payload = JSON.stringify({});

  const res = http.post(`${BASE_URL}/v2/session/renew`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'renew_session' }
  });

  if (res.status === 200) {
    const json = res.json();
    const newCsrf = extractCsrfFromJson(json);

    if (newCsrf) {
      renewPerformed.add(1);
      return { success: true, csrf: newCsrf };
    }
    return { success: false, error: 'no csrf in renew response' };
  }

  return { success: false, error: `renew status ${res.status}`, status: res.status };
}

function recoverCart(cartId, csrf) {
  const payload = JSON.stringify({});

  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'recover_cart' }
  });

  if (res.status === 200 || res.status === 201) {
    recoveryPerformed.add(1);
    const json = res.json();
    const newCsrf = extractCsrfFromJson(json);
    return { success: true, csrf: newCsrf || csrf };
  }

  return { success: false, error: `recover cart status ${res.status}`, status: res.status };
}

function doWork(csrf) {
  const payload = JSON.stringify({});

  for (let attempt = 0; attempt < 4; attempt++) {
    const res = http.post(`${BASE_URL}/v2/work`, payload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      tags: { name: 'work' }
    });

    businessResponses.add(1);

    if (res.status === 200) {
      const json = res.json();
      if (json.ok === true) {
        return { success: true };
      }
      businessFailures.add(1);
      return { success: false, error: 'work not ok' };
    }

    if (res.status === 429) {
      retry429.add(1);
      const retryAfter = parseInt(res.headers['Retry-After'] || '1');
      sleep(retryAfter);
      continue;
    }

    if (res.status === 401) {
      const json = res.json();
      const errorCode = extractErrorCode(json);
      if (errorCode === 'expired') {
        // Expected expiry - not a business failure
        return { success: false, error: 'expired', status: 401, errorCode: 'expired' };
      }
      businessFailures.add(1);
      return { success: false, error: `work 401 ${errorCode}`, status: 401 };
    }

    if (res.status === 500) {
      businessFailures.add(1);
      return { success: false, error: 'work 500', status: 500 };
    }

    businessFailures.add(1);
    return { success: false, error: `work status ${res.status}`, status: res.status };
  }

  businessFailures.add(1);
  return { success: false, error: 'work retry exhausted' };
}

function doBrowse(csrf) {
  const payload = JSON.stringify({});

  for (let attempt = 0; attempt < 4; attempt++) {
    const res = http.post(`${BASE_URL}/v2/browse`, payload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      tags: { name: 'browse' }
    });

    businessResponses.add(1);

    if (res.status === 200) {
      const json = res.json();
      if (json.ok === true) {
        return { success: true };
      }
      businessFailures.add(1);
      return { success: false, error: 'browse not ok' };
    }

    if (res.status === 429) {
      retry429.add(1);
      const retryAfter = parseInt(res.headers['Retry-After'] || '1');
      sleep(retryAfter);
      continue;
    }

    if (res.status === 401) {
      const json = res.json();
      const errorCode = extractErrorCode(json);
      if (errorCode === 'expired') {
        return { success: false, error: 'expired', status: 401, errorCode: 'expired' };
      }
      businessFailures.add(1);
      return { success: false, error: `browse 401 ${errorCode}`, status: 401 };
    }

    if (res.status === 500) {
      businessFailures.add(1);
      return { success: false, error: 'browse 500', status: 500 };
    }

    businessFailures.add(1);
    return { success: false, error: `browse status ${res.status}`, status: res.status };
  }

  businessFailures.add(1);
  return { success: false, error: 'browse retry exhausted' };
}

function handle401Expired(operation, cartId, csrf, retryFn) {
  // Try to renew session
  const renewRes = renewSession(csrf);
  if (!renewRes.success) {
    // Session revoked - need fresh login
    return { success: false, error: 'renew failed', revoked: true };
  }

  csrf = renewRes.csrf;

  // Recover cart if exists
  if (cartId) {
    const recoverRes = recoverCart(cartId, csrf);
    if (!recoverRes.success) {
      return { success: false, error: 'recover failed' };
    }
    csrf = recoverRes.csrf;
  }

  // Retry the interrupted operation
  return retryFn(csrf);
}

function handle401SessionRevoked(vuId, profile, cartId, csrf, retryFn) {
  // Get fresh login
  const loginRes = login(vuId, profile);
  if (!loginRes.success) {
    return { success: false, error: 'fresh login failed' };
  }

  csrf = loginRes.csrf;

  // Recover cart
  if (cartId) {
    const recoverRes = recoverCart(cartId, csrf);
    if (!recoverRes.success) {
      return { success: false, error: 'recover after fresh login failed' };
    }
    csrf = recoverRes.csrf;
  }

  return retryFn(csrf);
}

function executeJourney(vuId, iteration) {
  const profile = getProfile(vuId);

  // Step 1: Login
  const loginRes = login(vuId, profile);
  if (!loginRes.success) {
    return { success: false, error: loginRes.error };
  }

  let csrf = loginRes.csrf;

  // Step 2: Select product
  const productRes = selectProduct(profile);
  if (!productRes.success) {
    return { success: false, error: productRes.error };
  }

  // Step 3: Try to get challenge grant
  let grantId = null;
  const challengeFormRes = getChallengeForm(csrf);
  if (challengeFormRes.success) {
    const challengeRes = postChallenge(challengeFormRes.action, challengeFormRes.challenge, csrf);
    if (challengeRes.success) {
      grantId = challengeRes.grantId;
      csrf = challengeRes.csrf;
    }
  }

  // Step 4: Create cart
  let cartRes = createCart(csrf, productRes.productId, productRes.variantId, grantId);

  // Handle 401 expired on cart creation
  if (!cartRes.success && cartRes.status === 401) {
    const retryFn = (newCsrf) => createCart(newCsrf, productRes.productId, productRes.variantId, grantId);
    const recoveryRes = handle401Expired('create_cart', null, csrf, retryFn);
    if (recoveryRes.success) {
      cartRes = recoveryRes;
    } else if (recoveryRes.revoked) {
      const freshLoginRes = login(vuId, profile);
      if (freshLoginRes.success) {
        csrf = freshLoginRes.csrf;
        cartRes = createCart(csrf, productRes.productId, productRes.variantId, grantId);
      }
    }
  }

  if (!cartRes.success) {
    return { success: false, error: cartRes.error };
  }

  csrf = cartRes.csrf;
  const cartId = cartRes.cartId;
  let etag = cartRes.etag;

  // Step 5: Patch cart quantity
  let patchRes = patchCart(cartId, csrf, etag, 1);

  // Handle 412 - re-read and retry once
  if (!patchRes.success && patchRes.status === 412) {
    retry412.add(1);
    const getCartRes = getCart(cartId, csrf);
    if (getCartRes.success) {
      etag = getCartRes.etag;
      patchRes = patchCart(cartId, csrf, etag, 1);
    }
  }

  // Handle 401 expired on patch
  if (!patchRes.success && patchRes.status === 401) {
    const retryFn = (newCsrf) => {
      const getRes = getCart(cartId, newCsrf);
      if (getRes.success) {
        return patchCart(cartId, newCsrf, getRes.etag, 1);
      }
      return { success: false, error: 'get cart failed during retry' };
    };
    const recoveryRes = handle401Expired('patch_cart', cartId, csrf, retryFn);
    if (recoveryRes.success) {
      patchRes = recoveryRes;
      csrf = patchRes.csrf;
      etag = patchRes.etag;
    } else if (recoveryRes.revoked) {
      const freshLoginRes = login(vuId, profile);
      if (freshLoginRes.success) {
        csrf = freshLoginRes.csrf;
        const recoverRes = recoverCart(cartId, csrf);
        if (recoverRes.success) {
          csrf = recoverRes.csrf;
          const getRes = getCart(cartId, csrf);
          if (getRes.success) {
            patchRes = patchCart(cartId, csrf, getRes.etag, 1);
            if (patchRes.success) {
              csrf = patchRes.csrf;
              etag = patchRes.etag;
            }
          }
        }
      }
    }
  }

  if (!patchRes.success) {
    return { success: false, error: patchRes.error };
  }

  csrf = patchRes.csrf;
  etag = patchRes.etag;

  // Step 6: Create reservation
  let reservationId = null;
  const reservationRes = createReservation(cartId, csrf);

  if (reservationRes.success) {
    csrf = reservationRes.csrf;
    const pollRes = pollReservation(reservationRes.statusUrl, csrf);
    if (pollRes.success) {
      reservationId = pollRes.reservationId;
      csrf = pollRes.csrf;
    }
  } else if (reservationRes.status === 401) {
    const retryFn = (newCsrf) => {
      const res = createReservation(cartId, newCsrf);
      if (res.success) {
        const poll = pollReservation(res.statusUrl, res.csrf);
        if (poll.success) {
          return { success: true, reservationId: poll.reservationId, csrf: poll.csrf };
        }
        return { success: false, error: poll.error };
      }
      return res;
    };
    const recoveryRes = handle401Expired('create_reservation', cartId, csrf, retryFn);
    if (recoveryRes.success) {
      reservationId = recoveryRes.reservationId;
      csrf = recoveryRes.csrf;
    } else if (recoveryRes.revoked) {
      const freshLoginRes = login(vuId, profile);
      if (freshLoginRes.success) {
        csrf = freshLoginRes.csrf;
        const recoverRes = recoverCart(cartId, csrf);
        if (recoverRes.success) {
          csrf = recoverRes.csrf;
          const res = createReservation(cartId, csrf);
          if (res.success) {
            csrf = res.csrf;
            const poll = pollReservation(res.statusUrl, csrf);
            if (poll.success) {
              reservationId = poll.reservationId;
              csrf = poll.csrf;
            }
          }
        }
      }
    }
  }

  // Step 7: Create order
  const idempotencyKey = makeIdempotencyKey(cartId);
  let orderRes = createOrder(cartId, csrf, reservationId, etag, idempotencyKey);

  // Handle 401 expired on order
  if (!orderRes.success && orderRes.status === 401) {
    const retryFn = (newCsrf) => createOrder(cartId, newCsrf, reservationId, etag, idempotencyKey);
    const recoveryRes = handle401Expired('create_order', cartId, csrf, retryFn);
    if (recoveryRes.success) {
      orderRes = recoveryRes;
      csrf = orderRes.csrf;
    } else if (recoveryRes.revoked) {
      const freshLoginRes = login(vuId, profile);
      if (freshLoginRes.success) {
        csrf = freshLoginRes.csrf;
        const recoverRes = recoverCart(cartId, csrf);
        if (recoverRes.success) {
          csrf = recoverRes.csrf;
          orderRes = createOrder(cartId, csrf, reservationId, etag, idempotencyKey);
          if (orderRes.success) {
            csrf = orderRes.csrf;
          }
        }
      }
    }
  }

  if (!orderRes.success) {
    if (orderRes.businessFailure) {
      businessFailures.add(1);
    }
    return { success: false, error: orderRes.error };
  }

  csrf = orderRes.csrf;

  // Step 8: Do work
  const workRes = doWork(csrf);
  if (!workRes.success && workRes.errorCode === 'expired') {
    // Expected expiry - not a failure
  }

  // Step 9: Do browse
  const browseRes = doBrowse(csrf);
  if (!browseRes.success && browseRes.errorCode === 'expired') {
    // Expected expiry - not a failure
  }

  return { success: true, orderId: orderRes.orderId };
}

export const options = {
