def extract_csrf(html):
    """Extract csrf from hidden input named csrf, handling attribute variants."""
    import re
    # Try common patterns: name="csrf" value="..." or name='csrf' value='...'
    patterns = [
        r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\'][^>]*/?>',
        r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\'][^>]*/?>',
    ]
    for p in patterns:
        m = re.search(p, html, re.IGNORECASE)
        if m:
            return m.group(1)
    # Fallback: find any input with name csrf and extract value
    m = re.search(r'<input[^>]*name=["\']csrf["\'][^>]*>', html, re.IGNORECASE)
    if m:
        tag = m.group(0)
        vm = re.search(r'value=["\']([^"\']+)["\']', tag, re.IGNORECASE)
        if vm:
            return vm.group(1)
    raise ValueError("CSRF token not found in form")


class ShopUser(HttpUser):
