        }
        payload = {"quantity": quantity}
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                if "csrf" in resp.json():
