                if self.get_cart():
                    headers["If-Match"] = self.cart_etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                    ) as retry_resp:
                        if retry_resp.status_code == 200:
                            if "csrf" in retry_resp.json():
                                self.csrf = retry_resp.json()["csrf"]
                            self.cart_etag = retry_resp.headers.get("ETag")
                            return True
                        else:
                            retry_resp.failure(f"cart patch retry failed: {retry_resp.status_code}")
                            return False
                return False
            else:
                resp.failure(f"cart patch failed: {resp.status_code}")
                return False

    def handle_challenge(self):
        """Complete challenge if present."""
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code != 200:
