                return False
            tag = m.group(0)
            vm = re.search(r'value=["\']([^"\']+)["\']', tag, re.IGNORECASE)
            challenge_value = vm.group(1) if vm else ""
            # Extract form action
            am = re.search(r'<form[^>]*action=["\']([^"\']+)["\'][^>]*>', resp.text, re.IGNORECASE)
            if not am:
                resp.failure("challenge form action not found")
                return False
            action = am.group(1)

        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            action,
