        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code == 202:
                data = resp.json()
                status_url = data.get("status_url")
                if "csrf" in data:
                    self.csrf = data["csrf"]
                # Poll status
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(status_url, catch_response=True) as status_resp:
                        if status_resp.status_code == 200:
                            status_data = status_resp.json()
                            status = status_data.get("status")
                            if status == "ready":
                                self.reservation_id = status_data.get("reservation_id")
                                if "csrf" in status_data:
                                    self.csrf = status_data["csrf"]
                                return True
                            elif status == "failed":
                                status_resp.failure("reservation failed")
                                return False
                            # pending: continue polling
                        else:
                            status_resp.failure(f"reservation status failed: {status_resp.status_code}")
                            return False
                resp.failure("reservation polling exhausted")
                return False
            else:
                resp.failure(f"reservation creation failed: {resp.status_code}")
                return False

    def place_order(self):
        """Place order with idempotency key."""
        if not self.idempotency_key:
            self.idempotency_key = f"order-{self.cart_id}-{random.randint(100000, 999999)}"
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") is True:
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                    return True
                else:
                    resp.failure("order not accepted")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted") is False:
                    resp.failure("business failure: accepted=false")
                    return False
                # accepted true with 200?
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            else:
                resp.failure(f"order failed: {resp.status_code}")
                return False

    def handle_401(self, operation_func, *args, **kwargs):
        """Handle 401 expiry by renewing session and retrying once."""
        # Try renew
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            catch_response=True,
        ) as renew_resp:
            if renew_resp.status_code == 200:
                data = renew_resp.json()
                if "csrf" in data:
                    self.csrf = data["csrf"]
                # Recover cart if exists
                if self.cart_id:
                    with self.client.post(
                        f"/v2/carts/{self.cart_id}/recover",
                        json={},
                        headers={"X-CSRF-Token": self.csrf},
                        catch_response=True,
                    ) as recover_resp:
                        if recover_resp.status_code == 200:
                            if "csrf" in recover_resp.json():
                                self.csrf = recover_resp.json()["csrf"]
                            self.cart_etag = recover_resp.headers.get("ETag")
                        # Continue even if recover fails
                # Retry operation
                return operation_func(*args, **kwargs)
            else:
                # Session revoked: fresh login and recover
                if self.login():
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf},
                            catch_response=True,
                        ) as recover_resp:
                            if recover_resp.status_code == 200:
                                if "csrf" in recover_resp.json():
                                    self.csrf = recover_resp.json()["csrf"]
                                self.cart_etag = recover_resp.headers.get("ETag")
                    return operation_func(*args, **kwargs)
                return False

    def do_work(self):
        """Perform work endpoint with retry on 429."""
        for attempt in range(5):
            with self.client.post("/v2/work", json={}, catch_response=True) as resp:
                if resp.status_code == 200:
                    return True
                elif resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After", "1")
                    try:
                        time.sleep(float(retry_after))
                    except ValueError:
                        time.sleep(1)
                    continue
                elif resp.status_code == 500:
                    resp.failure("work 500 error")
                    return False
                else:
                    resp.failure(f"work failed: {resp.status_code}")
                    return False
        return False

    def journey(self):
        """Complete shop flow: login -> catalog -> cart -> order."""
        # Fresh login
        if not self.login():
            return False

        # Get catalog
        catalog_result = self.get_catalog()
        if not catalog_result:
            return False
        product_id, variant_id = catalog_result

        # Create cart
        if not self.create_cart(product_id, variant_id):
            return False

        # Update cart
        if not self.update_cart(1):
            return False

        # Try challenge (optional)
        self.handle_challenge()

        # Create reservation
        if not self.create_reservation():
            return False

        # Place order
        if not self.place_order():
            return False

        # Do work
        self.do_work()

        return True

    @task
    def shop_task(self):
        if self.iterations_done >= self.total_iterations:
            raise StopUser()

        self.iterations_done += 1

        # Reset per-journey state
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        self.journey()


class LoginCsrfUser(ShopUser):
    """Profile: login_csrf=true"""
    login_csrf = True
    html_layout = 0
    reverse_catalog = False


class LoginCsrfHtmlReverseUser(ShopUser):
    """Profile: login_csrf=true, html_layout=1, reverse_catalog=true"""
    login_csrf = True
    html_layout = 1
    reverse_catalog = True


class ShopLoadShape(LoadTestShape):
    """Shape that runs 2 users for 2 iterations each."""

    def __init__(self):
        super().__init__()
        self.user_classes = [LoginCsrfUser, LoginCsrfHtmlReverseUser]
        self.current_users = 0
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            # Start 2 users: one of each profile
            return (2, 2)
        # Check if all users have completed their iterations
        # The harness will stop when tick returns None
        # We need to track completion
        runner = self.runner
        if runner:
            total_done = sum(
                getattr(user, 'iterations_done', 0)
                for user in runner.user_classes
                if hasattr(user, 'iterations_done')
            )
            # Actually check user instances
            done_count = 0
            for user in runner.user_classes:
                if hasattr(user, 'iterations_done') and user.iterations_done >= user.total_iterations:
                    done_count += 1
            if done_count >= 2:
                return None
        return (2, 2)
