    // ---------- Regex helpers ----------
    private static final Pattern CSRF_INPUT = Pattern.compile(
            "<input[^>]*name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"'][^>]*>",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CSRF_INPUT_REVERSED = Pattern.compile(
            "<input[^>]*value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"'][^>]*>",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern LOCATION = Pattern.compile("(?i)location:\\s*(.+)");
    private static final Pattern CHALLENGE_ACTION = Pattern.compile(
            "<form[^>]*action=[\"']([^\"']+/challenges/[^\"']+)[\"'][^>]*>",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT = Pattern.compile(
            "<input[^>]*name=[\"']challenge[\"'][^>]*value=[\"']([^\"']+)[\"'][^>]*>",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern CHALLENGE_INPUT_REVERSED = Pattern.compile(
            "<input[^>]*value=[\"']([^\"']+)[\"'][^>]*name=[\"']challenge[\"'][^>]*>",
            Pattern.CASE_INSENSITIVE);

    private static String extractCsrf(String html) {
        Matcher m = CSRF_INPUT.matcher(html);
        if (m.find()) return m.group(1);
        m = CSRF_INPUT_REVERSED.matcher(html);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallengeAction(String html) {
        Matcher m = CHALLENGE_ACTION.matcher(html);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractChallengeValue(String html) {
        Matcher m = CHALLENGE_INPUT.matcher(html);
        if (m.find()) return m.group(1);
        m = CHALLENGE_INPUT_REVERSED.matcher(html);
        if (m.find()) return m.group(1);
        return null;
    }

    private static String extractLocation(io.gatling.javaapi.http.Response response) {
        String loc = response.header("Location");
        if (loc != null && !loc.isEmpty()) return loc;
        // fallback: parse from body if header missing
        String body = response.body().string();
        Matcher m = LOCATION.matcher(body);
        if (m.find()) return m.group(1).trim();
        return null;
    }

    // ---------- Chain builders ----------

    private static ChainBuilder getLoginForm() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().transform((html, session) -> {
                            String csrf = extractCsrf(html);
                            if (csrf == null) {
                                throw new RuntimeException("No csrf input found in login form");
                            }
                            return session.set("login_csrf", csrf);
                        }))
        );
    }

    private static ChainBuilder postLogin() {
        return exec(
                http("POST /v2/login")
                        .post("/v2/login")
                        .body(StringBody(session -> {
                            String csrf = session.getString("login_csrf");
                            String username = session.getString("username");
                            String password = session.getString("password");
                            return String.format(
                                    "{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}",
                                    username, password, csrf);
                        }))
                        .check(status().in(200, 302))
                        .check(
                                bodyString().transform((body, session) -> {
                                    if (body != null && !body.isEmpty() && body.trim().startsWith("{")) {
                                        // JSON response
                                        try {
                                            // simple parse for csrf and user
                                            String csrf = extractJsonString(body, "csrf");
                                            if (csrf != null) {
                                                session = session.set("csrf", csrf);
                                            }
                                            String user = extractJsonString(body, "user");
                                            if (user != null) {
                                                session = session.set("user", user);
                                            }
                                        } catch (Exception e) {
                                            // ignore parse errors
                                        }
                                    }
                                    return session;
                                })
                        )
                        .check(
                                header("Location").optional().transform((loc, session) -> {
                                    if (loc != null && !loc.isEmpty()) {
                                        return session.set("login_location", loc);
                                    }
                                    return session;
                                })
                        )
        ).exec(session -> {
            String loc = session.getString("login_location");
            if (loc != null && !loc.isEmpty()) {
                return session.markAsSucceeded();
            }
            return session;
        }).doIf(session -> session.contains("login_location")).then(
                exec(
                        http("GET login Location")
                                .get(session -> session.getString("login_location"))
                                .check(status().in(200, 302))
                                .check(
                                        bodyString().transform((body, sess) -> {
                                            if (body != null && !body.isEmpty() && body.trim().startsWith("{")) {
                                                String csrf = extractJsonString(body, "csrf");
                                                if (csrf != null) {
                                                    sess = sess.set("csrf", csrf);
                                                }
                                                String user = extractJsonString(body, "user");
                                                if (user != null) {
                                                    sess = sess.set("user", user);
                                                }
                                            }
                                            return sess;
                                        })
                                )
                )
        );
    }

    private static String extractJsonString(String json, String key) {
        String pattern = "\"" + key + "\"\\s*:\\s*\"([^\"]+)\"";
        Matcher m = Pattern.compile(pattern).matcher(json);
        if (m.find()) return m.group(1);
        return null;
    }

