                                        throw new RuntimeException("Work not ok");
                                    }
                                    return sess;
                                })
                        )
        ).doIf(session -> session.getInt("status") == 429).then(
                exec(session -> session.set("retry_after", 1))
                        .pause(1)
                        .exec(doWorkRetry(1))
        );
