    private static ChainBuilder doWorkRetry(int attempt) {
        if (attempt > 4) {
            return exec(session -> {
                throw new RuntimeException("Work 429 retries exhausted");
            });
        }
        return exec(
                http("POST /v2/work retry " + attempt)
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .body(StringBody("{}"))
                        .check(status().in(200, 429))
                        .check(
                                jsonPath("$.ok").optional().transform((ok, sess) -> {
                                    if (ok != null && !ok.equals("true")) {
                                        throw new RuntimeException("Work not ok");
                                    }
                                    return sess;
                                })
                        )
        ).doIf(session -> session.getInt("status") == 429).then(
                exec(session -> session.set("retry_after", 1))
                        .pause(1)
                        .exec(doWorkRetry(attempt + 1))
        );
    }

    private static ChainBuilder renewSession() {
        return exec(
