    // ---------- Main journey ----------
    private static final ChainBuilder journey = exec(getLoginForm())
            .exec(postLogin())
            .exec(getCatalog())
            .exec(getChallengeForm())
            .exec(postChallenge())
            .exec(createCart())
            .exec(getCart())
            .exec(patchCart())
            .exec(createReservation())
            .exec(pollReservationLoop())
            .exec(createOrder())
            .exec(doWork());

    // ---------- Scenario ----------
    private static final ScenarioBuilder scn = scenario("ModelScenario")
            .feed(userFeeder)
            .exec(journey);

    {
        setUp(
                scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
