function extractCsrfFromHtml(html) {
  // Parse all input elements with name=csrf, handle attribute ordering and decoys
  const inputRegex = /<input\b[^>]*>/gi;
  let match;
  const candidates = [];
  while ((match = inputRegex.exec(html)) !== null) {
    const tag = match[0];
    const nameMatch = tag.match(/name\s*=\s*["']csrf["']/i);
    if (nameMatch) {
      const valueMatch = tag.match(/value\s*=\s*["']([^"']*)["']/i);
      if (valueMatch) {
        candidates.push(valueMatch[1]);
      }
    }
  }
  if (candidates.length === 0) {
    return null;
  }
  // If multiple csrf inputs, prefer the one that is not a decoy
  // Decoys typically have empty or placeholder values
  const nonEmpty = candidates.filter(v => v && v.length > 0 && v !== 'decoy' && v !== 'placeholder');
  if (nonEmpty.length > 0) {
    return nonEmpty[0];
  }
  return candidates[0];
}

function extractCsrfFromJson(body) {
  try {
    const data = JSON.parse(body);
    if (data && data.csrf) {
      return data.csrf;
    }
  } catch (e) {
    // ignore
  }
  return null;
}

