  return csrf;
}

function login(httpClient, username, password, csrf) {
  const payload = JSON.stringify({
    username: username,
    password: password,
    csrf: csrf,
  });
  const res = httpClient.post('/v2/login', payload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
