}

function getCatalog(httpClient, csrf, reverse) {
  const products = [];
  let nextUrl = '/v2/catalog';
  let pages = 0;

  while (nextUrl && pages < 3) {
    const res = httpClient.get(nextUrl, {
      headers: { 'X-CSRF-Token': csrf },
