      fail('Invalid catalog JSON');
    }
    if (data && data.data && data.data.products) {
      for (const p of data.data.products) {
        products.push(p);
      }
    }
    nextUrl = data && data.next ? data.next : null;
    pages++;
    if (nextUrl && !nextUrl.startsWith('/')) {
      nextUrl = '/' + nextUrl;
    }
  }

  if (reverse) {
    products.reverse();
