function pollReservation(httpClient, csrf, statusUrl) {
  let reservationId = null;
  let finalCsrf = csrf;
  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      sleep(0.05);
    }
    const res = httpClient.get(statusUrl, {
      headers: { 'X-CSRF-Token': finalCsrf },
      tags: { name: 'poll_reservation' },
    });
    if (res.status !== 200) {
      fail(`poll reservation failed: ${res.status}`);
