    let data;
    try {
      data = JSON.parse(res.body);
    } catch (e) {
      fail('Invalid poll reservation JSON');
    }
    if (data.csrf) {
      finalCsrf = data.csrf;
    }
    if (data.status === 'ready') {
      reservationId = data.reservation_id;
      break;
    } else if (data.status === 'failed') {
      fail('Reservation failed');
    }
    // pending - continue polling
  }
  if (!reservationId) {
    fail('Reservation never became ready');
  }
  return { reservationId: reservationId, csrf: finalCsrf };
}

function createOrder(httpClient, csrf, cartId, reservationId, etag, idempotencyKey) {
  const payload = {
    cart_id: cartId,
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (etag) {
    headers['If-Match'] = etag;
