    if (!data.accepted) {
      fail('Order not accepted');
    }
    return { csrf: data.csrf || csrf, orderId: data.id };
  }
  if (res.status === 200) {
    let data;
    try {
      data = JSON.parse(res.body);
    } catch (e) {
      fail('Invalid order JSON');
    }
    if (data.accepted === false) {
      fail('Business failure: order not accepted');
    }
    return { csrf: data.csrf || csrf, orderId: data.id };
  }
  fail(`create order failed: ${res.status} body=${res.body}`);
}

function doWork(httpClient, csrf) {
  const res = httpClient.post('/v2/work', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'work' },
  });
  if (res.status === 429) {
    const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10);
    sleep(retryAfter);
    for (let i = 0; i < 4; i++) {
      const retryRes = httpClient.post('/v2/work', '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
        },
        tags: { name: 'work_retry' },
      });
      if (retryRes.status === 200) {
        return { ok: true, csrf: csrf };
      }
      if (retryRes.status === 429) {
        const ra = parseInt(retryRes.headers['Retry-After'] || '1', 10);
        sleep(ra);
        continue;
      }
      // Other status - count as business failure
      businessFailureRate.add(1);
      return { ok: false, csrf: csrf };
    }
    businessFailureRate.add(1);
    return { ok: false, csrf: csrf };
  }
  if (res.status === 200) {
    return { ok: true, csrf: csrf };
  }
  if (res.status === 401) {
    // Expected expiry - not a business failure
    return { ok: false, csrf: csrf, expired: true };
  }
  if (res.status === 500) {
    businessFailureRate.add(1);
    return { ok: false, csrf: csrf };
  }
  businessFailureRate.add(1);
  return { ok: false, csrf: csrf };
}

function renewSession(httpClient, csrf) {
