  });
  if (res.status !== 200 && res.status !== 201) {
    return null;
  }
  const newCsrf = extractCsrfFromJson(res.body);
  return newCsrf || csrf;
}

function handleExpiredSession(httpClient, csrf, cartId, operationFn) {
  // Try renew
  const newCsrf = renewSession(httpClient, csrf);
  if (newCsrf) {
    if (cartId) {
      const recoveredCsrf = recoverCart(httpClient, newCsrf, cartId);
      if (recoveredCsrf) {
        return operationFn(recoveredCsrf);
      }
    }
    return operationFn(newCsrf);
  }
  // Renew failed - session revoked, get fresh login
  const formCsrf = getLoginForm(httpClient, { login_csrf: true });
  const loginResult = login(httpClient, 'bench', 'bench', formCsrf);
  if (cartId) {
    const recoveredCsrf = recoverCart(httpClient, loginResult.csrf, cartId);
    if (recoveredCsrf) {
      return operationFn(recoveredCsrf);
    }
  }
  return operationFn(loginResult.csrf);
}

export default function () {
  const vuIndex = __VU - 1;
  const profile = getProfile(vuIndex);
  const username = `bench-${((vuIndex) % 16) + 1}`;
  const password = 'bench';

  const httpClient = http;

  // Step 1: Get login form and extract CSRF
  const loginCsrf = getLoginForm(httpClient, profile);

  // Step 2: Login
  const loginResult = login(httpClient, username, password, loginCsrf);
  let csrf = loginResult.csrf;

  // Step 3: Get catalog
  let products = [];
  if (profile.reverse_catalog) {
    products = getCatalog(httpClient, csrf, true);
  } else {
    products = getCatalog(httpClient, csrf, false);
  }
  if (products.length === 0) {
    // Try catalog page
    const pageData = getCatalogPage(httpClient, csrf);
    if (pageData && pageData.data && pageData.data.products) {
      products = pageData.data.products;
    }
  }
  if (products.length === 0) {
    fail('No products available');
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }
  if (!selectedProduct || !selectedVariant) {
    fail('No in-stock product found');
  }

  // Step 4: Try to get grant_id via challenge
  let grantId = null;
  try {
    const challengeForm = getChallengeForm(httpClient, csrf);
    // Extract challenge value from the input tag
    const valueMatch = challengeForm.challengeInput.match(/value\s*=\s*["']([^"']*)["']/i);
    const challengeValue = valueMatch ? valueMatch[1] : '';
    const challengeResult = submitChallenge(httpClient, csrf, challengeForm.action, challengeValue);
    grantId = challengeResult.grantId;
    csrf = challengeResult.csrf;
  } catch (e) {
    // Challenge may not be available, continue without grant
    grantId = null;
  }

  // Step 5: Create cart
  const cartResult = createCart(httpClient, csrf, selectedProduct.id, selectedVariant.id, grantId);
  let cartId = cartResult.cartId;
  csrf = cartResult.csrf;
  let etag = cartResult.etag;

  // Step 6: Update cart quantity
  const updateResult = updateCartQuantity(httpClient, csrf, cartId, 1, etag);
  csrf = updateResult.csrf;
  etag = updateResult.etag;

  // Step 7: Create reservation
  let reservationId = null;
  try {
    const reservationResult = createReservation(httpClient, csrf, cartId);
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(httpClient, csrf, reservationResult.statusUrl);
    reservationId = pollResult.reservationId;
    csrf = pollResult.csrf;
  } catch (e) {
    // Reservation may not be required, continue without it
    reservationId = null;
  }

  // Step 8: Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  let orderResult;
  try {
    orderResult = createOrder(httpClient, csrf, cartId, reservationId, etag, idempotencyKey);
    csrf = orderResult.csrf;
  } catch (e) {
    // Check if it's a 401 expiry
    if (e.message && e.message.includes('401')) {
      // Handle expired session
      const operationFn = (newCsrf) => {
        const retryResult = createOrder(httpClient, newCsrf, cartId, reservationId, etag, idempotencyKey);
        return retryResult;
      };
      orderResult = handleExpiredSession(httpClient, csrf, cartId, operationFn);
      csrf = orderResult.csrf;
    } else {
      throw e;
    }
  }

  // Step 9: Do work
  const workResult = doWork(httpClient, csrf);
  if (workResult.csrf) {
    csrf = workResult.csrf;
  }

  // Record metrics
  businessFailureRate.add(0);
}
