import os
import time
import uuid
from urllib.parse import urljoin, urlparse

from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf(html):
    """Extract the real CSRF token from login/challenge form HTML.

    The fixture may include decoy hidden fields and may reorder attributes.
    We locate the input whose name is exactly 'csrf' and whose value is a
    non-empty token. Decoys use other names or empty values.
    """
    import re

    # Find all input tags
    for tag in re.findall(r"<input\b[^>]*>", html, re.IGNORECASE):
        attrs = dict(re.findall(r'([a-zA-Z_][a-zA-Z0-9_-]*)\s*=\s*["\']([^"\']*)["\']', tag))
        if attrs.get("name") == "csrf" and attrs.get("value", "").strip():
            return attrs["value"].strip()
    raise ValueError("No csrf input found in form HTML")


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)
    host = BASE

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.iterations_done = 0
        self.max_iterations = 2

    def _mark_failure(self, response, msg):
        response.failure(msg)

    def _get_csrf_from_login_form(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                self._mark_failure(r, f"login-form status {r.status_code}")
                return None
            try:
                token = _extract_csrf(r.text)
            except ValueError as e:
                self._mark_failure(r, str(e))
                return None
            self.csrf = token
            return token

    def _login(self):
        token = self._get_csrf_from_login_form()
        if not token:
            return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": token},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 302):
                if r.status_code == 302:
                    loc = r.headers.get("Location")
                    if not loc:
                        self._mark_failure(r, "302 without Location")
                        return False
                    with self.client.get(
                        urljoin(BASE, loc),
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code != 200:
                            self._mark_failure(r2, f"login redirect status {r2.status_code}")
                            return False
                        try:
                            data = r2.json()
                        except Exception:
                            self._mark_failure(r2, "login redirect non-JSON")
                            return False
                        self.csrf = data.get("csrf", self.csrf)
                        return True
                else:
                    try:
                        data = r.json()
                    except Exception:
                        self._mark_failure(r, "login non-JSON")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    return True
            else:
                self._mark_failure(r, f"login status {r.status_code}")
                return False

    def _renew_session(self):
        if not self.csrf:
            return False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "renew non-JSON")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            self._mark_failure(r, f"renew status {r.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id or not self.csrf:
            return False
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "recover non-JSON")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            self._mark_failure(r, f"recover status {r.status_code}")
            return False

    def _handle_401(self, response, operation_name):
        """Handle 401 expiry/session errors. Returns True if operation should be retried."""
        try:
            body = response.json()
        except Exception:
            self._mark_failure(response, f"{operation_name} 401 non-JSON")
            return False
        error = body.get("error", "")
        if error == "expired":
            if self._renew_session():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        elif error == "session":
            # Revoked: fresh login and recover cart
            if self._login():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        elif error == "denied":
            self._mark_failure(response, f"{operation_name} denied")
            return False
        else:
            self._mark_failure(response, f"{operation_name} unknown 401 error {error}")
            return False

    def _get_catalog_page(self, url="/v2/catalog"):
        with self.client.get(url, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                self._mark_failure(r, f"catalog status {r.status_code}")
                return None, None
            try:
                data = r.json()
            except Exception:
                self._mark_failure(r, "catalog non-JSON")
                return None, None
            products = data.get("data", {}).get("products", [])
            nxt = data.get("next")
            return products, nxt

    def _get_catalog_page_single(self, url="/v2/catalog/page"):
        with self.client.get(url, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                self._mark_failure(r, f"catalog page status {r.status_code}")
                return None, None
            try:
                data = r.json()
            except Exception:
                self._mark_failure(r, "catalog page non-JSON")
                return None, None
            product = data.get("data", {}).get("product") or data.get("product")
            nxt = data.get("next")
            return product, nxt

    def _pick_product_and_variant(self):
        """Try /v2/catalog first, then traverse up to 3 pages of /v2/catalog/page."""
        products, nxt = self._get_catalog_page()
        if products:
            for p in products:
                variants = p.get("variants", [])
                for v in variants:
                    if v.get("in_stock"):
                        return p["id"], v["id"]
        # Traverse pages
        page_url = "/v2/catalog/page"
        for _ in range(3):
            product, nxt = self._get_catalog_page_single(page_url)
            if product:
                variants = product.get("variants", [])
                for v in variants:
                    if v.get("in_stock"):
                        return product["id"], v["id"]
            if not nxt:
                break
            page_url = urljoin(BASE, nxt)
        return None, None

    def _solve_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                self._mark_failure(r, f"challenge-form status {r.status_code}")
                return False
            import re

            action_match = re.search(r'<form\b[^>]*action\s*=\s*["\']([^"\']+)["\']', r.text, re.IGNORECASE)
            if not action_match:
                self._mark_failure(r, "challenge-form missing action")
                return False
            action = action_match.group(1)
            challenge_match = re.search(
                r'<input\b[^>]*name\s*=\s*["\']challenge["\'][^>]*>', r.text, re.IGNORECASE
            )
            if not challenge_match:
                self._mark_failure(r, "challenge-form missing challenge input")
                return False
            attrs = dict(
                re.findall(
                    r'([a-zA-Z_][a-zA-Z0-9_-]*)\s*=\s*["\']([^"\']*)["\']',
                    challenge_match.group(0),
                )
            )
            challenge_value = attrs.get("value", "")
            if not challenge_value:
                self._mark_failure(r, "challenge input empty value")
                return False
        if not self.csrf:
            self._mark_failure(r, "no csrf for challenge")
            return False
        with self.client.post(
            urljoin(BASE, action),
            json={"challenge": challenge_value},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                self._mark_failure(r, f"challenge POST status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                self._mark_failure(r, "challenge 302 without Location")
                return False
        with self.client.get(
            urljoin(BASE, loc),
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                self._mark_failure(r, f"challenge redirect status {r.status_code}")
                return False
            try:
                data = r.json()
            except Exception:
                self._mark_failure(r, "challenge redirect non-JSON")
                return False
            self.grant_id = data.get("grant_id")
            self.csrf = data.get("csrf", self.csrf)
            return self.grant_id is not None

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
            self.grant_id = None
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "cart create non-JSON")
                    return False
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag")
                return self.cart_id is not None
            elif r.status_code == 401:
                if self._handle_401(r, "cart create"):
                    return self._create_cart(product_id, variant_id)
                return False
            else:
                self._mark_failure(r, f"cart create status {r.status_code}")
                return False

    def _get_cart(self):
        if not self.cart_id:
            return False
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                self.cart_etag = r.headers.get("ETag", self.cart_etag)
                return True
            elif r.status_code == 401:
                if self._handle_401(r, "cart get"):
                    return self._get_cart()
                return False
            else:
                self._mark_failure(r, f"cart get status {r.status_code}")
                return False

    def _patch_cart(self, quantity):
        if not self.cart_id or not self.csrf:
            return False
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "cart patch non-JSON")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag", self.cart_etag)
                return True
            elif r.status_code == 412:
                # Re-read and retry once
                if self._get_cart():
                    headers = {"X-CSRF-Token": self.csrf}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers=headers,
                        catch_response=True,
                        allow_redirects=False,
                    ) as r2:
                        if r2.status_code == 200:
                            try:
                                data = r2.json()
                            except Exception:
                                self._mark_failure(r2, "cart patch retry non-JSON")
                                return False
                            self.csrf = data.get("csrf", self.csrf)
                            self.cart_etag = r2.headers.get("ETag", self.cart_etag)
                            return True
                        elif r2.status_code == 401:
                            if self._handle_401(r2, "cart patch retry"):
                                return self._patch_cart(quantity)
                            return False
                        else:
                            self._mark_failure(r2, f"cart patch retry status {r2.status_code}")
                            return False
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "cart patch"):
                    return self._patch_cart(quantity)
                return False
            else:
                self._mark_failure(r, f"cart patch status {r.status_code}")
                return False

    def _create_reservation(self):
        if not self.cart_id or not self.csrf:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 202:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "reservation non-JSON")
                    return False
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                if not status_url:
                    self._mark_failure(r, "reservation missing status_url")
                    return False
                # Poll at least 50ms apart, at most 5 times
                for _ in range(5):
                    time.sleep(0.06)
                    with self.client.get(
                        urljoin(BASE, status_url),
                        catch_response=True,
                        allow_redirects=False,
                    ) as pr:
                        if pr.status_code != 200:
                            self._mark_failure(pr, f"reservation poll status {pr.status_code}")
                            return False
                        try:
                            pdata = pr.json()
                        except Exception:
                            self._mark_failure(pr, "reservation poll non-JSON")
                            return False
                        status = pdata.get("status")
                        if status == "ready":
                            self.reservation_id = pdata.get("reservation_id")
                            self.csrf = pdata.get("csrf", self.csrf)
                            return self.reservation_id is not None
                        elif status in ("pending",):
                            continue
                        elif status == "failed":
                            self._mark_failure(pr, "reservation failed")
                            return False
                        else:
                            self._mark_failure(pr, f"reservation unknown status {status}")
                            return False
                self._mark_failure(r, "reservation polling exhausted")
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "reservation create"):
                    return self._create_reservation()
                return False
            else:
                self._mark_failure(r, f"reservation create status {r.status_code}")
                return False

    def _create_order(self):
        if not self.cart_id or not self.csrf:
            return False
        idem_key = f"order-{self.cart_id}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": idem_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "order non-JSON")
                    return False
                if not data.get("accepted", False):
                    self._mark_failure(r, "order accepted:false")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, "order 200 non-JSON")
                    return False
                if data.get("accepted", False):
                    self.csrf = data.get("csrf", self.csrf)
                    return True
                self._mark_failure(r, "order 200 accepted:false business failure")
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "order create"):
                    return self._create_order()
                return False
            else:
                self._mark_failure(r, f"order create status {r.status_code}")
                return False

    def _do_work(self):
        """Perform a raw /v2/work or /v2/browse call as a native sample."""
        url = "/v2/work" if (self.iterations_done % 2 == 0) else "/v2/browse"
        with self.client.post(
            url,
            json={},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    self._mark_failure(r, f"{url} non-JSON")
                    return
                if not data.get("ok"):
                    self._mark_failure(r, f"{url} ok:false")
            elif r.status_code == 429:
                # Scheduled 429: retry after 1s, at most 4 retries
                retries = 0
                while retries < 4:
                    time.sleep(1)
                    retries += 1
                    with self.client.post(
                        url,
                        json={},
                        catch_response=True,
                        allow_redirects=False,
                    ) as rr:
                        if rr.status_code == 200:
                            try:
                                data = rr.json()
                            except Exception:
                                self._mark_failure(rr, f"{url} retry non-JSON")
                                return
                            if not data.get("ok"):
                                self._mark_failure(rr, f"{url} retry ok:false")
                            return
                        elif rr.status_code == 429:
                            continue
                        else:
                            self._mark_failure(rr, f"{url} retry status {rr.status_code}")
                            return
                self._mark_failure(r, f"{url} 429 retries exhausted")
            else:
                self._mark_failure(r, f"{url} status {r.status_code}")

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login and cart each journey
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None

        if not self._login():
            return

        # Optional challenge
        self._solve_challenge()

        product_id, variant_id = self._pick_product_and_variant()
        if product_id is None or variant_id is None:
            return

        if not self._create_cart(product_id, variant_id):
            return

        if not self._patch_cart(2):
            return

        if not self._create_reservation():
            return

        if not self._create_order():
            return

        # Raw work sample
        self._do_work()


class ShopLoadShape(LoadTestShape):
    """Exactly one LoadTestShape; stops when tick() returns None."""

    def __init__(self):
        super().__init__()
        self._start_time = time.time()
        self._max_duration = 120  # seconds safety cap

    def tick(self):
        run_time = time.time() - self._start_time
        if run_time > self._max_duration:
            return None
        # Keep 2 users running until they finish their iterations
        return (2, 2)
