        // But that's complex. Instead, we'll use a JSON path that returns objects.
        // For now, we'll use a simpler approach: capture the full JSON and parse in Java.
        return session;
    });

    // Use a more robust approach: capture the entire catalog response and parse it
    private static ChainBuilder catalogTraversalV3 = exec(
            http("GET catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(bodyString().saveAs("catalogBody"))
                    .check(jsonPath("$.next").optional().saveAs("nextPage"))
    ).exec(session -> {
        String body = session.getString("catalogBody");
        List<String> eligibleVariants = new ArrayList<>();
        List<String> eligibleProducts = new ArrayList<>();
        if (body != null) {
            // Simple JSON parsing without external libraries
            // We'll use regex to extract product objects and their variants
            // Pattern: {"id":"...","variants":[{"id":"...","in_stock":true},...]}
            // We'll do a manual parse
            int pos = 0;
            while (true) {
                int prodStart = body.indexOf("\"id\":\"", pos);
                if (prodStart < 0) break;
                int prodIdStart = prodStart + 6;
                int prodIdEnd = body.indexOf("\"", prodIdStart);
                if (prodIdEnd < 0) break;
                String productId = body.substring(prodIdStart, prodIdEnd);
                // Find variants array for this product
                int variantsStart = body.indexOf("\"variants\":[", prodIdEnd);
                if (variantsStart < 0) {
                    pos = prodIdEnd;
                    continue;
                }
                int variantsEnd = body.indexOf("]", variantsStart);
                if (variantsEnd < 0) break;
                String variantsStr = body.substring(variantsStart + 12, variantsEnd);
                // Parse variants
                int vPos = 0;
                while (true) {
                    int vIdIdx = variantsStr.indexOf("\"id\":\"", vPos);
                    if (vIdIdx < 0) break;
                    int vIdStart = vIdIdx + 6;
                    int vIdEnd = variantsStr.indexOf("\"", vIdStart);
                    if (vIdEnd < 0) break;
                    String variantId = variantsStr.substring(vIdStart, vIdEnd);
                    // Check in_stock
                    int stockIdx = variantsStr.indexOf("\"in_stock\":", vIdEnd);
                    if (stockIdx < 0) break;
                    int stockValStart = stockIdx + 11;
                    int stockValEnd = variantsStr.indexOf(",", stockValStart);
                    if (stockValEnd < 0) stockValEnd = variantsStr.indexOf("}", stockValStart);
                    if (stockValEnd < 0) break;
                    String stockStr = variantsStr.substring(stockValStart, stockValEnd).trim();
                    boolean inStock = stockStr.equals("true");
                    if (inStock) {
                        eligibleVariants.add(variantId);
                        eligibleProducts.add(productId);
                    }
                    vPos = stockValEnd;
                }
                pos = variantsEnd + 1;
            }
        }
        if (eligibleVariants.isEmpty()) {
            return session.set("selectionFailed", true);
        }
        int idx = ThreadLocalRandom.current().nextInt(eligibleVariants.size());
        return session.set("selectedProductId", eligibleProducts.get(idx))
                .set("selectedVariantId", eligibleVariants.get(idx))
                .set("selectionFailed", false);
    });

    private static ChainBuilder createCart = exec(
            http("POST create cart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{\"product_id\":\"#{selectedProductId}\",\"variant_id\":\"#{selectedVariantId}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cartId"))
                    .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                    .check(header("ETag").optional().saveAs("cartEtag"))
    ).exec(session -> {
        String newCsrf = session.getString("cartCsrf");
        if (newCsrf != null && !newCsrf.isEmpty()) {
            return session.set("csrf", newCsrf);
        }
        return session;
    });

    private static ChainBuilder getCart = exec(
            http("GET cart")
                    .get("/v2/carts/#{cartId}")
                    .check(status().is(200))
                    .check(header("ETag").optional().saveAs("cartEtag"))
    );

    private static ChainBuilder patchCart = exec(
            http("PATCH cart quantity")
                    .patch("/v2/carts/#{cartId}")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("If-Match", session -> session.getString("cartEtag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(status().in(200, 412))
                    .check(jsonPath("$.csrf").optional().saveAs("patchCsrf"))
                    .check(header("ETag").optional().saveAs("patchEtag"))
    ).exec(session -> {
        String newCsrf = session.getString("patchCsrf");
        if (newCsrf != null && !newCsrf.isEmpty()) {
            session = session.set("csrf", newCsrf);
        }
        String newEtag = session.getString("patchEtag");
        if (newEtag != null && !newEtag.isEmpty()) {
            session = session.set("cartEtag", newEtag);
        }
        return session;
    }).doIf(session -> session.getInt("status") == 412).exec(
            http("GET cart after 412")
                    .get("/v2/carts/#{cartId}")
                    .check(status().is(200))
                    .check(header("ETag").saveAs("cartEtag"))
    ).doIf(session -> session.getInt("status") == 412).exec(
            http("PATCH cart retry")
                    .patch("/v2/carts/#{cartId}")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("If-Match", session -> session.getString("cartEtag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("patchCsrf2"))
                    .check(header("ETag").optional().saveAs("patchEtag2"))
    ).exec(session -> {
        String newCsrf = session.getString("patchCsrf2");
        if (newCsrf != null && !newCsrf.isEmpty()) {
            session = session.set("csrf", newCsrf);
        }
        String newEtag = session.getString("patchEtag2");
        if (newEtag != null && !newEtag.isEmpty()) {
            session = session.set("cartEtag", newEtag);
        }
        return session;
    });

    private static ChainBuilder createOrder = exec(
            http("POST create order")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .header("Idempotency-Key", session -> "order-" + session.getString("cartId"))
                    .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is(true))
                    .check(jsonPath("$.id").saveAs("orderId"))
                    .check(jsonPath("$.csrf").optional().saveAs("orderCsrf"))
    ).exec(session -> {
        String newCsrf = session.getString("orderCsrf");
        if (newCsrf != null && !newCsrf.isEmpty()) {
            return session.set("csrf", newCsrf);
        }
        return session;
    });

    private static ChainBuilder workCall = exec(
            http("POST work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 429))
                    .check(jsonPath("$.ok").optional().is(true))
    ).doIf(session -> session.getInt("status") == 429).exec(
            pause(Duration.ofSeconds(1))
    ).doIf(session -> session.getInt("status") == 429).exec(
            http("POST work retry")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 429))
    );

    private static ChainBuilder fullJourney = exec(loginJourney)
            .exec(catalogTraversalV3)
            .doIf(session -> !session.getBoolean("selectionFailed")).exec(
                    createCart,
                    getCart,
                    patchCart,
                    createOrder,
                    workCall
            );

    private static final ScenarioBuilder userScenario = scenario("UserJourney")
            .exec(fullJourney);

    {
        setUp(
                userScenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
