```javascript
import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailureRate = new Rate('business_failure');
const checkoutLatency = new Trend('checkout_latency', true);

const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true }
];

function getProfile(vuId) {
  return PROFILES[(vuId - 1) % PROFILES.length];
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  check(formRes, {
    'login form status 200': (r) => r.status === 200,
    'login form has csrf': (r) => r.html('input[name=csrf]').attr('value') !== undefined
  });

  const csrf = formRes.html('input[name=csrf]').attr('value');
  if (!csrf) {
    return null;
  }

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(new URL(location, BASE_URL).toString(), {
        redirects: 0,
        tags: { name: 'login_follow' }
      });
      if (followRes.status === 200) {
        try {
          const body = followRes.json();
          return { csrf: body.csrf, user: body.user };
        } catch (e) {
          return null;
        }
      }
    }
    return null;
  }

  if (loginRes.status === 200) {
    try {
      const body = loginRes.json();
      return { csrf: body.csrf, user: body.user };
    } catch (e) {
      return null;
    }
  }

  return null;
}

function renewSession(currentCsrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf
    },
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    try {
      const body = renewRes.json();
      return body.csrf || currentCsrf;
    } catch (e) {
      return currentCsrf;
    }
  }
  return null;
}

function recoverCart(cartId, csrf) {
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_recover' }
  });
  return recoverRes.status === 200 || recoverRes.status === 201;
}

function getCatalogPage(pageUrl, profile) {
  let url = pageUrl || `${BASE_URL}/v2/catalog`;
  if (profile.reverse_catalog && !pageUrl) {
    url = `${BASE_URL}/v2/catalog/page`;
  }

  const res = http.get(url, {
    tags: { name: 'catalog' }
  });

  if (res.status !== 200) {
    return null;
  }

  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function selectEligibleProduct(profile) {
  let pagesTraversed = 0;
  let currentUrl = null;

  if (profile.reverse_catalog) {
    currentUrl = `${BASE_URL}/v2/catalog/page`;
  } else {
    currentUrl = `${BASE_URL}/v2/catalog`;
  }

  while (pagesTraversed < 3) {
    const data = getCatalogPage(currentUrl, profile);
    if (!data || !data.data) {
      return null;
    }

    let products = [];
    if (data.data.products) {
      products = data.data.products;
    } else if (data.data.id) {
      products = [data.data];
    }

    for (const product of products) {
      if (product.variants && Array.isArray(product.variants)) {
        for (const variant of product.variants) {
          if (variant.in_stock === true) {
            return {
              product_id: product.id,
              variant_id: variant.id
            };
          }
        }
      }
    }

    if (data.next) {
      currentUrl = new URL(data.next, BASE_URL).toString();
      pagesTraversed++;
    } else {
      break;
    }
  }

  return null;
}

function createCart(productId, variantId, csrf, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_cart' }
  });

  if (res.status === 201) {
    try {
      const body = res.json();
      return {
        cartId: body.id,
        csrf: body.csrf || csrf,
        etag: res.headers['ETag']
      };
    } catch (e) {
      return null;
    }
  }
  return null;
}

function getCart(cartId, csrf) {
  const res = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'X-CSRF-Token': csrf
    },
    tags: { name: 'get_cart' }
  });

  if (res.status === 200) {
    return {
      etag: res.headers['ETag'],
      body: res.json()
    };
  }
  return null;
}

function patchCart(cartId, quantity, etag, csrf) {
  const res = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'patch_cart' }
  });

  if (res.status === 412) {
    // Re-read and retry once
    const cartData = getCart(cartId, csrf);
    if (cartData && cartData.etag) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': cartData.etag
        },
        tags: { name: 'patch_cart_retry' }
      });
      return retryRes.status === 200;
    }
    return false;
  }

  return res.status === 200;
}

function solveChallenge(csrf) {
  const challengeFormRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    tags: { name: 'challenge_form' }
  });

  if (challengeFormRes.status !== 200) {
    return null;
  }

  const formAction = challengeFormRes.html('form').attr('action');
  const challengeValue = challengeFormRes.html('input[name=challenge]').attr('value');

  if (!formAction || !challengeValue) {
    return null;
  }

  const challengeUrl = new URL(formAction, BASE_URL).toString();
  const challengeRes = http.post(challengeUrl, JSON.stringify({
    challenge: challengeValue
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_submit' }
  });

  if (challengeRes.status === 302) {
    const location = challengeRes.headers['Location'];
    if (location) {
      const grantRes = http.get(new URL(location, BASE_URL).toString(), {
        tags: { name: 'challenge_grant' }
      });
      if (grantRes.status === 200) {
        try {
          const body = grantRes.json();
          return {
            grantId: body.grant_id,
            csrf: body.csrf || csrf
          };
        } catch (e) {
          return null;
        }
      }
    }
  }

  return null;
}

function createReservation(cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'create_reservation' }
  });

  if (res.status !== 202) {
    return null;
  }

  try {
    const body = res.json();
    return {
      statusUrl: body.status_url,
      csrf: body.csrf || csrf
    };
  } catch (e) {
    return null;
  }
}

function pollReservation(statusUrl, csrf) {
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const res = http.get(new URL(statusUrl, BASE_URL).toString(), {
      headers: {
        'X-CSRF-Token': csrf
      },
      tags: { name: 'poll_reservation' }
    });

    if (res.status === 200) {
      try {
        const body = res.json();
        if (body.status === 'ready' && body.reservation_id) {
          return {
            reservationId: body.reservation_id,
            csrf: body.csrf || csrf
          };
        }
        if (body.status === 'failed') {
          return null;
        }
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

function createOrder(cartId, reservationId, csrf, etag, idempotencyKey) {
  const payload = {
    cart_id: cartId
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) {
    headers['If-Match'] = etag;
  }

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'create_order' }
  });

  if (res.status === 201) {
    try {
      const body = res.json();
      if (body.accepted === true) {
        return {
          success: true,
          orderId: body.id,
          csrf: body.csrf || csrf
        };
      }
    } catch (e) {
      return { success: false };
    }
  }

  if (res.status === 200) {
    try {
      const body = res.json();
      if (body.accepted === false) {
        return { success: false, businessFailure: true };
      }
    } catch (e) {
      return { success: false };
    }
  }

  return { success: false };
}

function doWork(csrf) {
  let attempts = 0;
  while (attempts < 4) {
    const res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      tags: { name: 'work' }
    });

    if (res.status === 200) {
      try {
        const body = res.json();
        if (body.ok === true) {
          return { success: true, csrf: body.csrf || csrf };
        }
      } catch (e) {
        return { success: false };
      }
    }

    if (res.status === 429) {
      const retryAfter = parseInt(res.headers['Retry-After'] || '1');
      sleep(retryAfter);
      attempts++;
      continue;
    }

    if (res.status === 401) {
      try {
        const body = res.json();
        if (body.error === 'expired') {
          const newCsrf = renewSession(csrf);
          if (newCsrf) {
            csrf = newCsrf;
            attempts++;
            continue;
          }
        }
      } catch (e) {
        // fall through
      }
    }

    return { success: false };
  }
  return { success: false };
}

function handleExpiredSession(csrf, cartId) {
  const newCsrf = renewSession(csrf);
  if (newCsrf) {
    if (cartId) {
      recoverCart(cartId, newCsrf);
    }
    return newCsrf;
  }
  return null;
}

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

export default function () {
  const vuId = __VU;
  const iterationId = __ITER;
  const profile = getProfile(vuId);

  const username = `bench-${((vuId - 1) % 16) + 1}`;
  const password = 'bench';

  group('login', function () {
    const loginResult = login(username, password);
    if (!loginResult) {
      businessFailureRate.add(1);
      return;
    }

    let csrf = loginResult.csrf;
    let cartId = null;
    let cartEtag = null;
    let grantId = null;
    let reservationId = null;
    let orderPlaced = false;

    group('select_product', function () {
      const selected = selectEligibleProduct(profile);
      if (!selected) {
        businessFailureRate.add(1);
        return;
      }

      check(selected, {
        'product selected': (s) => s.product_id !== undefined && s.variant_id !== undefined,
      });

      group('challenge', function () {
        const challengeResult = solveChallenge(csrf);
        if (challengeResult) {
          grantId = challengeResult.grantId;
          csrf = challengeResult.csrf;
        }
      });

      group('create_cart', function () {
        const cartResult = createCart(selected.product_id, selected.variant_id, csrf, grantId);
        if (!cartResult) {
          businessFailureRate.add(1);
          return;
        }

        cartId = cartResult.cartId;
        csrf = cartResult.csrf;
        cartEtag = cartResult.etag;

        check(cartResult, {
          'cart created': (c) => c.cartId !== undefined,
        });
      });

      if (!cartId) {
        return;
      }

      group('patch_cart', function () {
        const patchSuccess = patchCart(cartId, 1, cartEtag, csrf);
        if (!patchSuccess) {
          businessFailureRate.add(1);
          return;
        }

        const cartData = getCart(cartId, csrf);
        if (cartData && cartData.etag) {
          cartEtag = cartData.etag;
        }
      });

      group('reservation', function () {
        const reservationResult = createReservation(cartId, csrf);
        if (!reservationResult) {
          businessFailureRate.add(1);
          return;
        }

        csrf = reservationResult.csrf;

        const pollResult = pollReservation(reservationResult.statusUrl, csrf);
        if (!pollResult) {
          businessFailureRate.add(1);
          return;
        }

        reservationId = pollResult.reservationId;
        csrf = pollResult.csrf;
      });

      group('create_order', function () {
        const idempotencyKey = `order-${vuId}-${iterationId}-${cartId}`;
        const orderResult = createOrder(cartId, reservationId, csrf, cartEtag, idempotencyKey);

        if (orderResult.success) {
          orderPlaced = true;
          csrf = orderResult.csrf;
          checkoutLatency.add(1);
        } else if (orderResult.businessFailure) {
          businessFailureRate.add(1);
        } else {
          // Check for 401 expired
          const checkRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
            headers: { 'X-CSRF-Token': csrf },
            tags: { name: 'check_cart_after_order_fail' }
          });

          if (checkRes.status === 401) {
            try {
              const body = checkRes.json();
              if (body.error === 'expired') {
                const newCsrf = handleExpiredSession(csrf, cartId);
                if (newCsrf) {
                  csrf = newCsrf;
                  // Retry order once
                  const retryResult = createOrder(cartId, reservationId, csrf, cartEtag, idempotencyKey);
                  if (retryResult.success) {
                    orderPlaced = true;
                    csrf = retryResult.csrf;
                    checkoutLatency.add(1);
                  } else if (retryResult.businessFailure) {
                    businessFailureRate.add(1);
                  } else {
                    businessFailureRate.add(1);
                  }
                } else {
                  businessFailureRate.add(1);
                }
              } else if (body.error === 'denied') {
                businessFailureRate.add(1);
              } else {
                businessFailureRate.add(1);
              }
            } catch (e) {
              businessFailureRate.add(1);
            }
          } else {
            businessFailureRate.add(1);
          }
        }
      });

      group('work', function () {
        const workResult = doWork(csrf);
        if (!workResult.success) {
          businessFailureRate.add(1);
        }
      });

      check(orderPlaced, {
        'order placed': (o) => o === true,
      });
    });
  });

  sleep(0.1);
}
