import time
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


def _extract_csrf(html):
    import re
    m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)', html)
    if not m:
        m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', html)
    if not m:
        raise ValueError("csrf not found")
    return m.group(1)


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)
    host = BASE

    def on_start(self):
        self.client.trust_env = False
        self.client.max_redirects = 0
        self.csrf = None
        self.session_user = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None
        self.iterations_done = 0
        self.profile = self.environment.runner.user_classes[0].profile if hasattr(self.environment.runner.user_classes[0], 'profile') else {}
        self.reverse_catalog = self.profile.get("reverse_catalog", False)
        self.html_layout = self.profile.get("html_layout", 1)
        self._login()

    def _login(self):
        with self.client.get("/v2/login-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            try:
                self.csrf = _extract_csrf(r.text)
            except Exception as e:
                r.failure(f"csrf extract: {e}")
                return
        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return
                with self.client.get(urljoin(BASE, loc), catch_response=True) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"follow login redirect {r2.status_code}")
                        return
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("login redirect not json")
                        return
                    self.csrf = data.get("csrf", self.csrf)
                    self.session_user = data.get("user")
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login not json")
                    return
                self.csrf = data.get("csrf", self.csrf)
                self.session_user = data.get("user")
            else:
                r.failure(f"login status {r.status_code}")
                return

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("renew not json")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return False
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("recover not json")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag")
                return True
            r.failure(f"recover status {r.status_code}")
            return False

    def _handle_401(self, response, operation_label):
        try:
            err = response.json().get("error", "")
        except Exception:
            err = ""
        if err == "expired":
            if self._renew_session():
                if self.cart_id:
                    self._recover_cart()
                return "retry"
            return "fail"
        if err == "session":
            self._login()
            if self.cart_id:
                self._recover_cart()
            return "retry"
        if err == "denied":
            response.failure(f"{operation_label}: denied")
            return "fail"
        response.failure(f"{operation_label}: unknown 401 error {err}")
        return "fail"

    def _get_catalog(self):
        products = []
        with self.client.get("/v2/catalog", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return products
            try:
                data = r.json()
            except Exception:
                r.failure("catalog not json")
                return products
            prods = data.get("data", {}).get("products", [])
            products.extend(prods)
        for _ in range(3):
            with self.client.get("/v2/catalog/page", catch_response=True) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    break
                try:
                    data = r.json()
                except Exception:
                    r.failure("catalog page not json")
                    break
                prod = data.get("product")
                if prod:
                    products.append(prod)
                nxt = data.get("next")
                if not nxt:
                    break
        return products

    def _select_product(self, products):
        eligible = []
        for p in products:
            for v in p.get("variants", []):
                if v.get("in_stock"):
                    eligible.append((p, v))
        if not eligible:
            return None, None
        if self.reverse_catalog:
            eligible.reverse()
        return eligible[0]

    def _challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            import re
            m = re.search(r'action=["\']([^"\']+)["\']', r.text)
            if not m:
                r.failure("challenge action not found")
                return False
            action = m.group(1)
            m2 = re.search(r'name=["\']challenge["\']', r.text)
            if not m2:
                r.failure("challenge input not found")
                return False
        with self.client.post(
            urljoin(BASE, action),
            json={"challenge": "bench"},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 without Location")
                    return False
                with self.client.get(urljoin(BASE, loc), catch_response=True) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"challenge redirect status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("challenge redirect not json")
                        return False
                    self.grant_id = data.get("grant_id")
                    self.csrf = data.get("csrf", self.csrf)
                    return self.grant_id is not None
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("challenge not json")
                    return False
                self.grant_id = data.get("grant_id")
                self.csrf = data.get("csrf", self.csrf)
                return self.grant_id is not None
            else:
                r.failure(f"challenge status {r.status_code}")
                return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("cart create not json")
                    return False
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag")
                return self.cart_id is not None
            if r.status_code == 401:
                action = self._handle_401(r, "cart create")
                if action == "retry":
                    return self._create_cart(product_id, variant_id)
                return False
            r.failure(f"cart create status {r.status_code}")
            return False

    def _get_cart(self):
        with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as r:
            if r.status_code == 200:
                self.cart_etag = r.headers.get("ETag")
                return True
            if r.status_code == 401:
                action = self._handle_401(r, "cart get")
                if action == "retry":
                    return self._get_cart()
                return False
            r.failure(f"cart get status {r.status_code}")
            return False

    def _patch_cart(self, quantity):
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("patch not json")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag")
                return True
            if r.status_code == 412:
                if self._get_cart():
                    headers = {"X-CSRF-Token": self.csrf}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers=headers,
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            try:
                                data = r2.json()
                            except Exception:
                                r2.failure("patch retry not json")
                                return False
                            self.csrf = data.get("csrf", self.csrf)
                            self.cart_etag = r2.headers.get("ETag")
                            return True
                        if r2.status_code == 401:
                            action = self._handle_401(r2, "patch retry")
                            if action == "retry":
                                return self._patch_cart(quantity)
                            return False
                        r2.failure(f"patch retry status {r2.status_code}")
                        return False
                return False
            if r.status_code == 401:
                action = self._handle_401(r, "patch")
                if action == "retry":
                    return self._patch_cart(quantity)
                return False
            r.failure(f"patch status {r.status_code}")
            return False

    def _reserve(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as r:
            if r.status_code == 202:
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation not json")
                    return False
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                if not status_url:
                    r.failure("reservation no status_url")
                    return False
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(urljoin(BASE, status_url), catch_response=True) as r2:
                        if r2.status_code == 200:
                            try:
                                sdata = r2.json()
                            except Exception:
                                r2.failure("reservation status not json")
                                return False
                            status = sdata.get("status")
                            if status == "ready":
                                self.reservation_id = sdata.get("reservation_id")
                                self.csrf = sdata.get("csrf", self.csrf)
                                return self.reservation_id is not None
                            if status == "failed":
                                r2.failure("reservation failed")
                                return False
                        elif r2.status_code == 401:
                            action = self._handle_401(r2, "reservation poll")
                            if action == "retry":
                                continue
                            return False
                        else:
                            r2.failure(f"reservation poll status {r2.status_code}")
                            return False
                r.failure("reservation polling exhausted")
                return False
            if r.status_code == 401:
                action = self._handle_401(r, "reservation")
                if action == "retry":
                    return self._reserve()
                return False
            r.failure(f"reservation status {r.status_code}")
            return False

    def _order(self):
        if not self.idem_key:
            self.idem_key = f"idem-{self.session_user or 'bench'}-{self.cart_id}-{int(time.time()*1000)}"
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": self.idem_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if not data.get("accepted"):
                    r.failure("order accepted:false")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order 200 not json")
                    return False
                if not data.get("accepted"):
                    r.failure("order 200 accepted:false")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True
            if r.status_code == 401:
                action = self._handle_401(r, "order")
                if action == "retry":
                    return self._order()
                return False
            r.failure(f"order status {r.status_code}")
            return False

    def _work(self):
        with self.client.post("/v2/work", json={}, catch_response=True) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("work not json")
                    return
                if not data.get("ok"):
                    r.failure("work ok:false")
            elif r.status_code == 429:
                retry_after = r.headers.get("Retry-After")
                if retry_after:
                    try:
                        time.sleep(float(retry_after))
                    except ValueError:
                        time.sleep(1)
                else:
                    time.sleep(1)
                for _ in range(4):
                    with self.client.post("/v2/work", json={}, catch_response=True) as r2:
                        if r2.status_code == 200:
                            try:
                                data = r2.json()
                            except Exception:
                                r2.failure("work retry not json")
                                return
                            if not data.get("ok"):
                                r2.failure("work retry ok:false")
                            return
                        elif r2.status_code == 429:
                            retry_after = r2.headers.get("Retry-After")
                            if retry_after:
                                try:
                                    time.sleep(float(retry_after))
                                except ValueError:
                                    time.sleep(1)
                            else:
                                time.sleep(1)
                            continue
                        else:
                            r2.failure(f"work retry status {r2.status_code}")
                            return
                r.failure("work 429 retries exhausted")
            elif r.status_code == 401:
                action = self._handle_401(r, "work")
                if action == "retry":
                    self._work()
            else:
                r.failure(f"work status {r.status_code}")

    @task
    def journey(self):
        if self.iterations_done >= self.environment.runner.user_classes[0].iterations_per_user:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login and cart per journey
        self._login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None

        products = self._get_catalog()
        if not products:
            return
        parent, variant = self._select_product(products)
        if parent is None or variant is None:
            return

        # Optional challenge
        self._challenge()

        if not self._create_cart(parent["id"], variant["id"]):
            return
        if not self._get_cart():
            return
        if not self._patch_cart(random.randint(1, 20)):
            return
        if not self._reserve():
            return
        if not self._order():
            return
        self._work()


class ProfileOne(ShopUser):
    profile = {}
    iterations_per_user = 2


class ProfileTwo(ShopUser):
    profile = {"html_layout": 1, "reverse_catalog": True}
    iterations_per_user = 2


class TestShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.users_started = False

    def tick(self):
        if not self.users_started:
            self.users_started = True
            return (2, 2)
        run_time = time.time() - self.start_time
        if run_time > 120:
            return None
        return (2, 2)
