import os
import random
import time
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)

    def on_start(self):
        self.client.base_url = BASE
        self.client.trust_env = False
        self.client.follow_redirects = False
        self.csrf = None
        self.session_user = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iterations_done = 0
        self.login()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            import re
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf', r.text)
            if not m:
                r.failure("no csrf in login form")
                return
            self.csrf = m.group(1)

        username = f"bench-{random.randint(1, 16)}"
        with self.client.post(
            "/v2/login",
            json={"username": username, "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/login",
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("302 without Location")
                    return
                with self.client.get(
                    urljoin(BASE, loc),
                    catch_response=True,
                    name="/v2/login-redirect",
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"redirect status {r2.status_code}")
                        return
                    self._process_login_response(r2)
            elif r.status_code == 200:
                self._process_login_response(r)
            else:
                r.failure(f"login status {r.status_code}")

    def _process_login_response(self, r):
        try:
            data = r.json()
        except Exception:
            r.failure("login response not json")
            return
        self.csrf = data.get("csrf") or self.csrf
        self.session_user = data.get("user")

    def _handle_401(self, response, operation_name):
        """Returns True if the operation should be retried after recovery."""
        try:
            err = response.json().get("error", "")
        except Exception:
            err = ""
        if err == "expired":
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                name="/v2/session/renew",
            ) as rr:
                if rr.status_code == 200:
                    try:
                        self.csrf = rr.json().get("csrf") or self.csrf
                    except Exception:
                        pass
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf},
                            catch_response=True,
                            name="/v2/carts/recover",
                        ) as rc:
                            if rc.status_code == 200:
                                try:
                                    self.csrf = rc.json().get("csrf") or self.csrf
                                except Exception:
                                    pass
                    return True
                else:
                    rr.failure(f"renew failed {rr.status_code}")
                    return False
        elif err == "session":
            # Revoked: get fresh form/login, recover cart
            self.login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    name="/v2/carts/recover",
                ) as rc:
                    if rc.status_code == 200:
                        try:
                            self.csrf = rc.json().get("csrf") or self.csrf
                        except Exception:
                            pass
            return True
        elif err == "denied":
            response.failure("denied is not expiry")
            return False
        return False

    def _get_catalog_page(self, url):
        with self.client.get(
            url,
            catch_response=True,
            name="/v2/catalog-page",
        ) as r:
            if r.status_code != 200:
                r.failure(f"catalog page status {r.status_code}")
                return None
            try:
                return r.json()
            except Exception:
                r.failure("catalog page not json")
                return None

    def _find_eligible_product(self):
        """Traverse at most 3 pages of /v2/catalog/page to find an in-stock variant."""
        url = "/v2/catalog/page"
        for _ in range(3):
            data = self._get_catalog_page(url)
            if data is None:
                return None
            product = data.get("data", {})
            variants = product.get("variants", [])
            for v in variants:
                if v.get("in_stock"):
                    return product.get("id"), v.get("id")
            nxt = data.get("next")
            if not nxt:
                return None
            url = nxt
        return None

    def _handle_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
            name="/v2/challenge-form",
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            import re
            m = re.search(r'action=["\']([^"\']+)', r.text)
            if not m:
                r.failure("no challenge action")
                return False
            action = m.group(1)
            m2 = re.search(r'name=["\']challenge["\'][^>]*value=["\']([^"\']+)', r.text)
            if not m2:
                m2 = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']challenge', r.text)
            if not m2:
                r.failure("no challenge value")
                return False
            challenge_value = m2.group(1)

        with self.client.post(
            urljoin(BASE, action),
            json={"challenge": challenge_value},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/challenge-submit",
        ) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if not loc:
                    r.failure("challenge 302 without Location")
                    return False
                with self.client.get(
                    urljoin(BASE, loc),
                    catch_response=True,
                    name="/v2/challenge-redirect",
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"challenge redirect status {r2.status_code}")
                        return False
                    try:
                        data = r2.json()
                    except Exception:
                        r2.failure("challenge redirect not json")
                        return False
                    self.grant_id = data.get("grant_id")
                    self.csrf = data.get("csrf") or self.csrf
                    return self.grant_id is not None
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("challenge response not json")
                    return False
                self.grant_id = data.get("grant_id")
                self.csrf = data.get("csrf") or self.csrf
                return self.grant_id is not None
            else:
                r.failure(f"challenge status {r.status_code}")
                return False

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts",
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("cart create not json")
                    return False
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf") or self.csrf
                self.cart_etag = r.headers.get("ETag")
                return self.cart_id is not None
            elif r.status_code == 401:
                if self._handle_401(r, "cart-create"):
                    return self._create_cart(product_id, variant_id)
                return False
            else:
                r.failure(f"cart create status {r.status_code}")
                return False

    def _get_cart(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            name="/v2/carts/get",
        ) as r:
            if r.status_code == 200:
                self.cart_etag = r.headers.get("ETag")
                return True
            elif r.status_code == 401:
                if self._handle_401(r, "cart-get"):
                    return self._get_cart()
                return False
            else:
                r.failure(f"cart get status {r.status_code}")
                return False

    def _patch_cart(self, quantity):
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            catch_response=True,
            name="/v2/carts/patch",
        ) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    pass
                else:
                    self.csrf = data.get("csrf") or self.csrf
                self.cart_etag = r.headers.get("ETag")
                return True
            elif r.status_code == 412:
                # Re-read and retry once
                if self._get_cart():
                    headers = {"X-CSRF-Token": self.csrf}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers=headers,
                        catch_response=True,
                        name="/v2/carts/patch-retry",
                    ) as r2:
                        if r2.status_code == 200:
                            try:
                                data = r2.json()
                            except Exception:
                                pass
                            else:
                                self.csrf = data.get("csrf") or self.csrf
                            self.cart_etag = r2.headers.get("ETag")
                            return True
                        elif r2.status_code == 401:
                            if self._handle_401(r2, "cart-patch-retry"):
                                return self._patch_cart(quantity)
                            return False
                        else:
                            r2.failure(f"patch retry status {r2.status_code}")
                            return False
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "cart-patch"):
                    return self._patch_cart(quantity)
                return False
            else:
                r.failure(f"patch status {r.status_code}")
                return False

    def _create_reservation(self):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/reservations",
        ) as r:
            if r.status_code == 202:
                try:
                    data = r.json()
                except Exception:
                    r.failure("reservation not json")
                    return False
                status_url = data.get("status_url")
                self.csrf = data.get("csrf") or self.csrf
                if not status_url:
                    r.failure("no status_url")
                    return False
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(
                        urljoin(BASE, status_url),
                        catch_response=True,
                        name="/v2/reservations/status",
                    ) as sr:
                        if sr.status_code == 200:
                            try:
                                sdata = sr.json()
                            except Exception:
                                sr.failure("reservation status not json")
                                return False
                            status = sdata.get("status")
                            if status == "ready":
                                self.reservation_id = sdata.get("reservation_id")
                                self.csrf = sdata.get("csrf") or self.csrf
                                return self.reservation_id is not None
                            elif status in ("pending",):
                                continue
                            elif status == "failed":
                                sr.failure("reservation failed")
                                return False
                            else:
                                sr.failure(f"unknown reservation status {status}")
                                return False
                        elif sr.status_code == 401:
                            if self._handle_401(sr, "reservation-status"):
                                continue
                            return False
                        else:
                            sr.failure(f"reservation status http {sr.status_code}")
                            return False
                r.failure("reservation polling exhausted")
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "reservation-create"):
                    return self._create_reservation()
                return False
            else:
                r.failure(f"reservation create status {r.status_code}")
                return False

    def _create_order(self):
        self.idempotency_key = f"order-{self.cart_id}-{random.randint(100000, 999999)}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="/v2/orders",
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order not json")
                    return False
                if data.get("accepted") is True:
                    self.csrf = data.get("csrf") or self.csrf
                    return True
                else:
                    r.failure("order accepted=false")
                    return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order 200 not json")
                    return False
                if data.get("accepted") is False:
                    r.failure("business failure accepted=false")
                    return False
                r.failure("unexpected 200 order response")
                return False
            elif r.status_code == 401:
                if self._handle_401(r, "order-create"):
                    return self._create_order()
                return False
            else:
                r.failure(f"order status {r.status_code}")
                return False

    def _do_work(self):
        for _ in range(4):
            with self.client.post(
                "/v2/work",
                json={},
                catch_response=True,
                name="/v2/work",
            ) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                    except Exception:
                        r.failure("work not json")
                        return
                    if data.get("ok") is True:
                        return
                    else:
                        r.failure("work ok=false")
                        return
                elif r.status_code == 429:
                    retry_after = r.headers.get("Retry-After")
                    try:
                        wait = float(retry_after) if retry_after else 1.0
                    except ValueError:
                        wait = 1.0
                    time.sleep(wait)
                    continue
                elif r.status_code == 401:
                    if self._handle_401(r, "work"):
                        continue
                    return
                else:
                    r.failure(f"work status {r.status_code}")
                    return
        # exhausted retries
        with self.client.post(
            "/v2/work",
            json={},
            catch_response=True,
            name="/v2/work",
        ) as r:
            r.failure("work retries exhausted")

    @task
    def journey(self):
        if self.iterations_done >= self.environment.parsed_options.iterations:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login/cart per journey
        self.login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        # Optional challenge (some fixtures require it)
        self._handle_challenge()

        # Find eligible product via cursor pagination
        found = self._find_eligible_product()
        if not found:
            # No eligible product found; still do work sample
            self._do_work()
            return
        product_id, variant_id = found

        if not self._create_cart(product_id, variant_id):
            self._do_work()
            return

        if not self._get_cart():
            self._do_work()
            return

        if not self._patch_cart(random.randint(1, 20)):
            self._do_work()
            return

        # Reservation (optional but recommended)
        self._create_reservation()

        if not self._create_order():
            self._do_work()
            return

        self._do_work()


class Shape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
