import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ModelSimulation extends Simulation {

    // --- Configuration ---
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");
    private static final int USERS = 2;
    private static final int ITERATIONS = 2;
    private static final int QUANTITY = 2;

    // --- Feeder for users ---
    private static final List<Map<String, Object>> USER_FEED = new ArrayList<>();
    static {
        for (int i = 1; i <= 16; i++) {
            Map<String, Object> m = new HashMap<>();
            m.put("username", "bench-" + i);
            m.put("password", "bench");
            USER_FEED.add(m);
        }
    }

    // --- Regex patterns ---
    private static final Pattern CSRF_INPUT_PATTERN = Pattern.compile("name=[\"']csrf[\"'][^>]*value=[\"']([^\"']+)[\"']");
    private static final Pattern CSRF_INPUT_PATTERN2 = Pattern.compile("value=[\"']([^\"']+)[\"'][^>]*name=[\"']csrf[\"']");
    private static final Pattern CHALLENGE_ACTION_PATTERN = Pattern.compile("action=[\"']([^\"']*challenges/[^\"']+)[\"']");
    private static final Pattern CHALLENGE_INPUT_PATTERN = Pattern.compile("name=[\"']challenge[\"'][^>]*value=[\"']([^\"']+)[\"']");
    private static final Pattern CHALLENGE_INPUT_PATTERN2 = Pattern.compile("value=[\"']([^\"']+)[\"'][^>]*name=[\"']challenge[\"']");
    private static final Pattern LOCATION_PATTERN = Pattern.compile("Location:\\s*(\\S+)");
    private static final Pattern ETAG_PATTERN = Pattern.compile("ETag:\\s*\"?([^\"]+)\"?");

    // --- Helper to extract CSRF from HTML ---
    private static String extractCsrfFromHtml(String html) {
        Matcher m1 = CSRF_INPUT_PATTERN.matcher(html);
        if (m1.find()) return m1.group(1);
        Matcher m2 = CSRF_INPUT_PATTERN2.matcher(html);
        if (m2.find()) return m2.group(1);
        return null;
    }

    // --- Helper to extract challenge action ---
    private static String extractChallengeAction(String html) {
        Matcher m = CHALLENGE_ACTION_PATTERN.matcher(html);
        if (m.find()) return m.group(1);
        return null;
    }

    // --- Helper to extract challenge value ---
    private static String extractChallengeValue(String html) {
        Matcher m1 = CHALLENGE_INPUT_PATTERN.matcher(html);
        if (m1.find()) return m1.group(1);
        Matcher m2 = CHALLENGE_INPUT_PATTERN2.matcher(html);
        if (m2.find()) return m2.group(1);
        return null;
    }

    // --- Helper to extract Location header from a response ---
    private static String extractLocation(String headers) {
        Matcher m = LOCATION_PATTERN.matcher(headers);
        if (m.find()) return m.group(1);
        return null;
    }

    // --- Helper to extract ETag from headers ---
    private static String extractEtag(String headers) {
        Matcher m = ETAG_PATTERN.matcher(headers);
        if (m.find()) return m.group(1);
        return null;
    }

    // --- HTTP Protocol ---
    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json, text/html, */*")
            .contentTypeHeader("application/json")
            .userAgentHeader("Gatling/3.15");

    // --- Chain: Login and get CSRF ---
    private static ChainBuilder loginAndGetCsrf() {
        return exec(
                http("GET login-form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(bodyString().transform(ModelSimulation::extractCsrfFromHtml).saveAs("loginCsrf"))
                        .check(bodyString().saveAs("loginFormHtml"))
        ).exec(session -> {
            String csrf = session.getString("loginCsrf");
            if (csrf == null || csrf.isEmpty()) {
                throw new RuntimeException("No CSRF found in login form");
            }
            return session;
        }).exec(
                http("POST login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> session.getString("loginCsrf"))
                        .body(StringBody(session -> {
                            String csrf = session.getString("loginCsrf");
                            String username = session.getString("username");
                            String password = session.getString("password");
                            return String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}", username, password, csrf);
                        }))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(bodyString().optional().saveAs("loginResponseBody"))
                        .check(header("Set-Cookie").optional().saveAs("loginSetCookie"))
        ).exec(session -> {
            String location = session.getString("loginLocation");
            if (location != null && !location.isEmpty()) {
                return session.set("loginRedirectUrl", location);
