                    }
                    return session;
                });
    }

    // --- Chain: Create order with Idempotency-Key and If-Match ---
    private static ChainBuilder createOrder() {
        return exec(session -> {
            String idempotencyKey = "order-" + session.getString("cartId") + "-" + System.nanoTime();
            return session.set("idempotencyKey", idempotencyKey);
        }).exec(
                http("POST order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                        .header("Idempotency-Key", session -> session.getString("idempotencyKey"))
