                        .check(status().is(201))
                        .check(jsonPath("$.accepted").is("true"))
                        .check(jsonPath("$.id").saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrfFromOrder"))
        ).exec(session -> {
            String newCsrf = session.getString("newCsrfFromOrder");
            if (newCsrf != null && !newCsrf.isEmpty()) {
                session = session.set("csrf", newCsrf);
            }
            return session;
        });
    }

    // --- Chain: Scheduled work with 429 retry ---
    private static ChainBuilder scheduledWork() {
        return exec(session -> session.set("workRetryCount", 0))
                .asLongAs(session -> session.getInt("workRetryCount") < 4).on(
                        exec(
                                http("POST work")
                                        .post("/v2/work")
                                        .header("X-CSRF-Token", session -> session.getString("csrf"))
                                        .body(StringBody("{}"))
                                        .check(status().in(200, 429))
                                        .check(bodyString().saveAs("workResponseBody"))
                        ).exec(session -> {
                            int status = session.getInt("status");
                            if (status == 429) {
                                session = session.set("workRetryCount", session.getInt("workRetryCount") + 1);
                                session = session.set("workRetryNeeded", true);
                            } else {
                                session = session.set("workRetryNeeded", false);
                            }
                            return session;
                        }).doIf(session -> session.getBoolean("workRetryNeeded")).then(
                                pause(Duration.ofSeconds(1))
                        )
                ).exec(session -> {
                    if (session.getInt("workRetryCount") >= 4 && session.getInt("status") == 429) {
                        throw new RuntimeException("Work 429 retries exhausted");
                    }
                    return session;
                });
    }

    // --- Main journey ---
    private static final ChainBuilder journey = exec(loginAndGetCsrf())
            .exec(getCatalogAndSelectProduct())
            .exec(getChallengeAndGrant())
            .exec(createCart())
            .exec(getCartForEtag())
            .exec(patchCartWithRetry())
            .exec(createReservation())
            .exec(pollReservation())
            .exec(createOrder())
            .exec(scheduledWork());

    // --- Scenario ---
    private static final ScenarioBuilder scn = scenario("ETag Cart Journey")
            .feed(USER_FEED.iterator())
            .repeat(ITERATIONS).on(
                    exec(journey)
            );

    {
        setUp(
                scn.injectOpen(atOnceUsers(USERS))
        ).protocols(httpProtocol);
    }
}
