```javascript
import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const USERS = 2;
const ITERATIONS = 2;
const QUANTITY = 2;

const businessFailureRate = new Rate('business_failure');
const unexpectedFailures = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');

const profiles = [
  { require_etag: true, dynamic_etag: true, etag_conflict_once: true },
  { require_etag: true, dynamic_etag: true, etag_conflict_once: true, html_layout: 1, reverse_catalog: true }
];

function getProfile(vuId) {
  return profiles[(vuId - 1) % profiles.length];
}

function extractCsrf(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                html.match(/name=["']csrf["']/i);
  if (match && match[1]) return match[1];
  const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function extractNonce(html) {
  const match = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  return match ? match[1] : null;
}

function extractETag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  return etag || null;
}

function login(httpClient, username, password) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login form loads': (r) => r.status === 200 });
  const csrf = extractCsrf(formRes.body);
  const nonce = extractNonce(formRes.body);
  if (!csrf) fail('No CSRF token found in login form');

  const loginPayload = JSON.stringify({ username, password, csrf });
  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, { redirects: 0 });
      check(followRes, { 'login redirect followed': (r) => r.status === 200 });
      const newCsrf = extractCsrf(followRes.body);
      if (newCsrf) return { csrf: newCsrf, user: username };
      return { csrf, user: username };
    }
  }

  if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      return { csrf: body.csrf || csrf, user: body.user || username };
    } catch (e) {
      return { csrf, user: username };
    }
  }

  fail(`Login failed with status ${loginRes.status}`);
}

function getCatalog(httpClient, csrf, reverse) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(res, { 'catalog loads': (r) => r.status === 200 });
  let products = [];
  try {
    const body = JSON.parse(res.body);
    products = body.data && body.data.products ? body.data.products : [];
  } catch (e) {
    fail('Failed to parse catalog');
  }

  if (reverse && products.length > 0) {
    products = products.slice().reverse();
  }

  return products;
}

function getCatalogPage(httpClient, csrf, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = httpClient.get(url, { headers: { 'X-CSRF-Token': csrf } });
  check(res, { 'catalog page loads': (r) => r.status === 200 });
  try {
    const body = JSON.parse(res.body);
    return body;
  } catch (e) {
    fail('Failed to parse catalog page');
  }
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;

  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });

  check(res, { 'cart created': (r) => r.status === 201 });
  if (res.status !== 201) fail(`Cart creation failed: ${res.status}`);

  const etag = extractETag(res.headers);
  let body;
  try {
    body = JSON.parse(res.body);
  } catch (e) {
    fail('Failed to parse cart creation response');
  }

  return {
    cartId: body.id,
    csrf: body.csrf || csrf,
    etag
  };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(res, { 'cart fetched': (r) => r.status === 200 });
  const etag = extractETag(res.headers);
  return { etag, status: res.status, body: res.body };
}

function patchCart(httpClient, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf
  };
  if (etag) headers['If-Match'] = etag;

  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, { headers });
  return {
    status: res.status,
    etag: extractETag(res.headers),
    body: res.body,
    csrf: res.headers['X-CSRF-Token'] || csrf
  };
}

function createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) headers['If-Match'] = etag;

  const res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), { headers });
  return {
    status: res.status,
    body: res.body,
    csrf: res.headers['X-CSRF-Token'] || csrf,
    etag: extractETag(res.headers)
  };
}

function getChallengeForm(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf }
  });
  check(res, { 'challenge form loads': (r) => r.status === 200 });
  const actionMatch = res.body.match(/action=["']([^"']*challenges[^"']*)["']/i);
  const challengeMatch = res.body.match(/name=["']challenge["']/i);
  if (!actionMatch || !challengeMatch) return null;
  return { action: actionMatch[1], hasChallenge: true };
}

function submitChallenge(httpClient, csrf, action, challengeValue) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const res = httpClient.post(url, JSON.stringify({ challenge: challengeValue }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0
  });
  if (res.status === 302) {
    const location = res.headers['Location'];
    if (location) {
      const followRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        headers: { 'X-CSRF-Token': csrf }
      });
      check(followRes, { 'challenge grant fetched': (r) => r.status === 200 });
      try {
        const body = JSON.parse(followRes.body);
        return { grantId: body.grant_id, csrf: body.csrf || csrf };
      } catch (e) {
        return { grantId: null, csrf };
      }
    }
  }
  return { grantId: null, csrf };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  check(res, { 'reservation created': (r) => r.status === 202 });
  if (res.status !== 202) return { status: res.status, reservationId: null, csrf };

  let body;
  try {
    body = JSON.parse(res.body);
  } catch (e) {
    return { status: res.status, reservationId: null, csrf };
  }

  const statusUrl = body.status_url;
  const newCsrf = body.csrf || csrf;
  let reservationId = null;
  let pollCount = 0;

  while (pollCount < 5) {
    sleep(0.05);
    pollCount++;
    const pollRes = httpClient.get(statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`, {
      headers: { 'X-CSRF-Token': newCsrf }
    });
    businessResponses.add(1);
    if (pollRes.status === 200) {
      try {
        const pollBody = JSON.parse(pollRes.body);
        if (pollBody.status === 'ready' && pollBody.reservation_id) {
          reservationId = pollBody.reservation_id;
          break;
        }
        if (pollBody.status === 'failed') {
          break;
        }
      } catch (e) {
        break;
      }
    } else if (pollRes.status === 429) {
      const retryAfter = parseInt(pollRes.headers['Retry-After'] || '1', 10);
      sleep(retryAfter);
    } else if (pollRes.status === 500) {
      unexpectedFailures.add(1);
      break;
    }
  }

  return { status: 202, reservationId, csrf: newCsrf };
}

function renewSession(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      return { csrf: body.csrf || csrf, renewed: true };
    } catch (e) {
      return { csrf, renewed: true };
    }
  }
  return { csrf, renewed: false };
}

function recoverCart(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  return { status: res.status, csrf: res.headers['X-CSRF-Token'] || csrf };
}

function doWork(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  businessResponses.add(1);
  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.ok !== true) unexpectedFailures.add(1);
    } catch (e) {
      unexpectedFailures.add(1);
    }
  } else if (res.status === 429) {
    let retries = 0;
    let retryRes = res;
    while (retryRes.status === 429 && retries < 4) {
      const retryAfter = parseInt(retryRes.headers['Retry-After'] || '1', 10);
      sleep(retryAfter);
      retries++;
      retryRes = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
        headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
      });
      businessResponses.add(1);
    }
    if (retryRes.status === 200) {
      try {
        const body = JSON.parse(retryRes.body);
        if (body.ok !== true) unexpectedFailures.add(1);
      } catch (e) {
        unexpectedFailures.add(1);
      }
    } else if (retryRes.status === 500) {
      unexpectedFailures.add(1);
