    if (firstPage && firstPage.data && firstPage.data.products) {
      products = firstPage.data.products;
      pageUrl = firstPage.next;
      pageCount = 1;
    }
    while (products.length === 0 && pageUrl && pageCount < 3) {
      const page = getCatalogPage(httpClient, csrf, pageUrl);
      if (page && page.data && page.data.products) {
        products = page.data.products;
        pageUrl = page.next;
        pageCount++;
      } else {
        break;
      }
    }
  }

  if (products.length === 0) {
    fail('No products found in catalog');
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    fail('No in-stock product variant found');
  }

  // Optional challenge for grant_id
  let grantId = null;
  const challengeForm = getChallengeForm(httpClient, csrf);
  if (challengeForm && challengeForm.hasChallenge) {
    const challengeResult = submitChallenge(httpClient, csrf, challengeForm.action, 'bench');
    grantId = challengeResult.grantId;
    csrf = challengeResult.csrf;
  }

