  const cart = createCart(httpClient, csrf, selectedProduct.id, selectedVariant.id, grantId);
  let cartId = cart.cartId;
  csrf = cart.csrf;
  let etag = cart.etag;

  // Get cart to extract ETag (setup checkpoint)
  const cartGet = getCart(httpClient, csrf, cartId);
  etag = cartGet.etag || etag;

  // PATCH with If-Match, handle 412 conflict once
  let patchResult = patchCart(httpClient, csrf, cartId, etag, QUANTITY);
  csrf = patchResult.csrf;

  if (patchResult.status === 412) {
    // Re-read cart to get fresh ETag
    const reRead = getCart(httpClient, csrf, cartId);
    etag = reRead.etag || etag;
