    patchResult = patchCart(httpClient, csrf, cartId, etag, QUANTITY);
    csrf = patchResult.csrf;
  }

  check(patchResult.status, { 'cart patched successfully': (s) => s === 200 || s === 204 });

  // Get final ETag after patch
  const finalCartGet = getCart(httpClient, csrf, cartId);
  etag = finalCartGet.etag || etag;

  // Create reservation (optional)
  let reservationId = null;
  const reservation = createReservation(httpClient, csrf, cartId);
  reservationId = reservation.reservationId;
  csrf = reservation.csrf;

