  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  let orderResult = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
  csrf = orderResult.csrf;

  // Handle 401 expiry
  if (orderResult.status === 401) {
    let body;
    try {
      body = JSON.parse(orderResult.body);
    } catch (e) {
      body = {};
    }
    if (body.error === 'expired') {
