      csrf = renewResult.csrf;
      if (cartId) {
        const recoverResult = recoverCart(httpClient, csrf, cartId);
        csrf = recoverResult.csrf;
      }
      // Retry order once
      orderResult = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
      csrf = orderResult.csrf;
    } else if (body.error === 'session') {
      // Session revoked: fresh login and recover
      session = login(httpClient, username, password);
      csrf = session.csrf;
      if (cartId) {
        const recoverResult = recoverCart(httpClient, csrf, cartId);
        csrf = recoverResult.csrf;
      }
      orderResult = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
      csrf = orderResult.csrf;
    } else if (body.error === 'denied') {
      fail('401 denied error - assertion failure');
    }
  }

  // Handle 412 on order
  if (orderResult.status === 412) {
    const reRead = getCart(httpClient, csrf, cartId);
    etag = reRead.etag || etag;
    orderResult = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
    csrf = orderResult.csrf;
  }

  businessResponses.add(1);
  if (orderResult.status === 201) {
    try {
      const orderBody = JSON.parse(orderResult.body);
      if (orderBody.accepted === true) {
        check(true, { 'order accepted': (v) => v === true });
      } else {
        unexpectedFailures.add(1);
        check(false, { 'order accepted': (v) => v === true });
      }
    } catch (e) {
      unexpectedFailures.add(1);
    }
  } else if (orderResult.status === 200) {
    try {
      const orderBody = JSON.parse(orderResult.body);
      if (orderBody.accepted === false) {
        unexpectedFailures.add(1);
        check(false, { 'order accepted': (v) => v === true });
      } else {
        check(true, { 'order accepted': (v) => v === true });
      }
    } catch (e) {
      unexpectedFailures.add(1);
    }
  } else if (orderResult.status === 500) {
    unexpectedFailures.add(1);
  } else {
    unexpectedFailures.add(1);
  }

  // Do work
  doWork(httpClient, csrf);

  // Record business failure rate
  const totalBusiness = businessResponses.value || 1;
  const totalUnexpected = unexpectedFailures.value || 0;
  businessFailureRate.add(totalUnexpected / totalBusiness);

  sleep(0.1);
}
