                data = resp.json()
                self.grant_id = data.get("grant_id")
                self.csrf = data.get("csrf", self.csrf)
                resp.success()
                return True
            else:
                resp.failure(f"challenge status {resp.status_code}")
                return False

    def maybe_reservation(self):
        """Optionally create a reservation for the cart."""
        if not self.cart_id:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=self.get_csrf_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 202:
                data = resp.json()
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                resp.success()
                if not status_url:
                    return False
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(
                        urljoin(BASE, status_url),
                        catch_response=True,
                        allow_redirects=False,
                    ) as poll_resp:
                        if poll_resp.status_code == 200:
                            poll_data = poll_resp.json()
                            status = poll_data.get("status")
                            if status == "ready":
                                self.reservation_id = poll_data.get("reservation_id")
                                self.csrf = poll_data.get("csrf", self.csrf)
                                poll_resp.success()
                                return True
                            elif status == "pending":
                                poll_resp.success()
                                continue
                            elif status == "failed":
                                poll_resp.success()
                                return False
                            else:
                                poll_resp.failure(f"unknown reservation status {status}")
                                return False
                        else:
                            poll_resp.failure(f"reservation poll status {poll_resp.status_code}")
                            return False
                return False
            elif resp.status_code == 401:
                if self.handle_401(resp, "reservation"):
                    return self.maybe_reservation()
                return False
            else:
                resp.failure(f"reservation status {resp.status_code}")
                return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login/cart per journey
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.idempotency_key = None
        self.reservation_id = None
        self.login()

        # Optional challenge
        if random.random() < 0.3:
            self.maybe_challenge()

        # Get product
        product = self.get_catalog_product()
        if not product:
            return
        variants = product.get("variants", [])
        if not variants:
            return
        variant = random.choice(variants)
        product_id = product.get("id")
        variant_id = variant.get("id")

        # Create cart
        if not self.create_cart(product_id, variant_id):
            return

        # Get cart to extract ETag
        if not self.get_cart():
            return

        # Update cart with quantity
        quantity = random.randint(1, 20)
        if not self.update_cart(quantity):
            return

        # Optional reservation
        if random.random() < 0.3:
            self.maybe_reservation()

        # Create order
        self.create_order()

        # Do work
        self.do_work()


