                String body = session.getString("body");
                String error = extractError(body);
                if (error != null) session = session.set("error", error);
                return session;
            })
            .exec(handle401Expired())
            .exec(handle401SessionRevoked())
            .exec(handle401Denied())
        );
    }

    // ---------- Main journey ----------
    private static ChainBuilder journey() {
        return exec(
            getLoginForm()
            .exec(postLogin())
            .exec(handleLoginRedirect())
            .exec(getCatalog())
            .exec(traverseCatalogPages())
            .exec(getChallengeForm())
            .exec(postChallenge())
            .exec(createCart())
            .exec(getCart())
            .exec(patchCart())
            .exec(createReservation())
            .exec(pollReservation())
            .exec(createOrder())
            .exec(doWork())
        );
    }

    // ---------- Scenario ----------
    private static final ScenarioBuilder scn = scenario("ModelSimulation")
        .feed(userFeeder)
        .feed(profileFeeder)
        .exec(journey());

    {
        setUp(
            scn.injectOpen(
                atOnceUsers(2)
            )
        ).protocols(httpProtocol)
         .assertions(
            global().successfulRequests().percent().gt(95.0)
         );
    }
}
