import os
import random
import time
from urllib.parse import urljoin

from locust import HttpUser, LoadTestShape, between, task
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0.1, 0.3)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iterations_done = 0
        self.max_iterations = 2
        self.rotate_csrf = True
        self.html_layout = 0
        self.reverse_catalog = False

    def on_start(self):
        self.client.redirect_enabled = False
        self.login()

    def login(self):
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            # Extract csrf from input[name=csrf]
            import re
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', r.text)
            if not m:
                r.failure("no csrf in login form")
                return
            login_csrf = m.group(1)

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": login_csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 302):
                if r.status_code == 302:
                    loc = r.headers.get("Location")
                    if loc:
                        with self.client.get(urljoin(BASE, loc), catch_response=True) as r2:
                            if r2.status_code != 200:
                                r2.failure(f"login redirect status {r2.status_code}")
                                return
                            self._extract_csrf_from_json(r2)
                    else:
                        r.failure("302 without Location")
                        return
                else:
                    self._extract_csrf_from_json(r)
            else:
                r.failure(f"login status {r.status_code}")

    def _extract_csrf_from_json(self, response):
        try:
            data = response.json()
            self.csrf = data.get("csrf", self.csrf)
        except Exception:
            response.failure("invalid JSON in login response")

    def _update_csrf_from_response(self, response):
        if not self.rotate_csrf:
            return
        try:
            data = response.json()
            new_csrf = data.get("csrf")
            if new_csrf:
                self.csrf = new_csrf
        except Exception:
            pass

    def _handle_401(self, response, operation_retry):
        """Handle 401 expiry/session. Returns True if retry should be attempted."""
        try:
            err = response.json().get("error")
        except Exception:
            err = None

        if err == "expired":
            # Renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf or ""},
                catch_response=True,
            ) as rr:
                if rr.status_code == 200:
                    self._update_csrf_from_response(rr)
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf or ""},
                            catch_response=True,
                        ) as rc:
                            if rc.status_code == 200:
                                self._update_csrf_from_response(rc)
                    return True
                else:
                    rr.failure(f"renew failed: {rr.status_code}")
                    return False
        elif err == "session":
            # Revoked: fresh login, recover cart
            self.login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf or ""},
                    catch_response=True,
                ) as rc:
                    if rc.status_code == 200:
                        self._update_csrf_from_response(rc)
            return True
        elif err == "denied":
            response.failure("401 denied - assertion failure")
            return False
        else:
            response.failure(f"unexpected 401: {err}")
            return False

    def _get_catalog(self):
        """Traverse catalog, return list of (product_id, variant_id, in_stock)."""
        products = []
        with self.client.get("/v2/catalog", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return products
            try:
                data = r.json()
                for p in data.get("data", {}).get("products", []):
                    for v in p.get("variants", []):
                        products.append((p["id"], v["id"], v.get("in_stock", False)))
            except Exception:
                r.failure("invalid catalog JSON")
                return products

        # Traverse pages
        next_url = "/v2/catalog/page"
        pages = 0
        while next_url and pages < 3:
            pages += 1
            with self.client.get(next_url, catch_response=True) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page status {r.status_code}")
                    break
                try:
                    data = r.json()
                    p = data.get("data", {})
                    if p:
                        pid = p.get("id")
                        for v in p.get("variants", []):
                            products.append((pid, v["id"], v.get("in_stock", False)))
                    next_url = data.get("next")
                except Exception:
                    r.failure("invalid page JSON")
                    break

        if self.reverse_catalog:
            products.reverse()
        return products

    def _get_challenge_grant(self):
        """Complete challenge to get grant_id."""
        with self.client.get("/v2/challenge-form", catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return None
            import re
            m = re.search(r'action=["\']([^"\']+)["\']', r.text)
            if not m:
                r.failure("no challenge form action")
                return None
            action = m.group(1)
            m2 = re.search(r'name=["\']challenge["\']', r.text)
            if not m2:
                r.failure("no challenge input")
                return None

        with self.client.post(
            urljoin(BASE, action),
            json={"challenge": "bench"},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure(f"challenge POST status {r.status_code}")
                return None
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 without Location")
                return None

        with self.client.get(urljoin(BASE, loc), catch_response=True) as r:
            if r.status_code != 200:
                r.failure(f"challenge GET status {r.status_code}")
                return None
            try:
                data = r.json()
                self.grant_id = data.get("grant_id")
                self._update_csrf_from_response(r)
                return self.grant_id
            except Exception:
                r.failure("invalid challenge response")
                return None

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
            self.grant_id = None  # one-time use

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                self._update_csrf_from_response(r)
                try:
                    data = r.json()
                    self.cart_id = data["id"]
                    self.cart_etag = r.headers.get("ETag")
                except Exception:
                    r.failure("invalid cart creation response")
            elif r.status_code == 401:
                if self._handle_401(r, "create_cart"):
                    # Retry once
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 201:
                            self._update_csrf_from_response(r2)
                            try:
                                data = r2.json()
                                self.cart_id = data["id"]
                                self.cart_etag = r2.headers.get("ETag")
                            except Exception:
                                r2.failure("invalid cart creation response (retry)")
                        else:
                            r2.failure(f"cart creation retry status {r2.status_code}")
            else:
                r.failure(f"cart creation status {r.status_code}")

    def _update_cart_quantity(self, quantity):
        if not self.cart_id:
            return
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers={
                "X-CSRF-Token": self.csrf or "",
                "If-Match": self.cart_etag or "",
            },
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                self._update_csrf_from_response(r)
                self.cart_etag = r.headers.get("ETag", self.cart_etag)
            elif r.status_code == 412:
                # Re-read and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True) as rg:
                    if rg.status_code == 200:
                        self.cart_etag = rg.headers.get("ETag", self.cart_etag)
                        self._update_csrf_from_response(rg)
                    else:
                        rg.failure(f"cart re-read status {rg.status_code}")
                        return
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json={"quantity": quantity},
                    headers={
                        "X-CSRF-Token": self.csrf or "",
                        "If-Match": self.cart_etag or "",
                    },
                    catch_response=True,
                ) as r2:
                    if r2.status_code == 200:
                        self._update_csrf_from_response(r2)
                        self.cart_etag = r2.headers.get("ETag", self.cart_etag)
                    else:
                        r2.failure(f"cart PATCH retry status {r2.status_code}")
            elif r.status_code == 401:
                if self._handle_401(r, "patch_cart"):
                    with self.client.patch(
                        f"/v2/carts/{self.cart_id}",
                        json={"quantity": quantity},
                        headers={
                            "X-CSRF-Token": self.csrf or "",
                            "If-Match": self.cart_etag or "",
                        },
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 200:
                            self._update_csrf_from_response(r2)
                            self.cart_etag = r2.headers.get("ETag", self.cart_etag)
                        else:
                            r2.failure(f"cart PATCH 401 retry status {r2.status_code}")
            else:
                r.failure(f"cart PATCH status {r.status_code}")

    def _create_reservation(self):
        if not self.cart_id:
            return
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf or ""},
            catch_response=True,
        ) as r:
            if r.status_code == 202:
                self._update_csrf_from_response(r)
                try:
                    status_url = r.json().get("status_url")
                except Exception:
                    r.failure("invalid reservation response")
                    return
                # Poll
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(status_url, catch_response=True) as pr:
                        if pr.status_code == 200:
                            self._update_csrf_from_response(pr)
                            try:
                                data = pr.json()
                                status = data.get("status")
                                if status == "ready":
                                    self.reservation_id = data.get("reservation_id")
                                    return
                                elif status in ("pending",):
                                    continue
                                elif status == "failed":
                                    pr.failure("reservation failed")
                                    return
                            except Exception:
                                pr.failure("invalid poll response")
                                return
                        else:
                            pr.failure(f"reservation poll status {pr.status_code}")
                            return
                r.failure("reservation polling exhausted")
            elif r.status_code == 401:
                if self._handle_401(r, "reservation"):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": self.cart_id},
                        headers={"X-CSRF-Token": self.csrf or ""},
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 202:
                            self._update_csrf_from_response(r2)
                            try:
                                status_url = r2.json().get("status_url")
                            except Exception:
                                r2.failure("invalid reservation response (retry)")
                                return
                            for _ in range(5):
                                time.sleep(0.05)
                                with self.client.get(status_url, catch_response=True) as pr:
                                    if pr.status_code == 200:
                                        self._update_csrf_from_response(pr)
                                        try:
                                            data = pr.json()
                                            status = data.get("status")
                                            if status == "ready":
                                                self.reservation_id = data.get("reservation_id")
                                                return
                                            elif status == "pending":
                                                continue
                                            elif status == "failed":
                                                pr.failure("reservation failed (retry)")
                                                return
                                        except Exception:
                                            pr.failure("invalid poll response (retry)")
                                            return
                                    else:
                                        pr.failure(f"reservation poll retry status {pr.status_code}")
                                        return
                            r2.failure("reservation polling exhausted (retry)")
                        else:
                            r2.failure(f"reservation retry status {r2.status_code}")
            else:
                r.failure(f"reservation status {r.status_code}")

    def _place_order(self):
        if not self.cart_id:
            return
        if not self.idempotency_key:
            self.idempotency_key = f"bench-{self.cart_id}-{int(time.time()*1000)}"

        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id

        headers = {
            "X-CSRF-Token": self.csrf or "",
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                self._update_csrf_from_response(r)
                try:
                    data = r.json()
                    if not data.get("accepted", False):
                        r.failure("order accepted:false")
                except Exception:
                    r.failure("invalid order response")
            elif r.status_code == 200:
                # Business failure
                r.failure("order HTTP 200 accepted:false")
            elif r.status_code == 401:
                if self._handle_401(r, "order"):
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                    ) as r2:
                        if r2.status_code == 201:
                            self._update_csrf_from_response(r2)
                            try:
                                data = r2.json()
                                if not data.get("accepted", False):
                                    r2.failure("order accepted:false (retry)")
                            except Exception:
                                r2.failure("invalid order response (retry)")
                        elif r2.status_code == 200:
                            r2.failure("order HTTP 200 accepted:false (retry)")
                        else:
                            r2.failure(f"order retry status {r2.status_code}")
            else:
                r.failure(f"order status {r.status_code}")

    def _do_work(self):
        with self.client.post("/v2/work", json={}, catch_response=True) as r:
            if r.status_code == 200:
                try:
                    data = r.json()
                    if not data.get("ok"):
                        r.failure("work ok:false")
                except Exception:
                    r.failure("invalid work response")
            elif r.status_code == 429:
                # Scheduled 429 - retry with Retry-After
                retry_after = r.headers.get("Retry-After", "1")
                try:
                    wait = float(retry_after)
                except ValueError:
                    wait = 1.0
                for attempt in range(4):
                    time.sleep(wait)
                    with self.client.post("/v2/work", json={}, catch_response=True) as r2:
                        if r2.status_code == 200:
                            try:
                                data = r2.json()
                                if not data.get("ok"):
                                    r2.failure("work ok:false (retry)")
                            except Exception:
                                r2.failure("invalid work response (retry)")
                            return
                        elif r2.status_code == 429:
                            retry_after = r2.headers.get("Retry-After", "1")
                            try:
                                wait = float(retry_after)
                            except ValueError:
                                wait = 1.0
                            continue
                        else:
                            r2.failure(f"work retry status {r2.status_code}")
                            return
                r.failure("work 429 retries exhausted")
            elif r.status_code == 500:
                r.failure("work 500 unexpected")
            else:
                r.failure(f"work status {r.status_code}")

    @task
    def shop_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        self.iterations_done += 1

        # Fresh login and cart each journey
        self.cart_id = None
        self.cart_etag = None
        self.reservation_id = None
        self.idempotency_key = None
        self.grant_id = None
        self.login()

        # Get catalog
        products = self._get_catalog()
        if not products:
            return

        # Pick first in-stock product
        chosen = None
        for pid, vid, in_stock in products:
            if in_stock:
                chosen = (pid, vid)
                break
        if not chosen:
            # Fallback to first product
            chosen = (products[0][0], products[0][1])

        # Optionally get challenge grant
        if random.random() < 0.3:
            self._get_challenge_grant()

        # Create cart
        self._create_cart(chosen[0], chosen[1])
        if not self.cart_id:
            return

        # Update quantity
        self._update_cart_quantity(random.randint(1, 20))

        # Create reservation
        self._create_reservation()

        # Place order
        self._place_order()

        # Do work
        self._do_work()


class ShopLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.users = 2
        self.spawn_rate = 2
        self.run_time = 120
        self.start_time = time.time()

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > self.run_time:
            return None
        return (self.users, self.spawn_rate)
