import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Map<String, String> SESSION_HEADERS = Map.of(
            "X-CSRF-Token", "#{csrf}",
            "Content-Type", "application/json"
    );

    private static final HttpProtocolBuilder httpProtocol =
            http.baseUrl(BASE_URL)
                    .disableAutoRedirect()
                    .acceptHeader("application/json")
                    .contentTypeHeader("application/json")
                    .userAgentHeader("gatling-perf-test");

    private static String randomUsername() {
        int idx = ThreadLocalRandom.current().nextInt(1, 17);
        return "bench-" + idx;
    }

    private static ChainBuilder getLoginForm() {
        return exec(http("GET login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("loginCsrf"))
                .check(regex("name=\"login_nonce\" value=\"([^\"]+)\"").find().saveAs("loginNonce"))
        );
    }

    private static ChainBuilder doLogin() {
        return exec(http("POST login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{loginCsrf}\"}"))
                .check(status().in(200, 302))
                .check(
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        jsonPath("$.user").optional().saveAs("user")
                )
        ).exec(session -> {
            if (session.contains("csrf") && session.getString("csrf") != null && !session.getString("csrf").isEmpty()) {
                return session;
            }
            return session.set("csrf", session.getString("loginCsrf"));
        });
    }

    private static ChainBuilder handleLoginRedirect() {
        return doIf(session -> session.contains("Location") && session.getString("Location") != null && !session.getString("Location").isEmpty())
                .then(
                        exec(session -> session.set("redirectLocation", session.getString("Location")))
                                .exec(http("GET login redirect")
                                        .get("#{redirectLocation}")
                                        .check(status().is(200))
                                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                                        .check(jsonPath("$.user").optional().saveAs("user"))
                                )
                );
    }

    private static ChainBuilder fullLogin() {
        return exec(session -> session.set("username", randomUsername()))
                .exec(getLoginForm())
                .exec(doLogin())
                .exec(handleLoginRedirect())
                .exec(session -> {
                    if (!session.contains("csrf") || session.getString("csrf") == null || session.getString("csrf").isEmpty()) {
                        return session.set("csrf", session.getString("loginCsrf"));
                    }
                    return session;
                });
    }

    private static ChainBuilder getCatalog() {
        return exec(http("GET catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
                .check(jsonPath("$.data.products[0].variants[0].in_stock").saveAs("inStock"))
        );
    }

    private static ChainBuilder getCatalogPage() {
        return exec(http("GET catalog page")
                .get("/v2/catalog/page")
                .check(status().is(200))
                .check(jsonPath("$.product.id").optional().saveAs("pageProductId"))
                .check(jsonPath("$.product.variants[0].id").optional().saveAs("pageVariantId"))
                .check(jsonPath("$.product.variants[0].in_stock").optional().saveAs("pageInStock"))
                .check(jsonPath("$.next").optional().saveAs("nextPage"))
        ).exec(session -> {
            if (session.contains("pageProductId") && session.getString("pageProductId") != null) {
                return session.set("productId", session.getString("pageProductId"))
                        .set("variantId", session.getString("pageVariantId"))
                        .set("inStock", session.getString("pageInStock"));
            }
            return session;
        });
    }

    private static ChainBuilder createCart() {
        return exec(http("POST create cart")
                .post("/v2/carts")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
                .check(status().is(201))
                .check(jsonPath("$.id").saveAs("cartId"))
                .check(jsonPath("$.csrf").optional().saveAs("cartCsrf"))
                .check(header("ETag").optional().saveAs("cartEtag"))
