package default;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Map<String, String> OWNER_SEEDS = new LinkedHashMap<>();

    private static final FeederBuilder<String> USER_FEEDER = list(
            Map.of("username", "bench-1", "password", "bench"),
            Map.of("username", "bench-2", "password", "bench")
    ).circular();

    private static String freshOwnerSeed(String username) {
        String seed = "owner-" + username + "-" + UUID.randomUUID().toString().substring(0, 8);
        OWNER_SEEDS.put(username, seed);
        return seed;
    }

    private static final ChainBuilder login = exec(
            http("GET login form")
                    .get("/v2/login-form")
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs("login_csrf"))
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs("csrf"))
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs("current_csrf"))
    ).exec(
            http("POST login")
                    .post("/v2/login")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{login_csrf}")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{login_csrf}\"}"))
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").saveAs("csrf"))
                    .check(jsonPath("$.csrf").saveAs("current_csrf"))
    );

    private static final ChainBuilder createCart = exec(
            http("GET catalog")
                    .get("/v2/catalog")
                    .header("X-CSRF-Token", "#{current_csrf}")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").saveAs("product_id"))
                    .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variant_id"))
    ).exec(session -> {
        String ownerSeed = freshOwnerSeed(session.getString("username"));
        return session.set("owner_seed", ownerSeed);
    }).exec(
            http("POST create cart")
                    .post("/v2/carts")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{current_csrf}")
                    .body(StringBody("{\"product_id\":\"#{product_id}\",\"variant_id\":\"#{variant_id}\",\"grant_id\":\"#{owner_seed}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("cart_id"))
                    .check(jsonPath("$.csrf").optional().saveAs("cart_csrf"))
    ).exec(session -> {
        String cartCsrf = session.getString("cart_csrf");
        if (cartCsrf != null && !cartCsrf.isEmpty()) {
            return session.set("current_csrf", cartCsrf).set("csrf", cartCsrf);
        }
        return session;
    });

    private static final ChainBuilder createReservation = exec(
            http("POST create reservation")
                    .post("/v2/reservations")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{current_csrf}")
                    .body(StringBody("{\"cart_id\":\"#{cart_id}\"}"))
                    .check(status().is(202))
                    .check(jsonPath("$.status_url").saveAs("status_url"))
                    .check(jsonPath("$.csrf").optional().saveAs("reservation_csrf"))
    ).exec(session -> {
        String resCsrf = session.getString("reservation_csrf");
        if (resCsrf != null && !resCsrf.isEmpty()) {
            return session.set("current_csrf", resCsrf).set("csrf", resCsrf);
        }
        return session;
    });

    private static final ChainBuilder pollReservation = exec(session -> {
        String statusUrl = session.getString("status_url");
        String base = BASE_URL;
        if (statusUrl.startsWith("http://") || statusUrl.startsWith("https://")) {
            base = "";
        }
        return session.set("full_status_url", base + statusUrl);
    }).exec(
            http("GET reservation status")
                    .get("#{full_status_url}")
                    .header("X-CSRF-Token", "#{current_csrf}")
                    .check(status().is(200))
                    .check(jsonPath("$.status").saveAs("reservation_status"))
                    .check(jsonPath("$.reservation_id").optional().saveAs("reservation_id"))
    );

    private static final ChainBuilder checkout = exec(
            http("POST create order")
                    .post("/v2/orders")
                    .header("Content-Type", "application/json")
                    .header("X-CSRF-Token", "#{current_csrf}")
                    .header("Idempotency-Key", "idem-#{cart_id}")
                    .body(StringBody("{\"cart_id\":\"#{cart_id}\",\"reservation_id\":\"#{reservation_id}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is("true"))
                    .check(jsonPath("$.id").saveAs("order_id"))
                    .check(jsonPath("$.csrf").optional().saveAs("order_csrf"))
    ).exec(session -> {
        String orderCsrf = session.getString("order_csrf");
        if (orderCsrf != null && !orderCsrf.isEmpty()) {
            return session.set("current_csrf", orderCsrf).set("csrf", orderCsrf);
        }
        return session;
    });

    private static final ChainBuilder journeyProfile1 = exec(login)
            .exec(createCart)
            .exec(createReservation)
            .exec(pollReservation)
            .pause(Duration.ofMillis(20))
            .exec(pollReservation)
            .exec(session -> {
                String status = session.getString("reservation_status");
                String reservationId = session.getString("reservation_id");
                if ("ready".equals(status) && reservationId != null && !reservationId.isEmpty()) {
                    return session.set("ready_to_checkout", true);
                }
                return session.set("ready_to_checkout", false);
            })
            .doIfEquals(session -> session.getBoolean("ready_to_checkout"), true).then(
                    checkout
            );

    private static final ChainBuilder journeyProfile2 = exec(login)
            .exec(createCart)
            .exec(createReservation)
            .exec(pollReservation)
            .pause(Duration.ofMillis(20))
            .exec(pollReservation)
            .pause(Duration.ofMillis(20))
            .exec(pollReservation)
            .exec(session -> {
                String status = session.getString("reservation_status");
                String reservationId = session.getString("reservation_id");
                if ("ready".equals(status) && reservationId != null && !reservationId.isEmpty()) {
                    return session.set("ready_to_checkout", true);
                }
                return session.set("ready_to_checkout", false);
            })
            .doIfEquals(session -> session.getBoolean("ready_to_checkout"), true).then(
                    checkout
            );

    private static final ChainBuilder journeyNegativeControl = exec(login)
            .exec(createCart)
            .exec(createReservation)
            .exec(pollReservation)
            .pause(Duration.ofMillis(20))
            .exec(pollReservation)
            .exec(session -> {
                String status = session.getString("reservation_status");
                String reservationId = session.getString("reservation_id");
                if ("ready".equals(status) && reservationId != null && !reservationId.isEmpty()) {
                    return session.set("ready_to_checkout", true);
                }
                return session.set("ready_to_checkout", false);
            })
            .doIfEquals(session -> session.getBoolean("ready_to_checkout"), true).then(
                    checkout
            );

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench");

    {
        setUp(
                scenario("reservation-journey-profile1")
                        .feed(USER_FEEDER)
                        .exec(journeyProfile1)
                        .injectOpen(atOnceUsers(1)),
                scenario("reservation-journey-profile2")
                        .feed(USER_FEEDER)
                        .exec(journeyProfile2)
                        .injectOpen(atOnceUsers(1)),
                scenario("reservation-journey-negative-control")
                        .feed(USER_FEEDER)
                        .exec(journeyNegativeControl)
                        .injectOpen(atOnceUsers(0))
        ).protocols(httpProtocol);
    }
}

