def extract_csrf(html):
    import re
    m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)', html)
    if not m:
        m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf', html)
    if not m:
        m = re.search(r'name=["\']csrf["\'][^>]*>', html)
        if m:
            # try to find value in same tag
            tag = html[m.start():m.start()+200]
            vm = re.search(r'value=["\']([^"\']+)', tag)
            if vm:
                return vm.group(1)
    return m.group(1) if m else None


def extract_etag(headers):
    return headers.get("ETag") or headers.get("etag")


class ShopUser(HttpUser):
    wait_time = between(0.01, 0.05)
    abstract = True

    def on_start(self):
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.profile = None
        self.negative = None
        self.iterations_done = 0
        self.job_polls_used = 0
        self.last_poll_time = 0.0
        self.reservation_id = None
        self.order_placed = False
        self.idempotency_key = None

    def _fresh_login(self):
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                        r = r2
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            self.csrf = extract_csrf(r.text)
            if not self.csrf:
                r.failure("no csrf in login form")
                return False
        with self.client.post("/v2/login", json={"username": "bench", "password": "bench", "csrf": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location")
                if loc:
                    with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                        r = r2
            if r.status_code != 200:
                r.failure(f"login status {r.status_code}")
                return False
            data = r.json()
            if "csrf" in data:
                self.csrf = data["csrf"]
            if "user" not in data:
                r.failure("no user in login response")
                return False
        return True

    def _renew_session(self):
        with self.client.post("/v2/session/renew", json={}, headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                data = r.json()
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            r.failure(f"renew status {r.status_code}")
            return False

    def _recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(f"/v2/carts/{self.cart_id}/recover", json={},
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                data = r.json()
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            r.failure(f"recover status {r.status_code}")
            return False

    def _handle_401(self, response, operation_label):
        if response.status_code != 401:
            return False
        try:
            err = response.json().get("error", "")
        except Exception:
            err = ""
        if err == "expired":
            if self._renew_session():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        elif err == "session":
            if self._fresh_login():
                if self.cart_id:
                    self._recover_cart()
                return True
            return False
        else:
            response.failure(f"401 denied on {operation_label}")
            return False

    def _create_cart(self):
        # get catalog
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return False
            data = r.json()
            products = data.get("data", {}).get("products", [])
            if not products:
                r.failure("no products in catalog")
                return False
            product = products[0]
            variants = product.get("variants", [])
            if not variants:
                r.failure("no variants in product")
                return False
            variant = variants[0]
            product_id = product["id"]
            variant_id = variant["id"]

        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "cart create"):
                    with self.client.post("/v2/carts", json=payload,
                                          headers={"X-CSRF-Token": self.csrf},
                                          catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return False
            data = r.json()
            self.cart_id = data.get("id")
            if not self.cart_id:
                r.failure("no cart id")
                return False
            if "csrf" in data:
                self.csrf = data["csrf"]
            self.cart_etag = extract_etag(r.headers)
            self.idempotency_key = f"idem-{self.cart_id}-{random.randint(100000,999999)}"
        return True

    def _patch_cart_quantity(self, quantity):
        if not self.cart_id:
            return False
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(f"/v2/carts/{self.cart_id}", json={"quantity": quantity},
                               headers=headers, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "cart patch"):
                    headers = {"X-CSRF-Token": self.csrf}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.patch(f"/v2/carts/{self.cart_id}", json={"quantity": quantity},
                                           headers=headers, catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code == 412:
                # re-read and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True, allow_redirects=False) as rg:
                    if rg.status_code == 200:
                        self.cart_etag = extract_etag(rg.headers)
                        if "csrf" in rg.json():
                            self.csrf = rg.json()["csrf"]
                    else:
                        rg.failure(f"cart re-read status {rg.status_code}")
                        return False
                headers = {"X-CSRF-Token": self.csrf}
                if self.cart_etag:
                    headers["If-Match"] = self.cart_etag
                with self.client.patch(f"/v2/carts/{self.cart_id}", json={"quantity": quantity},
                                       headers=headers, catch_response=True, allow_redirects=False) as r2:
                    r = r2
            if r.status_code != 200:
                r.failure(f"cart patch status {r.status_code}")
                return False
            data = r.json()
            if "csrf" in data:
                self.csrf = data["csrf"]
            self.cart_etag = extract_etag(r.headers)
        return True

    def _get_challenge_grant(self):
        with self.client.get("/v2/challenge-form", catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            html = r.text
            import re
            m = re.search(r'action=["\']([^"\']*challenges/[^"\']+)', html)
            if not m:
                r.failure("no challenge action")
                return False
            action = m.group(1)
            if action.startswith("/"):
                action = action
            else:
                action = "/" + action
            cm = re.search(r'name=["\']challenge["\']', html)
            if not cm:
                r.failure("no challenge input")
                return False
        with self.client.post(action, json={"challenge": "bench"},
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "challenge post"):
                    with self.client.post(action, json={"challenge": "bench"},
                                          headers={"X-CSRF-Token": self.csrf},
                                          catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 302:
                r.failure(f"challenge post status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                r.failure("no location after challenge")
                return False
        with self.client.get(loc, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "challenge get"):
                    with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 200:
                r.failure(f"challenge get status {r.status_code}")
                return False
            data = r.json()
            if "grant_id" not in data:
                r.failure("no grant_id in challenge response")
                return False
            self.grant_id = data["grant_id"]
            if "csrf" in data:
                self.csrf = data["csrf"]
        return True

    def _create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "reservation create"):
                    with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                                          headers={"X-CSRF-Token": self.csrf},
                                          catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 202:
                r.failure(f"reservation create status {r.status_code}")
                return False
            data = r.json()
            status_url = data.get("status_url")
            if not status_url:
                r.failure("no status_url in reservation response")
                return False
            if "csrf" in data:
                self.csrf = data["csrf"]
            self.status_url = status_url
        return True

    def _poll_reservation(self):
        if not hasattr(self, "status_url"):
            return False
        max_polls = self.profile.get("job_polls", 2)
        interval = self.profile.get("poll_interval", 0.02)
        if self.job_polls_used >= max_polls:
            return False
        now = time.monotonic()
        if self.job_polls_used > 0 and (now - self.last_poll_time) < interval:
            time.sleep(interval - (now - self.last_poll_time))
        self.job_polls_used += 1
        self.last_poll_time = time.monotonic()
        with self.client.get(self.status_url, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "reservation poll"):
                    with self.client.get(self.status_url, catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code != 200:
                r.failure(f"reservation poll status {r.status_code}")
                return False
            data = r.json()
            status = data.get("status")
            if status == "ready":
                self.reservation_id = data.get("reservation_id")
                if not self.reservation_id:
                    r.failure("ready but no reservation_id")
                    return False
                if "csrf" in data:
                    self.csrf = data["csrf"]
                return True
            elif status in ("pending", "failed"):
                if status == "failed":
                    r.failure("reservation failed")
                return False
            else:
                r.failure(f"unknown reservation status {status}")
                return False

    def _place_order(self):
        if not self.cart_id or not self.reservation_id:
            return False
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": self.idempotency_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        payload = {"cart_id": self.cart_id, "reservation_id": self.reservation_id}
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as r:
            if r.status_code == 401:
                if self._handle_401(r, "order create"):
                    headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": self.idempotency_key}
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.post("/v2/orders", json=payload, headers=headers,
                                          catch_response=True, allow_redirects=False) as r2:
                        r = r2
                else:
                    return False
            if r.status_code == 201:
                data = r.json()
                if data.get("accepted") is True:
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                    self.order_placed = True
                    return True
                else:
                    r.failure("order accepted:false")
                    return False
            elif r.status_code == 200:
                data = r.json()
                if data.get("accepted") is False:
                    r.failure("order accepted:false (200)")
                    return False
                else:
                    r.failure(f"unexpected 200 accepted {data}")
                    return False
            else:
                r.failure(f"order create status {r.status_code}")
                return False

    def _do_work(self):
        with self.client.post("/v2/work", json={}, catch_response=True, allow_redirects=False) as r:
            if r.status_code == 200:
                data = r.json()
                if data.get("ok") is True:
                    return True
                r.failure("work ok not true")
                return False
            elif r.status_code == 429:
                retry_after = r.headers.get("Retry-After")
                try:
                    delay = float(retry_after) if retry_after else 1.0
                except Exception:
                    delay = 1.0
                for attempt in range(4):
                    time.sleep(delay)
                    with self.client.post("/v2/work", json={}, catch_response=True, allow_redirects=False) as r2:
                        if r2.status_code == 200:
                            data = r2.json()
                            if data.get("ok") is True:
                                return True
                            r2.failure("work ok not true on retry")
                            return False
                        elif r2.status_code == 429:
                            retry_after2 = r2.headers.get("Retry-After")
                            try:
                                delay = float(retry_after2) if retry_after2 else 1.0
                            except Exception:
                                delay = 1.0
                            continue
                        else:
                            r2.failure(f"work retry status {r2.status_code}")
                            return False
                r.failure("work 429 retries exhausted")
                return False
            else:
                r.failure(f"work status {r.status_code}")
                return False

    def _journey(self):
        if not self._fresh_login():
            return
        # optionally get challenge grant
        if self.profile.get("html_layout") == 1:
            self._get_challenge_grant()
        if not self._create_cart():
            return
        if not self._patch_cart_quantity(1):
            return
        if not self._create_reservation():
            return
        # poll up to profile job_polls
        ready = False
        for _ in range(self.profile.get("job_polls", 2)):
            if self._poll_reservation():
                ready = True
                break
            if self.job_polls_used >= self.profile.get("job_polls", 2):
                break
        if self.negative and self.negative.get("job_fails"):
            # negative control: job should fail; if ready, that's a failure
            if ready:
                # mark failure on the last poll response? We need to fail an assertion.
                # We'll fail the order attempt or mark a failure.
                # Since we can't easily mark a previous response, we'll do a work call and fail it.
                with self.client.post("/v2/work", json={}, catch_response=True, allow_redirects=False) as r:
                    r.failure("negative control: job unexpectedly ready")
                return
            else:
                # expected failure, do a work call to mark success
                self._do_work()
                return
        if not ready:
            # pending/failed job must never reach checkout; do a work call as success
            self._do_work()
            return
        # ready reservation consumed by correct checkout
        if not self._place_order():
            return
        # optional work after order
        self._do_work()

    @task
    def run_iteration(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()
        self.iterations_done += 1
        self._journey()


