class TestShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.monotonic()
        self.total_users = USERS
        self.current_users = 0
        self.started = False

    def tick(self):
        if not self.started:
            self.started = True
            self.current_users = self.total_users
            return (self.current_users, self.total_users)
        # check if all users have finished their iterations
        # We can't easily know from shape; rely on StopUser to stop users.
        # Return None when we've been running long enough? The harness stops when tick returns None.
        # We'll return None after a reasonable time or when all users stopped.
        # Since we can't track user completion easily, we'll return None after a timeout.
        # But the harness may expect tick to return None to stop.
        # We'll return None after 60 seconds or when user count drops to 0.
        # We can check runner.user_count if available.
        runner = self.runner
        if runner is not None:
            if runner.user_count == 0:
                return None
        if time.monotonic() - self.start_time > 120:
            return None
        return (self.current_users, self.total_users)
