            .get(session -> session.getString("statusUrl"))
            .check(status().is(200))
            .check(jsonPath("$.status").saveAs("reservationStatus"))
            .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
            .check(jsonPath("$.csrf").optional().saveAs("csrfToken"))
    );

    private static final ChainBuilder pollReservationLoop = asLongAs(session -> {
        String status = session.getString("reservationStatus");
        return (status == null || (!status.equals("ready") && !status.equals("failed"))) && session.getInt("pollCount") < 5;
    }).on(
        pause(Duration.ofMillis(60))
            .exec(session -> session.set("pollCount", session.getInt("pollCount") + 1))
            .exec(pollReservation)
    );

    private static final ChainBuilder createOrder = exec(
        http("POST /v2/orders")
            .post("/v2/orders")
            .header("X-CSRF-Token", session -> session.getString("csrfToken"))
            .header("Idempotency-Key", session -> "order-" + session.getString("cartId"))
            .header("If-Match", session -> session.getString("cartEtag"))
            .body(StringBody(session -> {
                String cartId = session.getString("cartId");
                String reservationId = session.getString("reservationId");
                if (reservationId != null && !reservationId.isEmpty()) {
                    return String.format("{\"cart_id\":\"%s\",\"reservation_id\":\"%s\"}", cartId, reservationId);
