            .check(jsonPath("$.accepted").is("true"))
            .check(jsonPath("$.id").saveAs("orderId"))
            .check(jsonPath("$.csrf").optional().saveAs("csrfToken"))
    );

    private static final ChainBuilder doWork = exec(
