            .post("/v2/work")
            .header("X-CSRF-Token", session -> session.getString("csrfToken"))
            .body(StringBody("{}"))
            .check(status().in(200, 429))
            .check(jsonPath("$.ok").optional().is("true"))
    );

    private static final ChainBuilder retryWork429 = asLongAs(session -> session.getInt("workRetryCount") < 4 && session.getInt("workStatus") == 429).on(
        pause(Duration.ofSeconds(1))
            .exec(session -> session.set("workRetryCount", session.getInt("workRetryCount") + 1))
            .exec(
                http("POST /v2/work retry")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                    .body(StringBody("{}"))
                    .check(status().in(200, 429))
                    .check(jsonPath("$.ok").optional().is("true"))
            )
    );

    private static final ChainBuilder journey = exec(
        session -> session.set("pollCount", 0).set("workRetryCount", 0).set("patchStatus", 0)
    )
        .exec(getLoginForm)
        .exec(doLogin)
        .exec(followLoginRedirect)
        .exec(getChallengeForm)
        .exec(postChallenge)
        .exec(followChallengeRedirect)
        .exec(getCatalog)
        .exec(createCart)
        .exec(getCart)
        .exec(
            http("PATCH /v2/carts/{cartId} initial")
                .patch("/v2/carts/#{cartId}")
                .header("X-CSRF-Token", session -> session.getString("csrfToken"))
                .header("If-Match", session -> session.getString("cartEtag"))
                .body(StringBody("{\"quantity\":2}"))
                .check(status().saveAs("patchStatus"))
                .check(jsonPath("$.csrf").optional().saveAs("csrfToken"))
                .check(header("ETag").optional().saveAs("cartEtag"))
        )
        .exec(retryPatchCart)
        .exec(createReservation)
        .exec(pollReservationLoop)
        .doIf(session -> "ready".equals(session.getString("reservationStatus"))).then(
            exec(createOrder)
        )
        .exec(doWork)
        .exec(retryWork429);

    private static final ScenarioBuilder userScenario = scenario("UserJourney")
        .exec(journey);

    {
        setUp(
            userScenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
