function extractCsrfFromHtml(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function extractChallengeAction(html) {
  const formMatch = html.match(/<form[^>]*action=["']([^"']*\/challenges\/[^"']+)["'][^>]*>/i);
  if (formMatch) return formMatch[1];
  const actionMatch = html.match(/action=["']([^"']*\/challenges\/[^"']+)["']/i);
  return actionMatch ? actionMatch[1] : null;
}

function extractChallengeInputName(html) {
  const match = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  if (match) {
    const valMatch = match[0].match(/value=["']([^"']*)["']/i);
    return valMatch ? valMatch[1] : '';
  }
  return '';
}

function extractLocationFromHeaders(headers) {
  const loc = headers['Location'] || headers['location'];
  return loc || null;
}

function getSessionCookie(jar) {
  const cookies = jar.cookiesForURL(BASE_URL);
  for (const name in cookies) {
    if (name.toLowerCase().includes('session')) return cookies[name];
  }
  return null;
}

function getCsrfFromResponse(res) {
  if (res.body && typeof res.body === 'string') {
    const json = tryParseJson(res.body);
    if (json && json.csrf) return json.csrf;
  }
  return null;
}

function tryParseJson(str) {
  try { return JSON.parse(str); } catch (e) { return null; }
}

function getGrantIdFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.grant_id) return json.grant_id;
  return null;
}

function getReservationIdFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.reservation_id) return json.reservation_id;
  return null;
}

function getStatusUrlFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.status_url) return json.status_url;
  return null;
}

function getCartIdFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.id) return json.id;
  return null;
}

function getEtagFromResponse(res) {
  return res.headers['ETag'] || res.headers['etag'] || null;
}

function getNextFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.next !== undefined) return json.next;
  return null;
}

function getProductsFromResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.data && json.data.products) return json.data.products;
  return [];
}

function getProductFromPageResponse(res) {
  const json = tryParseJson(res.body);
  if (json && json.data && json.data.product) return json.data.product;
  return null;
}

function getVariantsFromProduct(product) {
  if (product && product.variants) return product.variants;
  return [];
}

function getFirstInStockVariant(product) {
  const variants = getVariantsFromProduct(product);
  for (const v of variants) {
    if (v.in_stock) return v;
  }
  return null;
}

function getProductId(product) {
  return product ? product.id : null;
}

function getVariantId(variant) {
  return variant ? variant.id : null;
}

function getErrorMessage(res) {
  const json = tryParseJson(res.body);
  if (json && json.error) return json.error;
  return null;
