function isSessionError(res) {
  return res.status === 401 && getErrorMessage(res) === 'session';
}

function isDeniedError(res) {
  return res.status === 401 && getErrorMessage(res) === 'denied';
}

function isScheduled429(res) {
  return res.status === 429;
}

function isUnexpected500(res) {
  return res.status === 500;
}

function isBusinessSuccess(res) {
  return res.status >= 200 && res.status < 300;
}

function isAcceptedOrder(res) {
  if (res.status !== 201 && res.status !== 200) return false;
  const json = tryParseJson(res.body);
  return json && json.accepted === true;
}

function isBusinessFailure(res) {
  return res.status === 200 && res.body && tryParseJson(res.body) && tryParseJson(res.body).accepted === false;
}

function recordWorkResponse(res) {
  workResponses.add(1);
  if (isUnexpected500(res) || (res.status >= 400 && !isScheduled429(res) && !isExpiredError(res) && !isSessionError(res) && !isDeniedError(res))) {
    businessFailureRate.add(1);
  }
}

function doWorkWithRetry(csrf, maxRetries = 4) {
  let retries = 0;
  let res;
  while (retries <= maxRetries) {
    res = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
    });
    recordWorkResponse(res);
    if (isScheduled429(res)) {
      const retryAfter = res.headers['Retry-After'];
      const waitSec = retryAfter ? parseInt(retryAfter) : 1;
      sleep(waitSec);
      retries++;
      continue;
    }
    if (isUnexpected500(res)) {
      retries++;
      sleep(0.5);
      continue;
    }
    break;
  }
  return res;
}

function doBrowseWithRetry(csrf, maxRetries = 4) {
  let retries = 0;
  let res;
  while (retries <= maxRetries) {
    res = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
    });
    recordWorkResponse(res);
    if (isScheduled429(res)) {
      const retryAfter = res.headers['Retry-After'];
      const waitSec = retryAfter ? parseInt(retryAfter) : 1;
      sleep(waitSec);
      retries++;
      continue;
    }
    if (isUnexpected500(res)) {
      retries++;
      sleep(0.5);
      continue;
    }
    break;
  }
  return res;
}

function renewSession(csrf) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
