  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  check(formRes, { 'login form loads': (r) => r.status === 200 }) || fail('login form failed');

  const csrf = extractCsrfFromHtml(formRes.body);
  check(csrf, { 'csrf extracted from login form': (c) => c !== null && c !== undefined && c !== '' }) || fail('no csrf in login form');

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: 'bench',
    password: 'bench',
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0
  });

  let loginCsrf = csrf;
  let sessionCookie = getSessionCookie(jar);

  if (loginRes.status === 302) {
    const loc = extractLocationFromHeaders(loginRes.headers);
    if (loc) {
      const locRes = http.get(new URL(loc, BASE_URL).toString(), { redirects: 0 });
      const locCsrf = getCsrfFromResponse(locRes);
      if (locCsrf) loginCsrf = locCsrf;
