function handleExpiredSession(state, operationFn) {
  // state: { csrf, cartId, etag, ... }
  const renewRes = renewSession(state.csrf);
  let newCsrf = renewRes.newCsrf || state.csrf;
  if (renewRes.res.status === 200 || renewRes.res.status === 201) {
    if (state.cartId) {
      const recoverRes = recoverCart(state.cartId, newCsrf);
      newCsrf = recoverRes.newCsrf || newCsrf;
    }
    const retryRes = operationFn(newCsrf);
    return { res: retryRes, csrf: newCsrf, recovered: true };
  }
  return { res: renewRes.res, csrf: newCsrf, recovered: false };
