function handleSessionRevoked(state, operationFn) {
  // Get fresh form/login, recover cart
  const fresh = freshLogin();
  let newCsrf = fresh.csrf;
  if (state.cartId) {
    const recoverRes = recoverCart(state.cartId, newCsrf);
    newCsrf = recoverRes.newCsrf || newCsrf;
  }
  const retryRes = operationFn(newCsrf);
  return { res: retryRes, csrf: newCsrf, recovered: true };
