    const err = getErrorMessage(res);
    if (err === 'expired') {
      const result = handleExpiredSession(state, (newCsrf) => operationFn(newCsrf));
      return { res: result.res, csrf: result.csrf, handled: true, type: 'expired' };
    } else if (err === 'session') {
      const result = handleSessionRevoked(state, (newCsrf) => operationFn(newCsrf));
      return { res: result.res, csrf: result.csrf, handled: true, type: 'session' };
