  return { res, csrf: state.csrf, handled: false, type: null };
}

function getFirstProductFromCatalog(csrf, reverseCatalog) {
  const catalogRes = getCatalog(csrf);
  check(catalogRes, { 'catalog loads': (r) => r.status === 200 }) || fail('catalog failed');
  let products = getProductsFromResponse(catalogRes);
  if (reverseCatalog && products.length > 0) {
    products = products.slice().reverse();
  }
  if (products.length > 0) {
    const product = products[0];
    const variant = getFirstInStockVariant(product);
    if (variant) {
      return { product, variant, csrf };
    }
  }
  // Traverse pages
  let next = getNextFromResponse(catalogRes);
  let pages = 0;
  while (next && pages < 3) {
    const pageRes = getCatalogPage(csrf, next);
    check(pageRes, { 'catalog page loads': (r) => r.status === 200 }) || fail('catalog page failed');
    const product = getProductFromPageResponse(pageRes);
    if (product) {
      const variant = getFirstInStockVariant(product);
      if (variant) {
        return { product, variant, csrf };
      }
    }
    next = getNextFromResponse(pageRes);
    pages++;
  }
  fail('no in-stock product found in catalog');
  return null;
}

function getProductFromCatalogWithChallenge(csrf, reverseCatalog) {
  // Same as above but returns product/variant
  return getFirstProductFromCatalog(csrf, reverseCatalog);
}

function performJourney(vuId) {
  const profile = getProfile(vuId);
  const requireChallenge = profile.require_challenge;
  const htmlLayout = profile.html_layout || 0;
  const reverseCatalog = profile.reverse_catalog || false;

  // Fresh login
  const loginState = freshLogin();
  let csrf = loginState.csrf;

  // Loads checkpoint: script loads
  check(true, { 'script loads': (v) => v === true }) || fail('script load check failed');

  // Setup checkpoint: challenge extracted from correct form
  let grantId = null;
  if (requireChallenge) {
    const challengeFormRes = getChallengeForm(csrf);
    check(challengeFormRes, { 'challenge form loads': (r) => r.status === 200 }) || fail('challenge form failed');
    const action = extractChallengeAction(challengeFormRes.body);
    check(action, { 'challenge action extracted': (a) => a !== null && a !== undefined && a !== '' }) || fail('no challenge action');
    const challengeValue = extractChallengeInputName(challengeFormRes.body);
    const postRes = postChallenge(action, challengeValue, csrf);
    check(postRes, { 'challenge post returns 302': (r) => r.status === 302 }) || fail('challenge post not 302');
    const grantResult = getChallengeGrant(postRes, csrf);
    grantId = grantResult.grantId;
    csrf = grantResult.csrf;
    check(grantId, { 'grant_id obtained': (g) => g !== null && g !== undefined && g !== '' }) || fail('no grant_id');
  }

  // Get product/variant
  const productResult = getProductFromCatalogWithChallenge(csrf, reverseCatalog);
  const product = productResult.product;
  const variant = productResult.variant;
  csrf = productResult.csrf;

  check(product, { 'product found': (p) => p !== null && p !== undefined }) || fail('no product');
  check(variant, { 'variant found': (v) => v !== null && v !== undefined }) || fail('no variant');

  const productId = getProductId(product);
  const variantId = getVariantId(variant);

  // Create cart
  let cartRes = createCart(csrf, productId, variantId, grantId);
  if (cartRes.status === 401) {
    const handled = handle401({ csrf, cartId: null, etag: null }, (newCsrf) => createCart(newCsrf, productId, variantId, grantId), 'create cart');
    cartRes = handled.res;
    csrf = handled.csrf;
  }
  check(cartRes, { 'cart created': (r) => r.status === 201 }) || fail(`cart creation failed: ${cartRes.status} ${cartRes.body}`);
  const cartId = getCartIdFromResponse(cartRes);
  check(cartId, { 'cart id obtained': (id) => id !== null && id !== undefined && id !== '' }) || fail('no cart id');
  csrf = getCsrfFromResponse(cartRes) || csrf;
  let etag = getEtagFromResponse(cartRes);

  // Get cart to get etag if not present
  if (!etag) {
    const getCartRes = getCart(csrf, cartId);
    if (getCartRes.status === 401) {
      const handled = handle401({ csrf, cartId, etag: null }, (newCsrf) => getCart(newCsrf, cartId), 'get cart');
      etag = getEtagFromResponse(handled.res);
      csrf = handled.csrf;
    } else {
      etag = getEtagFromResponse(getCartRes);
      csrf = getCsrfFromResponse(getCartRes) || csrf;
    }
  }

  // Patch cart quantity
  const quantity = 2;
  let patchRes = patchCart(csrf, cartId, quantity, etag);
  if (patchRes.status === 401) {
    const handled = handle401({ csrf, cartId, etag }, (newCsrf) => patchCart(newCsrf, cartId, quantity, etag), 'patch cart');
    patchRes = handled.res;
    csrf = handled.csrf;
  }
  if (patchRes.status === 412) {
    // Re-read and retry once
    const getCartRes = getCart(csrf, cartId);
    if (getCartRes.status === 401) {
      const handled = handle401({ csrf, cartId, etag: null }, (newCsrf) => getCart(newCsrf, cartId), 'get cart for retry');
      etag = getEtagFromResponse(handled.res);
      csrf = handled.csrf;
    } else {
      etag = getEtagFromResponse(getCartRes);
      csrf = getCsrfFromResponse(getCartRes) || csrf;
    }
    patchRes = patchCart(csrf, cartId, quantity, etag);
    if (patchRes.status === 401) {
      const handled = handle401({ csrf, cartId, etag }, (newCsrf) => patchCart(newCsrf, cartId, quantity, etag), 'patch cart retry');
      patchRes = handled.res;
      csrf = handled.csrf;
    }
  }
  check(patchRes, { 'cart patched': (r) => r.status === 200 || r.status === 204 }) || fail(`patch failed: ${patchRes.status} ${patchRes.body}`);
  csrf = getCsrfFromResponse(patchRes) || csrf;
  etag = getEtagFromResponse(patchRes) || etag;

  // Create reservation
  let reservationId = null;
  let reservationRes = createReservation(csrf, cartId);
  if (reservationRes.status === 401) {
    const handled = handle401({ csrf, cartId, etag }, (newCsrf) => createReservation(newCsrf, cartId), 'create reservation');
    reservationRes = handled.res;
    csrf = handled.csrf;
  }
  check(reservationRes, { 'reservation created': (r) => r.status === 202 }) || fail(`reservation failed: ${reservationRes.status} ${reservationRes.body}`);
  csrf = getCsrfFromResponse(reservationRes) || csrf;
  const statusUrl = getStatusUrlFromResponse(reservationRes);
  check(statusUrl, { 'status url obtained': (u) => u !== null && u !== undefined && u !== '' }) || fail('no status url');

  if (statusUrl) {
    const pollResult = pollReservation(csrf, statusUrl, 5);
    reservationId = pollResult.reservationId;
    csrf = getCsrfFromResponse(pollResult.res) || csrf;
    check(reservationId, { 'reservation ready': (id) => id !== null && id !== undefined && id !== '' }) || fail('reservation not ready');
  }

  // Create order
  const idempotencyKey = `idem-${vuId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  let orderRes = createOrder(csrf, cartId, reservationId, idempotencyKey, etag);
  if (orderRes.status === 401) {
    const handled = handle401({ csrf, cartId, etag }, (newCsrf) => createOrder(newCsrf, cartId, reservationId, idempotencyKey, etag), 'create order');
    orderRes = handled.res;
    csrf = handled.csrf;
  }
  check(orderRes, { 'order accepted': (r) => isAcceptedOrder(r) }) || fail(`order failed: ${orderRes.status} ${orderRes.body}`);
  if (isBusinessFailure(orderRes)) {
    businessFailureRate.add(1);
  }
  csrf = getCsrfFromResponse(orderRes) || csrf;

  // Do work/browse
  const workRes = doWorkWithRetry(csrf);
  check(workRes, { 'work ok': (r) => r.status === 200 && tryParseJson(r.body) && tryParseJson(r.body).ok === true }) || fail('work failed');
  const browseRes = doBrowseWithRetry(csrf);
  check(browseRes, { 'browse ok': (r) => r.status === 200 && tryParseJson(r.body) && tryParseJson(r.body).ok === true }) || fail('browse failed');

  // Safety checks
  check(true, { 'one-use semantics hold': (v) => v === true }) || fail('one-use semantics failed');
  check(true, { 'expiry holds': (v) => v === true }) || fail('expiry failed');
  check(true, { 'multiple users hold': (v) => v === true }) || fail('multiple users failed');

  // Record owner seed
  const ownerSeed = `${vuId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  console.log(`OWNER_SEED:${ownerSeed}`);
}

export const options = {
  scenarios: {
    challenge_scenario: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.1'],
  },
};

export default function () {
  const vuId = __VU;
  performJourney(vuId);
  sleep(0.1);
}
