import os
import time
import random
from locust import HttpUser, task, between, LoadTestShape, StopUser
from locust.exception import StopUser


BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ChallengeUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def on_start(self):
        self.username = "bench"
        self.password = "bench"
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iterations_done = 0
        self.require_challenge = True
        self.html_layout = 0
        self.reverse_catalog = False
        self.login()

    def login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return
            # Extract csrf from input[name=csrf]
            import re
            m = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', r.text)
            if not m:
                m = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', r.text)
            if not m:
                r.failure("no csrf in login form")
                return
            self.csrf = m.group(1)

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code in (200, 302):
                if r.status_code == 302:
                    loc = r.headers.get("Location")
                    if loc:
                        with self.client.get(loc, catch_response=True, allow_redirects=False) as r2:
                            if r2.status_code != 200:
                                r2.failure(f"login redirect status {r2.status_code}")
                                return
                            self._extract_csrf_from_json(r2)
                    else:
                        r.failure("302 without Location")
                        return
                else:
                    self._extract_csrf_from_json(r)
            else:
                r.failure(f"login status {r.status_code}")

    def _extract_csrf_from_json(self, r):
        try:
            data = r.json()
            self.csrf = data.get("csrf", self.csrf)
        except Exception:
            r.failure("login response not JSON")

    def _get_challenge(self):
        with self.client.get(
            "/v2/challenge-form",
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"challenge-form status {r.status_code}")
                return False
            import re
            m = re.search(r'action=["\']/v2/challenges/([^"\']+)["\']', r.text)
            if not m:
                r.failure("no challenge action")
                return False
            challenge_id = m.group(1)
            m2 = re.search(r'name=["\']challenge["\']', r.text)
            if not m2:
                r.failure("no challenge input")
                return False

        with self.client.post(
            f"/v2/challenges/{challenge_id}",
            json={"challenge": "bench"},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 302:
                r.failure(f"challenge POST status {r.status_code}")
                return False
            loc = r.headers.get("Location")
            if not loc:
                r.failure("challenge 302 without Location")
                return False

        with self.client.get(loc, catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure(f"challenge GET status {r.status_code}")
                return False
            try:
                data = r.json()
                self.grant_id = data.get("grant_id")
                self.csrf = data.get("csrf", self.csrf)
                if not self.grant_id:
                    r.failure("no grant_id in challenge response")
                    return False
                return True
            except Exception:
                r.failure("challenge response not JSON")
                return False

    def _get_catalog_product(self):
        if self.reverse_catalog:
            # Use /v2/catalog/page traversal
            url = "/v2/catalog/page"
            for _ in range(3):
                with self.client.get(url, catch_response=True, allow_redirects=False) as r:
                    if r.status_code != 200:
                        r.failure(f"catalog page status {r.status_code}")
                        return None, None
                    try:
                        data = r.json()
                        product = data.get("data", {}).get("product") or data.get("data", {})
                        if not product:
                            product = data.get("data", {})
                        pid = product.get("id")
                        variants = product.get("variants", [])
                        if pid and variants:
                            for v in variants:
                                if v.get("in_stock"):
                                    return pid, v["id"]
                        nxt = data.get("next")
                        if not nxt:
                            break
                        url = nxt
                    except Exception:
                        r.failure("catalog page not JSON")
                        return None, None
            return None, None
        else:
            with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"catalog status {r.status_code}")
                    return None, None
                try:
                    data = r.json()
                    products = data.get("data", {}).get("products", [])
                    for p in products:
                        for v in p.get("variants", []):
                            if v.get("in_stock"):
                                return p["id"], v["id"]
                except Exception:
                    r.failure("catalog not JSON")
                    return None, None
            return None, None

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 201:
                r.failure(f"cart create status {r.status_code}")
                return False
            try:
                data = r.json()
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = r.headers.get("ETag")
                if not self.cart_id:
                    r.failure("no cart id")
                    return False
                return True
            except Exception:
                r.failure("cart create not JSON")
                return False

    def _update_cart_quantity(self):
        if not self.cart_id:
            return False
        quantity = random.randint(1, 20)
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 412:
                # Re-read and retry once
                with self.client.get(
                    f"/v2/carts/{self.cart_id}",
                    catch_response=True,
                    allow_redirects=False,
                ) as r2:
                    if r2.status_code != 200:
                        r2.failure(f"cart re-read status {r2.status_code}")
                        return False
                    self.cart_etag = r2.headers.get("ETag")
                    self.csrf = r2.json().get("csrf", self.csrf) if r2.headers.get("content-type", "").startswith("application/json") else self.csrf
                headers2 = {"X-CSRF-Token": self.csrf}
                if self.cart_etag:
                    headers2["If-Match"] = self.cart_etag
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json={"quantity": quantity},
                    headers=headers2,
                    catch_response=True,
                    allow_redirects=False,
                ) as r3:
                    if r3.status_code != 200:
                        r3.failure(f"cart patch retry status {r3.status_code}")
                        return False
                    self.csrf = r3.json().get("csrf", self.csrf) if r3.headers.get("content-type", "").startswith("application/json") else self.csrf
                    self.cart_etag = r3.headers.get("ETag") or self.cart_etag
                    return True
            elif r.status_code != 200:
                r.failure(f"cart patch status {r.status_code}")
                return False
            else:
                try:
                    data = r.json()
                    self.csrf = data.get("csrf", self.csrf)
                except Exception:
                    pass
                self.cart_etag = r.headers.get("ETag") or self.cart_etag
                return True

    def _create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 202:
                r.failure(f"reservation status {r.status_code}")
                return False
            try:
                data = r.json()
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                if not status_url:
                    r.failure("no status_url")
                    return False
            except Exception:
                r.failure("reservation not JSON")
                return False

        for i in range(5):
            time.sleep(0.05)
            with self.client.get(status_url, catch_response=True, allow_redirects=False) as r:
                if r.status_code != 200:
                    r.failure(f"reservation poll status {r.status_code}")
                    return False
                try:
                    data = r.json()
                    status = data.get("status")
                    self.csrf = data.get("csrf", self.csrf)
                    if status == "ready":
                        self.reservation_id = data.get("reservation_id")
                        if not self.reservation_id:
                            r.failure("ready without reservation_id")
                            return False
                        return True
                    elif status in ("pending",):
                        continue
                    elif status == "failed":
                        return False
                    else:
                        r.failure(f"unknown reservation status {status}")
                        return False
                except Exception:
                    r.failure("reservation poll not JSON")
                    return False
        return False

    def _place_order(self):
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"bench-{self.username}-{self.cart_id}-{int(time.time()*1000)}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                    if data.get("accepted") is True:
                        self.csrf = data.get("csrf", self.csrf)
                        return True
                    else:
                        r.failure("order accepted false")
                        return False
                except Exception:
                    r.failure("order 201 not JSON")
                    return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                    if data.get("accepted") is False:
                        r.failure("business failure accepted:false")
                        return False
                    else:
                        self.csrf = data.get("csrf", self.csrf)
                        return True
                except Exception:
                    r.failure("order 200 not JSON")
                    return False
            else:
                r.failure(f"order status {r.status_code}")
                return False

    def _handle_401(self, r, operation):
        try:
            data = r.json()
            error = data.get("error", "")
        except Exception:
            error = ""
        if error == "expired":
            # Renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                allow_redirects=False,
            ) as rr:
                if rr.status_code == 200:
                    try:
                        self.csrf = rr.json().get("csrf", self.csrf)
                    except Exception:
                        pass
                    # Recover cart if exists
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf},
                            catch_response=True,
                            allow_redirects=False,
                        ) as rc:
                            if rc.status_code == 200:
                                try:
                                    self.csrf = rc.json().get("csrf", self.csrf)
                                except Exception:
                                    pass
                                self.cart_etag = rc.headers.get("ETag") or self.cart_etag
                    return True
                else:
                    rr.failure(f"renew status {rr.status_code}")
                    return False
        elif error == "session":
            # Revoked: fresh login and recover
            self.login()
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    allow_redirects=False,
                ) as rc:
                    if rc.status_code == 200:
                        try:
                            self.csrf = rc.json().get("csrf", self.csrf)
                        except Exception:
                            pass
                        self.cart_etag = rc.headers.get("ETag") or self.cart_etag
                        return True
                    else:
                        rc.failure(f"recover after session status {rc.status_code}")
                        return False
            return True
        elif error == "denied":
            r.failure("denied is not expiry")
            return False
        else:
            return False

    def _do_work(self):
        for attempt in range(4):
            with self.client.post(
                "/v2/work",
                json={},
                catch_response=True,
                allow_redirects=False,
            ) as r:
                if r.status_code == 200:
                    try:
                        data = r.json()
                        if data.get("ok") is True:
                            return True
                        else:
                            r.failure("work ok false")
                            return False
                    except Exception:
                        r.failure("work not JSON")
                        return False
                elif r.status_code == 429:
                    retry_after = r.headers.get("Retry-After", "1")
                    try:
                        time.sleep(float(retry_after))
                    except ValueError:
                        time.sleep(1)
                    continue
                elif r.status_code == 401:
                    if self._handle_401(r, "work"):
                        continue
                    else:
                        return False
                elif r.status_code == 500:
                    r.failure("work 500 unexpected")
                    return False
                else:
                    r.failure(f"work status {r.status_code}")
                    return False
        return False

    @task
    def journey(self):
        if self.iterations_done >= 2:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login and cart each journey
        self.login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None

        # Challenge if required
        if self.require_challenge:
            if not self._get_challenge():
                return

        # Get product
        product_id, variant_id = self._get_catalog_product()
        if not product_id:
            return

        # Create cart
        if not self._create_cart(product_id, variant_id):
            return

        # Update quantity
        if not self._update_cart_quantity():
            return

        # Reservation
        if not self._create_reservation():
            return

        # Place order
        if not self._place_order():
            return

        # Work
        self._do_work()


class Profile1User(ChallengeUser):
    def on_start(self):
        self.require_challenge = True
        self.html_layout = 0
        self.reverse_catalog = False
        super().on_start()


class Profile2User(ChallengeUser):
    def on_start(self):
        self.require_challenge = True
        self.html_layout = 1
        self.reverse_catalog = True
        super().on_start()


class TestShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.users_spawned = False

    def tick(self):
        if not self.users_spawned:
            self.users_spawned = True
            return (2, 2)
        run_time = time.time() - self.start_time
        if run_time > 30:
            return None
        return (2, 2)
