import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    // Protocol
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-test");

    // Feeder for accounts
    private static final List<Map<String, Object>> ACCOUNTS = Arrays.asList(
            Collections.singletonMap("username", "bench"),
            Collections.singletonMap("username", "bench")
    );

    private static final Iterator<Map<String, Object>> accountFeeder = ACCOUNTS.iterator();

    // Chain: GET login form, extract csrf and nonce
    private static final ChainBuilder getLoginForm = exec(
            http("GET /v2/login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").find().saveAs("csrf"))
                    .check(regex("name=\"login_nonce\" value=\"([^\"]+)\"").find().optional().saveAs("login_nonce"))
    );

    // Chain: POST login
    private static final ChainBuilder doLogin = exec(
            http("POST /v2/login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("loginLocation"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(jsonPath("$.user").optional().saveAs("user"))
    ).exec(session -> {
        String location = session.getString("loginLocation");
        if (location != null && !location.isEmpty()) {
            return session.set("redirectUrl", location);
        }
        return session;
    }).doIf(session -> session.contains("redirectUrl")).then(
            exec(http("GET login redirect")
                    .get("#{redirectUrl}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(jsonPath("$.user").optional().saveAs("user"))
            )
    );

    // Chain: GET catalog
    private static final ChainBuilder getCatalog = exec(
            http("GET /v2/catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                    .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
                    .check(jsonPath("$.data.products[0].variants[0].in_stock").saveAs("inStock"))
    );

    // Chain: GET challenge form
    private static final ChainBuilder getChallengeForm = exec(
            http("GET /v2/challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().is(200))
                    .check(regex("action=\"/v2/challenges/([^\"]+)\"").find().saveAs("challengeId"))
                    .check(regex("name=\"challenge\"").find().exists())
    );

    // Chain: POST challenge
    private static final ChainBuilder postChallenge = exec(
            http("POST /v2/challenges/#{challengeId}")
                    .post("/v2/challenges/#{challengeId}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challenge}\"}"))
                    .check(status().is(302))
                    .check(header("Location").saveAs("challengeLocation"))
    ).exec(
            http("GET challenge redirect")
                    .get("#{challengeLocation}")
                    .check(status().is(200))
                    .check(jsonPath("$.grant_id").saveAs("grantId"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
    );

    // Chain: POST cart
    private static final ChainBuilder createCart = exec(
            http("POST /v2/carts")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", "#{csrf}")
