// Helper: perform login
function performLogin(httpClient, username, password) {
  // Get login form
  const formResponse = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
  });

  if (formResponse.status !== 200) {
    return { success: false, error: `login-form status ${formResponse.status}` };
  }

  const csrf = extractCsrfFromHtml(formResponse.body);
  const nonce = extractNonceFromHtml(formResponse.body);

  if (!csrf) {
    return { success: false, error: 'no csrf in login form' };
  }

  // POST login
  const loginPayload = JSON.stringify({
    username: username,
    password: password,
    csrf: csrf,
  });

  const loginResponse = httpClient.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  if (loginResponse.status === 302) {
    const location = getLocation(loginResponse);
    if (location) {
      const followResponse = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
      });
      if (followResponse.status === 200 || followResponse.status === 302) {
        const newCsrf = extractCsrfFromJson(followResponse.body) || extractCsrfFromHtml(followResponse.body);
        return { success: true, csrf: newCsrf || csrf, response: followResponse };
      }
      return { success: false, error: `follow status ${followResponse.status}` };
    }
    return { success: false, error: '302 without Location' };
  }

  if (loginResponse.status === 200) {
    const newCsrf = extractCsrfFromJson(loginResponse.body);
    return { success: true, csrf: newCsrf || csrf, response: loginResponse };
  }

  return { success: false, error: `login status ${loginResponse.status}` };
}

