  });

  if (patchResponse.status === 200 || patchResponse.status === 201) {
    const newCsrf = extractCsrfFromJson(patchResponse.body);
    const newEtag = extractETag(patchResponse);
    return { success: true, csrf: newCsrf || currentCsrf, etag: newEtag || etag, response: patchResponse };
