// Helper: post challenge
function postChallenge(httpClient, action, challengeValue, currentCsrf) {
  const fullUrl = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const payload = {};
  payload.challenge = challengeValue;

  const challengeResponse = httpClient.post(fullUrl, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf,
    },
    redirects: 0,
  });

  if (challengeResponse.status === 302) {
    const location = getLocation(challengeResponse);
    if (location) {
      const followResponse = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
      });
      if (followResponse.status === 200) {
        const grantId = extractGrantId(followResponse.body);
        const newCsrf = extractCsrfFromJson(followResponse.body);
        return { success: true, grantId, csrf: newCsrf || currentCsrf, response: followResponse };
      }
      return { success: false, grantId: null, csrf: currentCsrf, response: followResponse };
    }
    return { success: false, grantId: null, csrf: currentCsrf, response: challengeResponse };
  }

  return { success: false, grantId: null, csrf: currentCsrf, response: challengeResponse };
}

// Helper: get catalog
function getCatalog(httpClient, currentCsrf) {
