// Helper: do work
function doWork(httpClient, currentCsrf) {
  const workResponse = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf,
    },
    redirects: 0,
  });

  businessResponses.add(1);

  if (workResponse.status === 200) {
    return { success: true, response: workResponse };
  }

  if (workResponse.status === 429) {
    // Scheduled 429, retry after 1s up to 4 times
    let retryCount = 0;
    let retryResponse = workResponse;
    while (retryResponse.status === 429 && retryCount < 4) {
      sleep(1);
      retryResponse = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': currentCsrf,
        },
        redirects: 0,
      });
      businessResponses.add(1);
      retryCount++;
    }
    if (retryResponse.status === 200) {
      return { success: true, response: retryResponse };
    }
    return { success: false, response: retryResponse };
  }

  unexpectedFailures.add(1);
  return { success: false, response: workResponse };
}

// Helper: handle 401 error
function handle401(httpClient, errorBody, currentCsrf, cartId) {
  let errorType = null;
  try {
    const data = JSON.parse(errorBody);
    errorType = data.error || null;
  } catch (e) {
    errorType = null;
  }

  if (errorType === 'expired') {
    // Session expired, renew
    const renewResult = renewSession(httpClient, currentCsrf);
    renewalCount.add(1);
    if (renewResult.success) {
      // Recover cart if exists
      if (cartId) {
        const recoverResult = recoverCart(httpClient, cartId, renewResult.csrf);
        recoveryCount.add(1);
        if (recoverResult.success) {
          return { success: true, csrf: recoverResult.csrf, recovered: true, response: recoverResult.response };
        }
        return { success: false, csrf: renewResult.csrf, recovered: false, response: recoverResult.response };
      }
      return { success: true, csrf: renewResult.csrf, recovered: false, response: renewResult.response };
    }
    return { success: false, csrf: currentCsrf, recovered: false, response: renewResult.response };
  }

  if (errorType === 'session') {
    // Session revoked, need fresh login
    const loginResult = performLogin(httpClient, 'bench', 'bench');
    if (loginResult.success) {
      // Recover cart
      if (cartId) {
        const recoverResult = recoverCart(httpClient, cartId, loginResult.csrf);
        recoveryCount.add(1);
        if (recoverResult.success) {
          return { success: true, csrf: recoverResult.csrf, recovered: true, response: recoverResult.response };
        }
        return { success: false, csrf: loginResult.csrf, recovered: false, response: recoverResult.response };
      }
      return { success: true, csrf: loginResult.csrf, recovered: false, response: loginResult.response };
    }
    return { success: false, csrf: currentCsrf, recovered: false, response: loginResult.response || null };
  }

  // error=denied or other
  return { success: false, csrf: currentCsrf, recovered: false, response: null, errorType };
}

// Helper: get a product for cart creation
function getProductForCart(httpClient, currentCsrf, reverseCatalog) {
  // Try catalog first
  const catalogResult = getCatalog(httpClient, currentCsrf);
  if (catalogResult.success && catalogResult.products.length > 0) {
    let products = catalogResult.products;
    if (reverseCatalog) {
      products = products.slice().reverse();
    }
    for (const product of products) {
      const variant = getInStockVariant(product);
      if (variant) {
        return { success: true, productId: product.id, variantId: variant.id, response: catalogResult.response };
      }
    }
  }

  // Try catalog pages
  let nextUrl = '/v2/catalog/page';
  let pagesTraversed = 0;
  while (nextUrl && pagesTraversed < 3) {
    const pageResult = getCatalogPage(httpClient, nextUrl, currentCsrf);
    if (pageResult.success && pageResult.product) {
      const variant = getInStockVariant(pageResult.product);
      if (variant) {
        return { success: true, productId: pageResult.product.id, variantId: variant.id, response: pageResult.response };
      }
      nextUrl = pageResult.next;
    } else {
      break;
    }
    pagesTraversed++;
  }

  return { success: false, productId: null, variantId: null, response: null };
}

// Helper: get grant_id via challenge
function getGrantId(httpClient, currentCsrf) {
  const challengeFormResult = getChallengeForm(httpClient, currentCsrf);
  if (!challengeFormResult.success || !challengeFormResult.action) {
    return { success: false, grantId: null, csrf: currentCsrf, response: challengeFormResult.response };
  }

  const challengeValue = 'bench';
  const challengeResult = postChallenge(httpClient, challengeFormResult.action, challengeValue, currentCsrf);
  if (challengeResult.success && challengeResult.grantId) {
    return { success: true, grantId: challengeResult.grantId, csrf: challengeResult.csrf, response: challengeResult.response };
  }

  return { success: false, grantId: null, csrf: challengeResult.csrf || currentCsrf, response: challengeResult.response };
}

// Helper: complete order journey
function completeOrderJourney(httpClient, currentCsrf, reverseCatalog, useGrantId) {
  // Get product
  const productResult = getProductForCart(httpClient, currentCsrf, reverseCatalog);
  if (!productResult.success) {
    return { success: false, csrf: currentCsrf, error: 'no product found' };
  }

  let csrf = currentCsrf;
  let grantId = null;

  // Get grant_id if needed
  if (useGrantId) {
    const grantResult = getGrantId(httpClient, csrf);
    if (grantResult.success) {
      grantId = grantResult.grantId;
      csrf = grantResult.csrf;
    }
  }

  // Create cart
  const createResult = createCart(httpClient, productResult.productId, productResult.variantId, grantId, csrf);
  if (!createResult.success) {
    // Check for 401
    if (createResult.response && createResult.response.status === 401) {
      const handleResult = handle401(httpClient, createResult.response.body, csrf, null);
      if (handleResult.success) {
        csrf = handleResult.csrf;
        // Retry cart creation
        const retryCreate = createCart(httpClient, productResult.productId, productResult.variantId, grantId, csrf);
        if (retryCreate.success) {
          cartCreations.add(1);
          csrf = retryCreate.csrf;
          return completeOrderWithCart(httpClient, retryCreate.cartId, retryCreate.etag, csrf, reverseCatalog);
        }
        return { success: false, csrf, error: 'cart creation failed after 401 recovery' };
      }
      return { success: false, csrf, error: '401 recovery failed' };
    }
    return { success: false, csrf, error: `cart creation failed: ${createResult.response ? createResult.response.status : 'unknown'}` };
  }

  cartCreations.add(1);
  csrf = createResult.csrf;
  return completeOrderWithCart(httpClient, createResult.cartId, createResult.etag, csrf, reverseCatalog);
}

// Helper: complete order with existing cart
function completeOrderWithCart(httpClient, cartId, etag, currentCsrf, reverseCatalog) {
  let csrf = currentCsrf;
  let currentEtag = etag;

  // Get cart to get fresh ETag
  const getResult = getCart(httpClient, cartId, csrf);
  if (getResult.success && getResult.etag) {
    currentEtag = getResult.etag;
  } else if (getResult.response && getResult.response.status === 401) {
    const handleResult = handle401(httpClient, getResult.response.body, csrf, cartId);
    if (handleResult.success) {
      csrf = handleResult.csrf;
      const retryGet = getCart(httpClient, cartId, csrf);
      if (retryGet.success && retryGet.etag) {
        currentEtag = retryGet.etag;
      }
    }
  }

  // Patch cart quantity
  const patchResult = patchCart(httpClient, cartId, 1, currentEtag, csrf);
  if (patchResult.success) {
    csrf = patchResult.csrf;
    currentEtag = patchResult.etag;
  } else if (patchResult.response && patchResult.response.status === 412) {
    // Re-read and retry once
    const reReadResult = getCart(httpClient, cartId, csrf);
    if (reReadResult.success && reReadResult.etag) {
      currentEtag = reReadResult.etag;
      const retryPatch = patchCart(httpClient, cartId, 1, currentEtag, csrf);
      if (retryPatch.success) {
        csrf = retryPatch.csrf;
        currentEtag = retryPatch.etag;
      }
    }
  } else if (patchResult.response && patchResult.response.status === 401) {
    const handleResult = handle401(httpClient, patchResult.response.body, csrf, cartId);
    if (handleResult.success) {
      csrf = handleResult.csrf;
      const retryPatch = patchCart(httpClient, cartId, 1, currentEtag, csrf);
      if (retryPatch.success) {
        csrf = retryPatch.csrf;
        currentEtag = retryPatch.etag;
      }
    }
  }

  // Create reservation
  const reserveResult = createReservation(httpClient, cartId, csrf);
  let reservationId = null;
  if (reserveResult.success) {
    csrf = reserveResult.csrf;
    // Poll reservation
    let pollCount = 0;
    let pollResult = null;
    while (pollCount < 5) {
      sleep(0.05);
      pollResult = pollReservation(httpClient, reserveResult.statusUrl, csrf);
      if (pollResult.success) {
        csrf = pollResult.csrf;
        if (pollResult.status === 'ready') {
          reservationId = pollResult.reservationId;
          break;
        } else if (pollResult.status === 'failed') {
          break;
        }
      } else if (pollResult.response && pollResult.response.status === 401) {
        const handleResult = handle401(httpClient, pollResult.response.body, csrf, cartId);
        if (handleResult.success) {
          csrf = handleResult.csrf;
        }
      }
      pollCount++;
    }
  } else if (reserveResult.response && reserveResult.response.status === 401) {
    const handleResult = handle401(httpClient, reserveResult.response.body, csrf, cartId);
    if (handleResult.success) {
      csrf = handleResult.csrf;
      // Retry reservation
      const retryReserve = createReservation(httpClient, cartId, csrf);
      if (retryReserve.success) {
        csrf = retryReserve.csrf;
        let pollCount = 0;
        let pollResult = null;
        while (pollCount < 5) {
          sleep(0.05);
          pollResult = pollReservation(httpClient, retryReserve.statusUrl, csrf);
          if (pollResult.success) {
            csrf = pollResult.csrf;
            if (pollResult.status === 'ready') {
              reservationId = pollResult.reservationId;
              break;
            } else if (pollResult.status === 'failed') {
              break;
            }
          }
          pollCount++;
        }
      }
    }
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  const orderResult = createOrder(httpClient, cartId, reservationId, idempotencyKey, currentEtag, csrf);
  orderAttempts.add(1);

  if (orderResult.success) {
    committedOrders.add(1);
    csrf = orderResult.csrf;
    return { success: true, csrf, orderId: orderResult.orderId };
  }

  if (orderResult.response && orderResult.response.status === 401) {
    const handleResult = handle401(httpClient, orderResult.response.body, csrf, cartId);
    if (handleResult.success) {
      csrf = handleResult.csrf;
      // Retry order once
      const retryOrder = createOrder(httpClient, cartId, reservationId, idempotencyKey, currentEtag, csrf);
      orderAttempts.add(1);
      if (retryOrder.success) {
        committedOrders.add(1);
        csrf = retryOrder.csrf;
        return { success: true, csrf, orderId: retryOrder.orderId };
      }
      if (retryOrder.response && retryOrder.response.status === 200) {
        // Check if accepted:false
        try {
          const data = JSON.parse(retryOrder.response.body);
          if (data.accepted === false) {
            businessFailures.add(1);
            return { success: false, csrf, error: 'order accepted:false' };
          }
        } catch (e) {
          // ignore
        }
      }
      return { success: false, csrf, error: 'order failed after 401 recovery' };
    }
    return { success: false, csrf, error: '401 recovery failed for order' };
  }

  if (orderResult.response && orderResult.response.status === 200) {
    try {
      const data = JSON.parse(orderResult.response.body);
      if (data.accepted === false) {
        businessFailures.add(1);
        return { success: false, csrf, error: 'order accepted:false' };
      }
    } catch (e) {
      // ignore
    }
  }

  return { success: false, csrf, error: `order failed: ${orderResult.response ? orderResult.response.status : 'unknown'}` };
}

