        """Perform a fresh login and capture CSRF token."""
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form failed: {resp.status_code}")
                return False
            # Extract CSRF from input[name=csrf]
            import re
            match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not match:
                match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', resp.text)
            if not match:
                resp.failure("No CSRF token found in login form")
                return False
            self.csrf = match.group(1)

        with self.client.post("/v2/login", json={"username": self.username, "password": self.password, "csrf": self.csrf},
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True, allow_redirects=False) as resp2:
                        if resp2.status_code != 200:
                            resp2.failure(f"login redirect failed: {resp2.status_code}")
                            return False
                        data = resp2.json()
                        self.csrf = data.get("csrf", self.csrf)
                        self.session_cookie = self.client.cookies.get("session")
                        return True
                else:
                    resp.failure("302 without Location")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                self.csrf = data.get("csrf", self.csrf)
                self.session_cookie = self.client.cookies.get("session")
                return True
            else:
                resp.failure(f"login failed: {resp.status_code}")
                return False

    def renew_session(self):
        """Attempt to renew an expired session."""
        with self.client.post("/v2/session/renew", json={}, headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.csrf = data.get("csrf", self.csrf)
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                error_type = error_data.get("error", "")
                if error_type == "session":
                    return False  # revoked
                elif error_type == "expired":
                    return True  # expired but renew succeeded? Actually 401 expired means renew failed
                else:
                    return False
            else:
                return False

    def recover_cart(self):
        """Recover cart after session renewal."""
        if not self.cart_id:
            return True
        with self.client.post(f"/v2/carts/{self.cart_id}/recover", json={},
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = resp.headers.get("ETag")
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                if error_data.get("error") == "session":
                    return False
                return False
            else:
                return False

    def get_catalog(self):
        """Fetch catalog and return a product/variant."""
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog failed: {resp.status_code}")
                return None
            data = resp.json()
            products = data.get("data", {}).get("products", [])
            if not products:
                resp.failure("No products in catalog")
                return None
            if self.reverse_catalog:
                products = list(reversed(products))
            product = products[0]
            variants = product.get("variants", [])
            if not variants:
                resp.failure("No variants for product")
                return None
            variant = variants[0]
            if not variant.get("in_stock", False):
                resp.failure("Variant not in stock")
                return None
            return {"product_id": product["id"], "variant_id": variant["id"]}

    def create_cart(self, product_id, variant_id):
        """Create a cart with optional grant_id."""
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post("/v2/carts", json=payload,
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 201:
                data = resp.json()
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = resp.headers.get("ETag")
                return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                error_type = error_data.get("error", "")
                if error_type == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            # Retry cart creation
                            return self.create_cart(product_id, variant_id)
                elif error_type == "session":
                    # Revoked - need fresh login
                    if self.do_login():
                        if self.recover_cart():
                            return self.create_cart(product_id, variant_id)
                resp.failure(f"cart creation 401 {error_type}")
                return False
            else:
                resp.failure(f"cart creation failed: {resp.status_code}")
                return False

    def update_cart_quantity(self, quantity=1):
        """Update cart quantity with retry on 412."""
        if not self.cart_id:
            return False
        payload = {"quantity": quantity}
        headers = {"X-CSRF-Token": self.csrf}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.patch(f"/v2/carts/{self.cart_id}", json=payload,
                               headers=headers, catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = resp.json()
                self.csrf = data.get("csrf", self.csrf)
                self.cart_etag = resp.headers.get("ETag")
                return True
            elif resp.status_code == 412:
                # Re-read and retry once
                with self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True, allow_redirects=False) as get_resp:
                    if get_resp.status_code == 200:
                        self.cart_etag = get_resp.headers.get("ETag")
                        headers["If-Match"] = self.cart_etag
                        with self.client.patch(f"/v2/carts/{self.cart_id}", json=payload,
                                               headers=headers, catch_response=True, allow_redirects=False) as retry_resp:
                            if retry_resp.status_code == 200:
                                data = retry_resp.json()
                                self.csrf = data.get("csrf", self.csrf)
                                self.cart_etag = retry_resp.headers.get("ETag")
                                return True
                            else:
                                retry_resp.failure(f"cart update retry failed: {retry_resp.status_code}")
                                return False
                    else:
                        get_resp.failure(f"cart re-read failed: {get_resp.status_code}")
                        return False
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                error_type = error_data.get("error", "")
                if error_type == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.update_cart_quantity(quantity)
                elif error_type == "session":
                    if self.do_login():
                        if self.recover_cart():
                            return self.update_cart_quantity(quantity)
                resp.failure(f"cart update 401 {error_type}")
                return False
            else:
                resp.failure(f"cart update failed: {resp.status_code}")
                return False

    def create_reservation(self):
        """Create a reservation for the cart."""
        if not self.cart_id:
            return False
        with self.client.post("/v2/reservations", json={"cart_id": self.cart_id},
                              headers={"X-CSRF-Token": self.csrf},
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 202:
                data = resp.json()
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                if not status_url:
                    resp.failure("No status_url in reservation response")
                    return False
                # Poll at least 50ms apart, at most 5 times
                for i in range(5):
                    time.sleep(0.05)
                    with self.client.get(status_url, catch_response=True, allow_redirects=False) as poll_resp:
                        if poll_resp.status_code == 200:
                            poll_data = poll_resp.json()
                            status = poll_data.get("status")
                            if status == "ready":
                                self.reservation_id = poll_data.get("reservation_id")
                                self.csrf = poll_data.get("csrf", self.csrf)
                                return True
                            elif status == "pending":
                                continue
                            elif status == "failed":
                                poll_resp.failure("Reservation failed")
                                return False
                        else:
                            poll_resp.failure(f"Reservation poll failed: {poll_resp.status_code}")
                            return False
                resp.failure("Reservation polling exhausted")
                return False
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                error_type = error_data.get("error", "")
                if error_type == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.create_reservation()
                elif error_type == "session":
                    if self.do_login():
                        if self.recover_cart():
                            return self.create_reservation()
                resp.failure(f"reservation 401 {error_type}")
                return False
            else:
                resp.failure(f"reservation failed: {resp.status_code}")
                return False

    def place_order(self):
        """Place an order for the cart."""
        if not self.cart_id:
            return False
        import uuid
        idempotency_key = f"order-{self.cart_id}-{uuid.uuid4()}"
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = {"X-CSRF-Token": self.csrf, "Idempotency-Key": idempotency_key}
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag
        with self.client.post("/v2/orders", json=payload, headers=headers,
                              catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 201:
                data = resp.json()
                if data.get("accepted") is True:
                    self.order_id = data.get("id")
                    self.csrf = data.get("csrf", self.csrf)
                    self.committed_orders += 1
                    return True
                else:
                    resp.failure("Order not accepted")
                    return False
            elif resp.status_code == 200:
                data = resp.json()
                if data.get("accepted") is False:
                    resp.failure("Order accepted:false is business failure")
                    return False
                else:
                    self.order_id = data.get("id")
                    self.csrf = data.get("csrf", self.csrf)
                    self.committed_orders += 1
                    return True
            elif resp.status_code == 401:
                error_data = resp.json() if resp.text else {}
                error_type = error_data.get("error", "")
                if error_type == "expired":
                    if self.renew_session():
                        if self.recover_cart():
                            return self.place_order()
                elif error_type == "session":
                    if self.do_login():
                        if self.recover_cart():
                            return self.place_order()
                resp.failure(f"order 401 {error_type}")
                return False
            else:
                resp.failure(f"order failed: {resp.status_code}")
                return False

    def do_work(self):
        """Perform a work request."""
        with self.client.post("/v2/work", json={}, catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = resp.json()
                if data.get("ok") is True:
                    return True
                else:
                    resp.failure("Work not ok")
                    return False
            elif resp.status_code == 429:
                # Scheduled 429 - retry after 1s, at most 4 retries
                for i in range(4):
                    time.sleep(1)
                    with self.client.post("/v2/work", json={}, catch_response=True, allow_redirects=False) as retry_resp:
                        if retry_resp.status_code == 200:
                            data = retry_resp.json()
                            if data.get("ok") is True:
                                return True
                            else:
                                retry_resp.failure("Work retry not ok")
                                return False
                        elif retry_resp.status_code == 429:
                            continue
                        else:
                            retry_resp.failure(f"Work retry failed: {retry_resp.status_code}")
                            return False
                resp.failure("Work 429 retries exhausted")
                return False
            else:
                resp.failure(f"Work failed: {resp.status_code}")
                return False

    def complete_journey(self):
        """Complete one full order journey."""
        # Get catalog
        catalog_item = self.get_catalog()
        if not catalog_item:
            return False

        # Create cart
        if not self.create_cart(catalog_item["product_id"], catalog_item["variant_id"]):
            return False

        # Update quantity
        if not self.update_cart_quantity(1):
            return False

        # Create reservation
        if not self.create_reservation():
            return False

        # Place order
        if not self.place_order():
            return False

        # Do work
        if not self.do_work():
            return False

        return True

    @task
    def run_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        # Apply per-virtual-user CSV delay stagger
        if self.delay_ms > 0 and self.iterations_done > 0:
            time.sleep(self.delay_ms / 1000.0)

        # Complete journey
        success = self.complete_journey()
        if success:
            self.iterations_done += 1
        else:
            # If journey failed, still count as iteration attempt
            self.iterations_done += 1

        if self.iterations_done >= self.max_iterations:
            raise StopUser()


class LoadShape(LoadTestShape):
    """Shape that runs until all users complete their iterations."""
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.max_duration = 120  # safety timeout

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > self.max_duration:
            return None

        # Check if all users are done
        runner = self.runner
        if runner and runner.user_count == 0:
            return None

        # Return current user count to keep running
        if runner:
            return (runner.user_count, runner.user_count)
        return None
