```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    flow: {
      executor: 'shared-iterations',
      vus: 2,
      iterations: 4,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function extractCsrfFromForm(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc ? loc.trim() : null;
}

function extractETag(headers) {
  const etag = headers['ETag'];
  return etag ? etag.trim() : null;
}

function isExpiryError(body) {
  return /"error"\s*:\s*"(?:expired|session)"/.test(body);
}

function isDeniedError(body) {
  return /"error"\s*:\s*"denied"/.test(body);
}

function handleExpiry(res, state, operationFn) {
  if (res.status === 401 && isExpiryError(res.body)) {
    // Try renew
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });

    if (renewRes.status === 200) {
      try {
        const renewBody = JSON.parse(renewRes.body);
        if (renewBody.csrf) state.csrf = renewBody.csrf;
      } catch (e) {}
    } else {
      // Session revoked: fresh login
      const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
      const formCsrf = extractCsrfFromForm(formRes.body);
      if (formCsrf) {
        const loginRes = http.post(
          `${BASE_URL}/v2/login`,
          JSON.stringify({ username: state.username, password: 'bench', csrf: formCsrf }),
          {
            headers: { 'Content-Type': 'application/json' },
            redirects: 0,
          }
        );
        if (loginRes.status === 200) {
          try {
            const loginBody = JSON.parse(loginRes.body);
            if (loginBody.csrf) state.csrf = loginBody.csrf;
          } catch (e) {}
        } else if (loginRes.status === 302) {
          const loc = extractLocation(loginRes.headers);
          if (loc) {
            const followRes = http.get(new URL(loc, BASE_URL).toString(), { redirects: 0 });
            try {
              const followBody = JSON.parse(followRes.body);
              if (followBody.csrf) state.csrf = followBody.csrf;
            } catch (e) {}
          }
        }
      }
    }

    // Recover cart if exists
    if (state.hasCart && state.cartId) {
      http.post(
        `${BASE_URL}/v2/carts/${state.cartId}/recover`,
        '{}',
        {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
          redirects: 0,
        }
      );
    }

    // Retry the interrupted operation once
    return operationFn();
  }
  return res;
}

function login(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const formCsrf = extractCsrfFromForm(formRes.body);
  if (!formCsrf) {
    throw new Error('No CSRF token found in login form');
  }

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: state.username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    }
  );

  if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      if (body.csrf) state.csrf = body.csrf;
    } catch (e) {}
  } else if (loginRes.status === 302) {
    const loc = extractLocation(loginRes.headers);
    if (loc) {
      const followRes = http.get(new URL(loc, BASE_URL).toString(), { redirects: 0 });
      try {
        const followBody = JSON.parse(followRes.body);
        if (followBody.csrf) state.csrf = followBody.csrf;
      } catch (e) {}
    }
  }
}

function getCatalog(state) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  if (catalogRes.status !== 200) {
    throw new Error(`Catalog failed: ${catalogRes.status}`);
  }

  const catalog = JSON.parse(catalogRes.body);
  const products = catalog.data?.products || [];
  const inStockProduct = products.find((p) => p.variants && p.variants[0]?.in_stock === true);

  if (inStockProduct) {
    state.productId = inStockProduct.id;
    state.variantId = inStockProduct.variants[0].id;
    return;
  }

  // Traverse pages (at most 3)
  let next = catalog.next;
  let pages = 0;
  while (next && pages < 3) {
    pages++;
    const pageRes = http.get(new URL(next, BASE_URL).toString(), { redirects: 0 });
    if (pageRes.status !== 200) break;
    const pageData = JSON.parse(pageRes.body);
    const product = pageData.data?.product;
    if (product && product.variants && product.variants[0]?.in_stock === true) {
      state.productId = product.id;
      state.variantId = product.variants[0].id;
      return;
    }
    next = pageData.next;
  }

  throw new Error('No in-stock product found');
}

function createCart(state) {
  const payload = {
    product_id: state.productId,
    variant_id: state.variantId,
  };
  if (state.grantId) {
    payload.grant_id = state.grantId;
  }

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  if (res.status === 401 && isExpiryError(res.body)) {
    return handleExpiry(res, state, () => createCart(state));
  }

  if (res.status !== 201) {
    throw new Error(`Cart creation failed: ${res.status}`);
  }

  const body = JSON.parse(res.body);
  state.cartId = body.id;
  state.hasCart = true;
  if (body.csrf) state.csrf = body.csrf;
  state.etag = extractETag(res.headers) || state.etag;
}

function checkout(state) {
  const idempotencyKey = state.cartId;
  const payload = { cart_id: state.cartId };

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (state.etag) {
    headers['If-Match'] = state.etag;
  }

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers,
    redirects: 0,
  });

  if (res.status === 401 && isExpiryError(res.body)) {
    return handleExpiry(res, state, () => checkout(state));
  }

  if (res.status === 401 && isDeniedError(res.body)) {
    throw new Error('Denied error on checkout');
  }

  if (res.status === 200) {
    const body = JSON.parse(res.body);
    if (body.accepted === false) {
      throw new Error('Order not accepted (business failure)');
    }
  }

  if (res.status !== 201 && res.status !== 200) {
    throw new Error(`Checkout failed: ${res.status}`);
  }

  const body = JSON.parse(res.body);
  if (body.csrf) state.csrf = body.csrf;
}

export default function () {
  const vuId = __VU;
  const iterId = __ITER;
  const username = `bench-${vuId}`;

  const state = {
    username,
    csrf: 'MISSING',
    cartId: null,
    etag: null,
    hasCart: false,
    grantId: null,
    productId: null,
    variantId: null,
  };

  login(state);
  getCatalog(state);
  createCart(state);
  checkout(state);
}
