import os
import re
import time
import json
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = between(0, 0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.quantity = 2
        self.iterations_done = 0
        self.max_iterations = 2

    def _extract_csrf_from_form(self, text):
        pattern = re.compile(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            re.IGNORECASE,
        )
        m = pattern.search(text)
        if m:
            return m.group(1)
        return self.csrf

    def _extract_json_csrf(self, text):
        try:
            data = json.loads(text)
            if "csrf" in data:
                return data["csrf"]
        except Exception:
            pass
        return self.csrf

    def _extract_etag(self, headers):
        etag = headers.get("ETag")
        if etag:
            return etag
        return self.etag

    def _extract_location(self, headers):
        return headers.get("Location")

    def _has_error_expired_or_session(self, text):
        return bool(re.search(r'"error"\s*:\s*"(?:expired|session)"', text))

    def _recover_session(self):
        # 401 expired: renew with current CSRF
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
            catch_response=True,
            name="/v2/session/renew",
        ) as resp:
            if resp.status_code == 200:
                self.csrf = self._extract_json_csrf(resp.text)
                if self.has_cart and self.cart != "MISSING":
                    with self.client.post(
                        f"/v2/carts/{self.cart}/recover",
                        json={},
                        headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                        catch_response=True,
                        name="/v2/carts/recover",
                    ) as rec:
                        if rec.status_code == 200:
                            self.csrf = self._extract_json_csrf(rec.text)
                            self.etag = self._extract_etag(rec.headers)
                return True
            else:
                # session revoked: fresh form/login
                return self._fresh_login()

    def _fresh_login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form failed")
                return False
            form_csrf = self._extract_csrf_from_form(resp.text)
            if form_csrf:
                self.csrf = form_csrf

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/login",
        ) as resp:
            if resp.status_code == 302:
                location = self._extract_location(resp.headers)
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        name="/v2/login-redirect",
                    ) as redir:
                        if redir.status_code == 200:
                            self.csrf = self._extract_json_csrf(redir.text)
                            if "grant_id" in redir.text:
                                try:
                                    data = json.loads(redir.text)
                                    self.grant = data.get("grant_id", self.grant)
                                except Exception:
                                    pass
                            return True
                        else:
                            redir.failure("login redirect failed")
                            return False
                else:
                    resp.failure("login 302 without Location")
                    return False
            elif resp.status_code == 200:
                if '"csrf"' not in resp.text:
                    resp.failure("login response missing csrf")
                    return False
                self.csrf = self._extract_json_csrf(resp.text)
                return True
            else:
                resp.failure(f"login failed with {resp.status_code}")
                return False

    def _do_login(self):
        self.username = f"bench-{self._user_id}"
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as resp:
            if resp.status_code != 200:
                resp.failure("login-form failed")
                return False
            form_csrf = self._extract_csrf_from_form(resp.text)
            if form_csrf:
                self.csrf = form_csrf

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/login",
        ) as resp:
            if resp.status_code == 302:
                location = self._extract_location(resp.headers)
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        name="/v2/login-redirect",
                    ) as redir:
                        if redir.status_code == 200:
                            self.csrf = self._extract_json_csrf(redir.text)
                            if "grant_id" in redir.text:
                                try:
                                    data = json.loads(redir.text)
                                    self.grant = data.get("grant_id", self.grant)
                                except Exception:
                                    pass
                            return True
                        else:
                            redir.failure("login redirect failed")
                            return False
                else:
                    resp.failure("login 302 without Location")
                    return False
            elif resp.status_code == 200:
                if '"csrf"' not in resp.text:
                    resp.failure("login response missing csrf")
                    return False
                self.csrf = self._extract_json_csrf(resp.text)
                return True
            else:
                resp.failure(f"login failed with {resp.status_code}")
                return False

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            catch_response=True,
            name="/v2/catalog",
        ) as resp:
            if resp.status_code != 200:
                resp.failure("catalog failed")
                return False
            try:
                data = json.loads(resp.text)
                products = data.get("data", {}).get("products", [])
                for prod in products:
                    variants = prod.get("variants", [])
                    if variants and variants[0].get("in_stock") is True:
                        self.product = prod.get("id", self.product)
                        self.variant = variants[0].get("id", self.variant)
                        return True
                resp.failure("no in-stock product found")
                return False
            except Exception:
                resp.failure("catalog parse failed")
                return False

    def _create_cart(self):
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
            "grant_id": self.grant,
        }
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts",
        ) as resp:
            if resp.status_code == 201:
                if '"id"' not in resp.text or '"cart-' not in resp.text:
                    resp.failure("cart creation missing id")
                    return False
                try:
                    data = json.loads(resp.text)
                    self.cart = data.get("id", self.cart)
                    self.csrf = data.get("csrf", self.csrf)
                    self.has_cart = True
                    self.etag = self._extract_etag(resp.headers)
                    return True
                except Exception:
                    resp.failure("cart parse failed")
                    return False
            elif resp.status_code == 401 and self._has_error_expired_or_session(resp.text):
                if self._recover_session():
                    return self._create_cart()
                return False
            else:
                resp.failure(f"cart creation failed with {resp.status_code}")
                return False

    def _place_order(self):
        payload = {"cart_id": self.cart}
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.cart,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="/v2/orders",
        ) as resp:
            if resp.status_code == 201:
                if '"accepted"' not in resp.text or '"accepted"\s*:\s*true' not in resp.text:
                    resp.failure("order not accepted")
                    return False
                self.csrf = self._extract_json_csrf(resp.text)
                return True
            elif resp.status_code == 401 and self._has_error_expired_or_session(resp.text):
                if self._recover_session():
                    return self._place_order()
                return False
            else:
                resp.failure(f"order failed with {resp.status_code}")
                return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1

        # Fresh login/cart per journey
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"

        if not self._do_login():
            return
        if not self._get_catalog():
            return
        if not self._create_cart():
            return
        self._place_order()


class ShopLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.max_users = 2
        self.max_duration = 120  # safety cap

    def tick(self):
        run_time = time.time() - self.start_time
        if run_time > self.max_duration:
            return None
        # Ramp to 2 users immediately
        if self.get_current_user_count() < self.max_users:
            return (self.max_users, 1.0)
        return None
