    );

    private static String nextUser() {
        int idx = USER_SEQ.incrementAndGet();
        return "bench-" + idx;
    }

    private static ChainBuilder loginForm() {
        return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .headers(Map.of("Content-Type", "application/json"))
                .check(status().is(200))
                .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>").saveAs("form"))
        );
    }

    private static ChainBuilder login() {
        return exec(
            http("POST /v2/login")
                .post("/v2/login")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
