                .check(header("Location").optional().saveAs("location"))
                .check(header("Location").exists().transform(s -> true).optional().saveAs("redirect"))
        );
    }

    private static ChainBuilder followRedirect() {
        return doIf(session -> session.contains("redirect") && session.getBoolean("redirect"))
            .then(
                exec(
                    http("GET redirect location")
                        .get("#{location}")
                        .headers(Map.of(
                            "Content-Type", "application/json",
                            "X-CSRF-Token", "#{csrf}"
                        ))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(jsonPath("$.grant_id").optional().saveAs("grant"))
                )
            );
    }

    private static ChainBuilder catalog() {
        return exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
                ))
                .check(status().is(200))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant"))
        );
    }

    private static ChainBuilder createCart() {
        return exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}"
                ))
                .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
                .check(status().is(201))
                .check(jsonPath("$.id").saveAs("cart"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                .check(header("ETag").optional().saveAs("etag"))
        );
    }

    private static ChainBuilder createOrder() {
        return exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .headers(Map.of(
                    "Content-Type", "application/json",
                    "X-CSRF-Token", "#{csrf}",
                    "Idempotency-Key", "#{cart}"
