                .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                .check(status().is(201))
                .check(jsonPath("$.accepted").is("true"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        );
    }

    private static ChainBuilder journey() {
        return exec(session -> session.set("username", nextUser()))
            .exec(loginForm())
            .exec(login())
            .exec(followRedirect())
            .exec(catalog())
            .exec(createCart())
            .exec(createOrder());
    }

    private final HttpProtocolBuilder httpProtocol =
        http.baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableUrlEncoding()
            .shareConnections()
            .maxConnectionsPerHost(16)
            .userAgentHeader("Gatling/3.15");

    {
        setUp(
            scenario("ModelScenario")
                .exec(journey())
                .injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .assertions(
            global().successfulRequests().percent().gte(100.0)
         );
    }
}
