function parseCsrfFromForm(html) {
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match) return match[1];
  }
  return null;
}

function extractJsonPath(obj, path) {
  // Minimal JSONPath support for the paths used in this script
  if (path === '$.csrf') return obj.csrf;
  if (path === '$.grant_id') return obj.grant_id;
  if (path === '$.id') return obj.id;
  if (path === '$.data.products[?(@.variants[0].in_stock == true)].id') {
    if (obj && obj.data && Array.isArray(obj.data.products)) {
      for (const product of obj.data.products) {
        if (product.variants && product.variants[0] && product.variants[0].in_stock === true) {
          return product.id;
        }
      }
    }
    return null;
  }
  if (path === '$.data.products[?(@.variants[0].in_stock == true)].variants[0].id') {
    if (obj && obj.data && Array.isArray(obj.data.products)) {
      for (const product of obj.data.products) {
        if (product.variants && product.variants[0] && product.variants[0].in_stock === true) {
          return product.variants[0].id;
        }
      }
    }
    return null;
  }
  return null;
}

function getHeader(headers, name) {
  const lower = name.toLowerCase();
  for (const key of Object.keys(headers || {})) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return null;
}

function handleExpiry(response, state, operationName) {
  if (response.status !== 401) return false;
  let body = null;
  try { body = response.json(); } catch (e) { body = null; }
  const error = body && body.error;
  if (error === 'expired' || error === 'session') {
    // Attempt session renewal
    const renewHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), { headers: renewHeaders });
    if (renewRes.status === 200) {
      try {
        const renewBody = renewRes.json();
        if (renewBody.csrf) state.csrf = renewBody.csrf;
      } catch (e) {}
    } else {
      // Session revoked: fresh login
      const formRes = http.get(`${BASE_URL}/v2/login-form`);
      const formCsrf = parseCsrfFromForm(formRes.body);
      if (!formCsrf) fail('login-form missing csrf');
      const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
        username: state.username,
        password: PASSWORD,
        csrf: formCsrf,
      }), { headers: { 'Content-Type': 'application/json' } });
      if (loginRes.status === 302) {
        const location = getHeader(loginRes.headers, 'Location');
        if (location) {
          const redirectRes = http.get(new URL(location, BASE_URL).toString());
          try {
            const redirectBody = redirectRes.json();
            if (redirectBody.csrf) state.csrf = redirectBody.csrf;
            if (redirectBody.grant_id) state.grant = redirectBody.grant_id;
          } catch (e) {}
        }
      } else {
        try {
          const loginBody = loginRes.json();
          if (loginBody.csrf) state.csrf = loginBody.csrf;
        } catch (e) {}
      }
    }
    // Recover cart if exists
    if (state.hasCart && state.cart && state.cart !== 'MISSING') {
      const recoverHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      };
      http.post(`${BASE_URL}/v2/carts/${state.cart}/recover`, JSON.stringify({}), { headers: recoverHeaders });
    }
    return true;
  }
  if (error === 'denied') {
    fail(`denied error on ${operationName}`);
  }
  return false;
}

function login(state) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`);
  check(formRes, { 'login-form status 200': (r) => r.status === 200 });
  const formCsrf = parseCsrfFromForm(formRes.body);
  if (!formCsrf) fail('login-form missing csrf');

  const loginHeaders = {
    'Content-Type': 'application/json',
  };
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: state.username,
    password: PASSWORD,
    csrf: formCsrf,
  }), { headers: loginHeaders });

  if (loginRes.status === 302) {
    const location = getHeader(loginRes.headers, 'Location');
    if (!location) fail('login 302 missing Location');
    const redirectRes = http.get(new URL(location, BASE_URL).toString());
    check(redirectRes, { 'redirect GET status 200': (r) => r.status === 200 });
    try {
      const redirectBody = redirectRes.json();
      if (redirectBody.csrf) state.csrf = redirectBody.csrf;
      if (redirectBody.grant_id) state.grant = redirectBody.grant_id;
    } catch (e) {
      fail('redirect response not JSON');
    }
  } else {
    check(loginRes, { 'login status 200': (r) => r.status === 200 });
    try {
      const loginBody = loginRes.json();
      if (loginBody.csrf) state.csrf = loginBody.csrf;
    } catch (e) {
      fail('login response not JSON');
    }
  }
}

function getCatalog(state) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`);
  check(catalogRes, { 'catalog status 200': (r) => r.status === 200 });
  try {
    const catalogBody = catalogRes.json();
    if (catalogBody.csrf) state.csrf = catalogBody.csrf;
    const productId = extractJsonPath(catalogBody, '$.data.products[?(@.variants[0].in_stock == true)].id');
    const variantId = extractJsonPath(catalogBody, '$.data.products[?(@.variants[0].in_stock == true)].variants[0].id');
    if (productId) state.product = productId;
    if (variantId) state.variant = variantId;
  } catch (e) {
    fail('catalog response not JSON');
  }
  if (!state.product || !state.variant) {
    fail('no in-stock product found in catalog');
  }
}

function createCart(state) {
  const cartHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
  };
  const payload = {
    product_id: state.product,
    variant_id: state.variant,
  };
  if (state.grant && state.grant !== 'MISSING') {
    payload.grant_id = state.grant;
  }
  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), { headers: cartHeaders });

  if (cartRes.status === 401) {
    if (handleExpiry(cartRes, state, 'createCart')) {
      // Retry once after recovery
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      };
      const retryRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), { headers: retryHeaders });
      check(retryRes, { 'cart retry status 201': (r) => r.status === 201 });
      try {
        const retryBody = retryRes.json();
        if (retryBody.csrf) state.csrf = retryBody.csrf;
        if (retryBody.id) {
          state.cart = retryBody.id;
          state.hasCart = true;
        }
        const etag = getHeader(retryRes.headers, 'ETag');
        if (etag) state.etag = etag;
      } catch (e) {
        fail('cart retry response not JSON');
      }
      return;
    }
  }

  check(cartRes, { 'cart status 201': (r) => r.status === 201 });
  try {
    const cartBody = cartRes.json();
    if (cartBody.csrf) state.csrf = cartBody.csrf;
    if (cartBody.id) {
      state.cart = cartBody.id;
      state.hasCart = true;
    }
    const etag = getHeader(cartRes.headers, 'ETag');
    if (etag) state.etag = etag;
  } catch (e) {
    fail('cart response not JSON');
  }
}

function createOrder(state) {
  const orderHeaders = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
    'Idempotency-Key': state.cart,
  };
  if (state.etag && state.etag !== 'MISSING') {
    orderHeaders['If-Match'] = state.etag;
  }
  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id: state.cart }), { headers: orderHeaders });

  if (orderRes.status === 401) {
    if (handleExpiry(orderRes, state, 'createOrder')) {
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'Idempotency-Key': state.cart,
      };
      if (state.etag && state.etag !== 'MISSING') {
        retryHeaders['If-Match'] = state.etag;
      }
      const retryRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify({ cart_id: state.cart }), { headers: retryHeaders });
      check(retryRes, { 'order retry accepted': (r) => r.status === 201 });
      try {
        const retryBody = retryRes.json();
        if (retryBody.csrf) state.csrf = retryBody.csrf;
        check(retryBody, { 'order retry accepted true': (b) => b.accepted === true });
      } catch (e) {
        fail('order retry response not JSON');
      }
      return;
    }
  }

  check(orderRes, { 'order status 201': (r) => r.status === 201 });
  try {
    const orderBody = orderRes.json();
    if (orderBody.csrf) state.csrf = orderBody.csrf;
    check(orderBody, { 'order accepted true': (b) => b.accepted === true });
  } catch (e) {
    fail('order response not JSON');
  }
}

export default function () {
  const vuId = __VU;
  const state = {
    username: `${USERNAME_PREFIX}${vuId}`,
    csrf: 'MISSING',
    cart: 'MISSING',
    etag: 'MISSING',
    hasCart: false,
    grant: 'MISSING',
    product: 'MISSING',
    variant: 'MISSING',
  };

  login(state);
  getCatalog(state);
  createCart(state);
  createOrder(state);
}
