import os
import re
import time
import json
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2


class ShopUser(HttpUser):
    host = BASE
    wait_time = between(0, 0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.has_cart = False
        self.iterations_done = 0

    def _mark_failure(self, response, msg):
        response.failure(msg)

    def _extract_csrf(self, response):
        try:
            data = response.json()
            if "csrf" in data:
                self.csrf = data["csrf"]
        except Exception:
            pass

    def _extract_etag(self, response):
        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag

    def _extract_location(self, response):
        loc = response.headers.get("Location")
        return loc

    def _handle_401(self, response, operation_retry):
        if response.status_code != 401:
            return False
        try:
            body = response.json()
            error = body.get("error", "")
        except Exception:
            error = ""
        if error == "expired":
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                catch_response=True,
                name="/v2/session/renew",
            ) as renew_resp:
                if renew_resp.status_code == 200:
                    self._extract_csrf(renew_resp)
                else:
                    self._mark_failure(renew_resp, f"Renew failed: {renew_resp.status_code}")
            if self.has_cart:
                with self.client.post(
                    f"/v2/carts/{self.cart}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                    catch_response=True,
                    name="/v2/carts/recover",
                ) as rec_resp:
                    if rec_resp.status_code == 200:
                        self._extract_csrf(rec_resp)
                    else:
                        self._mark_failure(rec_resp, f"Recover failed: {rec_resp.status_code}")
            return True
        elif error == "session":
            # Session revoked: fresh login
            self._login()
            if self.has_cart:
                with self.client.post(
                    f"/v2/carts/{self.cart}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                    catch_response=True,
                    name="/v2/carts/recover",
                ) as rec_resp:
                    if rec_resp.status_code == 200:
                        self._extract_csrf(rec_resp)
                    else:
                        self._mark_failure(rec_resp, f"Recover failed: {rec_resp.status_code}")
            return True
        elif error == "denied":
            self._mark_failure(response, "401 denied is not expiry")
            return False
        return False

    def _login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="/v2/login-form",
        ) as form_resp:
            if form_resp.status_code != 200:
                self._mark_failure(form_resp, f"Login form failed: {form_resp.status_code}")
                return False
            # Extract csrf from input
            match = re.search(
                r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                form_resp.text,
            )
            if match:
                form_csrf = match.group(1)
            else:
                self._mark_failure(form_resp, "No csrf input found")
                return False

        # POST login
        payload = {"username": self.username, "password": "bench", "csrf": form_csrf}
        with self.client.post(
            "/v2/login",
            json=payload,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/login",
        ) as login_resp:
            if login_resp.status_code == 302:
                location = self._extract_location(login_resp)
                if not location:
                    self._mark_failure(login_resp, "302 without Location")
                    return False
                # Follow exactly once
                with self.client.get(
                    location,
                    headers={"X-CSRF-Token": self.csrf},
                    catch_response=True,
                    name="/v2/login-redirect",
                ) as redir_resp:
                    if redir_resp.status_code != 200:
                        self._mark_failure(redir_resp, f"Redirect GET failed: {redir_resp.status_code}")
                        return False
                    self._extract_csrf(redir_resp)
                    try:
                        data = redir_resp.json()
                        if "grant_id" in data:
                            self.grant = data["grant_id"]
                    except Exception:
                        pass
            elif login_resp.status_code == 200:
                self._extract_csrf(login_resp)
                try:
                    data = login_resp.json()
                    if "grant_id" in data:
                        self.grant = data["grant_id"]
                except Exception:
                    pass
            else:
                self._mark_failure(login_resp, f"Login failed: {login_resp.status_code}")
                return False
        return True

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/catalog",
        ) as cat_resp:
            if cat_resp.status_code != 200:
                self._mark_failure(cat_resp, f"Catalog failed: {cat_resp.status_code}")
                return False
            self._extract_csrf(cat_resp)
            try:
                data = cat_resp.json()
                products = data.get("data", {}).get("products", [])
                for p in products:
                    variants = p.get("variants", [])
                    if variants and variants[0].get("in_stock"):
                        self.product = p["id"]
                        self.variant = variants[0]["id"]
                        return True
            except Exception:
                pass
            self._mark_failure(cat_resp, "No in-stock product found")
            return False

    def _create_cart(self):
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
            "grant_id": self.grant,
        }
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/carts",
        ) as cart_resp:
            if cart_resp.status_code == 201:
                self._extract_csrf(cart_resp)
                self._extract_etag(cart_resp)
                try:
                    data = cart_resp.json()
                    self.cart = data.get("id", "MISSING")
                    if self.cart != "MISSING":
                        self.has_cart = True
                except Exception:
                    pass
                if self.cart == "MISSING":
                    self._mark_failure(cart_resp, "Cart creation missing id")
                    return False
                return True
            elif cart_resp.status_code == 401:
                if self._handle_401(cart_resp, "create_cart"):
                    # Retry once
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
                        catch_response=True,
                        name="/v2/carts",
                    ) as retry_resp:
                        if retry_resp.status_code == 201:
                            self._extract_csrf(retry_resp)
                            self._extract_etag(retry_resp)
                            try:
                                data = retry_resp.json()
                                self.cart = data.get("id", "MISSING")
                                if self.cart != "MISSING":
                                    self.has_cart = True
                            except Exception:
                                pass
                            if self.cart == "MISSING":
                                self._mark_failure(retry_resp, "Cart retry missing id")
                                return False
                            return True
                        else:
                            self._mark_failure(retry_resp, f"Cart retry failed: {retry_resp.status_code}")
                            return False
                else:
                    return False
            else:
                self._mark_failure(cart_resp, f"Cart creation failed: {cart_resp.status_code}")
                return False

    def _create_order(self):
        payload = {"cart_id": self.cart}
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.cart,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            name="/v2/orders",
        ) as order_resp:
            if order_resp.status_code == 201:
                self._extract_csrf(order_resp)
                try:
                    data = order_resp.json()
                    if not data.get("accepted"):
                        self._mark_failure(order_resp, "Order not accepted")
                        return False
                except Exception:
                    self._mark_failure(order_resp, "Invalid order response")
                    return False
                return True
            elif order_resp.status_code == 200:
                try:
                    data = order_resp.json()
                    if data.get("accepted") is False:
                        self._mark_failure(order_resp, "Business failure: accepted=false")
                        return False
                except Exception:
                    pass
                self._mark_failure(order_resp, "Unexpected 200 for order")
                return False
            elif order_resp.status_code == 401:
                if self._handle_401(order_resp, "create_order"):
                    # Retry once
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                        name="/v2/orders",
                    ) as retry_resp:
                        if retry_resp.status_code == 201:
                            self._extract_csrf(retry_resp)
                            try:
                                data = retry_resp.json()
                                if not data.get("accepted"):
                                    self._mark_failure(retry_resp, "Order retry not accepted")
                                    return False
                            except Exception:
                                self._mark_failure(retry_resp, "Invalid order retry response")
                                return False
                            return True
                        else:
                            self._mark_failure(retry_resp, f"Order retry failed: {retry_resp.status_code}")
                            return False
                else:
                    return False
            else:
                self._mark_failure(order_resp, f"Order failed: {order_resp.status_code}")
                return False

    def _journey(self):
        self.username = f"bench-{self._user_id}"
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.has_cart = False

        if not self._login():
            return
        if not self._get_catalog():
            return
        if not self._create_cart():
            return
        self._create_order()

    @task
    def run_journey(self):
        if self.iterations_done >= ITERATIONS:
            raise StopUser()
        self.iterations_done += 1
        self._journey()


class JourneyShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 1:
            return (USERS, 1)
        return None
