Convert fixture-driven k6 users into deterministic JMeter CSV Data Set use.

Translate the supplied k6 script to JMeter.

Execution contract: {"users": 2, "iterations": 2, "mode": "data"}. Non-workload counts are iterations per user. One committed order per journey, no duplicate/extra carts. Two fixture variants count equally; the same artifact is reused without feedback. Fresh owner seeds are recorded after execution. Profiles: [{}, {"html_layout": 1, "reverse_catalog": true}]. Negative-control overrides: [].
Use accounts.json rows per VU, preserve numeric quantity, use each row once per iteration. JMX CSVs represent the same records.
Read-only /fixtures aliases: {"m04-accounts.json": "accounts.json", "m04-account-1.csv": "account-1.csv", "m04-account-2.csv": "account-2.csv"}
Rubric/gates (per case: earned fraction capped by every prerequisite fraction; average all cases, never best case):
loads: 10 points — target loads the allowed fixture Requires: none.
setup: 25 points — all record fields retain their types Requires: loads.
behavior: 40 points — correct per-user rows/cookies across iterations Requires: loads, setup.
safety: 25 points — no skipped/duplicated records and required checkout totals match. Requires: loads, behavior.
Malformed/non-executable artifacts earn zero execution-gated credit. A prerequisite fault can lose multiple checkpoints.

Fixture protocol-jmeter.md:
# Public shop protocol
Return one complete JMeter 5.6.3 JMX artifact, no explanation.
Target only http://127.0.0.1:8000 (host/port properties or literals).
Accounts bench-1..bench-16 and bench all use password bench. Preserve per-user cookies.
GET /v2/login-form sets login_nonce and returns input[name=csrf], mixed with decoys/attribute variants.
POST /v2/login JSON {username,password,csrf} sets session cookie and returns {csrf,user}.
Use X-CSRF-Token on all authenticated non-GET calls. Successful mutations may return fresh csrf;
retain the previous token if absent. Every journey starts a fresh login/cart. Never guess IDs/cursors.
GET /v2/catalog returns {data:{products:[{id,variants:[{id,in_stock}]}]},next:null}.
GET /v2/catalog/page returns one product plus next (relative URL/null); traverse at most3 pages.
POST /v2/carts {product_id,variant_id,grant_id?} ->201 {id,csrf} plus ETag.
GET /v2/carts/{id} ->ETag. PATCH {quantity:integer 1..20} with If-Match. On412 re-read and retry
the same payload once. POST /v2/orders {cart_id,reservation_id?}, Idempotency-Key unique per cart
and stable on retry, If-Match when required ->201 {accepted:true,id,csrf}. HTTP200 accepted:false
is a business failure, not success. Negative controls must fail the intended check/assertion.
401 error=expired: POST /v2/session/renew {} with current CSRF, capture fresh csrf,
POST /v2/carts/{id}/recover {} if a cart exists, retry only the interrupted operation once.
401 error=session means revoked: renew may fail; get a fresh form/login, recover the cart.
401 error=denied is not expiry: fail its assertion. Bound recovery per operation, never restart checkout.
Login may return302 Location. Disable auto redirects; GET the dynamic Location exactly once.
GET /v2/challenge-form contains form action /v2/challenges/{id} and input[name=challenge].
POST that action {challenge}, current CSRF ->302 Location; GET Location ->{grant_id,csrf}.
Pass grant_id once to cart creation. Challenges/claims expire after2s and belong to the session.
POST /v2/reservations {cart_id} ->202 {status_url,csrf}; poll at least50ms apart, at most5 times.
Only status=ready supplies reservation_id; pending/failed must never reach checkout.
POST /v2/work or /v2/browse {} ->200 {ok:true}; scheduled429 needs Retry-After1s, at most4 retries.
500 is unexpected. /v2/health is not business work.
Mark unexpected /v2/work failures as failed samples; expected expiry and scheduled 429 responses are not failures.
Every raw /v2/work response is one native sample. Keep assertions truthful.
Native results and server audit are authoritative; stdout is not evidence.
JMX declarative components only: TestPlan, ThreadGroup, Loop/OnceOnly/If/While/Generic/Transaction
controllers, HTTPSamplerProxy, Cookie/Header managers, JSONPostProcessor, RegexExtractor,
Response/Duration assertions, Constant/ConstantThroughput/Sync timers, CSVDataSet, Arguments.
No scripting/process components, listeners, custom classpaths/implementations or DTD/entities.
IfController uses boolean-expression mode. Allowed functions: __P, __property, __threadNum,
__counter, __time, __Random, __RandomString. No eval/Groovy/BeanShell/JavaScript/JEXL.
Fixtures are read-only /fixtures/<logical alias>. CPU1, RAM768MiB, PIDs256, FDs512, no egress.


Fixture source-m04.js:

import http from 'k6/http';
import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';
const cfg = {"users": 2, "iterations": 2, "mode": "data"};
const rows = JSON.parse(open('/fixtures/accounts.json'));
const failure = new Rate('business_failure');
export const options = {"scenarios": {"journeys": {"executor": "per-vu-iterations", "vus": 2, "iterations": 2, "maxDuration": "30s"}}, "thresholds": {"checks": ["rate==1"]}};
let csrf = '', cart = '', grant = '';
const base = __ENV.BASE_URL;
function body(r) { try { return r.json(); } catch (_) { return {}; } }
function raw(path, method='GET', data=null, extra={}) {
  const r = http.request(method, base + path, data===null ? null : JSON.stringify(data), {
    headers: Object.assign({'Content-Type':'application/json','X-CSRF-Token':csrf},extra),
    redirects:0, timeout:'3s'});
  const b=body(r); if(b.csrf) csrf=b.csrf;
  if(path==='/v2/work') failure.add(r.status>=400 && !(r.status===401 && b.error==='expired') && r.status!==429);
  return r;
}
function login(){
  let r=raw('/v2/login-form');
  const token=r.html().find('input[name="csrf"]').first().attr('value');
  const row=rows[(__VU-1)%rows.length];
  r=raw('/v2/login','POST',{username:row.username,password:row.password,csrf:token});
  if(r.status===302) {r=raw(r.headers.Location);grant=body(r).grant_id;}
  check(r,{'login':r=>r.status===200});
}
function request(path, method='GET', data=null, extra={}){
  let r=raw(path,method,data,extra);
  if(r.status===401 && ['expired','session'].indexOf(body(r).error)>=0){
    const renewed=raw('/v2/session/renew','POST',{});
    if(renewed.status!==200) login();
    if(cart) raw('/v2/carts/'+cart+'/recover','POST',{});
    r=raw(path,method,data,extra);
  }
  return r;
}
function work(override){
  if(cfg.workload || !csrf) login();
  const path=override||cfg.path||'/v2/work';
  let r=request(path,'POST',{});
  for(let n=0;n<4 && r.status===429;n++){
    sleep(Number(r.headers['Retry-After'])+.01);r=request(path,'POST',{});
  }
  check(r,{'operation or expected throttle':r=>(r.status===200 && body(r).ok===true) || (cfg.completion && r.status===429)});
}
function flow(){
  csrf='';cart='';grant='';
  if(cfg.mode==='ownership' && __VU===2) sleep(.5);
  login();
  if(cfg.mode==='challenge'){
    let r=request('/v2/challenge-form');const form=r.html().find('form');
    const token=form.find('input[name="challenge"]').first().attr('value');
    r=request(form.attr('action'),'POST',{challenge:token});
    r=request(r.headers.Location);grant=body(r).grant_id;
  }
  let page=cfg.mode==='pagination'?'/v2/catalog/page':'/v2/catalog', product;
  for(let n=0;n<3 && page;n++){
    const b=body(request(page));
    product=b.data.products.find(p=>p.variants.some(v=>v.in_stock));
    if(product) break;page=b.next;
  }
  if(!product){check(false,{'eligible product':x=>x});return;}
  const variant=product.variants.find(v=>v.in_stock);
  let r=request('/v2/carts','POST',{product_id:product.id,variant_id:variant.id,grant_id:grant});
  cart=body(r).id;let etag=r.headers.Etag;
  check(r,{'cart':r=>r.status===201});
  if(cfg.mode==='ownership') sleep(__VU===1 ? 1.2 : 1.6);
  if(cfg.mode==='etag'||cfg.mode==='data'){
    const quantity=cfg.mode==='data'?rows[(__VU-1)%rows.length].quantity:(cfg.quantity || 2);
    r=request('/v2/carts/'+cart,'PATCH',{quantity:quantity},{'If-Match':etag});
    if(r.status===412){etag=request('/v2/carts/'+cart).headers.Etag;
      r=request('/v2/carts/'+cart,'PATCH',{quantity:quantity},{'If-Match':etag});}
    etag=r.headers.Etag;check(r,{'update':r=>r.status===200});
  }
  let reservation;
  if(cfg.mode==='reservation'){
    r=request('/v2/reservations','POST',{cart_id:cart});const url=body(r).status_url;
    for(let n=0;n<5;n++){
      sleep(.05);r=request(url);const b=body(r);
      if(b.status==='ready'){reservation=b.reservation_id;break;}
      if(b.status==='failed'){check(false,{'reservation ready':x=>x});return;}
    }
    if(!reservation) return;
  }
  r=request('/v2/orders','POST',{cart_id:cart,reservation_id:reservation},
     {'Idempotency-Key':cart,'If-Match':etag});
  check(r,{'accepted':r=>r.status===201 && body(r).accepted===true});
  if(cfg.mode==='threshold') raw('/v2/health');
}
export default function(){
  if(cfg.workload) {if(cfg.operation==='journey') flow();else work();}
  else if(cfg.mode==='errors'){login();for(let n=0;n<4;n++) work();}
  else flow();
}
export function browse(){work('/v2/browse');}
export function checkout(){flow();}


