```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import { Counter, Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const accounts = new SharedArray('accounts', function () {
  const data = JSON.parse(open('/fixtures/accounts.json'));
  return data.map((row) => ({
    username: String(row.username),
    password: String(row.password),
    quantity: Number(row.quantity),
    delay: Number(row.delay),
  }));
});

const businessFailures = new Counter('business_failures');
const businessResponses = new Counter('business_responses');

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {},
};

function extractCsrfFromHtml(html) {
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
    /<input[^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match) {
      if (match[1]) return match[1];
      const valueMatch = html.match(/\bvalue=["']([^"']+)["']/i);
      if (valueMatch) return valueMatch[1];
    }
  }
  return null;
}

function extractLocation(headers) {
  const location = headers['Location'];
  if (location) return location;
  return null;
}

function parseJsonSafely(response) {
  try {
    return response.json();
  } catch (e) {
    return null;
  }
}

function getCsrfFromResponse(response, currentCsrf) {
  const body = parseJsonSafely(response);
  if (body && body.csrf) return body.csrf;
  return currentCsrf;
}

function getEtagFromResponse(response, currentEtag) {
  const etag = response.headers['ETag'] || response.headers['Etag'] || response.headers['etag'];
  if (etag) return etag;
  return currentEtag;
}

function isExpiredOrSessionError(response) {
  const body = parseJsonSafely(response);
  if (body && body.error) {
    return body.error === 'expired' || body.error === 'session';
  }
  return false;
}

function isDeniedError(response) {
  const body = parseJsonSafely(response);
  if (body && body.error) {
    return body.error === 'denied';
  }
  return false;
}

function renewSession(state) {
  const response = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  state.csrf = getCsrfFromResponse(response, state.csrf);
  return response;
}

function recoverCart(state) {
  if (!state.hasCart || !state.cartId) return null;
  const response = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  state.csrf = getCsrfFromResponse(response, state.csrf);
  return response;
}

function freshLogin(state, username) {
  const formResponse = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const formCsrf = extractCsrfFromHtml(formResponse.body);
  if (!formCsrf) {
    throw new Error('Could not extract csrf from login form');
  }
  state.csrf = formCsrf;

  const loginResponse = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: username, password: 'bench', csrf: formCsrf }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    }
  );

  state.csrf = getCsrfFromResponse(loginResponse, state.csrf);

  const location = extractLocation(loginResponse.headers);
  if (location) {
    const grantResponse = http.get(`${BASE_URL}${location}`, {
      headers: {
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    const grantBody = parseJsonSafely(grantResponse);
    if (grantBody) {
      state.csrf = grantBody.csrf || state.csrf;
      state.grantId = grantBody.grant_id || null;
    }
  }

  return loginResponse;
}

function handleRecovery(state, response, operationFn) {
  if (isExpiredOrSessionError(response)) {
    const renewResponse = renewSession(state);
    if (isExpiredOrSessionError(renewResponse)) {
      freshLogin(state, state.username);
    }
    if (state.hasCart && state.cartId) {
      recoverCart(state);
    }
    return operationFn();
  }
  if (isDeniedError(response)) {
    throw new Error('Denied error encountered');
  }
  return response;
}

function getCatalogProduct(state) {
  const response = http.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  if (isExpiredOrSessionError(response)) {
    return handleRecovery(state, response, () => getCatalogProduct(state));
  }

  const body = parseJsonSafely(response);
  if (body && body.data && body.data.products && body.data.products.length > 0) {
    for (const product of body.data.products) {
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock === true) {
        return {
          productId: product.id,
          variantId: product.variants[0].id,
        };
      }
    }
  }

  // Try paginated catalog
  let nextUrl = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    const pageResponse = http.get(`${BASE_URL}${nextUrl}`, {
      headers: {
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    if (isExpiredOrSessionError(pageResponse)) {
      return handleRecovery(state, pageResponse, () => getCatalogProduct(state));
    }
    const pageBody = parseJsonSafely(pageResponse);
    if (pageBody && pageBody.data && pageBody.data.products && pageBody.data.products.length > 0) {
      const product = pageBody.data.products[0];
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock === true) {
        return {
          productId: product.id,
          variantId: product.variants[0].id,
        };
      }
    }
    if (pageBody && pageBody.next) {
      nextUrl = pageBody.next;
    } else {
      break;
    }
  }

  throw new Error('No in-stock product found');
}

function createCart(state, productId, variantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId,
  };
  if (state.grantId) {
    payload.grant_id = state.grantId;
  }

  const response = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  if (isExpiredOrSessionError(response)) {
    return handleRecovery(state, response, () => createCart(state, productId, variantId));
  }

  if (response.status !== 201) {
    throw new Error(`Cart creation failed with status ${response.status}`);
  }

  const body = parseJsonSafely(response);
  if (!body || !body.id) {
    throw new Error('Cart creation response missing id');
  }

  state.cartId = body.id;
  state.hasCart = true;
  state.csrf = body.csrf || state.csrf;
  state.etag = getEtagFromResponse(response, state.etag);

  return response;
}

function patchCartQuantity(state, quantity) {
  const response = http.patch(
    `${BASE_URL}/v2/carts/${state.cartId}`,
    JSON.stringify({ quantity: quantity }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'If-Match': state.etag,
      },
      redirects: 0,
    }
  );

  if (response.status === 412) {
    // Re-read and retry once
    const getResponse = http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
      headers: {
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    state.etag = getEtagFromResponse(getResponse, state.etag);
    const retryResponse = http.patch(
      `${BASE_URL}/v2/carts/${state.cartId}`,
      JSON.stringify({ quantity: quantity }),
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'If-Match': state.etag,
        },
        redirects: 0,
      }
    );
    state.csrf = getCsrfFromResponse(retryResponse, state.csrf);
    state.etag = getEtagFromResponse(retryResponse, state.etag);
    return retryResponse;
  }

  if (isExpiredOrSessionError(response)) {
    return handleRecovery(state, response, () => patchCartQuantity(state, quantity));
  }

  state.csrf = getCsrfFromResponse(response, state.csrf);
  state.etag = getEtagFromResponse(response, state.etag);

  return response;
}

function createOrder(state) {
  const idempotencyKey = `order-${state.cartId}`;
  const response = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: state.cartId }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
        'Idempotency-Key': idempotencyKey,
        'If-Match': state.etag,
      },
      redirects: 0,
    }
  );

  if (isExpiredOrSessionError(response)) {
    return handleRecovery(state, response, () => createOrder(state));
  }

  if (response.status === 201) {
    const body = parseJsonSafely(response);
    if (body && body.accepted === true) {
      state.csrf = body.csrf || state.csrf;
      return response;
    }
    throw new Error('Order not accepted');
  }

  if (response.status === 200) {
    const body = parseJsonSafely(response);
    if (body && body.accepted === false) {
      throw new Error('Order business failure: accepted=false');
    }
  }

  throw new Error(`Order creation failed with status ${response.status}`);
}

function doWork(state) {
  const response = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  businessResponses.add(1);

  if (response.status === 429) {
    let retries = 0;
    let workResponse = response;
    while (workResponse.status === 429 && retries < 4) {
      sleep(1);
      workResponse = http.post(`${BASE_URL}/v2/work`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
        },
        redirects: 0,
      });
      businessResponses.add(1);
      retries++;
    }
    if (workResponse.status === 429) {
      businessFailures.add(1);
      return workResponse;
    }
    if (workResponse.status !== 200) {
      businessFailures.add(1);
    }
    return workResponse;
  }

  if (response.status !== 200) {
    if (!isExpiredOrSessionError(response)) {
      businessFailures.add(1);
    }
  }

  return response;
}

export default function () {
  const vuIndex = __VU - 1;
  const account = accounts[vuIndex % accounts.length];

  const state = {
    username: account.username,
    csrf: 'MISSING',
    cartId: null,
    etag: 'MISSING',
    hasCart: false,
    grantId: null,
  };

  // Fresh login
  freshLogin(state, account.username);

  // Get catalog product
