```python
import os
import re
import json
import time
from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
FIXTURES = "/fixtures"

ACCOUNTS_FILE = os.path.join(FIXTURES, "accounts.json")
ACCOUNT_CSV_1 = os.path.join(FIXTURES, "account-1.csv")
ACCOUNT_CSV_2 = os.path.join(FIXTURES, "account-2.csv")

PROFILES = [{}, {"html_layout": 1, "reverse_catalog": True}]
NEGATIVE_CONTROLS = []


def load_accounts():
    with open(ACCOUNTS_FILE, "r", encoding="utf-8") as f:
        return json.load(f)


def load_csv_accounts(path):
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        lines = f.read().strip().splitlines()
    if not lines:
        return rows
    headers = [h.strip() for h in lines[0].split(",")]
    for line in lines[1:]:
        if not line.strip():
            continue
        values = [v.strip() for v in line.split(",")]
        row = dict(zip(headers, values))
        if "quantity" in row:
            row["quantity"] = int(row["quantity"])
        if "delay" in row:
            row["delay"] = int(row["delay"])
        rows.append(row)
    return rows


ACCOUNTS = load_accounts()
CSV_ACCOUNTS = {
    1: load_csv_accounts(ACCOUNT_CSV_1),
    2: load_csv_accounts(ACCOUNT_CSV_2),
}


def extract_csrf_from_html(html):
    pattern = re.compile(
        r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
        re.IGNORECASE,
    )
    m = pattern.search(html)
    return m.group(1) if m else None


def extract_error_type(text):
    m = re.search(r'"error"\s*:\s*"(expired|session|denied)"', text)
    return m.group(1) if m else None


class ShopUser(HttpUser):
    wait_time = between(0, 0)

    def on_start(self):
        self.iteration = 0
        self.profile_index = 0
        self.account_index = 0
        self.accounts = []
        self.username = None
        self.password = "bench"
        self.quantity = 2
        self.delay = 0
        self.csrf = "MISSING"
        self.cart_id = "MISSING"
        self.etag = "MISSING"
        self.grant_id = "MISSING"
        self.has_cart = False
        self.session_cookies = {}
        self._load_next_account()

    def _load_next_account(self):
        if self.profile_index >= len(PROFILES):
            raise StopUser()
        profile = PROFILES[self.profile_index]
        self.profile = profile

        if self.account_index >= len(ACCOUNTS):
            self.profile_index += 1
            self.account_index = 0
            if self.profile_index >= len(PROFILES):
                raise StopUser()
            profile = PROFILES[self.profile_index]
            self.profile = profile

        account = ACCOUNTS[self.account_index]
        self.account_index += 1
        self.username = account["username"]
        self.password = account.get("password", "bench")
        self.quantity = int(account.get("quantity", 2))
        self.delay = int(account.get("delay", 0))

    def _fresh_login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False
            csrf = extract_csrf_from_html(resp.text)
            if not csrf:
                resp.failure("no csrf in login form")
                return False
            self.csrf = csrf
            resp.success()
        return True

    def _post_login(self):
        payload = {
            "username": self.username,
            "password": self.password,
            "csrf": self.csrf,
        }
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            headers=headers,
            name="/v2/login",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 302):
                if resp.status_code == 302:
                    location = resp.headers.get("Location")
                    if location:
                        with self.client.get(
                            location,
                            name="/v2/login-redirect",
                            catch_response=True,
                            allow_redirects=False,
                        ) as redir_resp:
                            if redir_resp.status_code != 200:
                                redir_resp.failure(
                                    f"login redirect status {redir_resp.status_code}"
                                )
                                return False
                            self._extract_csrf_and_grant(redir_resp)
                            redir_resp.success()
                    else:
                        resp.failure("302 without Location")
                        return False
                else:
                    self._extract_csrf_and_grant(resp)
                resp.success()
                return True
            else:
                resp.failure(f"login status {resp.status_code}")
                return False

    def _extract_csrf_and_grant(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict):
            if "csrf" in data:
                self.csrf = data["csrf"]
            if "grant_id" in data:
                self.grant_id = data["grant_id"]

    def _extract_csrf(self, resp):
        try:
            data = resp.json()
        except Exception:
            return
        if isinstance(data, dict) and "csrf" in data:
            self.csrf = data["csrf"]

    def _extract_etag(self, resp):
        etag = resp.headers.get("ETag")
        if etag:
            self.etag = etag

    def _handle_401(self, resp, operation_name):
        error_type = extract_error_type(resp.text)
        if error_type == "denied":
            resp.failure(f"{operation_name}: denied")
            return False
        if error_type in ("expired", "session"):
            if error_type == "expired":
                with self.client.post(
                    "/v2/session/renew",
                    json={},
                    headers={
                        "Content-Type": "application/json",
                        "X-CSRF-Token": self.csrf,
                    },
                    name="/v2/session/renew",
                    catch_response=True,
                    allow_redirects=False,
                ) as renew_resp:
                    if renew_resp.status_code == 200:
                        self._extract_csrf(renew_resp)
                        renew_resp.success()
                    else:
                        renew_resp.failure(
                            f"renew status {renew_resp.status_code}"
                        )
                        return False
            else:
                if not self._fresh_login():
                    return False
                if not self._post_login():
                    return False
            if self.has_cart and self.cart_id != "MISSING":
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={
                        "Content-Type": "application/json",
                        "X-CSRF-Token": self.csrf,
                    },
                    name="/v2/carts/recover",
                    catch_response=True,
                    allow_redirects=False,
                ) as rec_resp:
                    if rec_resp.status_code == 200:
                        self._extract_csrf(rec_resp)
                        self._extract_etag(rec_resp)
                        rec_resp.success()
                    else:
                        rec_resp.failure(
                            f"recover status {rec_resp.status_code}"
                        )
                        return False
            return True
        resp.failure(f"{operation_name}: unexpected 401")
        return False

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            name="/v2/catalog",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog status {resp.status_code}")
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("catalog invalid json")
                return None
            products = data.get("data", {}).get("products", [])
            for product in products:
                variants = product.get("variants", [])
                for variant in variants:
                    if variant.get("in_stock"):
                        resp.success()
                        return {
                            "product_id": product["id"],
                            "variant_id": variant["id"],
                        }
            resp.failure("no in-stock product in catalog")
            return None

    def _get_catalog_page(self):
        with self.client.get(
            "/v2/catalog/page",
            name="/v2/catalog/page",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"catalog page status {resp.status_code}")
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("catalog page invalid json")
                return None
            product = data.get("data", {}).get("product")
            if product:
                variants = product.get("variants", [])
                for variant in variants:
                    if variant.get("in_stock"):
                        resp.success()
                        return {
                            "product_id": product["id"],
                            "variant_id": variant["id"],
                        }
            resp.failure("no in-stock product on catalog page")
            return None

    def _create_cart(self, product_id, variant_id):
        payload = {
            "product_id": product_id,
            "variant_id": variant_id,
        }
        if self.grant_id != "MISSING":
            payload["grant_id"] = self.grant_id
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=headers,
            name="/v2/carts",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, "create cart"):
                    return self._create_cart(product_id, variant_id)
                return None
            if resp.status_code != 201:
                resp.failure(f"create cart status {resp.status_code}")
                return None
            try:
                data = resp.json()
            except Exception:
                resp.failure("create cart invalid json")
                return None
            cart_id = data.get("id")
            if not cart_id:
                resp.failure("create cart no id")
                return None
            self.cart_id = cart_id
            self.has_cart = True
            self._extract_csrf(resp)
            self._extract_etag(resp)
            resp.success()
            return cart_id

    def _patch_cart(self, quantity, retry=True):
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": quantity},
            headers=headers,
            name="/v2/carts/patch",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, "patch cart"):
                    return self._patch_cart(quantity, retry)
                return False
            if resp.status_code == 412 and retry:
                with self.client.get(
                    f"/v2/carts/{self.cart_id}",
                    name="/v2/carts/get",
                    catch_response=True,
                    allow_redirects=False,
                ) as get_resp:
                    if get_resp.status_code == 200:
                        self._extract_etag(get_resp)
                        get_resp.success()
                    else:
                        get_resp.failure(
                            f"cart get status {get_resp.status_code}"
                        )
                        return False
                return self._patch_cart(quantity, retry=False)
            if resp.status_code not in (200, 201, 204):
                resp.failure(f"patch cart status {resp.status_code}")
                return False
            self._extract_csrf(resp)
            self._extract_etag(resp)
            resp.success()
            return True

    def _post_order(self):
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": f"order-{self.cart_id}",
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        with self.client.post(
            "/v2/orders",
            json={"cart_id": self.cart_id},
            headers=headers,
            name="/v2/orders",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self._handle_401(resp, "post order"):
                    return self._post_order()
                return False
            if resp.status_code != 201:
                resp.failure(f"order status {resp.status_code}")
                return False
            try:
                data = resp.json()
            except Exception:
                resp.failure("order invalid json")
                return False
            if not data.get("accepted"):
                resp.failure("order accepted:false")
                return False
            self._extract_csrf(resp)
            resp.success()
            return True

    def _do_journey(self):
        if self.delay > 0:
            time.sleep(self.delay / 1000.0)

        if not self._fresh_login():
            return False
        if not self._post_login():
            return False

        selection = self._get_catalog()
        if selection is None:
            selection = self._get_catalog_page()
        if selection is None:
            return False

        cart_id = self._create_cart(selection["product_id"], selection["variant_id"])
        if not cart_id:
            return False

        if not self._patch_cart(self.quantity):
            return False

        if not self._post_order():
            return False

        return True

    @task
    def run_iteration(self):
        self.iteration += 1
        if self.iteration > 2:
            raise StopUser()
        self._do_journey()
        self._load_next_account()


class ShopLoadShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
