const businessFailures = new Counter('business_failures');
const businessResponses = new Counter('business_responses');
const unexpectedErrors = new Counter('unexpected_errors');
const droppedWork = new Counter('dropped_work');

// Workload configuration
const TARGET_RATE = 2; // iterations per second
const WARMUP = 5;
const SCORED_DURATION = 30;
const DRAIN = 5;
const TOTAL_DURATION = WARMUP + SCORED_DURATION + DRAIN;
const MAX_VUS = 4;

// Phase targets: 5/15/5 across three 10s plateaus
const PHASE_TARGETS = [5, 15, 5];
const PHASE_DURATION = 10;

// Per-VU state
const vuState = new Map();

function getVUState() {
  const vuId = __VU;
  if (!vuState.has(vuId)) {
    vuState.set(vuId, {
      username: `bench-${vuId}`,
      password: 'bench',
      csrf: 'MISSING',
      cart: 'MISSING',
      etag: 'MISSING',
      hasCart: false,
      grant: 'MISSING',
      product: 'MISSING',
      variant: 'MISSING',
      quantity: 2,
      sessionCookie: null,
      loginNonce: null,
      idempotencyKey: null,
      reservationId: null,
      cartEtag: null,
      lastWork429: 0,
    });
  }
  return vuState.get(vuId);
}

function extractJsonField(body, path, defaultValue) {
  try {
    const data = JSON.parse(body);
    let value = data;
    for (const key of path.split('.')) {
      if (value === null || value === undefined) return defaultValue;
      value = value[key];
    }
    return value !== undefined && value !== null ? value : defaultValue;
  } catch (e) {
    return defaultValue;
  }
}

function extractCsrfFromForm(body) {
  // Match input with name="csrf" and value attribute
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const pattern of patterns) {
    const match = body.match(pattern);
    if (match) return match[1];
  }
  return null;
}

function extractLocation(headers) {
  const location = headers['Location'];
  if (location) return location;
  return null;
}

function extractEtag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  if (etag) return etag;
  return null;
}

function extractErrorType(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session|denied)"/);
  return match ? match[1] : null;
}

function getHeaders(state, extraHeaders = {}) {
  const headers = {
    'Content-Type': 'application/json',
  };
  if (state.csrf !== 'MISSING') {
    headers['X-CSRF-Token'] = state.csrf;
  }
  if (state.etag !== 'MISSING') {
    headers['If-Match'] = state.etag;
  }
  if (state.idempotencyKey) {
    headers['Idempotency-Key'] = state.idempotencyKey;
  }
