}

function handle401Recovery(state, response, operationFn, operationArgs) {
  const errorType = extractErrorType(response.body);
  if (errorType === 'expired') {
    // Renew session
    const renewHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    };
    const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
      headers: renewHeaders,
      redirects: 0,
    });
    businessResponses.add(1);
    if (renewRes.status === 200) {
      const newCsrf = extractJsonField(renewRes.body, 'csrf', state.csrf);
      if (newCsrf !== state.csrf) {
        state.csrf = newCsrf;
      }
      // Recover cart if exists
      if (state.hasCart && state.cart !== 'MISSING') {
        const recoverHeaders = {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
