        businessResponses.add(1);
        if (recoverRes.status === 200) {
          const newCsrf2 = extractJsonField(recoverRes.body, 'csrf', state.csrf);
          if (newCsrf2 !== state.csrf) {
            state.csrf = newCsrf2;
          }
          const newEtag = extractEtag(recoverRes.headers);
          if (newEtag) state.etag = newEtag;
        }
      }
      // Retry the interrupted operation once
      return operationFn(state, operationArgs, true);
    } else {
      unexpectedErrors.add(1);
      return null;
    }
