function doCheckout(state) {
  const checkoutBody = {
    cart_id: state.cart,
  };
  if (state.reservationId) {
    checkoutBody.reservation_id = state.reservationId;
  }

  const checkoutRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(checkoutBody), {
    headers: getHeaders(state),
    redirects: 0,
  });
  businessResponses.add(1);

  if (checkoutRes.status === 201) {
    const accepted = extractJsonField(checkoutRes.body, 'accepted', false);
    if (accepted === true) {
      const newCsrf = extractJsonField(checkoutRes.body, 'csrf', state.csrf);
      if (newCsrf !== state.csrf) {
        state.csrf = newCsrf;
      }
      return true;
    } else {
      // HTTP 200 accepted:false is business failure
      businessFailures.add(1);
      return false;
    }
  } else if (checkoutRes.status === 200) {
    const accepted = extractJsonField(checkoutRes.body, 'accepted', false);
    if (accepted === true) {
      const newCsrf = extractJsonField(checkoutRes.body, 'csrf', state.csrf);
      if (newCsrf !== state.csrf) {
        state.csrf = newCsrf;
      }
      return true;
    } else {
      businessFailures.add(1);
      return false;
    }
  } else if (checkoutRes.status === 401) {
    const errorType = extractErrorType(checkoutRes.body);
    if (errorType === 'expired' || errorType === 'session') {
      return handle401Recovery(state, checkoutRes, doCheckout, {});
    }
  }
  unexpectedErrors.add(1);
  return false;
}

function doWork(state) {
  const now = Date.now();
  if (now < state.lastWork429 + 1000) {
    // Respect Retry-After
    sleep((state.lastWork429 + 1000 - now) / 1000);
  }
  const workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: getHeaders(state),
    redirects: 0,
  });
  businessResponses.add(1);

  if (workRes.status === 200) {
    return true;
  } else if (workRes.status === 429) {
    state.lastWork429 = Date.now();
    // Scheduled 429 is expected
    return true;
  } else if (workRes.status === 500) {
    unexpectedErrors.add(1);
    return false;
  }
  unexpectedErrors.add(1);
  return false;
}

function runJourney(state) {
  // Fresh login
  if (!doLogin(state)) {
    droppedWork.add(1);
    return false;
  }

  // Catalog selection
  if (!doCatalogSelection(state)) {
    droppedWork.add(1);
    return false;
  }

  // Cart creation
  if (!doCartCreation(state)) {
    droppedWork.add(1);
    return false;
  }

  // Checkout - this is the counted operation
  const checkoutStartTime = Date.now();
  const checkoutSuccess = doCheckout(state);
  if (checkoutSuccess) {
    checkoutStarts.add(1);
  } else {
    droppedWork.add(1);
    return false;
  }

  // Work
  doWork(state);

  return true;
}

export const options = {
  scenarios: {
    journey: {
      executor: 'ramping-arrival-rate',
      exec: 'journey',
      startRate: 0,
      timeUnit: '1s',
      preAllocatedVUs: 2,
      maxVUs: MAX_VUS,
      stages: [
        { duration: `${WARMUP}s`, target: TARGET_RATE },
        { duration: `${PHASE_DURATION}s`, target: PHASE_TARGETS[0] },
        { duration: `${PHASE_DURATION}s`, target: PHASE_TARGETS[1] },
        { duration: `${PHASE_DURATION}s`, target: PHASE_TARGETS[2] },
        { duration: `${DRAIN}s`, target: 0 },
      ],
    },
  },
  thresholds: {
    'http_req_failed': ['rate<0.01'],
    'unexpected_errors': ['count<1'],
    'dropped_work': ['count<1'],
  },
};

export function journey() {
  const state = getVUState();
  runJourney(state);
}

export function setup() {
  // No setup needed
  return {};
}

export function teardown(data) {
  // No teardown needed
}
