```python
import os
import re
import time
import json
import random
import string
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ACCOUNTS = [f"bench-{i}" for i in range(1, 17)]
PASSWORD = "bench"


def extract_csrf_from_html(html):
    m = re.search(r'<input[^>]*\bname=["\']csrf["\'][^>]*\bvalue=["\']([^"\']+)["\']', html, re.I)
    if not m:
        m = re.search(r'<input[^>]*\bvalue=["\']([^"\']+)["\'][^>]*\bname=["\']csrf["\']', html, re.I)
    return m.group(1) if m else None


def extract_etag(headers):
    etag = headers.get("ETag") or headers.get("etag")
    return etag


class ShopUser(HttpUser):
    wait_time = between(0.0, 0.0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = random.choice(ACCOUNTS)
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.quantity = 2
        self.iterations_done = 0
        self.max_iterations = 2

    def on_start(self):
        self.client.cookies.clear()

    def _mark_failure(self, response, msg):
        response.failure(msg)

    def _check_response(self, response, expected_status=None, contains=None):
        if expected_status and response.status_code != expected_status:
            self._mark_failure(response, f"Expected {expected_status}, got {response.status_code}")
            return False
        if contains and contains not in response.text:
            self._mark_failure(response, f"Response missing {contains}")
            return False
        return True

    def _handle_401(self, response, operation_name):
        """Handle 401 expiry/session recovery. Returns True if retry should be attempted."""
        try:
            body = response.json()
        except Exception:
            return False
        error = body.get("error", "")
        if error == "denied":
            self._mark_failure(response, "401 denied is not expiry")
            return False
        if error in ("expired", "session"):
            # Try renew
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"},
                catch_response=True,
                name="/v2/session/renew",
            ) as renew_resp:
                if renew_resp.status_code == 200:
                    try:
                        data = renew_resp.json()
                        if "csrf" in data:
                            self.csrf = data["csrf"]
                    except Exception:
                        pass
                    # Recover cart if exists
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"},
                            catch_response=True,
                            name="/v2/carts/recover",
                        ) as rec_resp:
                            if rec_resp.status_code == 200:
                                try:
                                    data = rec_resp.json()
                                    if "csrf" in data:
                                        self.csrf = data["csrf"]
                                except Exception:
                                    pass
                    return True
                else:
                    # Session revoked: fresh login
                    self._fresh_login()
                    if self.cart_id:
                        with self.client.post(
                            f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"},
                            catch_response=True,
                            name="/v2/carts/recover",
                        ) as rec_resp:
                            if rec_resp.status_code == 200:
                                try:
                                    data = rec_resp.json()
                                    if "csrf" in data:
                                        self.csrf = data["csrf"]
                                except Exception:
                                    pass
                    return True
        return False

    def _fresh_login(self):
        with self.client.get("/v2/login-form", catch_response=True, name="/v2/login-form") as resp:
            if resp.status_code != 200:
                self._mark_failure(resp, "login-form failed")
                return False
            csrf = extract_csrf_from_html(resp.text)
            if not csrf:
                self._mark_failure(resp, "No csrf in login form")
                return False
            self.csrf = csrf

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": self.csrf},
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf},
            catch_response=True,
            name="/v2/login",
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True, name="/v2/login-redirect") as redir:
                        if redir.status_code == 200:
                            try:
                                data = redir.json()
                                if "csrf" in data:
                                    self.csrf = data["csrf"]
                                if "grant_id" in data:
                                    self.grant_id = data["grant_id"]
                            except Exception:
                                pass
                return True
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                return True
            else:
                self._mark_failure(resp, f"login failed: {resp.status_code}")
                return False

    def _get_catalog(self):
        with self.client.get("/v2/catalog", catch_response=True, name="/v2/catalog") as resp:
            if resp.status_code != 200:
                self._mark_failure(resp, "catalog failed")
                return False
            try:
                data = resp.json()
                products = data.get("data", {}).get("products", [])
                for p in products:
                    variants = p.get("variants", [])
                    for v in variants:
                        if v.get("in_stock"):
                            self.product_id = p["id"]
                            self.variant_id = v["id"]
                            return True
            except Exception:
                self._mark_failure(resp, "catalog parse failed")
                return False
        return False

    def _create_cart(self):
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""},
            catch_response=True,
            name="/v2/carts",
        ) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    self.cart_id = data.get("id")
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    self._mark_failure(resp, "cart parse failed")
                    return False
                etag = extract_etag(resp.headers)
                if etag:
                    self.etag = etag
                return True
            elif resp.status_code == 401:
                if self._handle_401(resp, "create_cart"):
                    return self._create_cart()
                return False
            else:
                self._mark_failure(resp, f"cart create failed: {resp.status_code}")
                return False

    def _update_cart(self):
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""}
        if self.etag:
            headers["If-Match"] = self.etag
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json={"quantity": self.quantity},
            headers=headers,
            catch_response=True,
            name="/v2/carts/patch",
        ) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                etag = extract_etag(resp.headers)
                if etag:
                    self.etag = etag
                return True
            elif resp.status_code == 412:
                # Re-read and retry once
                with self.client.get(
                    f"/v2/carts/{self.cart_id}",
                    catch_response=True,
                    name="/v2/carts/get",
                ) as get_resp:
                    if get_resp.status_code == 200:
                        etag = extract_etag(get_resp.headers)
                        if etag:
                            self.etag = etag
                        try:
                            data = get_resp.json()
                            if "csrf" in data:
                                self.csrf = data["csrf"]
                        except Exception:
                            pass
                headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""}
                if self.etag:
                    headers["If-Match"] = self.etag
                with self.client.patch(
                    f"/v2/carts/{self.cart_id}",
                    json={"quantity": self.quantity},
                    headers=headers,
                    catch_response=True,
                    name="/v2/carts/patch-retry",
                ) as retry_resp:
                    if retry_resp.status_code == 200:
                        try:
                            data = retry_resp.json()
                            if "csrf" in data:
                                self.csrf = data["csrf"]
                        except Exception:
                            pass
                        etag = extract_etag(retry_resp.headers)
                        if etag:
                            self.etag = etag
                        return True
                    elif retry_resp.status_code == 401:
                        if self._handle_401(retry_resp, "update_cart_retry"):
                            return self._update_cart()
                        return False
                    else:
                        self._mark_failure(retry_resp, f"cart patch retry failed: {retry_resp.status_code}")
                        return False
            elif resp.status_code == 401:
                if self._handle_401(resp, "update_cart"):
                    return self._update_cart()
                return False
            else:
                self._mark_failure(resp, f"cart patch failed: {resp.status_code}")
                return False

    def _checkout(self):
        headers = {"Content-Type": "application/json", "X-CSRF-Token": self.csrf or ""}
        if self.etag:
            headers["If-Match"] = self.etag
        headers["Idempotency-Key"] = self.cart_id or "missing"
        with self.client.post(
            "/v2/orders",
            json={"cart_id": self.cart_id},
            headers=headers,
            catch_response=True,
            name="/v2/orders",
        ) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    if data.get("accepted") is True:
                        if "csrf" in data:
                            self.csrf = data["csrf"]
                        return True
                    else:
                        self._mark_failure(resp, "accepted is not true")
                        return False
                except Exception:
                    self._mark_failure(resp, "order parse failed")
                    return False
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("accepted") is False:
                        self._mark_failure(resp, "business failure: accepted false")
                        return False
                except Exception:
                    pass
                self._mark_failure(resp, "unexpected 200 on order")
                return False
            elif resp.status_code == 401:
                if self._handle_401(resp, "checkout"):
                    return self._checkout()
                return False
            else:
                self._mark_failure(resp, f"order failed: {resp.status_code}")
                return False

    @task
    def journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        # Fresh login and cart each journey
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None

        if not self._fresh_login():
            self.iterations_done += 1
            return

        if not self._get_catalog():
            self.iterations_done += 1
            return

        if not self._create_cart():
            self.iterations_done += 1
            return

        if not self._update_cart():
            self.iterations_done += 1
            return

        self._checkout()
        self.iterations_done += 1


class JourneyShape(LoadTestShape):
    """
    Shape:
    - Warmup: 5s
    - Scored: 30s (T0+5 to T0+35), six 5s windows
    - Drain: <=5s
    Target phases: 5/15/5 VUs across three 10s plateaus.
    """
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 5:
            return (2, 2)
        elif run_time < 15:
            return (5, 5)
        elif run_time < 25:
            return (15, 15)
        elif run_time < 35:
            return (5, 5)
        elif run_time < 40:
            return (2, 2)
        else:
            return None
