import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT_PATTERN = Pattern.compile(
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>"
    );
    private static final Pattern ERROR_EXPIRED_SESSION_PATTERN = Pattern.compile(
        "\"error\"\\s*:\\s*\"(?:expired|session)\""
    );
    private static final Pattern ETAG_HEADER_PATTERN = Pattern.compile(
        "(?im)^ETag:\\s*([^\\r\\n]+)"
    );
    private static final Pattern LOCATION_HEADER_PATTERN = Pattern.compile(
        "(?im)^Location:\\s*([^\\r\\n]+)"
    );
    private static final Pattern LOCATION_PRESENT_PATTERN = Pattern.compile(
        "(?im)^Location:"
    );
    private static final Pattern CART_ID_PATTERN = Pattern.compile(
        "\"id\"\\s*:\\s*\"cart-"
    );
    private static final Pattern ACCEPTED_TRUE_PATTERN = Pattern.compile(
        "\"accepted\"\\s*:\\s*true"
    );
    private static final Pattern CSRF_JSON_PATTERN = Pattern.compile(
        "\"csrf\"\\s*:"
    );

    private static String extractFirst(Pattern pattern, String input, String defaultValue) {
        java.util.regex.Matcher matcher = pattern.matcher(input);
        if (matcher.find()) {
            return matcher.groupCount() >= 1 ? matcher.group(1) : "true";
        }
        return defaultValue;
    }

    private static boolean matches(Pattern pattern, String input) {
        return pattern.matcher(input).find();
    }

    private static String jsonPathFirst(String body, String path, String defaultValue) {
        try {
            com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
            com.fasterxml.jackson.databind.JsonNode root = mapper.readTree(body);
            String[] parts = path.replace("$", "").split("\\.");
            com.fasterxml.jackson.databind.JsonNode current = root;
            for (String part : parts) {
                if (part.isEmpty()) continue;
                if (part.contains("[") && part.contains("]")) {
                    String fieldName = part.substring(0, part.indexOf("["));
                    String filterExpr = part.substring(part.indexOf("[") + 1, part.indexOf("]"));
                    if (filterExpr.startsWith("?")) {
                        // Simple filter: @.variants[0].in_stock == true
                        if (current != null && current.isArray()) {
                            for (com.fasterxml.jackson.databind.JsonNode item : current) {
                                if (item.has("variants") && item.get("variants").isArray() && item.get("variants").size() > 0) {
                                    com.fasterxml.jackson.databind.JsonNode variant = item.get("variants").get(0);
                                    if (variant.has("in_stock") && variant.get("in_stock").asBoolean()) {
                                        current = item;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                } else {
                    if (current == null) return defaultValue;
                    current = current.get(part);
                }
            }
            if (current == null) return defaultValue;
            if (current.isTextual()) return current.asText();
            if (current.isNumber()) return current.asText();
            if (current.isBoolean()) return current.asText();
            return current.toString();
        } catch (Exception e) {
            return defaultValue;
        }
    }

    private static ChainBuilder loginJourney() {
        return exec(
            http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(bodyString().transform((body, session) -> {
                    String csrf = extractFirst(CSRF_INPUT_PATTERN, body, "MISSING");
                    return session.set("form", csrf);
                }))
        ).exec(
            http("POST /v2/login")
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .body(StringBody(session -> {
                    String username = "bench-" + (session.userId() % 16 + 1);
                    String form = session.getString("form");
                    return "{\"username\":\"" + username + "\",\"password\":\"bench\",\"csrf\":\"" + form + "\"}";
                }))
                .check(status().is(200))
                .check(bodyString().transform((body, session) -> {
                    String csrf = jsonPathFirst(body, "$.csrf", session.getString("csrf"));
                    String location = extractFirst(LOCATION_HEADER_PATTERN, body, "");
                    boolean redirect = matches(LOCATION_PRESENT_PATTERN, body);
                    return session.set("csrf", csrf)
                        .set("location", location)
                        .set("redirect", redirect);
                }))
        ).doIf(session -> session.getBoolean("redirect")).then(
            exec(
                http("GET redirect location")
                    .get(session -> session.getString("location"))
                    .check(status().is(200))
                    .check(bodyString().transform((body, session) -> {
                        String csrf = jsonPathFirst(body, "$.csrf", session.getString("csrf"));
                        String grant = jsonPathFirst(body, "$.grant_id", session.getString("grant"));
                        return session.set("csrf", csrf).set("grant", grant);
                    }))
            )
        );
    }

    private static ChainBuilder catalogJourney() {
        return exec(
            http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(bodyString().transform((body, session) -> {
                    String product = jsonPathFirst(body, "$.data.products[?(@.variants[0].in_stock == true)].id", session.getString("product"));
                    String variant = jsonPathFirst(body, "$.data.products[?(@.variants[0].in_stock == true)].variants[0].id", session.getString("variant"));
                    return session.set("product", product).set("variant", variant);
                }))
        );
    }

    private static ChainBuilder cartJourney() {
        return exec(
            http("POST /v2/carts")
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .body(StringBody(session -> {
                    String product = session.getString("product");
                    String variant = session.getString("variant");
                    String grant = session.getString("grant");
                    return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\",\"grant_id\":\"" + grant + "\"}";
                }))
                .check(status().is(201))
                .check(bodyString().transform((body, session) -> {
                    String csrf = jsonPathFirst(body, "$.csrf", session.getString("csrf"));
                    String cart = jsonPathFirst(body, "$.id", session.getString("cart"));
                    boolean hasCart = matches(CART_ID_PATTERN, body);
                    return session.set("csrf", csrf).set("cart", cart).set("hasCart", hasCart);
                }))
        );
    }

    private static ChainBuilder orderJourney() {
        return exec(
            http("POST /v2/orders")
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody(session -> {
                    String cart = session.getString("cart");
                    return "{\"cart_id\":\"" + cart + "\"}";
                }))
                .check(status().is(201))
                .check(bodyString().transform((body, session) -> {
                    String csrf = jsonPathFirst(body, "$.csrf", session.getString("csrf"));
                    return session.set("csrf", csrf);
                }))
        );
    }

    private static ChainBuilder fullJourney() {
        return exec(loginJourney())
            .exec(catalogJourney())
            .exec(cartJourney())
            .exec(orderJourney());
    }

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableAutoReferer()
        .disableCaching()
        .disableFollowRedirect()
        .shareConnections()
        .contentTypeHeader("application/json")
        .acceptHeader("application/json");

    {
        ScenarioBuilder scenario = scenario("ModelScenario")
            .repeat(2).on(
                exec(fullJourney())
            );

        setUp(
            scenario.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
