```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';
import { randomString } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');

const PROFILES = [
  {},
  { html_layout: 1, reverse_catalog: true },
];

const NEGATIVE_OVERRIDES = [
  { decline_orders: true },
];

const profile = PROFILES[__ITER % PROFILES.length];
const negative = NEGATIVE_OVERRIDES[__ITER % NEGATIVE_OVERRIDES.length];

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.01'],
    business_failure: ['rate<0.01'],
  },
};

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractCsrfFromForm(html) {
  const match = html.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["'][^>]*>/i)
    || html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["'][^>]*>/i);
  return match ? match[1] : null;
}

function extractLocation(res) {
  return res.headers['Location'] || null;
}

function extractEtag(res) {
  return res.headers['ETag'] || null;
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  check(formRes, {
    'login-form status 200': (r) => r.status === 200,
  });

  const csrf = extractCsrfFromForm(formRes.body);
  if (!csrf) {
    throw new Error('CSRF token not found in login form');
  }

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username,
    password,
    csrf,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'login' },
  });

  check(loginRes, {
    'login status 200 or 302': (r) => r.status === 200 || r.status === 302,
    'login has csrf': (r) => {
      const body = parseJson(r);
      return body && body.csrf !== undefined;
    },
  });

  let sessionCsrf = csrf;
  const loginBody = parseJson(loginRes);
  if (loginBody && loginBody.csrf) {
    sessionCsrf = loginBody.csrf;
  }

  if (loginRes.status === 302) {
    const location = extractLocation(loginRes);
    if (location) {
      const redirectRes = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login-redirect' },
      });
      check(redirectRes, {
        'login redirect status 200': (r) => r.status === 200,
      });
      const redirectBody = parseJson(redirectRes);
      if (redirectBody && redirectBody.csrf) {
        sessionCsrf = redirectBody.csrf;
      }
      if (redirectBody && redirectBody.grant_id) {
        return { csrf: sessionCsrf, grantId: redirectBody.grant_id };
      }
    }
  }

  return { csrf: sessionCsrf, grantId: null };
}

function renewSession(csrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'session-renew' },
  });
  check(renewRes, {
    'renew status 200': (r) => r.status === 200,
  });
  const body = parseJson(renewRes);
  return body && body.csrf ? body.csrf : csrf;
}

function recoverCart(csrf, cartId) {
  if (!cartId) return csrf;
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'cart-recover' },
  });
  check(recoverRes, {
    'recover status 200': (r) => r.status === 200,
  });
  const body = parseJson(recoverRes);
  return body && body.csrf ? body.csrf : csrf;
}

function handleAuthError(res, csrf, cartId) {
  const body = parseJson(res);
  if (!body || !body.error) return { csrf, retry: false };

  if (body.error === 'expired') {
    const newCsrf = renewSession(csrf);
    const recoveredCsrf = recoverCart(newCsrf, cartId);
    return { csrf: recoveredCsrf, retry: true };
  }

  if (body.error === 'session') {
    const fresh = login(`bench-${__VU}`, 'bench');
    const recoveredCsrf = recoverCart(fresh.csrf, cartId);
    return { csrf: recoveredCsrf, retry: true };
  }

  return { csrf, retry: false };
}

function getCatalog(csrf) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    redirects: 0,
    tags: { name: 'catalog' },
  });
  check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
  });

  const body = parseJson(catalogRes);
  if (!body || !body.data || !body.data.products) {
    throw new Error('Catalog response missing products');
  }

  let product = null;
  let variant = null;

  for (const p of body.data.products) {
    if (p.variants && p.variants.length > 0 && p.variants[0].in_stock) {
      product = p.id;
      variant = p.variants[0].id;
      break;
    }
  }

  if (!product) {
    for (let i = 0; i < 3; i++) {
      const pageRes = http.get(`${BASE_URL}/v2/catalog/page`, {
        redirects: 0,
        tags: { name: 'catalog-page' },
      });
      check(pageRes, {
        'catalog page status 200': (r) => r.status === 200,
      });
      const pageBody = parseJson(pageRes);
      if (pageBody && pageBody.variants && pageBody.variants.length > 0 && pageBody.variants[0].in_stock) {
        product = pageBody.id;
        variant = pageBody.variants[0].id;
        break;
      }
      if (!pageBody || !pageBody.next) break;
    }
  }

  if (!product || !variant) {
    throw new Error('No in-stock product found');
  }

  return { product, variant };
}

function createCart(csrf, product, variant, grantId) {
  const payload = {
    product_id: product,
    variant_id: variant,
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'cart-create' },
  });

  check(cartRes, {
    'cart create status 201': (r) => r.status === 201,
    'cart create has id': (r) => {
      const body = parseJson(r);
      return body && body.id && body.id.startsWith('cart-');
    },
  });

  const body = parseJson(cartRes);
  if (!body || !body.id) {
    throw new Error('Cart creation failed');
  }

  return {
    cartId: body.id,
    csrf: body.csrf || csrf,
    etag: extractEtag(cartRes),
  };
}

function createOrder(csrf, cartId, etag, idempotencyKey) {
  const payload = {
    cart_id: cartId,
  };

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (etag) {
    headers['If-Match'] = etag;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers,
    redirects: 0,
    tags: { name: 'order-create' },
  });

  check(orderRes, {
    'order status 201': (r) => r.status === 201,
    'order accepted true': (r) => {
      const body = parseJson(r);
      return body && body.accepted === true;
    },
  });

  const body = parseJson(orderRes);
  if (body && body.accepted === false) {
    businessFailure.add(1);
  }

  return {
    csrf: body && body.csrf ? body.csrf : csrf,
    accepted: body ? body.accepted : false,
  };
}

function doWork(csrf) {
  const workRes = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'work' },
  });

  if (workRes.status === 429) {
    let retried = false;
    for (let i = 0; i < 4; i++) {
      sleep(1);
      const retryRes = http.post(`${BASE_URL}/v2/work`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
        },
        redirects: 0,
        tags: { name: 'work-retry' },
      });
      if (retryRes.status === 200) {
        retried = true;
        break;
      }
    }
    if (!retried) {
      businessFailure.add(1);
    }
  } else if (workRes.status !== 200) {
    businessFailure.add(1);
  }

  check(workRes, {
    'work status 200 or 429': (r) => r.status === 200 || r.status === 429,
  });
}

export default function () {
  const username = `bench-${__VU}`;
  const password = 'bench';

  let session = login(username, password);
  let csrf = session.csrf;
  let grantId = session.grantId;
  let cartId = null;
  let etag = null;

  const catalog = getCatalog(csrf);
  const product = catalog.product;
  const variant = catalog.variant;

  const cart = createCart(csrf, product, variant, grantId);
  cartId = cart.cartId;
  csrf = cart.csrf;
  etag = cart.etag;

  const idempotencyKey = `order-${__VU}-${__ITER}-${randomString(8)}`;

  let orderResult = createOrder(csrf, cartId, etag, idempotencyKey);
  csrf = orderResult.csrf;

  if (!orderResult.accepted) {
    const authCheck = handleAuthError(
      { status: 401, json: () => ({ error: 'expired' }) },
      csrf,
      cartId
    );
    if (authCheck.retry) {
      csrf = authCheck.csrf;
      orderResult = createOrder(csrf, cartId, etag, idempotencyKey);
      csrf = orderResult.csrf;
    }
  }

  doWork(csrf);

  sleep(0.1);
}
