                            if self.has_cart:
                                recover_resp = self.client.post(
                                    f"/v2/carts/{self.cart}/recover",
                                    json={},
                                    headers=self._headers(),
                                    name="POST /v2/carts/{id}/recover (recovery)",
                                    catch_response=True,
                                )
                                if recover_resp.status_code == 200:
                                    self._extract_csrf(recover_resp)
                                    self._extract_etag(recover_resp)
                            return True
                return False
        return False

    def _login(self):
        """Fresh login. Returns True on success."""
        self.username = ACCOUNTS[self.iterations_done % len(ACCOUNTS)]
        form_resp = self.client.get(
            "/v2/login-form",
            name="GET /v2/login-form",
            catch_response=True,
        )
        if form_resp.status_code != 200:
            form_resp.failure(f"login-form status {form_resp.status_code}")
            return False

        match = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            form_resp.text,
        )
        if not match:
            form_resp.failure("csrf input not found in login form")
            return False
        self.csrf = match.group(1)

        login_resp = self.client.post(
            "/v2/login",
            json={
                "username": self.username,
                "password": PASSWORD,
                "csrf": self.csrf,
            },
            headers={"Content-Type": "application/json"},
            name="POST /v2/login",
            catch_response=True,
        )
        if login_resp.status_code == 302:
            location = login_resp.headers.get("Location")
            if location:
                redirect_resp = self.client.get(
                    location,
                    name="GET login redirect",
                    catch_response=True,
                )
                if redirect_resp.status_code == 200:
                    self._extract_csrf(redirect_resp)
                    self._extract_etag(redirect_resp)
                    return True
                redirect_resp.failure(f"login redirect status {redirect_resp.status_code}")
                return False
            login_resp.failure("302 without Location")
            return False
        elif login_resp.status_code == 200:
            try:
                data = login_resp.json()
                if "csrf" not in data:
                    login_resp.failure("login response missing csrf")
                    return False
                self.csrf = data["csrf"]
                self._extract_etag(login_resp)
                return True
            except Exception:
                login_resp.failure("login response not JSON")
                return False
        else:
            login_resp.failure(f"login status {login_resp.status_code}")
            return False

    def _get_catalog(self):
        """Fetch catalog and pick in-stock product/variant. Returns True on success."""
        catalog_resp = self.client.get(
            "/v2/catalog",
            name="GET /v2/catalog",
            catch_response=True,
        )
        if catalog_resp.status_code != 200:
            catalog_resp.failure(f"catalog status {catalog_resp.status_code}")
            return False

        try:
            data = catalog_resp.json()
            products = data.get("data", {}).get("products", [])
            for product in products:
                variants = product.get("variants", [])
                for variant in variants:
                    if variant.get("in_stock"):
                        self.product = product["id"]
                        self.variant = variant["id"]
                        self._extract_csrf(catalog_resp)
                        self._extract_etag(catalog_resp)
                        return True
        except Exception:
            catalog_resp.failure("catalog response not JSON")
            return False

        catalog_resp.failure("no in-stock product found in catalog")
        return False

    def _create_cart(self):
        """Create cart. Returns True on success."""
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
        }
        if self.grant != "MISSING":
            payload["grant_id"] = self.grant

        cart_resp = self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._headers(),
            name="POST /v2/carts",
            catch_response=True,
        )
        if cart_resp.status_code == 201:
            try:
                data = cart_resp.json()
                if "id" not in data or not str(data["id"]).startswith("cart-"):
                    cart_resp.failure("cart response missing valid id")
                    return False
                self.cart = data["id"]
                self.has_cart = True
                self._extract_csrf(cart_resp)
                self._extract_etag(cart_resp)
                return True
            except Exception:
                cart_resp.failure("cart response not JSON")
                return False
        elif cart_resp.status_code == 401:
            if self._handle_401(cart_resp, "create_cart"):
                # Retry once
                cart_resp = self.client.post(
                    "/v2/carts",
                    json=payload,
                    headers=self._headers(),
                    name="POST /v2/carts (retry)",
                    catch_response=True,
                )
                if cart_resp.status_code == 201:
                    try:
                        data = cart_resp.json()
                        if "id" not in data or not str(data["id"]).startswith("cart-"):
                            cart_resp.failure("cart retry response missing valid id")
                            return False
                        self.cart = data["id"]
                        self.has_cart = True
                        self._extract_csrf(cart_resp)
                        self._extract_etag(cart_resp)
                        return True
                    except Exception:
                        cart_resp.failure("cart retry response not JSON")
                        return False
                cart_resp.failure(f"cart retry status {cart_resp.status_code}")
                return False
            cart_resp.failure("cart 401 recovery failed")
            return False
        else:
            cart_resp.failure(f"cart status {cart_resp.status_code}")
            return False

    def _create_order(self):
        """Create order. Returns True on success (201 accepted:true)."""
        payload = {"cart_id": self.cart}
        order_resp = self.client.post(
            "/v2/orders",
            json=payload,
            headers=self._headers(),
            name="POST /v2/orders",
            catch_response=True,
        )
        if order_resp.status_code == 201:
            try:
                data = order_resp.json()
                if data.get("accepted") is True:
                    self._extract_csrf(order_resp)
                    self._extract_etag(order_resp)
                    return True
                order_resp.failure("order accepted is not true")
                return False
            except Exception:
                order_resp.failure("order response not JSON")
                return False
        elif order_resp.status_code == 200:
            try:
                data = order_resp.json()
                if data.get("accepted") is False:
                    order_resp.failure("business failure: order not accepted")
                    return False
            except Exception:
                pass
            order_resp.failure(f"order unexpected 200")
            return False
        elif order_resp.status_code == 401:
            if self._handle_401(order_resp, "create_order"):
                order_resp = self.client.post(
                    "/v2/orders",
                    json=payload,
                    headers=self._headers(),
                    name="POST /v2/orders (retry)",
                    catch_response=True,
                )
                if order_resp.status_code == 201:
                    try:
                        data = order_resp.json()
                        if data.get("accepted") is True:
                            self._extract_csrf(order_resp)
                            self._extract_etag(order_resp)
                            return True
                        order_resp.failure("order retry accepted is not true")
                        return False
                    except Exception:
                        order_resp.failure("order retry response not JSON")
                        return False
                elif order_resp.status_code == 200:
                    try:
                        data = order_resp.json()
                        if data.get("accepted") is False:
                            order_resp.failure("business failure: order retry not accepted")
                            return False
                    except Exception:
                        pass
                    order_resp.failure("order retry unexpected 200")
                    return False
                order_resp.failure(f"order retry status {order_resp.status_code}")
                return False
            order_resp.failure("order 401 recovery failed")
            return False
        else:
            order_resp.failure(f"order status {order_resp.status_code}")
            return False

    @task
    def journey(self):
        if self.iterations_done >= 2:
            raise StopUser()

        self.iterations_done += 1

        # Fresh login
        if not self._login():
            return

        # Catalog
        if not self._get_catalog():
            return

        # Cart
        if not self._create_cart():
            return

        # Order
        self._create_order()


class TestShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        if run_time < 60:
            return (2, 2)
        return None
