import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Pattern CSRF_INPUT_PATTERN = Pattern.compile(
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>"
    );
    private static final Pattern ERROR_EXPIRED_SESSION_PATTERN = Pattern.compile("\"error\"\\s*:\\s*\"(?:expired|session)\"");
    private static final Pattern ETAG_HEADER_PATTERN = Pattern.compile("(?im)^ETag:\\s*([^\\r\\n]+)");
    private static final Pattern LOCATION_HEADER_PATTERN = Pattern.compile("(?im)^Location:\\s*([^\\r\\n]+)");
    private static final Pattern LOCATION_PRESENT_PATTERN = Pattern.compile("(?im)^Location:");
    private static final Pattern CART_ID_PATTERN = Pattern.compile("\"id\"\\s*:\\s*\"cart-");

    private static String extractFirst(Pattern pattern, String input, String defaultValue) {
        if (input == null) return defaultValue;
        Matcher m = pattern.matcher(input);
        if (m.find()) {
            return m.groupCount() >= 1 ? m.group(1) : "true";
        }
        return defaultValue;
    }

    private static boolean matches(Pattern pattern, String input) {
        if (input == null) return false;
        return pattern.matcher(input).find();
    }

    private static String jsonString(String value) {
        if (value == null) return "null";
        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static ChainBuilder saveBodyString(String key) {
        return exec(session -> {
            String body = session.getString("gatling.http.response.body");
            return session.set(key, body);
        });
    }

    private static ChainBuilder saveHeaderString(String key, String headerName) {
        return exec(session -> {
            String header = session.getString("gatling.http.response.header." + headerName);
            return session.set(key, header);
        });
    }

    private static ChainBuilder extractCsrfFromBody(String bodyKey, String targetKey) {
        return exec(session -> {
            String body = session.getString(bodyKey);
            String csrf = extractFirst(CSRF_INPUT_PATTERN, body, session.getString(targetKey));
            return session.set(targetKey, csrf);
        });
    }

    private static ChainBuilder extractRecoverFromBody(String bodyKey) {
        return exec(session -> {
            String body = session.getString(bodyKey);
            boolean recover = matches(ERROR_EXPIRED_SESSION_PATTERN, body);
            return session.set("recover", recover);
        });
    }

    private static ChainBuilder extractEtagFromHeaders(String targetKey) {
        return exec(session -> {
            String etagHeader = session.getString("gatling.http.response.header.ETag");
            String etag = extractFirst(ETAG_HEADER_PATTERN, etagHeader, session.getString(targetKey));
            return session.set(targetKey, etag);
        });
    }

    private static ChainBuilder extractLocationFromHeaders() {
        return exec(session -> {
            String locationHeader = session.getString("gatling.http.response.header.Location");
            String location = extractFirst(LOCATION_HEADER_PATTERN, locationHeader, session.getString("location"));
            boolean redirect = matches(LOCATION_PRESENT_PATTERN, locationHeader);
            return session.set("location", location).set("redirect", redirect);
        });
    }

    private static ChainBuilder extractJsonFields(String bodyKey, Map<String, String> jsonPathToSessionKey, Map<String, String> defaults) {
        return exec(session -> {
            String body = session.getString(bodyKey);
            for (Map.Entry<String, String> entry : jsonPathToSessionKey.entrySet()) {
                String jsonPath = entry.getKey();
                String sessionKey = entry.getValue();
                String defaultValue = defaults.getOrDefault(sessionKey, session.getString(sessionKey));
                String value = extractJsonPath(body, jsonPath, defaultValue);
                session = session.set(sessionKey, value);
            }
            return session;
        });
    }

    private static String extractJsonPath(String body, String jsonPath, String defaultValue) {
        if (body == null || body.isEmpty()) return defaultValue;
        // Very limited JSON path extraction for the specific paths used in this JMX
        if (jsonPath.equals("$.csrf")) {
            return extractJsonStringField(body, "csrf", defaultValue);
        } else if (jsonPath.equals("$.grant_id")) {
            return extractJsonStringField(body, "grant_id", defaultValue);
        } else if (jsonPath.equals("$.id")) {
            return extractJsonStringField(body, "id", defaultValue);
        } else if (jsonPath.equals("$.data.products[?(@.variants[0].in_stock == true)].id")) {
            return extractFirstInStockProductId(body, defaultValue);
        } else if (jsonPath.equals("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")) {
            return extractFirstInStockVariantId(body, defaultValue);
        }
        return defaultValue;
    }

    private static String extractJsonStringField(String body, String fieldName, String defaultValue) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(fieldName) + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m = p.matcher(body);
        if (m.find()) {
            return m.group(1);
        }
        return defaultValue;
    }

    private static String extractFirstInStockProductId(String body, String defaultValue) {
        // Find first product with variants[0].in_stock == true
        Pattern productBlock = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher blockMatcher = productBlock.matcher(body);
        if (!blockMatcher.find()) return defaultValue;
        String products = blockMatcher.group(1);
        // Split by product objects - crude but works for this fixture
        Pattern productPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]*)\"[^{}]*?\"variants\"\\s*:\\s*\\[[^\\]]*?\\][^{}]*?\\}", Pattern.DOTALL);
        Matcher pm = productPattern.matcher(products);
        while (pm.find()) {
            String productObj = pm.group(0);
            if (productObj.contains("\"in_stock\"\\s*:\\s*true")) {
                return pm.group(1);
            }
        }
        return defaultValue;
    }

    private static String extractFirstInStockVariantId(String body, String defaultValue) {
        Pattern productBlock = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher blockMatcher = productBlock.matcher(body);
        if (!blockMatcher.find()) return defaultValue;
        String products = blockMatcher.group(1);
        Pattern productPattern = Pattern.compile("\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]*)\"[^{}]*?\"variants\"\\s*:\\s*\\[[^\\]]*?\\][^{}]*?\\}", Pattern.DOTALL);
        Matcher pm = productPattern.matcher(products);
        while (pm.find()) {
            String productObj = pm.group(0);
            if (productObj.contains("\"in_stock\"\\s*:\\s*true")) {
                Pattern variantIdPattern = Pattern.compile("\"variants\"\\s*:\\s*\\[\\s*\\{[^{}]*?\"id\"\\s*:\\s*\"([^\"]*)\"");
                Matcher vm = variantIdPattern.matcher(productObj);
                if (vm.find()) {
                    return vm.group(1);
                }
            }
        }
        return defaultValue;
    }

    private static ChainBuilder loginFormGet(String requestName) {
        return exec(
            http(requestName)
                .get("/v2/login-form")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .check(status().is(200))
        )
        .exec(saveBodyString("loginFormBody"))
        .exec(extractCsrfFromBody("loginFormBody", "form"))
        .exec(extractRecoverFromBody("loginFormBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder loginPost(String requestName) {
        return exec(
            http(requestName)
                .post("/v2/login")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody(session -> {
                    String username = "bench-" + session.getLong("threadNum");
                    String password = "bench";
                    String csrf = session.getString("form");
                    return "{\"username\":\"" + username + "\",\"password\":\"" + password + "\",\"csrf\":\"" + csrf + "\"}";
                }))
                .check(status().is(200))
        )
        .exec(saveBodyString("loginBody"))
        .exec(extractJsonFields("loginBody",
            Map.of("$.csrf", "csrf"),
            Map.of("csrf", session -> session.getString("csrf"))))
        .exec(extractRecoverFromBody("loginBody"))
        .exec(extractEtagFromHeaders("etag"))
        .exec(extractLocationFromHeaders());
    }

    private static ChainBuilder followRedirectGet(String requestName) {
        return exec(
            http(requestName)
                .get(session -> session.getString("location"))
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .check(status().is(200))
        )
        .exec(saveBodyString("redirectBody"))
        .exec(extractJsonFields("redirectBody",
            Map.of("$.csrf", "csrf", "$.grant_id", "grant"),
            Map.of("csrf", session -> session.getString("csrf"), "grant", session -> session.getString("grant"))))
        .exec(extractRecoverFromBody("redirectBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder catalogGet(String requestName) {
        return exec(
            http(requestName)
                .get("/v2/catalog")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .check(status().is(200))
        )
        .exec(saveBodyString("catalogBody"))
        .exec(extractJsonFields("catalogBody",
            Map.of("$.csrf", "csrf",
                   "$.data.products[?(@.variants[0].in_stock == true)].id", "product",
                   "$.data.products[?(@.variants[0].in_stock == true)].variants[0].id", "variant"),
            Map.of("csrf", session -> session.getString("csrf"),
                   "product", session -> session.getString("product"),
                   "variant", session -> session.getString("variant"))))
        .exec(extractRecoverFromBody("catalogBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder cartCreatePost(String requestName) {
        return exec(
            http(requestName)
                .post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody(session -> {
                    String product = session.getString("product");
                    String variant = session.getString("variant");
                    String grant = session.getString("grant");
                    return "{\"product_id\":\"" + product + "\",\"variant_id\":\"" + variant + "\",\"grant_id\":\"" + grant + "\"}";
                }))
                .check(status().is(201))
        )
        .exec(saveBodyString("cartCreateBody"))
        .exec(extractJsonFields("cartCreateBody",
            Map.of("$.csrf", "csrf", "$.id", "cart"),
            Map.of("csrf", session -> session.getString("csrf"), "cart", session -> session.getString("cart"))))
        .exec(extractRecoverFromBody("cartCreateBody"))
        .exec(extractEtagFromHeaders("etag"))
        .exec(session -> {
            String body = session.getString("cartCreateBody");
            boolean hasCart = matches(CART_ID_PATTERN, body);
            return session.set("hasCart", hasCart);
        });
    }

    private static ChainBuilder orderPost(String requestName) {
        return exec(
            http(requestName)
                .post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(status().is(201))
                .check(bodyString().transform(body -> body.contains("\"accepted\"\\s*:\\s*true") ? body : null))
        )
        .exec(saveBodyString("orderBody"))
        .exec(extractJsonFields("orderBody",
            Map.of("$.csrf", "csrf"),
            Map.of("csrf", session -> session.getString("csrf"))))
        .exec(extractRecoverFromBody("orderBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder sessionRenewPost(String requestName) {
        return exec(
            http(requestName)
                .post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody("{}"))
                .check(status().is(200))
        )
        .exec(saveBodyString("renewBody"))
        .exec(extractJsonFields("renewBody",
            Map.of("$.csrf", "csrf"),
            Map.of("csrf", session -> session.getString("csrf"))))
        .exec(extractRecoverFromBody("renewBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder cartRecoverPost(String requestName) {
        return exec(
            http(requestName)
                .post(session -> "/v2/carts/" + session.getString("cart") + "/recover")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", session -> session.getString("csrf"))
                .header("If-Match", session -> session.getString("etag"))
                .header("Idempotency-Key", session -> session.getString("cart"))
                .body(StringBody("{}"))
                .check(status().is(200))
        )
        .exec(saveBodyString("recoverBody"))
        .exec(extractJsonFields("recoverBody",
            Map.of("$.csrf", "csrf"),
            Map.of("csrf", session -> session.getString("csrf"))))
        .exec(extractRecoverFromBody("recoverBody"))
        .exec(extractEtagFromHeaders("etag"));
    }

    private static ChainBuilder doIf(ChainBuilder conditionChain, ChainBuilder thenChain) {
        return exec(session -> session.set("conditionResult", false))
            .exec(conditionChain)
            .doIf(session -> session.getBoolean("conditionResult"))
            .then(thenChain);
    }

    private static ChainBuilder refreshAndRecover() {
        return exec(session -> session.set("recover", false))
            .exec(sessionRenewPost("session-renew"))
            .doIf(session -> session.getBoolean("recover"))
            .then(
                exec(loginFormGet("login-form-refresh"))
                .exec(loginPost("login-refresh"))
                .doIf(session -> session.getBoolean("redirect"))
                .then(followRedirectGet("redirect-refresh"))
            )
            .doIf(session -> session.getBoolean("hasCart"))
            .then(cartRecoverPost("cart-recover"));
    }

    private static ChainBuilder orderWithRecovery() {
        return exec(orderPost("order"))
            .doIf(session -> session.getBoolean("recover"))
            .then(
                refreshAndRecover()
                .exec(orderPost("order-retry"))
            );
    }

    private static ChainBuilder journey() {
        return exec(session -> session
                .set("csrf", "MISSING")
                .set("cart", "MISSING")
                .set("etag", "MISSING")
                .set("hasCart", false)
                .set("grant", "MISSING")
                .set("product", "MISSING")
                .set("variant", "MISSING")
                .set("quantity", "2")
                .set("recover", false)
                .set("redirect", false)
                .set("location", "")
                .set("form", "MISSING")
                .set("threadNum", session.userId()))
            .exec(loginFormGet("login-form"))
            .exec(loginPost("login"))
            .doIf(session -> session.getBoolean("redirect"))
            .then(followRedirectGet("redirect"))
            .exec(catalogGet("catalog"))
            .exec(cartCreatePost("cart-create"))
            .exec(orderWithRecovery());
    }

    private static final HttpProtocolBuilder httpProtocol =
        http.baseUrl(BASE_URL)
            .disableAutoReferer()
            .disableCaching()
            .disableFollowRedirect()
            .shareConnections()
            .contentTypeHeader("application/json")
            .acceptHeader("application/json");

    {
        setUp(
            scenario("ModelScenario")
                .exec(journey())
                .injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol)
         .maxDuration(Duration.ofMinutes(5));
    }
}
