import http from 'k6/http';
import { check, sleep } from 'k6';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    expiry: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
  thresholds: {},
};

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractCsrfFromHtml(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(res) {
  const loc = res.headers['Location'];
  return loc ? loc.trim() : null;
}

function extractETag(res) {
  const etag = res.headers['ETag'];
  return etag ? etag.trim() : null;
}

function hasError(res, errorType) {
  const body = res.body;
  if (!body) return false;
  const regex = new RegExp(`"error"\\s*:\\s*"${errorType}"`);
  return regex.test(body);
}

function isExpiredOrSession(res) {
  return hasError(res, 'expired') || hasError(res, 'session');
}

function isDenied(res) {
  return hasError(res, 'denied');
}

function isScheduled429(res) {
  return res.status === 429;
}

function isUnexpected500(res) {
  return res.status === 500;
}

function getBusinessFailure(res) {
  if (isDenied(res)) return true;
  if (isUnexpected500(res)) return true;
  return false;
}

function recordBusinessResponse(res) {
  // Custom business_failure Rate: numerator=unexpected failures, denominator=all business responses
  // We'll track via a global counter and report at the end.
  if (typeof globalThis.__businessTotal === 'undefined') {
    globalThis.__businessTotal = 0;
    globalThis.__businessFailures = 0;
  }
  globalThis.__businessTotal++;
  if (getBusinessFailure(res)) {
    globalThis.__businessFailures++;
  }
}

function loginForm(state) {
  const res = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  check(res, { 'login-form status 200': (r) => r.status === 200 });
  const html = res.body;
  const csrf = extractCsrfFromHtml(html);
  if (csrf) state.csrf = csrf;
  return res;
}

function login(state, username) {
  const payload = JSON.stringify({
    username: username,
    password: 'bench',
    csrf: state.csrf,
  });
  const res = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  check(res, { 'login status 200 or 302': (r) => r.status === 200 || r.status === 302 });
  const json = parseJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  const location = extractLocation(res);
  if (location) {
    const locRes = http.get(new URL(location, BASE_URL).toString(), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
    });
    check(locRes, { 'login redirect status 200': (r) => r.status === 200 });
    const locJson = parseJson(locRes);
    if (locJson && locJson.csrf) state.csrf = locJson.csrf;
    if (locJson && locJson.grant_id) state.grant = locJson.grant_id;
  }
  return res;
}

function getCatalog(state) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  check(res, { 'catalog status 200': (r) => r.status === 200 });
  const json = parseJson(res);
  if (json && json.data && json.data.products && json.data.products.length > 0) {
    const products = json.data.products;
    for (const product of products) {
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock === true) {
        state.product = product.id;
        state.variant = product.variants[0].id;
        break;
      }
    }
  }
  return res;
}

function createCart(state) {
  const payload = JSON.stringify({
    product_id: state.product,
    variant_id: state.variant,
    grant_id: state.grant !== 'MISSING' ? state.grant : undefined,
  });
  const res = http.post(`${BASE_URL}/v2/carts`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  check(res, { 'create cart status 201': (r) => r.status === 201 });
  const json = parseJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  if (json && json.id) {
    state.cart = json.id;
    state.hasCart = true;
  }
  const etag = extractETag(res);
  if (etag) state.etag = etag;
  return res;
}

function postOrders(state, idempotencyKey) {
  const payload = JSON.stringify({ cart_id: state.cart });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (state.etag && state.etag !== 'MISSING') {
    headers['If-Match'] = state.etag;
  }
  const res = http.post(`${BASE_URL}/v2/orders`, payload, {
    headers: headers,
    redirects: 0,
  });
  recordBusinessResponse(res);
  const json = parseJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  return res;
}

function renewSession(state) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  const json = parseJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  return res;
}

function recoverCart(state) {
  const res = http.post(`${BASE_URL}/v2/carts/${state.cart}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  const json = parseJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  return res;
}

function fullRelogin(state, username) {
  loginForm(state);
  login(state, username);
}

function handleExpiryRecovery(state, username, operationFn, operationArgs) {
  // Attempt the operation once
  let res = operationFn(state, ...operationArgs);
  if (isExpiredOrSession(res)) {
    // Try renew
    const renewRes = renewSession(state);
    if (isExpiredOrSession(renewRes)) {
      // Session revoked, full relogin
      fullRelogin(state, username);
    }
    if (state.hasCart) {
      recoverCart(state);
    }
    // Retry the operation once
    res = operationFn(state, ...operationArgs);
  }
  return res;
}

export default function () {
  const vuId = __VU;
  const username = `bench-${vuId}`;
  const state = {
    csrf: 'MISSING',
    cart: 'MISSING',
    etag: 'MISSING',
    hasCart: false,
    grant: 'MISSING',
    product: 'MISSING',
    variant: 'MISSING',
  };

  // Fresh login
  loginForm(state);
  login(state, username);

  // Catalog
  getCatalog(state);

  // Create cart
  createCart(state);

  // Order with expiry recovery
  const idempotencyKey = state.cart;
  const orderRes = handleExpiryRecovery(state, username, postOrders, [idempotencyKey]);

  check(orderRes, {
    'order accepted': (r) => {
      const json = parseJson(r);
      return r.status === 201 && json && json.accepted === true;
    },
  });

  // Business work
  const workRes = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  recordBusinessResponse(workRes);
  check(workRes, { 'work ok': (r) => r.status === 200 && r.json().ok === true });

  sleep(0.1);
}

export function teardown() {
  // Report business failure rate
  if (typeof globalThis.__businessTotal !== 'undefined' && globalThis.__businessTotal > 0) {
    const rate = globalThis.__businessFailures / globalThis.__businessTotal;
    console.log(`business_failure_rate=${rate.toFixed(4)}`);
  }
}
