from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    wait_time = between(0, 0)
    host = BASE

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = "bench"
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.quantity = 2
        self.recover = False
        self.form = "MISSING"
        self.location = "MISSING"
        self.redirect = False
        self.iterations_done = 0
        self.max_iterations = 2

    def _extract_csrf(self, response):
        try:
            data = response.json()
            if isinstance(data, dict) and "csrf" in data:
                self.csrf = data["csrf"]
        except Exception:
            pass

    def _extract_etag(self, response):
        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag

    def _extract_recover(self, response):
        try:
            text = response.text
            if re.search(r'"error"\s*:\s*"(?:expired|session)"', text):
                self.recover = True
            else:
                self.recover = False
        except Exception:
            self.recover = False

    def _extract_form(self, response):
        try:
            text = response.text
            m = re.search(
                r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                text,
            )
            if m:
                self.form = m.group(1)
        except Exception:
            pass

    def _extract_location(self, response):
        loc = response.headers.get("Location")
        if loc:
            self.location = loc
            self.redirect = True
        else:
            self.redirect = False

    def _extract_grant(self, response):
        try:
            data = response.json()
            if isinstance(data, dict):
                if "csrf" in data:
                    self.csrf = data["csrf"]
                if "grant_id" in data:
                    self.grant = data["grant_id"]
        except Exception:
            pass

    def _extract_catalog(self, response):
        try:
            data = response.json()
            products = data.get("data", {}).get("products", [])
            for p in products:
                variants = p.get("variants", [])
                if variants and variants[0].get("in_stock") is True:
                    self.product = p.get("id")
                    self.variant = variants[0].get("id")
                    break
        except Exception:
            pass

    def _extract_cart(self, response):
        try:
            data = response.json()
            if isinstance(data, dict):
                if "csrf" in data:
                    self.csrf = data["csrf"]
                if "id" in data:
                    self.cart = data["id"]
                    self.has_cart = True
        except Exception:
            pass

    def _check_assertion(self, response, pattern, name):
        if not re.search(pattern, response.text):
            response.failure(f"Assertion failed: {name}")

    def _do_login_form(self):
        with self.client.get(
            "/v2/login-form",
            headers={"Content-Type": "application/json"},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_form(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure("login-form failed")
        return r

    def _do_login(self):
        payload = {
            "username": f"bench-{self.username}",
            "password": "bench",
            "csrf": self.form,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            headers={
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
            },
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            self._extract_location(r)
            if r.status_code not in (200, 302):
                r.failure("login failed")
            self._check_assertion(r, r'"csrf"\s*:', "login csrf")
        return r

    def _do_redirect_get(self):
        if not self.redirect:
            return None
        with self.client.get(
            self.location,
            headers={"Content-Type": "application/json"},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_grant(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure("redirect GET failed")
        return r

    def _do_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers={"Content-Type": "application/json"},
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_catalog(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure("catalog failed")
        return r

    def _do_create_cart(self):
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
            "grant_id": self.grant,
        }
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={
                "Content-Type": "application/json",
