            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 201:
                r.failure("order failed")
            self._check_assertion(r, r'"accepted"\s*:\s*true', "order accepted")
        return r

    def _do_renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
            },
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure("renew failed")
        return r

    def _do_recover_cart(self):
        if not self.has_cart:
            return None
        with self.client.post(
            f"/v2/carts/{self.cart}/recover",
            json={},
            headers={
                "Content-Type": "application/json",
                "X-CSRF-Token": self.csrf,
            },
            catch_response=True,
            allow_redirects=False,
        ) as r:
            self._extract_csrf(r)
            self._extract_recover(r)
            self._extract_etag(r)
            if r.status_code != 200:
                r.failure("cart recover failed")
        return r

    def _do_full_login_flow(self):
        self._do_login_form()
        self._do_login()
        if self.redirect:
            self._do_redirect_get()

    def _do_recovery_flow(self):
        # renew session
        self._do_renew()
        # if still recover (session revoked), re-login
        if self.recover:
            self._do_login_form()
            self._do_login()
            if self.redirect:
                self._do_redirect_get()
        # recover cart if exists
        if self.has_cart:
            self._do_recover_cart()

    def _do_journey(self):
        # Fresh login
        self._do_full_login_flow()

        # Catalog
        self._do_catalog()

        # Create cart
        self._do_create_cart()

        # Order
        self._do_order()

        # Recovery branch if needed
        if self.recover:
            self._do_recovery_flow()
            # Retry order once after recovery
            self._do_order()

    @task
    def run_iteration(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()
        self.iterations_done += 1
        self._do_journey()


