                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\""
                    + (MODE.equals("reservation") ? ",\"reservation_id\":\""
                        + session.getString("reservation") + "\"" : "") + "}"))
                .check(status().is(201), jsonPath("$.accepted").is("true"),
