import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    // --- Protocol ---
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench/3.15");

    // --- Feeder for accounts ---
    private static final List<Map<String, Object>> ACCOUNTS = new ArrayList<>();
    static {
        for (int i = 1; i <= 16; i++) {
            Map<String, Object> m = new HashMap<>();
            m.put("username", "bench-" + i);
            m.put("password", "bench");
            ACCOUNTS.add(m);
        }
    }

    private static final FeederBuilder<String> accountFeeder = listFeeder(ACCOUNTS).circular();

    // --- Session keys ---
    private static final String CSRF_KEY = "csrf";
    private static final String CART_ID_KEY = "cartId";
    private static final String ETAG_KEY = "etag";
    private static final String GRANT_ID_KEY = "grantId";
    private static final String RESERVATION_ID_KEY = "reservationId";
    private static final String IDEMPOTENCY_KEY = "idempotencyKey";
    private static final String LOGIN_NONCE_KEY = "loginNonce";
    private static final String CHALLENGE_FORM_ACTION_KEY = "challengeFormAction";
    private static final String CHALLENGE_INPUT_KEY = "challengeInput";
    private static final String CHALLENGE_ID_KEY = "challengeId";
    private static final String STATUS_URL_KEY = "statusUrl";
    private static final String RETRY_COUNT_KEY = "retryCount";
    private static final String WORK_START_KEY = "workStart";
    private static final String T0_KEY = "t0";
    private static final String PROFILE_KEY = "profile";

    // --- Profile selection: 0 = default, 1 = html_layout + reverse_catalog ---
    private static final List<Map<String, Object>> PROFILES = new ArrayList<>();
    static {
        PROFILES.add(new HashMap<>()); // profile 0: default
        Map<String, Object> p1 = new HashMap<>();
        p1.put("html_layout", 1);
        p1.put("reverse_catalog", true);
        PROFILES.add(p1);
    }

    private static final FeederBuilder<String> profileFeeder = listFeeder(PROFILES).circular();

    // --- Helper: extract CSRF from JSON ---
    private static String extractCsrf(String body) {
        if (body == null) return null;
        int idx = body.indexOf("\"csrf\"");
        if (idx < 0) return null;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return null;
        int start = body.indexOf('"', colon + 1);
        if (start < 0) return null;
        int end = body.indexOf('"', start + 1);
        if (end < 0) return null;
        return body.substring(start + 1, end);
    }

    // --- Helper: extract ETag from header ---
    private static String extractEtag(String headerValue) {
        if (headerValue == null) return null;
        String v = headerValue.trim();
        if (v.startsWith("W/")) v = v.substring(2);
        if (v.startsWith("\"") && v.endsWith("\"")) v = v.substring(1, v.length() - 1);
        return v;
    }

    // --- Helper: extract Location header ---
    private static String extractLocation(String headerValue) {
        if (headerValue == null) return null;
        return headerValue.trim();
    }

    // --- Helper: extract form action from HTML ---
    private static String extractFormAction(String html) {
        if (html == null) return null;
        int idx = html.indexOf("action=\"");
        if (idx < 0) return null;
        int start = idx + 8;
        int end = html.indexOf('"', start);
        if (end < 0) return null;
        return html.substring(start, end);
    }

    // --- Helper: extract challenge input value from HTML ---
    private static String extractChallengeInput(String html) {
        if (html == null) return null;
        int idx = html.indexOf("name=\"challenge\"");
        if (idx < 0) return null;
        int valueIdx = html.indexOf("value=\"", idx);
        if (valueIdx < 0) return null;
        int start = valueIdx + 7;
        int end = html.indexOf('"', start);
        if (end < 0) return null;
        return html.substring(start, end);
    }

    // --- Helper: extract challenge ID from form action ---
    private static String extractChallengeId(String action) {
        if (action == null) return null;
        int idx = action.lastIndexOf('/');
        if (idx < 0) return null;
        return action.substring(idx + 1);
    }

    // --- Helper: extract grant_id from JSON ---
    private static String extractGrantId(String body) {
        if (body == null) return null;
        int idx = body.indexOf("\"grant_id\"");
        if (idx < 0) return null;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return null;
        int start = body.indexOf('"', colon + 1);
        if (start < 0) return null;
        int end = body.indexOf('"', start + 1);
        if (end < 0) return null;
        return body.substring(start + 1, end);
    }

    // --- Helper: extract reservation_id from JSON ---
    private static String extractReservationId(String body) {
        if (body == null) return null;
        int idx = body.indexOf("\"reservation_id\"");
        if (idx < 0) return null;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return null;
        int start = body.indexOf('"', colon + 1);
        if (start < 0) return null;
        int end = body.indexOf('"', start + 1);
        if (end < 0) return null;
        return body.substring(start + 1, end);
    }

    // --- Helper: extract status_url from JSON ---
    private static String extractStatusUrl(String body) {
        if (body == null) return null;
        int idx = body.indexOf("\"status_url\"");
        if (idx < 0) return null;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return null;
        int start = body.indexOf('"', colon + 1);
        if (start < 0) return null;
        int end = body.indexOf('"', start + 1);
        if (end < 0) return null;
        return body.substring(start + 1, end);
    }

    // --- Helper: extract status from JSON ---
    private static String extractStatus(String body) {
        if (body == null) return null;
        int idx = body.indexOf("\"status\"");
        if (idx < 0) return null;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return null;
        int start = body.indexOf('"', colon + 1);
        if (start < 0) return null;
        int end = body.indexOf('"', start + 1);
        if (end < 0) return null;
        return body.substring(start + 1, end);
