        if (idx < 0) return false;
        int colon = body.indexOf(':', idx);
        if (colon < 0) return false;
        int start = colon + 1;
        while (start < body.length() && (body.charAt(start) == ' ' || body.charAt(start) == '"')) start++;
        if (start < body.length() && body.charAt(start) == 't') return true;
        return false;
    }

