    // --- Chain: Login ---
    private static ChainBuilder login() {
        return exec(
                http("GET /v2/login-form")
                        .get("/v2/login-form")
                        .check(
                                status().is(200),
                                regex("name=\"csrf\"[^>]*value=\"([^\"]*)\"").find().saveAs(CSRF_KEY),
                                regex("name=\"login_nonce\"[^>]*value=\"([^\"]*)\"").find().saveAs(LOGIN_NONCE_KEY)
                        )
        ).exec(
                http("POST /v2/login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                        .body(StringBody(session -> {
                            String csrf = session.getString(CSRF_KEY);
                            String username = session.getString("username");
                            String password = session.getString("password");
                            return "{\"username\":\"" + username + "\",\"password\":\"" + password + "\",\"csrf\":\"" + csrf + "\"}";
                        }))
                        .check(
                                status().in(200, 302),
                                header("Location").optional().saveAs("loginLocation"),
                                bodyString().optional().saveAs("loginBody")
                        )
        ).exec(session -> {
            String location = session.getString("loginLocation");
            if (location != null && !location.isEmpty()) {
                return session.set("loginRedirect", location);
            }
            String body = session.getString("loginBody");
            if (body != null) {
                String csrf = extractCsrf(body);
                if (csrf != null) {
                    return session.set(CSRF_KEY, csrf);
                }
            }
            return session;
        }).doIf(session -> session.contains("loginRedirect")).then(
                exec(
                        http("GET login redirect")
                                .get(session -> session.getString("loginRedirect"))
                                .check(
                                        status().is(200),
                                        bodyString().optional().saveAs("loginRedirectBody")
                                )
                ).exec(session -> {
                    String body = session.getString("loginRedirectBody");
                    if (body != null) {
                        String csrf = extractCsrf(body);
                        if (csrf != null) {
                            return session.set(CSRF_KEY, csrf);
                        }
                    }
                    return session;
                })
        );
    }

