    // --- Chain: Get catalog page (traverse at most 3 pages) ---
    private static ChainBuilder getCatalogPage() {
        return exec(
                http("GET /v2/catalog/page")
                        .get("/v2/catalog/page")
                        .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                        .check(
                                status().is(200),
                                bodyString().saveAs("catalogPageBody")
                        )
        ).exec(session -> {
            String body = session.getString("catalogPageBody");
            String productId = extractProductId(body);
            String variantId = extractVariantId(body);
            boolean inStock = extractInStock(body);
            String next = extractNext(body);
            if (productId != null && variantId != null && inStock) {
                session = session.set("productId", productId).set("variantId", variantId);
            }
            if (next != null && !next.isEmpty() && !next.equals("null")) {
                session = session.set("nextPage", next);
            } else {
                session = session.remove("nextPage");
            }
            return session;
        });
    }

    // --- Chain: Traverse catalog pages (up to 3) ---
    private static ChainBuilder traverseCatalog() {
        return exec(session -> session.set("pageCount", 0))
                .asLongAs(session -> session.getInt("pageCount") < 3 && session.contains("nextPage"))
                .on(
                        exec(session -> session.set("pageCount", session.getInt("pageCount") + 1))
                                .exec(
                                        http("GET catalog page")
                                                .get(session -> session.getString("nextPage"))
                                                .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                                                .check(
                                                        status().is(200),
                                                        bodyString().saveAs("catalogPageBody")
                                                )
                                ).exec(session -> {
                                    String body = session.getString("catalogPageBody");
                                    String productId = extractProductId(body);
                                    String variantId = extractVariantId(body);
                                    boolean inStock = extractInStock(body);
                                    String next = extractNext(body);
                                    if (productId != null && variantId != null && inStock) {
                                        session = session.set("productId", productId).set("variantId", variantId);
                                    }
                                    if (next != null && !next.isEmpty() && !next.equals("null")) {
                                        session = session.set("nextPage", next);
                                    } else {
                                        session = session.remove("nextPage");
                                    }
                                    return session;
                                })
                );
    }

