                    return session;
                }).exec(
                        http("PATCH /v2/carts/{id} retry")
                                .patch(session -> "/v2/carts/" + session.getString(CART_ID_KEY))
                                .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                                .header("If-Match", session -> session.getString(ETAG_KEY))
                                .body(StringBody("{\"quantity\":1}"))
                                .check(
