    // --- Chain: Create order (checkout) ---
    private static ChainBuilder createOrder() {
        return exec(session -> session.set(IDEMPOTENCY_KEY, generateIdempotencyKey()))
                .exec(
                        http("POST /v2/orders")
                                .post("/v2/orders")
                                .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                                .header("Idempotency-Key", session -> session.getString(IDEMPOTENCY_KEY))
                                .header("If-Match", session -> session.getString(ETAG_KEY))
                                .body(StringBody(session -> {
                                    String cartId = session.getString(CART_ID_KEY);
                                    String reservationId = session.getString(RESERVATION_ID_KEY);
                                    StringBuilder sb = new StringBuilder();
                                    sb.append("{\"cart_id\":\"").append(cartId).append("\"");
                                    if (reservationId != null && !reservationId.isEmpty()) {
                                        sb.append(",\"reservation_id\":\"").append(reservationId).append("\"");
                                    }
                                    sb.append("}");
                                    return sb.toString();
                                }))
                                .check(
                                        status().in(200, 201),
                                        bodyString().saveAs("orderBody")
