                    if (csrf != null) {
                        session = session.set(CSRF_KEY, csrf);
                    }
                    boolean accepted = extractAccepted(body);
                    if (!accepted) {
                        // Business failure, not success
                        session = session.markAsFailed();
                    }
                    return session;
                });
