    // --- Chain: Work operation (the scored pool) ---
    private static ChainBuilder workOperation() {
        return exec(session -> {
            // Record start timestamp for scoring
            return session.set(WORK_START_KEY, System.currentTimeMillis());
        }).exec(
                http("POST /v2/work")
                        .post("/v2/work")
                        .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                        .body(StringBody("{}"))
                        .check(
                                status().in(200, 429, 401, 500),
                                bodyString().optional().saveAs("workBody"),
                                header("Retry-After").optional().saveAs("retryAfter")
                        )
        ).exec(session -> {
            int statusCode = session.getInt("statusCode");
            String body = session.getString("workBody");
            String error = extractError(body);

            if (statusCode == 200) {
                boolean ok = extractOk(body);
                if (!ok) {
                    session = session.markAsFailed();
                }
                // Successful work event
                session = session.set("workSuccess", true);
            } else if (statusCode == 429) {
                // Scheduled 429, expected, retry up to 4 times
                session = session.set("workScheduled429", true);
                session = session.set(RETRY_COUNT_KEY, 0);
            } else if (statusCode == 401) {
                if ("expired".equals(error)) {
                    session = session.set("workExpired", true);
                } else if ("session".equals(error)) {
                    session = session.set("workRevoked", true);
                } else if ("denied".equals(error)) {
                    session = session.markAsFailed();
                    session = session.set("workDenied", true);
                }
            } else if (statusCode == 500) {
                session = session.markAsFailed();
                session = session.set("workUnexpectedError", true);
            }
            return session;
        });
    }

    // --- Chain: Retry work on scheduled 429 ---
    private static ChainBuilder retryWork429() {
        return asLongAs(session -> session.getInt(RETRY_COUNT_KEY) < 4 && session.contains("workScheduled429"))
                .on(
                        exec(session -> session.set(RETRY_COUNT_KEY, session.getInt(RETRY_COUNT_KEY) + 1))
                                .pause(Duration.ofSeconds(1))
                                .exec(
                                        http("POST /v2/work retry 429")
                                                .post("/v2/work")
                                                .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                                                .body(StringBody("{}"))
                                                .check(
                                                        status().in(200, 429, 401, 500),
                                                        bodyString().optional().saveAs("workBody"),
                                                        header("Retry-After").optional().saveAs("retryAfter")
                                                )
                                ).exec(session -> {
                                    int statusCode = session.getInt("statusCode");
                                    String body = session.getString("workBody");
                                    String error = extractError(body);

                                    if (statusCode == 200) {
                                        boolean ok = extractOk(body);
                                        if (!ok) {
                                            session = session.markAsFailed();
                                        }
                                        session = session.set("workSuccess", true);
                                        session = session.remove("workScheduled429");
                                    } else if (statusCode == 429) {
                                        // Still 429, continue retrying
                                    } else if (statusCode == 401) {
                                        if ("expired".equals(error)) {
                                            session = session.set("workExpired", true);
                                            session = session.remove("workScheduled429");
                                        } else if ("session".equals(error)) {
                                            session = session.set("workRevoked", true);
                                            session = session.remove("workScheduled429");
                                        } else if ("denied".equals(error)) {
                                            session = session.markAsFailed();
                                            session = session.set("workDenied", true);
                                            session = session.remove("workScheduled429");
                                        }
                                    } else if (statusCode == 500) {
                                        session = session.markAsFailed();
                                        session = session.set("workUnexpectedError", true);
                                        session = session.remove("workScheduled429");
                                    }
                                    return session;
                                })
                );
    }

