    // --- Chain: Full work with retry/expiry/revoked handling ---
    private static ChainBuilder workWithHandling() {
        return exec(workOperation())
                .doIf(session -> session.contains("workScheduled429")).then(
                        exec(retryWork429())
                )
                .doIf(session -> session.contains("workExpired")).then(
                        exec(handleWorkExpiry())
                )
                .doIf(session -> session.contains("workRevoked")).then(
                        exec(handleWorkRevoked())
                );
    }

    // --- Chain: Full journey (login, catalog, cart, reservation, order, work) ---
    private static ChainBuilder fullJourney() {
        return exec(login())
                .exec(getCatalog())
                .doIf(session -> session.getBoolean("reverse_catalog", false)).then(
                        exec(traverseCatalog())
                )
                .exec(getChallengeForm())
                .exec(postChallenge())
                .exec(createCart())
                .exec(getCart())
                .exec(updateCart())
                .exec(createReservation())
                .exec(pollReservation())
                .exec(createOrder())
                .exec(workWithHandling());
    }

