}

// Helper: extract grant_id from JSON
function extractGrantId(json) {
  if (json && json.grant_id) return json.grant_id;
  return null;
}

// Helper: extract reservation_id from JSON
function extractReservationId(json) {
  if (json && json.reservation_id) return json.reservation_id;
  return null;
}

// Helper: extract status_url from JSON
function extractStatusUrl(json) {
  if (json && json.status_url) return json.status_url;
  return null;
}

// Helper: extract next from JSON
function extractNext(json) {
  if (json && json.next) return json.next;
  return null;
}

// Helper: extract products from JSON
function extractProducts(json) {
  if (json && json.data && json.data.products) return json.data.products;
  return [];
}

// Helper: extract variants from product
function extractVariants(product) {
  if (product && product.variants) return product.variants;
  return [];
}

// Helper: extract ETag from response
function extractEtag(response) {
  const etag = response.headers['ETag'] || response.headers['Etag'] || response.headers['etag'];
