      const body = response.json();
      return body.error || null;
    } catch (e) {
      return null;
    }
  }
  return null;
}

// Helper: check if response is 429 scheduled
function isScheduled429(response) {
  if (response.status === 429) {
    try {
      const body = response.json();
      return body.scheduled === true || body.scheduled === 'true';
    } catch (e) {
      return false;
    }
  }
  return false;
}

// Helper: get Retry-After header
function getRetryAfter(response) {
  const ra = response.headers['Retry-After'] || response.headers['retry-after'];
  if (ra) {
    const seconds = parseInt(ra, 10);
    if (!isNaN(seconds)) return seconds * 1000;
  }
  return RETRY_AFTER_MS;
}

// Login function
function login() {
  const username = getRandomAccount();
