  }

  // POST login
  const loginPayload = JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  });

  const loginResponse = http.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { route: 'login' }
  });

  if (loginResponse.status === 302) {
    const location = extractLocation(loginResponse);
    if (location) {
      const followResponse = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        tags: { route: 'login-follow' }
      });
      if (followResponse.status === 200) {
        try {
          const json = followResponse.json();
          csrfToken = json.csrf || csrf;
          currentUser = json.user || username;
          sessionCookie = followResponse.cookies;
          return true;
        } catch (e) {
          unexpectedErrors.add(1);
          return false;
        }
      }
    }
    unexpectedErrors.add(1);
    return false;
  }

  if (loginResponse.status === 200) {
    try {
      const json = loginResponse.json();
      csrfToken = json.csrf || csrf;
      currentUser = json.user || username;
      sessionCookie = loginResponse.cookies;
      return true;
    } catch (e) {
      unexpectedErrors.add(1);
      return false;
    }
  }

  unexpectedErrors.add(1);
  return false;
}

// Session renewal
