  if (challengeResponse.status === 302) {
    const location = extractLocation(challengeResponse);
    if (location) {
      const followResponse = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        tags: { route: 'challenge-follow' }
      });
      if (followResponse.status === 200) {
        try {
          const json = followResponse.json();
          if (json.csrf) csrfToken = json.csrf;
          return extractGrantId(json);
        } catch (e) {
          return null;
        }
      }
    }
  } else if (challengeResponse.status === 200) {
    try {
      const json = challengeResponse.json();
      if (json.csrf) csrfToken = json.csrf;
      return extractGrantId(json);
    } catch (e) {
      return null;
