      'Content-Type': 'application/json',
      'X-CSRF-Token': csrfToken
    },
    redirects: 0,
    tags: { route: 'cart-create' }
  });

  if (cartResponse.status === 201) {
    try {
      const json = cartResponse.json();
      cartId = json.id;
      if (json.csrf) csrfToken = json.csrf;
      cartEtag = extractEtag(cartResponse);
      return true;
    } catch (e) {
      return false;
