// Perform work operation (the scored operation)
function performWork() {
  const workPayload = '{}';

  let retries = 0;
  let response = null;

  while (retries <= MAX_RETRIES_429) {
    const startTime = Date.now();

    response = http.post(`${BASE_URL}/v2/work`, workPayload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrfToken
      },
      redirects: 0,
      tags: { route: 'work' }
    });

    businessResponses.add(1);

    if (response.status === 200) {
      try {
        const json = response.json();
        if (json.ok === true) {
          workCompletions.add(1);
          return { success: true, status: 200, startTime };
        }
      } catch (e) {
        unexpectedErrors.add(1);
        return { success: false, status: response.status, startTime };
      }
    }

    if (response.status === 429 && isScheduled429(response)) {
      scheduled429s.add(1);
      retries++;
      if (retries <= MAX_RETRIES_429) {
        const retryAfter = getRetryAfter(response);
        sleep(retryAfter / 1000);
        continue;
      }
      return { success: false, status: 429, startTime };
    }

    if (response.status === 401) {
      const error = get401Error(response);
      if (error === 'expired') {
        // Try renewal
        if (renewSession()) {
          if (cartId) {
            recoverCart();
          }
          // Retry once
          retries++;
          if (retries <= MAX_RETRIES_429) {
            continue;
          }
        }
        return { success: false, status: 401, startTime };
      } else if (error === 'session') {
        // Session revoked - need fresh login
        if (login()) {
          if (cartId) {
            recoverCart();
          }
          retries++;
          if (retries <= MAX_RETRIES_429) {
            continue;
          }
        }
        return { success: false, status: 401, startTime };
      } else {
        // denied - fail assertion
        unexpectedErrors.add(1);
        return { success: false, status: 401, startTime };
      }
    }

    if (response.status >= 500) {
      unexpectedErrors.add(1);
      return { success: false, status: response.status, startTime };
    }

    if (response.status >= 400) {
      unexpectedErrors.add(1);
      return { success: false, status: response.status, startTime };
    }

    // Other status - unexpected
    unexpectedErrors.add(1);
    return { success: false, status: response.status, startTime };
  }

  return { success: false, status: response ? response.status : 0, startTime: Date.now() };
}

// Full journey: login -> catalog -> cart -> reservation -> order -> work
function fullJourney() {
  // Fresh login
  if (!login()) {
    unexpectedErrors.add(1);
    return false;
  }

  // Fresh cart
  cartId = null;
  cartEtag = null;
  grantId = null;
  reservationId = null;

  // Get catalog
