  if (products.length === 0) {
    unexpectedErrors.add(1);
    return false;
  }

  // Select a product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    const variants = extractVariants(product);
    for (const variant of variants) {
      if (variant.in_stock) {
        selectedProduct = product;
        selectedVariant = variant;
        break;
      }
    }
    if (selectedProduct) break;
  }

  if (!selectedProduct || !selectedVariant) {
    unexpectedErrors.add(1);
    return false;
  }

  // Try to get grant_id from challenge
  const challengeForm = getChallengeForm();
  if (challengeForm) {
    grantId = completeChallenge(challengeForm.action, challengeForm.inputName);
  }

  // Create cart
  if (!createCart(selectedProduct.id, selectedVariant.id, grantId)) {
    unexpectedErrors.add(1);
    return false;
  }

  // Update cart quantity
  if (!updateCartQuantity(1)) {
    unexpectedErrors.add(1);
    return false;
  }

  // Create reservation
  const statusUrl = createReservation();
  if (statusUrl) {
    reservationId = pollReservation(statusUrl);
  }

  // Create order
  if (!createOrder()) {
    unexpectedErrors.add(1);
    return false;
  }

  // Perform work (the scored operation)
  const workResult = performWork();

  if (workResult.success) {
    workStarts.add(1);
    workStartTimestamps.push(workResult.startTime);
    return true;
  }

  return false;
}

// Setup function
export function setup() {
  // Record owner seeds
  const seeds = [];
  for (let i = 0; i < 16; i++) {
    seeds.push(`bench-${i}-seed-${Date.now()}-${Math.random()}`);
  }
  seeds.push(`bench-seed-${Date.now()}-${Math.random()}`);

  return {
    seeds: seeds,
    timestamp: Date.now()
  };
}

// Main function
export default function(data) {
  // Assign profile based on VU
  profileIndex = (__VU - 1) % PROFILES.length;
  const profile = PROFILES[profileIndex];

  // Record owner seed
  ownerSeed = data.seeds[(__VU - 1) % data.seeds.length];

  // Perform full journey
  const journeyStart = Date.now();
  const success = fullJourney();

  if (!success) {
    unexpectedErrors.add(1);
  }

  // Small sleep to avoid tight loop
  sleep(0.1);
}

// Options
export const options = {
  scenarios: {
    main: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${TOTAL_SECONDS}s`,
      preAllocatedVUs: 2,
      maxVUs: MAX_VUS,
    },
  },
  thresholds: {
    // Custom thresholds for monitoring
    'unexpected_errors': ['count < 100'],
  },
  // Disable handleSummary
  handleSummary: null,
};

// Teardown function
export function teardown(data) {
  // Record final state
  const finalState = {
    ownerSeeds: data.seeds,
    workStarts: workStarts ? workStarts.value : 0,
    workCompletions: workCompletions ? workCompletions.value : 0,
    unexpectedErrors: unexpectedErrors ? unexpectedErrors.value : 0,
    businessResponses: businessResponses ? businessResponses.value : 0,
    scheduled429s: scheduled429s ? scheduled429s.value : 0,
    workStartTimestamps: workStartTimestamps,
    timestamp: Date.now()
  };

  // Write to stdout for audit
  console.log(JSON.stringify(finalState));

  return finalState;
}
