import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const workStarts = new Counter('work_starts');
const workCompletions = new Counter('work_completions');
const unexpectedErrors = new Rate('unexpected_errors');
const droppedWork = new Rate('dropped_work');
const rawWorkRate = new Counter('raw_work_rate');
const businessResponses = new Counter('business_responses');
const businessFailures = new Counter('business_failures');
const workStartTimestamps = new Trend('work_start_timestamps', true);

const PROFILES = [
  { delay_seconds: 0.2 },
  { delay_seconds: 0.2, html_layout: 1, reverse_catalog: true }
];

const USERS = ['bench-1', 'bench-2', 'bench-3', 'bench-4', 'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12', 'bench-13', 'bench-14', 'bench-15', 'bench-16'];

function getProfile(vuId) {
  return PROFILES[(vuId - 1) % PROFILES.length];
}

function login(vuId) {
  const username = USERS[(vuId - 1) % USERS.length];
  const password = 'bench';

  // GET login form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  if (formRes.status !== 200) {
    fail(`Login form failed: ${formRes.status}`);
  }

  // Extract CSRF from input[name=csrf]
  const csrfMatch = formRes.body.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
    formRes.body.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i);

  if (!csrfMatch) {
    fail('CSRF token not found in login form');
  }

  const csrf = csrfMatch[1];

  // POST login
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (!location) {
      fail('302 without Location header');
    }
    const followRes = http.get(new URL(location, BASE_URL).toString(), {
      redirects: 0,
      tags: { name: 'login_redirect' }
    });
    if (followRes.status !== 200) {
      fail(`Login redirect failed: ${followRes.status}`);
    }
    const followCsrf = followRes.body.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
      followRes.body.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
    if (followCsrf) {
      return { csrf: followCsrf[1], user: username };
    }
    // Try to parse JSON from redirect response
    try {
      const json = followRes.json();
      if (json.csrf) {
        return { csrf: json.csrf, user: username };
      }
    } catch (e) {
      // ignore
    }
    fail('Could not extract CSRF after login redirect');
  }

  if (loginRes.status !== 200) {
    fail(`Login failed: ${loginRes.status}`);
  }

  const loginJson = loginRes.json();
  if (!loginJson.csrf) {
    fail('Login response missing csrf');
  }

  return { csrf: loginJson.csrf, user: username };
}

function renewSession(csrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    const json = renewRes.json();
    return { csrf: json.csrf || csrf, renewed: true };
  }

  return { csrf: csrf, renewed: false };
}

function recoverCart(cartId, csrf) {
  if (!cartId) return null;
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_recover' }
  });
  return recoverRes;
}

function getCatalog(profile, csrf) {
  const products = [];
  let nextUrl = null;

  if (profile.reverse_catalog) {
    // Traverse pages
    let pageUrl = '/v2/catalog/page';
    let pagesTraversed = 0;
    while (pageUrl && pagesTraversed < 3) {
      const pageRes = http.get(`${BASE_URL}${pageUrl}`, {
        headers: { 'X-CSRF-Token': csrf },
        tags: { name: 'catalog_page' }
      });
      if (pageRes.status !== 200) break;
      const pageData = pageRes.json();
      if (pageData.data && pageData.data.products && pageData.data.products.length > 0) {
        products.push(...pageData.data.products);
      }
      nextUrl = pageData.next || null;
      if (!nextUrl) break;
      pageUrl = nextUrl;
      pagesTraversed++;
    }
  } else {
    const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'catalog' }
    });
    if (catalogRes.status === 200) {
      const catalogData = catalogRes.json();
      if (catalogData.data && catalogData.data.products) {
        products.push(...catalogData.data.products);
      }
    }
  }

  return products;
}

function createCart(productId, variantId, grantId, csrf) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) {
    payload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'cart_create' }
  });

  if (cartRes.status === 201) {
    const json = cartRes.json();
    return {
      cartId: json.id,
      csrf: json.csrf || csrf,
      etag: cartRes.headers['ETag'] || null
    };
  }

  return null;
}

function getCart(cartId, csrf) {
  const cartRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'cart_get' }
  });

  if (cartRes.status === 200) {
    return {
      etag: cartRes.headers['ETag'] || null,
      csrf: csrf
    };
  }

  return null;
}

function updateCart(cartId, quantity, etag, csrf) {
  const updateRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
    quantity: quantity
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag
    },
    tags: { name: 'cart_update' }
  });

  if (updateRes.status === 412) {
    // Re-read and retry once
    const cartInfo = getCart(cartId, csrf);
    if (cartInfo && cartInfo.etag) {
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${cartId}`, JSON.stringify({
        quantity: quantity
      }), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
          'If-Match': cartInfo.etag
        },
        tags: { name: 'cart_update_retry' }
      });
      if (retryRes.status === 200) {
        const json = retryRes.json();
        return {
          csrf: json.csrf || csrf,
          etag: retryRes.headers['ETag'] || cartInfo.etag
        };
      }
    }
    return null;
  }

  if (updateRes.status === 200) {
    const json = updateRes.json();
    return {
      csrf: json.csrf || csrf,
      etag: updateRes.headers['ETag'] || etag
    };
  }

  return null;
}

function getChallenge(csrf) {
  const challengeFormRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'challenge_form' }
  });

  if (challengeFormRes.status !== 200) return null;

  const actionMatch = challengeFormRes.body.match(/<form[^>]*action=["']([^"']+)["']/i);
  const challengeMatch = challengeFormRes.body.match(/<input[^>]*name=["']challenge["'][^>]*value=["']([^"']+)["']/i) ||
    challengeFormRes.body.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']challenge["']/i);

  if (!actionMatch || !challengeMatch) return null;

  const action = actionMatch[1];
  const challenge = challengeMatch[1];

  const challengeRes = http.post(new URL(action, BASE_URL).toString(), JSON.stringify({
    challenge: challenge
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'challenge_submit' }
  });

  if (challengeRes.status === 302) {
    const location = challengeRes.headers['Location'];
    if (!location) return null;
    const grantRes = http.get(new URL(location, BASE_URL).toString(), {
      headers: { 'X-CSRF-Token': csrf },
      tags: { name: 'challenge_grant' }
    });
    if (grantRes.status === 200) {
      const json = grantRes.json();
      return {
        grantId: json.grant_id,
        csrf: json.csrf || csrf
      };
    }
  }

  return null;
}

function createReservation(cartId, csrf) {
  const resRes = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: cartId
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    tags: { name: 'reservation_create' }
  });

  if (resRes.status !== 202) return null;

  const json = resRes.json();
  const statusUrl = json.status_url;
  const newCsrf = json.csrf || csrf;

  if (!statusUrl) return null;

  // Poll at least 50ms apart, at most 5 times
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const pollRes = http.get(new URL(statusUrl, BASE_URL).toString(), {
      headers: { 'X-CSRF-Token': newCsrf },
      tags: { name: 'reservation_poll' }
    });

    if (pollRes.status === 200) {
      const pollJson = pollRes.json();
      if (pollJson.status === 'ready' && pollJson.reservation_id) {
        return {
          reservationId: pollJson.reservation_id,
          csrf: pollJson.csrf || newCsrf
        };
      }
      if (pollJson.status === 'failed') {
        return null;
      }
      // pending - continue polling
    }
  }

  return null;
}

function createOrder(cartId, reservationId, csrf, etag) {
  const idempotencyKey = `order-${cartId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  const payload = {
    cart_id: cartId
  };
  if (reservationId) {
    payload.reservation_id = reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) {
    headers['If-Match'] = etag;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    tags: { name: 'order_create' }
  });

  if (orderRes.status === 201) {
    const json = orderRes.json();
    if (json.accepted === true) {
      return {
        orderId: json.id,
        csrf: json.csrf || csrf,
        accepted: true
      };
    }
    return {
      csrf: json.csrf || csrf,
      accepted: false
    };
  }

  return null;
}

function doWork(csrf, profile) {
  const startTime = Date.now();

  const payload = {};
  if (profile.delay_seconds) {
    payload.delay_seconds = profile.delay_seconds;
  }
  if (profile.html_layout) {
    payload.html_layout = profile.html_layout;
  }
  if (profile.reverse_catalog) {
    payload.reverse_catalog = profile.reverse_catalog;
  }

  let workRes = null;
  let retries = 0;

  while (retries <= 4) {
    workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify(payload), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf
      },
      tags: { name: 'work' }
    });

    rawWorkRate.add(1);
    businessResponses.add(1);

    if (workRes.status === 200) {
      const json = workRes.json();
      if (json.ok === true) {
        workCompletions.add(1);
        return {
          success: true,
          csrf: json.csrf || csrf,
          startTime: startTime
        };
      }
      // ok not true - unexpected
      unexpectedErrors.add(1);
      businessFailures.add(1);
      return {
        success: false,
        csrf: csrf,
        startTime: startTime
      };
    }

    if (workRes.status === 429) {
      // Scheduled 429 - expected, retry after Retry-After
      const retryAfter = parseInt(workRes.headers['Retry-After'] || '1');
      if (retries < 4) {
        sleep(retryAfter);
        retries++;
        continue;
      }
      // Exhausted retries - dropped work
      droppedWork.add(1);
      return {
        success: false,
        csrf: csrf,
        startTime: startTime,
        dropped: true
      };
    }

    if (workRes.status === 401) {
      const errorBody = workRes.json();
      const errorType = errorBody.error;

      if (errorType === 'expired') {
        // Session expired - renew and retry once
        const renewResult = renewSession(csrf);
        if (renewResult.renewed) {
          csrf = renewResult.csrf;
          retries++;
          continue;
        }
        // Renew failed - session revoked, need full re-login
        const loginResult = login(parseInt(__VU));
        csrf = loginResult.csrf;
        retries++;
        continue;
      }

      if (errorType === 'session') {
        // Session revoked - re-login
        const loginResult = login(parseInt(__VU));
        csrf = loginResult.csrf;
        retries++;
        continue;
      }

      if (errorType === 'denied') {
        // Not expiry - fail assertion
        unexpectedErrors.add(1);
        businessFailures.add(1);
        return {
          success: false,
          csrf: csrf,
          startTime: startTime
        };
      }

      // Unknown 401 error
      unexpectedErrors.add(1);
      businessFailures.add(1);
      return {
        success: false,
        csrf: csrf,
        startTime: startTime
      };
    }

    if (workRes.status === 500) {
      // Unexpected error
      unexpectedErrors.add(1);
      businessFailures.add(1);
      return {
        success: false,
        csrf: csrf,
        startTime: startTime
      };
    }

    // Other status codes
    unexpectedErrors.add(1);
    businessFailures.add(1);
    return {
      success: false,
      csrf: csrf,
      startTime: startTime
    };
  }

  // Exhausted retries
  droppedWork.add(1);
  return {
    success: false,
    csrf: csrf,
    startTime: startTime,
    dropped: true
  };
}

