  if (!cartResult) {
    fail('Failed to create cart');
  }

  let cartId = cartResult.cartId;
  csrf = cartResult.csrf;
  let etag = cartResult.etag;

  // Update cart quantity
  const updateResult = updateCart(cartId, 1, etag, csrf);
  if (updateResult) {
    csrf = updateResult.csrf;
    etag = updateResult.etag;
