  if (orderResult) {
    csrf = orderResult.csrf;
  }

  // Do work - this is the scored operation
  const workResult = doWork(csrf, profile);

  if (workResult.success) {
    workStarts.add(1);
    workStartTimestamps.add(workResult.startTime);
  }
