    def do_work(self):
        """Perform work operation."""
        with self.client.post("/v2/work",
                             json={},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True, name="work") as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("ok"):
                        return True
                    else:
                        resp.failure("Work not ok")
                        return False
                except:
                    resp.failure("Invalid work response")
                    return False
            elif resp.status_code == 429:
                # Scheduled 429 - retry with Retry-After
                retry_after = resp.headers.get("Retry-After", "1")
                try:
                    retry_after_seconds = int(retry_after)
                except:
                    retry_after_seconds = 1

                if self.work_retries < 4:
                    self.work_retries += 1
                    time.sleep(retry_after_seconds)
                    return self.do_work()
                else:
                    # Expected scheduled 429 after max retries
                    return True
            elif resp.status_code == 401:
                try:
                    error_data = resp.json()
                    error_type = error_data.get("error", "")
                    if error_type == "expired":
                        if self.renew_session():
                            return self.do_work()
                        else:
                            resp.failure("Work session renew failed")
                            return False
                    elif error_type == "session":
                        self.login()
                        return self.do_work()
                    else:
                        resp.failure(f"Work denied: {error_type}")
                        return False
                except:
                    resp.failure(f"Work 401: {resp.status_code}")
                    return False
            elif resp.status_code == 500:
                resp.failure("Work 500 unexpected")
                return False
            else:
                resp.failure(f"Work failed: {resp.status_code}")
                return False

    @task
    def shop_journey(self):
        """Main shopping journey."""
        if self.iteration_count >= self.max_iterations:
            raise StopUser()

        self.iteration_count += 1

        # Fresh login and cart for each journey
        self.login()
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0

        # Get catalog
        products = self.get_catalog()
        if not products:
            # Try catalog page
            product, next_url = self.get_catalog_page()
            if product:
                products = [product]
                # Traverse at most 3 pages
                for _ in range(2):
                    if next_url:
                        product, next_url = self.get_catalog_page(next_url)
                        if product:
                            products.append(product)
                    else:
                        break

        if not products:
            return

        # Select a product and variant
        product = random.choice(products)
        variants = product.get("variants", [])
        if not variants:
            return

        variant = random.choice(variants)
        product_id = product.get("id")
        variant_id = variant.get("id")

        if not product_id or not variant_id:
            return

        # Get challenge for grant_id
        self.get_challenge()

        # Create cart
        if not self.create_cart(product_id, variant_id):
            return

        # Get cart
        self.get_cart()

        # Update quantity
        quantity = random.randint(1, 20)
        self.update_cart_quantity(quantity)

        # Create reservation
        self.create_reservation()

        # Create order
        self.create_order()

        # Do work
        self.do_work()

        # Apply profile delay
        time.sleep(self.profile_delay)


class WorkShape(LoadTestShape):
    """Load test shape for work pool."""

    def __init__(self):
        super().__init__()
        self.start_time = None
        self.t0 = None
        self.phase = "warmup"
        self.current_users = 2
        self.rate = 5
        self.target_users = 2
        self.phase_start = None

    def tick(self):
        """Control user count over time."""
        current_time = time.time()

        if self.start_time is None:
            self.start_time = current_time
            self.phase_start = current_time
            return (self.current_users, 2)

        elapsed = current_time - self.start_time

        # T0 is when first authenticated eligible POST anchors
        # We'll use a fixed T0 at 10s from launch
        if self.t0 is None and elapsed >= 10:
            self.t0 = current_time

        if self.t0 is None:
            # Before T0 - warmup phase
            return (self.current_users, 2)

        time_since_t0 = current_time - self.t0

        if time_since_t0 < 5:
            # Warmup 5s
            self.phase = "warmup"
            self.current_users = 2
        elif time_since_t0 < 35:
            # Scored phase - 30s
            self.phase = "scored"
            # Maintain 5 starts/s with 2 users
            self.current_users = 2
        elif time_since_t0 < 40:
            # Drain phase - 5s
            self.phase = "drain"
            self.current_users = 0
        else:
            # End
            return None

        return (self.current_users, 2)


# Track work operation timestamps for scoring
work_start_times = []
authenticated_work_events = []


@events.request.add_listener
def on_request(request_type, name, response_time, response_length, exception, context, **kwargs):
    """Track work operation start timestamps."""
    if name == "work" and exception is None:
        # Check if this is an authenticated request with successful owner work event
        # and response status below 400
        if context and hasattr(context, 'user'):
            user = context.user
            if user.authenticated:
                # Record the start timestamp
                # We approximate start time as current time minus response time
                start_time = time.time() - (response_time / 1000.0)
                work_start_times.append(start_time)
                authenticated_work_events.append({
                    "timestamp": start_time,
                    "user": user.owner_seed,
                    "status": "success"
                })
