    private static final int WARMUP_SECONDS = 5;
    private static final int SCORED_SECONDS = 30;
    private static final int DRAIN_SECONDS = 5;
    private static final int TOTAL_SECONDS = WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS;

    // Users
    private static final List<String> USERNAMES = Arrays.asList(
        "bench-1", "bench-2", "bench-3", "bench-4", "bench-5", "bench-6", "bench-7", "bench-8",
        "bench-9", "bench-10", "bench-11", "bench-12", "bench-13", "bench-14", "bench-15", "bench-16"
    );
    private static final String PASSWORD = "bench";

