    // Feeder for users
    private static final Iterator<Map<String, Object>> userFeeder = 
        USERNAMES.stream()
            .map(u -> {
                Map<String, Object> m = new HashMap<>();
                m.put("username", u);
                m.put("password", PASSWORD);
                return m;
            })
            .iterator();

    // Scenario: work pool operation
    private static final ChainBuilder workJourney = exec(
        http("Login Form")
            .get("/v2/login-form")
            .check(
                regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs("login_csrf"),
                regex("name=\"csrf\" value='([^']+)'").saveAs("login_csrf_alt")
            )
    ).exec(session -> {
        String csrf = session.getString("login_csrf");
        if (csrf == null || csrf.isEmpty()) {
            csrf = session.getString("login_csrf_alt");
        }
        return session.set("login_csrf_final", csrf);
    }).exec(
        http("Login")
            .post("/v2/login")
            .header("X-CSRF-Token", session -> session.getString("login_csrf_final"))
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{login_csrf_final}\"}"))
            .check(
                status().is(200),
                jsonPath("$.csrf").saveAs("csrf_token"),
                jsonPath("$.user").saveAs("user_id")
            )
    ).exec(
        http("Work Operation")
            .post("/v2/work")
            .header("X-CSRF-Token", session -> session.getString("csrf_token"))
            .body(StringBody("{}"))
            .check(
                status().is(200),
                jsonPath("$.ok").is("true")
            )
    );

    private static final ScenarioBuilder workScenario = scenario("Work Pool Scenario")
        .feed(userFeeder)
        .exec(workJourney);

    {
        setUp(
            workScenario.injectOpen(
                constantUsersPerSec(TARGET_RATE).during(Duration.ofSeconds(TOTAL_SECONDS))
            )
        ).protocols(httpProtocol)
         .maxDuration(Duration.ofSeconds(TOTAL_SECONDS + 10));
    }
}
