import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Counter } from 'k6/metrics';
import { randomIntBetween } from 'https://jslib.k6.io/k6-utils/1.4.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const profiles = [
  { delay_seconds: 0.5 },
  { delay_seconds: 0.5, html_layout: 1, reverse_catalog: true }
];

const unexpectedErrorRate = new Rate('unexpected_errors');
const businessFailureRate = new Rate('business_failure');
const workSuccessCount = new Counter('work_success');
const workAttemptCount = new Counter('work_attempts');
const eligibleWorkCount = new Counter('eligible_work');

const USER_COUNT = 16;
const PASSWORD = 'bench';

function getUsername(vuId) {
  const idx = (vuId % USER_COUNT) + 1;
  return `bench-${idx}`;
}

function getProfile(vuId) {
  return profiles[vuId % profiles.length];
}

function extractCsrf(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const match2 = html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  if (match2) return match2[1];
  const match3 = html.match(/name=["']csrf["']/i);
  if (match3) {
    const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
    if (inputMatch) {
      const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
      if (valMatch) return valMatch[1];
    }
  }
  return null;
}

function extractNonce(html) {
  const match = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const match2 = html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  if (match2) return match2[1];
  return null;
}

function extractChallengeAction(html) {
  const match = html.match(/<form[^>]*action=["']([^"']*challenges[^"']*)["'][^>]*>/i);
  if (match) return match[1];
  const match2 = html.match(/action=["']([^"']*challenges[^"']*)["'][^>]*>/i);
  if (match2) return match2[1];
  return null;
}

function extractChallengeInput(html) {
  const match = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  if (match) {
    const valMatch = match[0].match(/value=["']([^"']*)["']/i);
    if (valMatch) return valMatch[1];
  }
  return '';
}

function extractGrantId(html) {
  const match = html.match(/grant_id["']?\s*[:=]\s*["']([^"']+)["']/i);
  if (match) return match[1];
  const match2 = html.match(/"grant_id"\s*:\s*"([^"]+)"/i);
  if (match2) return match2[1];
  return null;
}

function extractCsrfFromJson(json) {
  if (json && json.csrf) return json.csrf;
  return null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  if (loc) return loc;
  return null;
}

function extractETag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  if (etag) return etag;
  return null;
}

function extractNextFromJson(json) {
  if (json && json.next) return json.next;
  return null;
}

function extractProductsFromJson(json) {
  if (json && json.data && json.data.products) return json.data.products;
  return [];
}

function extractProductFromJson(json) {
  if (json && json.data && json.data.product) return json.data.product;
  return null;
}

function extractVariantsFromProduct(product) {
  if (product && product.variants) return product.variants;
  return [];
}

function extractCartIdFromJson(json) {
  if (json && json.id) return json.id;
  return null;
}

function extractReservationStatusUrl(json) {
  if (json && json.status_url) return json.status_url;
  return null;
}

function extractReservationStatus(json) {
  if (json && json.status) return json.status;
  return null;
}

function extractReservationId(json) {
  if (json && json.reservation_id) return json.reservation_id;
  return null;
}

function extractOrderId(json) {
  if (json && json.id) return json.id;
  return null;
}

function extractAccepted(json) {
  if (json && json.accepted !== undefined) return json.accepted;
  return null;
}

function extractRetryAfter(headers) {
  const ra = headers['Retry-After'];
  if (ra) {
    const parsed = parseInt(ra, 10);
    if (!isNaN(parsed)) return parsed;
  }
  return 1;
}

function login(httpClient, username, password) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });
  if (formRes.status !== 200) {
    return { ok: false, status: formRes.status, error: 'login_form_failed' };
  }
  const csrf = extractCsrf(formRes.body);
  const nonce = extractNonce(formRes.body);
  if (!csrf) {
    return { ok: false, status: formRes.status, error: 'no_csrf' };
  }
  const loginPayload = JSON.stringify({ username, password, csrf });
  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });
  if (loginRes.status === 302) {
    const loc = extractLocation(loginRes.headers);
    if (loc) {
      const followRes = httpClient.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, {
        redirects: 0,
        tags: { name: 'login_redirect' }
      });
      if (followRes.status !== 200) {
        return { ok: false, status: followRes.status, error: 'login_redirect_failed' };
      }
      const newCsrf = extractCsrfFromJson(parseJsonSafe(followRes.body));
      return { ok: true, csrf: newCsrf || csrf, status: followRes.status };
    }
    return { ok: false, status: loginRes.status, error: 'no_location' };
  }
  if (loginRes.status === 200) {
    const json = parseJsonSafe(loginRes.body);
    const newCsrf = extractCsrfFromJson(json);
    return { ok: true, csrf: newCsrf || csrf, status: loginRes.status };
  }
  return { ok: false, status: loginRes.status, error: 'login_failed' };
}

function parseJsonSafe(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function getCatalog(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'catalog' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, products: [], next: null };
  const json = parseJsonSafe(res.body);
  const products = extractProductsFromJson(json);
  const next = extractNextFromJson(json);
  return { ok: true, status: res.status, products, next };
}

function getCatalogPage(httpClient, csrf, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = httpClient.get(url, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'catalog_page' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, product: null, next: null };
  const json = parseJsonSafe(res.body);
  const product = extractProductFromJson(json);
  const next = extractNextFromJson(json);
  return { ok: true, status: res.status, product, next };
}

function createCart(httpClient, csrf, productId, variantId, grantId) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;
  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'create_cart' }
  });
  if (res.status !== 201) return { ok: false, status: res.status, cartId: null, csrf: null, etag: null };
  const json = parseJsonSafe(res.body);
  const cartId = extractCartIdFromJson(json);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  const etag = extractETag(res.headers);
  return { ok: true, status: res.status, cartId, csrf: newCsrf, etag };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'get_cart' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, etag: null };
  const etag = extractETag(res.headers);
  return { ok: true, status: res.status, etag };
}

function patchCart(httpClient, csrf, cartId, quantity, etag) {
  const payload = JSON.stringify({ quantity });
  const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
  if (etag) headers['If-Match'] = etag;
  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers,
    tags: { name: 'patch_cart' }
  });
  if (res.status === 412) {
    // Re-read and retry once
    const reRead = getCart(httpClient, csrf, cartId);
    if (!reRead.ok) return { ok: false, status: reRead.status, etag: null, csrf };
    const retryHeaders = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
    if (reRead.etag) retryHeaders['If-Match'] = reRead.etag;
    const retryRes = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
      headers: retryHeaders,
      tags: { name: 'patch_cart_retry' }
    });
    if (retryRes.status !== 200 && retryRes.status !== 204) {
      return { ok: false, status: retryRes.status, etag: null, csrf };
    }
    const retryJson = parseJsonSafe(retryRes.body);
    const newCsrf = extractCsrfFromJson(retryJson) || csrf;
    const newEtag = extractETag(retryRes.headers);
    return { ok: true, status: retryRes.status, etag: newEtag, csrf: newCsrf };
  }
  if (res.status !== 200 && res.status !== 204) {
    return { ok: false, status: res.status, etag: null, csrf };
  }
  const json = parseJsonSafe(res.body);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  const newEtag = extractETag(res.headers);
  return { ok: true, status: res.status, etag: newEtag, csrf: newCsrf };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'create_reservation' }
  });
  if (res.status !== 202) return { ok: false, status: res.status, statusUrl: null, csrf: null };
  const json = parseJsonSafe(res.body);
  const statusUrl = extractReservationStatusUrl(json);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  return { ok: true, status: res.status, statusUrl, csrf: newCsrf };
}

function pollReservation(httpClient, csrf, statusUrl) {
  let currentCsrf = csrf;
  for (let i = 0; i < 5; i++) {
    sleep(0.05 + (i * 0.01));
    const url = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
    const res = httpClient.get(url, {
      headers: { 'X-CSRF-Token': currentCsrf },
      tags: { name: 'poll_reservation' }
    });
    if (res.status !== 200) {
      return { ok: false, status: res.status, reservationId: null, csrf: currentCsrf };
    }
    const json = parseJsonSafe(res.body);
    const status = extractReservationStatus(json);
    const newCsrf = extractCsrfFromJson(json) || currentCsrf;
    currentCsrf = newCsrf;
    if (status === 'ready') {
      const reservationId = extractReservationId(json);
      return { ok: true, status: res.status, reservationId, csrf: currentCsrf };
    }
    if (status === 'failed') {
      return { ok: false, status: res.status, reservationId: null, csrf: currentCsrf, error: 'reservation_failed' };
    }
    // pending, continue polling
  }
  return { ok: false, status: 0, reservationId: null, csrf: currentCsrf, error: 'reservation_timeout' };
}

function createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) headers['If-Match'] = etag;
  const res = httpClient.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers,
    tags: { name: 'create_order' }
  });
  if (res.status !== 201 && res.status !== 200) {
    return { ok: false, status: res.status, orderId: null, csrf: null, accepted: null };
  }
  const json = parseJsonSafe(res.body);
  const accepted = extractAccepted(json);
  const orderId = extractOrderId(json);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  return { ok: true, status: res.status, orderId, csrf: newCsrf, accepted };
}

function getChallengeForm(httpClient, csrf) {
  const res = httpClient.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'challenge_form' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, action: null, challenge: null };
  const action = extractChallengeAction(res.body);
  const challenge = extractChallengeInput(res.body);
  return { ok: true, status: res.status, action, challenge };
}

function postChallenge(httpClient, csrf, action, challengeValue) {
  const url = action.startsWith('http') ? action : `${BASE_URL}${action}`;
  const res = httpClient.post(url, JSON.stringify({ challenge: challengeValue }), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'post_challenge' }
  });
  if (res.status !== 302) return { ok: false, status: res.status, location: null };
  const loc = extractLocation(res.headers);
  return { ok: true, status: res.status, location: loc };
}

function getChallengeResult(httpClient, csrf, location) {
  const url = location.startsWith('http') ? location : `${BASE_URL}${location}`;
  const res = httpClient.get(url, {
    headers: { 'X-CSRF-Token': csrf },
    tags: { name: 'challenge_result' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, grantId: null, csrf: null };
  const json = parseJsonSafe(res.body);
  const grantId = extractGrantId(res.body) || (json && json.grant_id) || null;
  const newCsrf = extractCsrfFromJson(json) || csrf;
  return { ok: true, status: res.status, grantId, csrf: newCsrf };
}

function renewSession(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'renew_session' }
  });
  if (res.status !== 200) return { ok: false, status: res.status, csrf: null };
  const json = parseJsonSafe(res.body);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  return { ok: true, status: res.status, csrf: newCsrf };
}

function recoverCart(httpClient, csrf, cartId) {
  const res = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'recover_cart' }
  });
  if (res.status !== 200 && res.status !== 201) return { ok: false, status: res.status, csrf: null };
  const json = parseJsonSafe(res.body);
  const newCsrf = extractCsrfFromJson(json) || csrf;
  return { ok: true, status: res.status, csrf: newCsrf };
}

function doWork(httpClient, csrf, profile) {
  const payload = {};
  if (profile.delay_seconds !== undefined) payload.delay_seconds = profile.delay_seconds;
  if (profile.html_layout !== undefined) payload.html_layout = profile.html_layout;
  if (profile.reverse_catalog !== undefined) payload.reverse_catalog = profile.reverse_catalog;

  const startTime = Date.now();
  let res = httpClient.post(`${BASE_URL}/v2/work`, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    tags: { name: 'work' }
  });
  workAttemptCount.add(1);

  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const retryAfter = extractRetryAfter(res.headers);
    sleep(retryAfter);
    res = httpClient.post(`${BASE_URL}/v2/work`, JSON.stringify(payload), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      tags: { name: 'work_retry' }
    });
    workAttemptCount.add(1);
    retries++;
  }

  const endTime = Date.now();
  const duration = endTime - startTime;

  if (res.status === 200) {
    const json = parseJsonSafe(res.body);
    if (json && json.ok === true) {
      workSuccessCount.add(1);
      eligibleWorkCount.add(1);
      return { ok: true, status: res.status, duration, csrf: extractCsrfFromJson(json) || csrf };
    }
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, status: res.status, duration, csrf: extractCsrfFromJson(json) || csrf, error: 'work_not_ok' };
  }
  if (res.status === 429) {
    // Scheduled 429 after retries exhausted - expected, not a completion
    businessFailureRate.add(1);
    return { ok: false, status: res.status, duration, csrf, error: 'scheduled_429' };
  }
  if (res.status === 401) {
    const json = parseJsonSafe(res.body);
    const errorType = json && json.error ? json.error : 'unknown';
    businessFailureRate.add(1);
    if (errorType === 'expired') {
      return { ok: false, status: res.status, duration, csrf, error: 'expired' };
    }
    if (errorType === 'session') {
      return { ok: false, status: res.status, duration, csrf, error: 'session_revoked' };
    }
    if (errorType === 'denied') {
      unexpectedErrorRate.add(1);
      return { ok: false, status: res.status, duration, csrf, error: 'denied' };
    }
    unexpectedErrorRate.add(1);
    return { ok: false, status: res.status, duration, csrf, error: 'unknown_401' };
  }
  if (res.status === 500) {
    unexpectedErrorRate.add(1);
    businessFailureRate.add(1);
    return { ok: false, status: res.status, duration, csrf, error: 'server_500' };
  }
  unexpectedErrorRate.add(1);
  businessFailureRate.add(1);
  return { ok: false, status: res.status, duration, csrf, error: 'unexpected_status' };
}

function handleExpiredSession(httpClient, csrf, cartId, operationFn) {
  // Try renew
  const renewRes = renewSession(httpClient, csrf);
  if (renewRes.ok) {
    let newCsrf = renewRes.csrf;
    if (cartId) {
      const recoverRes = recoverCart(httpClient, newCsrf, cartId);
      if (recoverRes.ok) {
        newCsrf = recoverRes.csrf;
      }
    }
    // Retry the interrupted operation once
    return operationFn(httpClient, newCsrf);
  }
  // Session revoked - get fresh login
  const username = getUsername(__VU);
  const loginRes = login(httpClient, username, PASSWORD);
  if (!loginRes.ok) {
    return { ok: false, status: loginRes.status, csrf: null, error: 'relogin_failed' };
  }
  let newCsrf = loginRes.csrf;
  if (cartId) {
    const recoverRes = recoverCart(httpClient, newCsrf, cartId);
    if (recoverRes.ok) {
      newCsrf = recoverRes.csrf;
    }
  }
  return operationFn(httpClient, newCsrf);
}

function performJourney(httpClient, vuId) {
  const username = getUsername(vuId);
  const profile = getProfile(vuId);

  // Fresh login
  const loginRes = login(httpClient, username, PASSWORD);
  if (!loginRes.ok) {
    unexpectedErrorRate.add(1);
    return { ok: false, error: 'login_failed' };
  }
  let csrf = loginRes.csrf;

  // Fresh cart
  const catalogRes = getCatalog(httpClient, csrf);
  if (!catalogRes.ok || catalogRes.products.length === 0) {
    unexpectedErrorRate.add(1);
    return { ok: false, error: 'catalog_failed' };
  }

  let product = catalogRes.products[0];
  let variant = product.variants && product.variants.length > 0 ? product.variants[0] : null;

  // Traverse at most 3 pages if needed
  let pagesTraversed = 0;
  let nextUrl = catalogRes.next;
  while ((!variant || !variant.in_stock) && nextUrl && pagesTraversed < 3) {
    const pageRes = getCatalogPage(httpClient, csrf, nextUrl);
    if (!pageRes.ok || !pageRes.product) break;
    product = pageRes.product;
    variant = product.variants && product.variants.length > 0 ? product.variants[0] : null;
    nextUrl = pageRes.next;
    pagesTraversed++;
  }

  if (!product || !variant) {
    unexpectedErrorRate.add(1);
    return { ok: false, error: 'no_product' };
  }

  // Try challenge for grant_id
  let grantId = null;
  const challengeFormRes = getChallengeForm(httpClient, csrf);
  if (challengeFormRes.ok && challengeFormRes.action) {
    const postChallengeRes = postChallenge(httpClient, csrf, challengeFormRes.action, challengeFormRes.challenge || '');
    if (postChallengeRes.ok && postChallengeRes.location) {
      const challengeResultRes = getChallengeResult(httpClient, csrf, postChallengeRes.location);
      if (challengeResultRes.ok) {
        grantId = challengeResultRes.grantId;
        csrf = challengeResultRes.csrf;
      }
    }
  }

  // Create cart
  let cartRes = createCart(httpClient, csrf, product.id, variant.id, grantId);
  if (!cartRes.ok) {
    if (cartRes.status === 401) {
      const retryRes = handleExpiredSession(httpClient, csrf, null, (client, newCsrf) => {
        return createCart(client, newCsrf, product.id, variant.id, grantId);
      });
      if (!retryRes.ok) {
        unexpectedErrorRate.add(1);
        return { ok: false, error: 'create_cart_failed_after_retry' };
      }
      cartRes = retryRes;
    } else {
      unexpectedErrorRate.add(1);
      return { ok: false, error: 'create_cart_failed' };
    }
  }
  csrf = cartRes.csrf;
  const cartId = cartRes.cartId;
  let etag = cartRes.etag;

  // Patch cart
  const quantity = randomIntBetween(1, 20);
  let patchRes = patchCart(httpClient, csrf, cartId, quantity, etag);
  if (!patchRes.ok) {
    if (patchRes.status === 401) {
      const retryRes = handleExpiredSession(httpClient, csrf, cartId, (client, newCsrf) => {
        return patchCart(client, newCsrf, cartId, quantity, etag);
      });
      if (!retryRes.ok) {
        unexpectedErrorRate.add(1);
        return { ok: false, error: 'patch_cart_failed_after_retry' };
      }
      patchRes = retryRes;
    } else {
      unexpectedErrorRate.add(1);
      return { ok: false, error: 'patch_cart_failed' };
    }
  }
  csrf = patchRes.csrf;
  etag = patchRes.etag;

  // Create reservation
  let reservationId = null;
  const reservationRes = createReservation(httpClient, csrf, cartId);
  if (reservationRes.ok) {
    csrf = reservationRes.csrf;
    const pollRes = pollReservation(httpClient, csrf, reservationRes.statusUrl);
    if (pollRes.ok) {
      csrf = pollRes.csrf;
      reservationId = pollRes.reservationId;
    }
  } else if (reservationRes.status === 401) {
    const retryRes = handleExpiredSession(httpClient, csrf, cartId, (client, newCsrf) => {
      return createReservation(client, newCsrf, cartId);
    });
    if (retryRes.ok) {
      csrf = retryRes.csrf;
      const pollRes = pollReservation(httpClient, csrf, retryRes.statusUrl);
      if (pollRes.ok) {
        csrf = pollRes.csrf;
        reservationId = pollRes.reservationId;
      }
    }
  }

  // Create order
  const idempotencyKey = `order-${cartId}-${Date.now()}`;
  let orderRes = createOrder(httpClient, csrf, cartId, reservationId, idempotencyKey, etag);
  if (!orderRes.ok) {
    if (orderRes.status === 401) {
      const retryRes = handleExpiredSession(httpClient, csrf, cartId, (client, newCsrf) => {
        return createOrder(client, newCsrf, cartId, reservationId, idempotencyKey, etag);
      });
      if (!retryRes.ok) {
        unexpectedErrorRate.add(1);
        return { ok: false, error: 'create_order_failed_after_retry' };
      }
      orderRes = retryRes;
    } else {
      unexpectedErrorRate.add(1);
      return { ok: false, error: 'create_order_failed' };
    }
  }
  csrf = orderRes.csrf;

  if (orderRes.accepted === false) {
    // Business failure, not success
    businessFailureRate.add(1);
    return { ok: false, error: 'order_not_accepted' };
  }

  // Do work
  const workRes = doWork(httpClient, csrf, profile);
  if (!workRes.ok) {
    if (workRes.error === 'expired') {
      const retryRes = handleExpiredSession(httpClient, csrf, cartId, (client, newCsrf) => {
        return doWork(client, newCsrf, profile);
      });
      if (!retryRes.ok) {
        if (retryRes.error === 'scheduled_429') {
          return { ok: false, error: 'scheduled_429' };
        }
        unexpectedErrorRate.add(1);
        return { ok: false, error: 'work_failed_after_retry' };
      }
      return { ok: true, workRes: retryRes };
    }
    if (workRes.error === 'session_revoked') {
      const retryRes = handleExpiredSession(httpClient, csrf, cartId, (client, newCsrf) => {
        return doWork(client, newCsrf, profile);
      });
      if (!retryRes.ok) {
        if (retryRes.error === 'scheduled_429') {
          return { ok: false, error: 'scheduled_429' };
        }
        unexpectedErrorRate.add(1);
        return { ok: false, error: 'work_failed_after_revoke' };
      }
      return { ok: true, workRes: retryRes };
    }
    if (workRes.error === 'scheduled_429') {
      return { ok: false, error: 'scheduled_429' };
    }
    unexpectedErrorRate.add(1);
    return { ok: false, error: 'work_failed' };
  }

  return { ok: true, workRes };
}

