                return False
            import re
            match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not match:
                match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', resp.text)
            if not match:
                resp.failure("No CSRF token in login form")
                return False
            self.csrf_token = match.group(1)

        with self.client.post("/v2/login",
                             json={"username": self.username, "password": PASSWORD, "csrf": self.csrf_token},
                             headers={"X-CSRF-Token": self.csrf_token},
                             catch_response=True) as resp:
            if resp.status_code >= 400:
                resp.failure(f"Login failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
            except:
                pass
        return True

    def handle_401(self, resp):
        try:
            error_data = resp.json()
            error_type = error_data.get("error", "")
        except:
            error_type = ""

        if error_type == "expired":
            with self.client.post("/v2/session/renew",
                                 json={},
                                 headers={"X-CSRF-Token": self.csrf_token},
                                 catch_response=True) as renew_resp:
                if renew_resp.status_code < 400:
                    try:
                        data = renew_resp.json()
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                    except:
                        pass
                    return True
                else:
                    return self.login()
        elif error_type == "session":
            return self.login()
        return False

    @task
    def do_work_only(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()

        self.iteration_count += 1

        retries = 0
        while retries <= 4:
            with self.client.post("/v2/work",
                                 json={},
                                 headers={"X-CSRF-Token": self.csrf_token},
                                 catch_response=True) as resp:
                if resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After", "1")
                    try:
                        wait_time = float(retry_after)
                    except:
                        wait_time = 1.0
                    time.sleep(wait_time)
                    retries += 1
                    continue
                elif resp.status_code == 401:
                    if self.handle_401(resp):
                        retries += 1
                        continue
                    else:
                        resp.failure("401 denied on work")
                        return
                elif resp.status_code == 200:
                    try:
                        data = resp.json()
                        if data.get("ok") == True:
                            return
                        else:
                            resp.failure("Work not ok")
                            return
                    except:
                        resp.failure("Work parse error")
                        return
                elif resp.status_code == 500:
                    resp.failure("Unexpected 500 on work")
                    return
                else:
                    resp.failure(f"Work failed: {resp.status_code}")
                    return


class TestShape(LoadTestShape):
    """
    Shape for sustaining 10 starts/s against 500ms work.
    Warmup 5s, scored period 30s (T0+5 to T0+35), drain <=5s.
    Phased targets: 5/15/5 for three 10s scored plateaus.
    """

    def __init__(self):
        super().__init__()
        self.start_time = None
        self.t0 = None
        self.phase = "warmup"
        self.current_users = 0
        self.target_users = 0

    def tick(self):
        current_time = time.time()

        if self.start_time is None:
            self.start_time = current_time
            self.t0 = current_time + 10  # T0 within 10s of launch
            return (2, 2)  # Start with 2 users

        elapsed = current_time - self.start_time

        # Phase 1: Warmup (0-5s)
        if elapsed < 5:
            # Ramp up to sustain 10/s
            # With 500ms work, need ~5 concurrent users for 10/s
            # But we need to account for login overhead
            target = 8
            if self.current_users < target:
                self.current_users = min(target, self.current_users + 2)
            return (self.current_users, self.current_users)

        # Phase 2: Scored period (5-35s)
        elif elapsed < 35:
            # Three 10s plateaus: 5/15/5 targets
            scored_elapsed = elapsed - 5

            if scored_elapsed < 10:
                # First plateau: target 5/s
                # With 500ms work, need ~3 concurrent users
                target = 4
            elif scored_elapsed < 20:
                # Second plateau: target 15/s
                # With 500ms work, need ~8 concurrent users
                target = 10
            else:
                # Third plateau: target 5/s
                target = 4

            # Adjust for rate
            if self.current_users < target:
                self.current_users = min(target, self.current_users + 1)
            elif self.current_users > target:
                self.current_users = max(target, self.current_users - 1)

            return (self.current_users, self.current_users)

        # Phase 3: Drain (35-40s)
        elif elapsed < 40:
            # Ramp down
            if self.current_users > 0:
                self.current_users = max(0, self.current_users - 2)
                return (self.current_users, self.current_users)
            return None

        # Done
        else:
            return None
