import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import io.gatling.javaapi.core.CoreDsl.*;
import io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class ModelSimulation extends Simulation {

    // --- Protocol ---
    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static HttpProtocolBuilder httpProtocol = http
            .baseUrl(BASE_URL)
            .disableAutoRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-bench");

    // --- Feeder for users ---
    private static final List<Map<String, Object>> USERS = new ArrayList<>();
    static {
        for (int i = 1; i <= 16; i++) {
            Map<String, Object> m = new HashMap<>();
            m.put("username", "bench-" + i);
            m.put("password", "bench");
            USERS.add(m);
        }
    }
    private static final Iterator<Map<String, Object>> userFeeder = USERS.iterator();

    // --- Session keys ---
    private static final String CSRF_KEY = "csrf";
    private static final String CART_ID_KEY = "cartId";
    private static final String ETAG_KEY = "etag";
    private static final String GRANT_ID_KEY = "grantId";
    private static final String RESERVATION_ID_KEY = "reservationId";
    private static final String IDEMPOTENCY_KEY = "idempotencyKey";
    private static final String WORK_RETRY_KEY = "workRetry";

    // --- Chain definitions ---

    // 1. Login form
    private static final ChainBuilder getLoginForm = exec(
            http("GET login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("name=\"csrf\" value=\"([^\"]+)\"").saveAs(CSRF_KEY))
    );

    // 2. Login
    private static final ChainBuilder doLogin = exec(
            http("POST login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                    .body(StringBody(session -> {
                        String csrf = session.getString(CSRF_KEY);
                        String username = session.getString("username");
                        String password = session.getString("password");
                        return String.format("{\"username\":\"%s\",\"password\":\"%s\",\"csrf\":\"%s\"}", username, password, csrf);
                    }))
                    .check(status().in(200, 302))
                    .check(
                            jsonPath("$.csrf").optional().saveAs(CSRF_KEY),
                            header("Location").optional().saveAs("loginLocation")
                    )
    ).exec(session -> {
        if (session.contains("loginLocation")) {
            String loc = session.getString("loginLocation");
            return session.set("loginLocation", loc);
        }
        return session;
    }).doIf(session -> session.contains("loginLocation")).then(
            exec(http("GET login redirect")
                    .get(session -> session.getString("loginLocation"))
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs(CSRF_KEY))
            )
    );

    // 3. Create cart (with optional grant_id)
    private static final ChainBuilder createCart = exec(session -> {
        // Pick a random product/variant from catalog (we'll fetch catalog first)
        return session;
    }).exec(
            http("GET catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[0].id").saveAs("productId"))
                    .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
    ).exec(session -> {
        String grantId = session.contains(GRANT_ID_KEY) ? session.getString(GRANT_ID_KEY) : null;
        String body;
        if (grantId != null) {
            body = String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}",
                    session.getString("productId"), session.getString("variantId"), grantId);
        } else {
            body = String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\"}",
                    session.getString("productId"), session.getString("variantId"));
        }
        return session.set("cartBody", body);
    }).exec(
            http("POST create cart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                    .body(StringBody(session -> session.getString("cartBody")))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs(CART_ID_KEY))
                    .check(jsonPath("$.csrf").optional().saveAs(CSRF_KEY))
                    .check(header("ETag").optional().saveAs(ETAG_KEY))
    );

    // 4. Update cart quantity (PATCH)
    private static final ChainBuilder updateCart = exec(session -> {
        int qty = ThreadLocalRandom.current().nextInt(1, 21);
        return session.set("quantity", qty);
    }).exec(
            http("PATCH cart quantity")
                    .patch(session -> "/v2/carts/" + session.getString(CART_ID_KEY))
                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                    .header("If-Match", session -> session.getString(ETAG_KEY))
                    .body(StringBody(session -> String.format("{\"quantity\":%d}", session.getInt("quantity"))))
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs(CSRF_KEY))
                    .check(header("ETag").optional().saveAs(ETAG_KEY))
    );

    // 5. Create reservation
    private static final ChainBuilder createReservation = exec(
            http("POST reservation")
                    .post("/v2/reservations")
                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                    .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString(CART_ID_KEY))))
                    .check(status().is(202))
                    .check(jsonPath("$.status_url").saveAs("statusUrl"))
                    .check(jsonPath("$.csrf").optional().saveAs(CSRF_KEY))
    ).exec(session -> session.set("pollCount", 0))
            .asLongAs(session -> session.getInt("pollCount") < 5 && !session.contains(RESERVATION_ID_KEY)).on(
                    pause(Duration.ofMillis(100)).exec(
                            http("GET reservation status")
                                    .get(session -> session.getString("statusUrl"))
                                    .check(status().is(200))
                                    .check(jsonPath("$.status").saveAs("resStatus"))
                                    .check(jsonPath("$.reservation_id").optional().saveAs(RESERVATION_ID_KEY))
                    ).exec(session -> {
                        int count = session.getInt("pollCount") + 1;
                        return session.set("pollCount", count);
                    }).doIf(session -> session.getString("resStatus").equals("failed")).then(
                            exec(session -> session.markAsFailed())
                    )
            );

    // 6. Create order (checkout)
    private static final ChainBuilder createOrder = exec(session -> {
        String idemKey = UUID.randomUUID().toString();
        return session.set(IDEMPOTENCY_KEY, idemKey);
    }).exec(session -> {
        String cartId = session.getString(CART_ID_KEY);
        String reservationId = session.contains(RESERVATION_ID_KEY) ? session.getString(RESERVATION_ID_KEY) : null;
        String body;
        if (reservationId != null) {
            body = String.format("{\"cart_id\":\"%s\",\"reservation_id\":\"%s\"}", cartId, reservationId);
        } else {
            body = String.format("{\"cart_id\":\"%s\"}", cartId);
        }
        return session.set("orderBody", body);
    }).exec(
            http("POST order")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                    .header("Idempotency-Key", session -> session.getString(IDEMPOTENCY_KEY))
                    .header("If-Match", session -> session.getString(ETAG_KEY))
                    .body(StringBody(session -> session.getString("orderBody")))
                    .check(status().is(201))
                    .check(jsonPath("$.accepted").is("true"))
                    .check(jsonPath("$.id").saveAs("orderId"))
                    .check(jsonPath("$.csrf").optional().saveAs(CSRF_KEY))
    );

    // 7. Work operation (the scored operation)
    private static final ChainBuilder doWork = exec(session -> session.set(WORK_RETRY_KEY, 0))
            .asLongAs(session -> session.getInt(WORK_RETRY_KEY) < 4).on(
                    exec(
                            http("POST work")
                                    .post("/v2/work")
                                    .header("X-CSRF-Token", session -> session.getString(CSRF_KEY))
                                    .body(StringBody("{}"))
                                    .check(status().in(200, 429, 500))
                                    .check(
                                            jsonPath("$.ok").optional().saveAs("workOk"),
                                            header("Retry-After").optional().saveAs("retryAfter")
                                    )
                    ).exec(session -> {
                        int status = session.getInt("status");
                        if (status == 200) {
                            return session.set("workSuccess", true);
                        } else if (status == 429) {
                            int retry = session.getInt(WORK_RETRY_KEY) + 1;
                            return session.set(WORK_RETRY_KEY, retry).set("workSuccess", false);
                        } else {
                            // 500 or other unexpected
                            return session.markAsFailed().set("workSuccess", false);
                        }
                    }).doIf(session -> session.getInt("status") == 429).then(
                            pause(Duration.ofSeconds(1))
                    )
            ).doIf(session -> !session.getBoolean("workSuccess")).then(
                    exec(session -> session.markAsFailed())
            );

    // Full journey: login -> cart -> update -> reservation -> order -> work
    private static final ChainBuilder journey = exec(getLoginForm)
            .exec(doLogin)
            .exec(createCart)
            .exec(updateCart)
            .exec(createReservation)
            .exec(createOrder)
            .exec(doWork);

    // --- Scenario ---
    private static final ScenarioBuilder scn = scenario("ModelSimulation")
            .feed(userFeeder)
            .exec(journey);

    {
        setUp(
                scn.injectOpen(
                        // Phase 1: 5 starts/s for 10 seconds
                        constantUsersPerSec(5).during(Duration.ofSeconds(10)),
                        // Phase 2: 15 starts/s for 10 seconds
                        constantUsersPerSec(15).during(Duration.ofSeconds(10)),
                        // Phase 3: 5 starts/s for 10 seconds
                        constantUsersPerSec(5).during(Duration.ofSeconds(10))
                )
        ).protocols(httpProtocol)
                .maxDuration(Duration.ofSeconds(45))
                .assertions(
                        global().successfulRequests().percent().gt(99.0)
                );
    }
}
