import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Custom metrics
const workSuccess = new Counter('work_success');
const workError = new Counter('work_error');
const workDropped = new Counter('work_dropped');
const businessFailure = new Rate('business_failure');
const workLatency = new Trend('work_latency', true);

// Configuration
const USERS = ['bench-1', 'bench-2', 'bench-3', 'bench-4', 'bench-5', 'bench-6', 'bench-7', 'bench-8',
               'bench-9', 'bench-10', 'bench-11', 'bench-12', 'bench-13', 'bench-14', 'bench-15', 'bench-16'];
const PASSWORD = 'bench';
const MAX_VUS = 32;
const T0_WINDOW = 10; // seconds to anchor T0
const WARMUP = 5;
const SCORE_DURATION = 30; // 6 windows of 5s
const DRAIN = 5;
const PLATEAU_DURATION = 10;
const TARGETS = [5, 15, 5];
const RETRY_AFTER_MS = 1000;
const MAX_RETRIES = 4;

// Phase timing (relative to T0)
// T0 = first authenticated eligible POST /v2/work
// Warmup: [T0, T0+5)
// Score: [T0+5, T0+35) - 6 windows of 5s
//   Window 0: [T0+5, T0+10) - target 5/s
//   Window 1: [T0+10, T0+15) - target 5/s
//   Window 2: [T0+15, T0+20) - target 15/s
//   Window 3: [T0+20, T0+25) - target 15/s
//   Window 4: [T0+25, T0+30) - target 5/s
//   Window 5: [T0+30, T0+35) - target 5/s
// Drain: [T0+35, T0+40]

// Global state
let t0 = null;
let t0Set = false;
let workCounts = new Array(6).fill(0);
let workTimestamps = [];
let activeVUs = 0;
let maxActiveVUs = 0;
let totalWorkAttempts = 0;
let totalWorkSuccess = 0;
let totalWorkErrors = 0;
let totalWorkDropped = 0;
let unexpectedFailures = 0;
let totalBusinessResponses = 0;
let scheduled429s = 0;
let retryAfterViolations = 0;
let burstCounts = new Array(6).fill(0);
let burstTimestamps = new Array(6).fill(null).map(() => []);

// Per-VU state
class VUState {
  constructor() {
    this.cookies = {};
    this.csrf = null;
    this.sessionCookie = null;
    this.user = null;
    this.cartId = null;
    this.cartEtag = null;
    this.grantId = null;
    this.reservationId = null;
    this.orderId = null;
    this.idempotencyKey = null;
    this.loggedIn = false;
    this.cartRecovered = false;
  }
}

function getCookie(cookies, name) {
  for (const c of cookies) {
    if (c.startsWith(name + '=')) {
      return c.split('=')[1].split(';')[0];
    }
  }
  return null;
}

function parseCookies(response) {
  const setCookies = response.headers['Set-Cookie'];
  if (!setCookies) return [];
  if (Array.isArray(setCookies)) return setCookies;
  return [setCookies];
}

function mergeCookies(state, response) {
  const cookies = parseCookies(response);
  for (const c of cookies) {
    const name = c.split('=')[0];
    const value = c.split('=')[1].split(';')[0];
    state.cookies[name] = value;
    if (name === 'session') {
      state.sessionCookie = value;
    }
  }
}

function getCookieHeader(state) {
  return Object.entries(state.cookies).map(([k, v]) => `${k}=${v}`).join('; ');
}

function extractCsrfFromHtml(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const inputMatch = html.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
  }
  return null;
}

function login(state) {
  // GET login form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Cookie': getCookieHeader(state) },
    redirects: 0,
  });
  mergeCookies(state, formRes);

  const csrf = extractCsrfFromHtml(formRes.body);
  if (!csrf) {
    return false;
  }
  state.csrf = csrf;

  // POST login
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: state.user,
    password: PASSWORD,
    csrf: csrf,
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Cookie': getCookieHeader(state),
    },
    redirects: 0,
  });
  mergeCookies(state, loginRes);

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const locRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        headers: { 'Cookie': getCookieHeader(state) },
        redirects: 0,
      });
      mergeCookies(state, locRes);
    }
  }

  if (loginRes.status >= 200 && loginRes.status < 400) {
    try {
      const body = JSON.parse(loginRes.body);
      if (body.csrf) state.csrf = body.csrf;
      if (body.user) state.user = body.user;
    } catch (e) {
      // ignore
    }
    state.loggedIn = true;
    return true;
  }

  // Check if login succeeded via session cookie
  if (state.sessionCookie) {
    state.loggedIn = true;
    return true;
  }

  return false;
}

function renewSession(state) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Cookie': getCookieHeader(state),
    },
    redirects: 0,
  });
  mergeCookies(state, res);
  if (res.status >= 200 && res.status < 400) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return false;
  const res = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Cookie': getCookieHeader(state),
    },
    redirects: 0,
  });
  mergeCookies(state, res);
  if (res.status >= 200 && res.status < 400) {
    try {
      const body = JSON.parse(res.body);
      if (body.csrf) state.csrf = body.csrf;
    } catch (e) {}
    return true;
  }
  return false;
}

function handle401(state, operation) {
  // Check error type from response body
  let errorType = 'expired';
  try {
    const body = JSON.parse(operation.response.body);
    if (body.error === 'session') errorType = 'session';
    else if (body.error === 'denied') errorType = 'denied';
    else if (body.error === 'expired') errorType = 'expired';
  } catch (e) {}

  if (errorType === 'denied') {
    return false; // fail assertion
  }

  if (errorType === 'expired') {
    if (renewSession(state)) {
      if (state.cartId) {
        recoverCart(state);
      }
      return true;
    }
    return false;
  }

  if (errorType === 'session') {
    // Revoked - get fresh login
    state.loggedIn = false;
    state.cookies = {};
    state.sessionCookie = null;
    state.csrf = null;
    if (login(state)) {
      if (state.cartId) {
        recoverCart(state);
      }
      return true;
    }
    return false;
  }

  return false;
}

function doWork(state) {
  const now = Date.now();

  // Check if T0 is set
  if (!t0Set) {
    // This is the first authenticated eligible POST /v2/work
    t0 = now;
    t0Set = true;
    console.log(`T0 anchored at ${t0}`);
  }

  const res = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Cookie': getCookieHeader(state),
    },
    redirects: 0,
  });

  totalWorkAttempts++;
  totalBusinessResponses++;

  const elapsed = now - t0;
  const windowIndex = Math.floor((elapsed - WARMUP * 1000) / 5000);

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.ok === true) {
        totalWorkSuccess++;
        workSuccess.add(1);
        workLatency.add(res.timings.duration);

        // Record timestamp for burst tracking
        if (windowIndex >= 0 && windowIndex < 6) {
          workCounts[windowIndex]++;
          burstTimestamps[windowIndex].push(now);
        }
        return true;
      }
    } catch (e) {}
    unexpectedFailures++;
    workError.add(1);
    totalWorkErrors++;
    return false;
  } else if (res.status === 429) {
    scheduled429s++;
    // Check Retry-After
    const retryAfter = res.headers['Retry-After'];
    if (retryAfter) {
      const retryAfterSec = parseInt(retryAfter);
      if (retryAfterSec < 1) {
        retryAfterViolations++;
      }
    } else {
      retryAfterViolations++;
    }
    return false;
  } else if (res.status === 401) {
    // Handle 401
    const recovered = handle401(state, { response: res });
    if (recovered) {
      // Retry the operation once
      const retryRes = http.post(`${BASE_URL}/v2/work`, '{}', {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'Cookie': getCookieHeader(state),
        },
        redirects: 0,
      });
      totalWorkAttempts++;
      totalBusinessResponses++;

      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.ok === true) {
            totalWorkSuccess++;
            workSuccess.add(1);
            workLatency.add(retryRes.timings.duration);
            if (windowIndex >= 0 && windowIndex < 6) {
              workCounts[windowIndex]++;
              burstTimestamps[windowIndex].push(now);
            }
            return true;
          }
        } catch (e) {}
      } else if (retryRes.status === 429) {
        scheduled429s++;
        return false;
      }
      unexpectedFailures++;
      workError.add(1);
      totalWorkErrors++;
      return false;
    }
    unexpectedFailures++;
    workError.add(1);
    totalWorkErrors++;
    return false;
  } else if (res.status === 500) {
    unexpectedFailures++;
    workError.add(1);
    totalWorkErrors++;
    return false;
  } else {
    unexpectedFailures++;
    workError.add(1);
    totalWorkErrors++;
    return false;
  }
}

function setupJourney(state) {
  // Fresh login
  state.cookies = {};
  state.sessionCookie = null;
  state.csrf = null;
  state.cartId = null;
  state.cartEtag = null;
  state.grantId = null;
  state.reservationId = null;
  state.orderId = null;
  state.idempotencyKey = null;
  state.loggedIn = false;
  state.cartRecovered = false;

  if (!login(state)) {
    return false;
  }

  // Create cart
  // First get catalog to find a product
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'Cookie': getCookieHeader(state) },
    redirects: 0,
  });
  mergeCookies(state, catalogRes);

  let productId = null;
  let variantId = null;
  try {
    const body = JSON.parse(catalogRes.body);
    if (body.data && body.data.products && body.data.products.length > 0) {
      productId = body.data.products[0].id;
      if (body.data.products[0].variants && body.data.products[0].variants.length > 0) {
        variantId = body.data.products[0].variants[0].id;
      }
    }
  } catch (e) {}

  if (!productId || !variantId) {
    // Try page
    const pageRes = http.get(`${BASE_URL}/v2/catalog/page`, {
      headers: { 'Cookie': getCookieHeader(state) },
      redirects: 0,
    });
    mergeCookies(state, pageRes);
    try {
      const body = JSON.parse(pageRes.body);
      if (body.data && body.data.id) {
        productId = body.data.id;
        if (body.data.variants && body.data.variants.length > 0) {
          variantId = body.data.variants[0].id;
        }
      }
    } catch (e) {}
  }

  if (!productId || !variantId) {
    return false;
  }

  // Create cart
  const cartPayload = {
    product_id: productId,
    variant_id: variantId,
  };
  if (state.grantId) {
    cartPayload.grant_id = state.grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(cartPayload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Cookie': getCookieHeader(state),
    },
    redirects: 0,
  });
  mergeCookies(state, cartRes);

  if (cartRes.status === 201) {
    try {
      const body = JSON.parse(cartRes.body);
      state.cartId = body.id;
      if (body.csrf) state.csrf = body.csrf;
      state.cartEtag = cartRes.headers['ETag'];
    } catch (e) {}
  }

  if (!state.cartId) {
    return false;
  }

  return true;
}

export function setup() {
  // Nothing to do here
