}

export default function () {
  const vuId = __VU;
  const iterId = __ITER;

  // Create or get VU state
  if (!globalThis.__vuStates) {
    globalThis.__vuStates = {};
  }
  if (!globalThis.__vuStates[vuId]) {
    globalThis.__vuStates[vuId] = new VUState();
  }
  const state = globalThis.__vuStates[vuId];

  // Assign user
  const userIndex = (vuId - 1) % USERS.length;
  state.user = USERS[userIndex];

  // Track active VUs
  activeVUs++;
  if (activeVUs > maxActiveVUs) {
    maxActiveVUs = activeVUs;
  }

  try {
    // Setup journey (fresh login + cart)
    if (!setupJourney(state)) {
      workDropped.add(1);
      totalWorkDropped++;
      return;
    }

    // Now do work
    // Check if we're in the scoring window
    if (t0Set) {
      const now = Date.now();
      const elapsed = now - t0;

      if (elapsed >= WARMUP * 1000 && elapsed < (WARMUP + SCORE_DURATION) * 1000) {
        // In scoring window - do work
        doWork(state);
      } else if (elapsed < WARMUP * 1000) {
        // In warmup - still do work to establish T0 if not set
        doWork(state);
      } else if (elapsed >= (WARMUP + SCORE_DURATION) * 1000 && elapsed < (WARMUP + SCORE_DURATION + DRAIN) * 1000) {
        // In drain - do work but don't count
        doWork(state);
      }
    } else {
      // T0 not set yet - do work to try to set it
      doWork(state);
    }
  } finally {
    activeVUs--;
  }
}

export function teardown(data) {
  // Calculate and output results
  const results = {
    t0: t0,
    t0Set: t0Set,
    workCounts: workCounts,
    totalWorkAttempts: totalWorkAttempts,
    totalWorkSuccess: totalWorkSuccess,
    totalWorkErrors: totalWorkErrors,
    totalWorkDropped: totalWorkDropped,
    unexpectedFailures: unexpectedFailures,
    totalBusinessResponses: totalBusinessResponses,
    scheduled429s: scheduled429s,
    retryAfterViolations: retryAfterViolations,
    maxActiveVUs: maxActiveVUs,
    burstTimestamps: burstTimestamps.map(arr => arr.map(ts => ts - t0)),
  };

  console.log(JSON.stringify(results, null, 2));

  // Check burst limits
  for (let w = 0; w < 6; w++) {
    const target = TARGETS[Math.floor(w / 2)];
    const burstLimit = Math.ceil(1.5 * target) + 1;
    const timestamps = burstTimestamps[w];

    // Check each 1s burst
    if (timestamps.length > 0) {
      const sorted = timestamps.slice().sort((a, b) => a - b);
      let burstStart = sorted[0];
      let burstCount = 0;

      for (const ts of sorted) {
        if (ts - burstStart < 1000) {
          burstCount++;
        } else {
          if (burstCount > burstLimit) {
            console.log(`BURST VIOLATION: window ${w}, burst count ${burstCount} > limit ${burstLimit}`);
          }
          burstStart = ts;
          burstCount = 1;
        }
      }
      if (burstCount > burstLimit) {
        console.log(`BURST VIOLATION: window ${w}, burst count ${burstCount} > limit ${burstLimit}`);
      }
    }
  }

  // Check error rate
  const errorRate = totalBusinessResponses > 0 ? unexpectedFailures / totalBusinessResponses : 0;
  console.log(`Error rate: ${errorRate}`);
  console.log(`Dropped work: ${totalWorkDropped}`);
  console.log(`Max active VUs: ${maxActiveVUs}`);

  return results;
}

