import os
import time
import random
from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"

class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf_token = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0
        self.authenticated = False
        self.work_start_time = None
        self.owner_seed = None

    def on_start(self):
        self.owner_seed = f"{self.environment.runner.user_count}-{time.time_ns()}"
        self.login()

    def login(self):
        # GET login form
        with self.client.get("/v2/login-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Login form failed: {resp.status_code}")
                return False
            # Extract CSRF from input[name=csrf]
            import re
            match = re.search(r'name="csrf"[^>]*value="([^"]*)"', resp.text)
            if not match:
                match = re.search(r'name=[\'"]csrf[\'"][^>]*value=[\'"]([^\'"]*)[\'"]', resp.text)
            if not match:
                resp.failure("No CSRF token in login form")
                return False
            self.csrf_token = match.group(1)

        # POST login
        with self.client.post("/v2/login", 
                            json={"username": self.username, "password": PASSWORD, "csrf": self.csrf_token},
                            headers={"X-CSRF-Token": self.csrf_token},
                            catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(location, catch_response=True) as resp2:
                        if resp2.status_code != 200:
                            resp2.failure(f"Login redirect failed: {resp2.status_code}")
                            return False
                        resp = resp2
                else:
                    resp.failure("302 without Location")
                    return False
            if resp.status_code != 200:
                resp.failure(f"Login failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                if "csrf" in data:
                    self.csrf_token = data["csrf"]
                self.authenticated = True
                return True
            except:
                resp.failure("Invalid login response")
                return False

    def renew_session(self):
        with self.client.post("/v2/session/renew", 
                            json={},
                            headers={"X-CSRF-Token": self.csrf_token},
                            catch_response=True) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    return True
                except:
                    resp.failure("Invalid renew response")
                    return False
            elif resp.status_code == 401:
                try:
                    data = resp.json()
                    if data.get("error") == "session":
                        # Session revoked, need full re-login
                        return self.login()
                except:
                    pass
                resp.failure(f"Renew failed: {resp.status_code}")
                return False
            else:
                resp.failure(f"Renew failed: {resp.status_code}")
                return False

    def recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(f"/v2/carts/{self.cart_id}/recover",
                            json={},
                            headers={"X-CSRF-Token": self.csrf_token},
                            catch_response=True) as resp:
            if resp.status_code == 200:
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    if "etag" in resp.headers:
                        self.cart_etag = resp.headers["etag"]
                    return True
                except:
                    resp.failure("Invalid recover response")
                    return False
            elif resp.status_code == 401:
                try:
                    data = resp.json()
                    if data.get("error") == "expired":
                        if self.renew_session():
                            return self.recover_cart()
                    elif data.get("error") == "session":
                        if self.login():
