    def get_challenge(self):
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Challenge form failed: {resp.status_code}")
                return False
            import re
            match = re.search(r'action="([^"]*)"', resp.text)
            if not match:
                resp.failure("No challenge action found")
                return False
            action = match.group(1)
            match = re.search(r'name="challenge"[^>]*value="([^"]*)"', resp.text)
            if not match:
                match = re.search(r'name=[\'"]challenge[\'"][^>]*value=[\'"]([^\'"]*)[\'"]', resp.text)
            if not match:
                resp.failure("No challenge value found")
                return False
            challenge_value = match.group(1)

        with self.client.post(action,
                            json={"challenge": challenge_value},
                            headers={"X-CSRF-Token": self.csrf_token},
                            catch_response=True) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
