                    data = resp.json()
                    if "grant_id" in data:
                        self.grant_id = data["grant_id"]
                    if "csrf" in data:
                        self.csrf_token = data["csrf"]
                    return True
                except:
                    resp.failure("Invalid challenge response")
                    return False
            else:
                resp.failure(f"Challenge failed: {resp.status_code}")
                return False

    def create_cart(self):
        # Get catalog
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"Catalog failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                products = data.get("data", {}).get("products", [])
                if not products:
                    resp.failure("No products in catalog")
