                        with self.client.get(status_url, catch_response=True) as resp2:
                            if resp2.status_code == 200:
                                try:
                                    data2 = resp2.json()
                                    if "csrf" in data2:
                                        self.csrf_token = data2["csrf"]
                                    status = data2.get("status")
                                    if status == "ready":
                                        self.reservation_id = data2.get("reservation_id")
                                        return True
                                    elif status == "failed":
                                        return False
                                    # pending, continue polling
                                except:
                                    resp2.failure("Invalid reservation status response")
                                    return False
                            elif resp2.status_code == 401:
                                try:
                                    data2 = resp2.json()
                                    if data2.get("error") == "expired":
