    def create_order(self):
        if not self.cart_id:
            return False
        if not self.idempotency_key:
            self.idempotency_key = f"order-{self.cart_id}-{time.time_ns()}"

        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id

        headers = {
            "X-CSRF-Token": self.csrf_token,
            "Idempotency-Key": self.idempotency_key
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post("/v2/orders",
                            json=payload,
                            headers=headers,
                            catch_response=True) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    if data.get("accepted") == True:
                        if "csrf" in data:
                            self.csrf_token = data["csrf"]
                        return True
                    else:
                        resp.failure("Order not accepted")
                        return False
                except:
                    resp.failure("Invalid order response")
                    return False
            elif resp.status_code == 200:
                try:
                    data = resp.json()
                    if data.get("accepted") == False:
                        resp.failure("Order business failure")
                        return False
                except:
                    resp.failure("Invalid order response")
                    return False
            elif resp.status_code == 401:
                try:
                    data = resp.json()
                    if data.get("error") == "expired":
                        if self.renew_session():
                            return self.create_order()
                    elif data.get("error") == "session":
                        if self.login():
                            if self.recover_cart():
                                return self.create_order()
                    elif data.get("error") == "denied":
                        resp.failure("Order denied")
                        return False
                except:
                    pass
                resp.failure(f"Order 401: {resp.status_code}")
                return False
            else:
                resp.failure(f"Order failed: {resp.status_code}")
                return False

    def do_work(self):
        """Perform the /v2/work operation. Returns True if successful completion."""
        self.work_retries = 0
        while self.work_retries < 4:
            with self.client.post("/v2/work",
                                json={},
                                headers={"X-CSRF-Token": self.csrf_token},
                                catch_response=True) as resp:
                if resp.status_code == 200:
                    try:
                        data = resp.json()
                        if data.get("ok") == True:
                            if "csrf" in data:
                                self.csrf_token = data["csrf"]
                            return True
                        else:
                            resp.failure("Work not ok")
                            return False
                    except:
                        resp.failure("Invalid work response")
                        return False
                elif resp.status_code == 429:
                    # Scheduled 429, retry after 1s
                    self.work_retries += 1
                    if self.work_retries >= 4:
                        return False
                    time.sleep(1)
                    continue
                elif resp.status_code == 401:
                    try:
                        data = resp.json()
                        if data.get("error") == "expired":
                            if self.renew_session():
                                continue
                            else:
                                return False
                        elif data.get("error") == "session":
                            if self.login():
                                continue
                            else:
                                return False
                        elif data.get("error") == "denied":
                            resp.failure("Work denied")
                            return False
                    except:
                        pass
                    resp.failure(f"Work 401: {resp.status_code}")
                    return False
                elif resp.status_code == 500:
                    resp.failure("Work 500 error")
                    return False
                else:
                    resp.failure(f"Work failed: {resp.status_code}")
                    return False
        return False

    @task
    def work_task(self):
        if not self.authenticated:
            self.login()
            if not self.authenticated:
                return

        # Record start time for eligible work
        self.work_start_time = time.time()

        # Perform work
        success = self.do_work()

        if success:
            # This is a successful completion
            pass
        else:
            # Failed work
            pass

        # Reset for next iteration
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.work_retries = 0

        # Stop after one iteration
        raise StopUser()


class WorkShape(LoadTestShape):
    """
    Shape that delivers 5 → 15 → 5 starts/s over three 10-second plateaus.
    Total duration: 30 seconds of load + warmup/drain handled by harness.
    """

    def __init__(self):
        super().__init__()
        self.start_time = None
        self.phase_duration = 10  # seconds per plateau
        self.rates = [5, 15, 5]
        self.total_duration = self.phase_duration * len(self.rates)  # 30 seconds

    def tick(self):
        if self.start_time is None:
            self.start_time = time.time()

        elapsed = time.time() - self.start_time

        if elapsed >= self.total_duration:
            return None

        # Determine which phase we're in
        phase_index = min(int(elapsed // self.phase_duration), len(self.rates) - 1)
        target_rate = self.rates[phase_index]

        # Calculate user count for this rate
        # Each user completes one work operation then stops
        # With wait_time between 0.05-0.15s, each user takes ~0.1s to complete
        # So user_count ≈ rate * 0.1
        user_count = max(1, int(target_rate * 0.1))

        return (user_count, target_rate)  # (user_count, spawn_rate)```

