import os
import time
import random
from urllib.parse import urljoin, urlparse, parse_qs

from locust import HttpUser, task, between, LoadTestShape, events
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

USERNAMES = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"


class ShopUser(HttpUser):
    wait_time = between(0.05, 0.15)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.csrf = None
        self.session_cookie = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.username = None
        self.work_retries = 0
        self.iteration_count = 0
        self.max_iterations = 2

    def on_start(self):
        self.username = random.choice(USERNAMES)
        self.login()

    def login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code >= 400:
                resp.failure(f"login-form failed: {resp.status_code}")
                return
            # Extract csrf from HTML
            import re
            match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not match:
                match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', resp.text)
            if not match:
                resp.failure("no csrf in login form")
                return
            self.csrf = match.group(1)

        # POST login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": PASSWORD, "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        allow_redirects=False,
                    ) as resp2:
                        if resp2.status_code >= 400:
                            resp2.failure(f"login redirect failed: {resp2.status_code}")
                            return
                        self._extract_csrf_from_response(resp2)
                else:
                    resp.failure("302 without Location")
                    return
            elif resp.status_code < 400:
                self._extract_csrf_from_response(resp)
            else:
                resp.failure(f"login failed: {resp.status_code}")
                return

    def _extract_csrf_from_response(self, resp):
        try:
            data = resp.json()
            if "csrf" in data:
                self.csrf = data["csrf"]
        except Exception:
            pass

    def ensure_cart(self):
        if self.cart_id is not None:
            return True

        # GET catalog
        with self.client.get("/v2/catalog", catch_response=True) as resp:
            if resp.status_code >= 400:
                resp.failure(f"catalog failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                products = data.get("data", {}).get("products", [])
                if not products:
                    resp.failure("no products in catalog")
                    return False
                product = products[0]
                product_id = product["id"]
                variants = product.get("variants", [])
                if not variants:
                    resp.failure("no variants for product")
                    return False
                variant = variants[0]
                variant_id = variant["id"]
            except Exception as e:
                resp.failure(f"catalog parse error: {e}")
                return False

        # Create cart
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        with self.client.post(
            "/v2/carts",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as resp:
            if resp.status_code == 201:
                try:
                    data = resp.json()
                    self.cart_id = data["id"]
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                    self.cart_etag = resp.headers.get("ETag")
                    self.idempotency_key = f"idem-{self.cart_id}-{int(time.time()*1000)}"
                    return True
                except Exception as e:
                    resp.failure(f"cart create parse error: {e}")
                    return False
            else:
                resp.failure(f"cart create failed: {resp.status_code}")
                return False

    def get_challenge_grant(self):
        # GET challenge form
        with self.client.get("/v2/challenge-form", catch_response=True) as resp:
            if resp.status_code >= 400:
                resp.failure(f"challenge-form failed: {resp.status_code}")
                return False
            import re
            match = re.search(r'action=["\']([^"\']+)["\']', resp.text)
            if not match:
                resp.failure("no challenge action found")
                return False
            action = match.group(1)
            match = re.search(r'name=["\']challenge["\']', resp.text)
            if not match:
                resp.failure("no challenge input found")
                return False

        # POST challenge
        with self.client.post(
            action,
            json={"challenge": "bench"},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("challenge 302 without Location")
                    return False
                with self.client.get(
                    location,
                    catch_response=True,
                    allow_redirects=False,
                ) as resp2:
                    if resp2.status_code >= 400:
                        resp2.failure(f"challenge redirect failed: {resp2.status_code}")
                        return False
                    try:
                        data = resp2.json()
                        self.grant_id = data.get("grant_id")
                        if "csrf" in data:
                            self.csrf = data["csrf"]
                        return self.grant_id is not None
                    except Exception as e:
                        resp2.failure(f"challenge parse error: {e}")
                        return False
            else:
                resp.failure(f"challenge failed: {resp.status_code}")
                return False

    def create_reservation(self):
        if not self.cart_id:
            return False
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as resp:
            if resp.status_code == 202:
                try:
                    data = resp.json()
                    status_url = data.get("status_url")
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception as e:
                    resp.failure(f"reservation parse error: {e}")
                    return False

                # Poll status
                for _ in range(5):
                    time.sleep(0.05)
                    with self.client.get(
                        status_url,
                        catch_response=True,
                    ) as poll_resp:
                        if poll_resp.status_code >= 400:
                            poll_resp.failure(f"reservation poll failed: {poll_resp.status_code}")
                            return False
                        try:
                            poll_data = poll_resp.json()
                            status = poll_data.get("status")
                            if "csrf" in poll_data:
                                self.csrf = poll_data["csrf"]
                            if status == "ready":
                                self.reservation_id = poll_data.get("reservation_id")
                                return self.reservation_id is not None
                            elif status in ("pending", "failed"):
                                if status == "failed":
                                    return False
                        except Exception as e:
                            poll_resp.failure(f"reservation poll parse error: {e}")
                            return False
                return False
            else:
                resp.failure(f"reservation create failed: {resp.status_code}")
                return False

    def do_work(self):
        """Perform POST /v2/work with retry logic for 429."""
        self.work_retries = 0
        while True:
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
                name="/v2/work",
            ) as resp:
                if resp.status_code == 200:
                    try:
                        data = resp.json()
                        if data.get("ok") is True:
                            if "csrf" in data:
                                self.csrf = data["csrf"]
                            return True
                        else:
                            resp.failure("work ok != true")
                            return False
                    except Exception as e:
                        resp.failure(f"work parse error: {e}")
                        return False
                elif resp.status_code == 429:
                    # Scheduled 429 - honor Retry-After
                    retry_after = resp.headers.get("Retry-After", "1")
                    try:
                        wait_s = float(retry_after)
                    except ValueError:
                        wait_s = 1.0
                    self.work_retries += 1
                    if self.work_retries > 4:
                        # Expected 429, not a failure
                        return False
                    time.sleep(wait_s)
                    continue
                elif resp.status_code == 401:
                    # Check error type
                    try:
                        err_data = resp.json()
                        err_type = err_data.get("error", "")
                    except Exception:
                        err_type = ""
                    if err_type == "expired":
                        # Renew session
                        if self.renew_session():
                            continue
                        else:
                            resp.failure("session renewal failed")
                            return False
                    elif err_type == "session":
                        # Revoked - fresh login and recover cart
                        if self.recover_session():
                            continue
                        else:
                            resp.failure("session recovery failed")
                            return False
                    else:
                        resp.failure(f"work 401 denied: {err_type}")
                        return False
                else:
                    resp.failure(f"work unexpected status: {resp.status_code}")
                    return False

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
        ) as resp:
            if resp.status_code < 400:
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    pass
                return True
            else:
                resp.failure(f"renew failed: {resp.status_code}")
                return False

    def recover_session(self):
        # Fresh login
        self.csrf = None
        self.login()
        if self.csrf is None:
            return False
        # Recover cart if exists
        if self.cart_id:
            with self.client.post(
                f"/v2/carts/{self.cart_id}/recover",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                catch_response=True,
            ) as resp:
                if resp.status_code >= 400:
                    resp.failure(f"cart recover failed: {resp.status_code}")
                    return False
                try:
                    data = resp.json()
                    if "csrf" in data:
                        self.csrf = data["csrf"]
                except Exception:
                    pass
        return True

    @task
    def work_task(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1

        # Ensure cart exists
        if not self.ensure_cart():
            return

        # Optionally get challenge grant (some profiles need it)
        # We'll try to get grant if not already have one
        if self.grant_id is None:
            self.get_challenge_grant()

        # Create reservation
        if not self.create_reservation():
            return

        # Do the work
        self.do_work()


class WorkShape(LoadTestShape):
    """
    Shape that runs for a fixed duration then stops.
    The harness will stop when tick() returns None.
    """
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.duration = 45  # seconds total

    def tick(self):
        elapsed = time.time() - self.start_time
        if elapsed > self.duration:
            return None
        # Run 2 users constantly
        return (2, 2)
