function getCsrfFromForm(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i) ||
                html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (match) return match[1];
  const inputMatch = html.match(/<input[^>]+name=["']csrf["'][^>]*>/i);
  if (inputMatch) {
    const valMatch = inputMatch[0].match(/value=["']([^"']+)["']/i);
    if (valMatch) return valMatch[1];
