function createReservation(jar, cartId, csrf) {
  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({ cart_id: cartId }), {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  if (res.status !== 202) {
    return { success: false, reservationId: null, csrf: null, status: res.status };
  }
  const statusUrl = getReservationStatusUrl(res.body);
  const newCsrf = getCsrfFromBody(res.body) || csrf;
  reservationCount.add(1);
  if (!statusUrl) return { success: false, reservationId: null, csrf: newCsrf, status: res.status };
  let reservationId = null;
  let pollCount = 0;
  let lastStatus = null;
  while (pollCount < MAX_POLLS) {
    sleep(POLL_INTERVAL_MS / 1000);
    const pollRes = http.get(new URL(statusUrl, BASE_URL).toString(), { jar, redirects: 0 });
    if (pollRes.status !== 200) {
      return { success: false, reservationId: null, csrf: newCsrf, status: pollRes.status };
    }
    lastStatus = getReservationStatus(pollRes.body);
    if (lastStatus === 'ready') {
      reservationId = getReservationId(pollRes.body);
      break;
    }
    if (lastStatus === 'failed') {
      return { success: false, reservationId: null, csrf: newCsrf, status: pollRes.status, failed: true };
    }
    pollCount++;
  }
  if (!reservationId) {
    return { success: false, reservationId: null, csrf: newCsrf, status: 200, pending: true };
  }
  return { success: true, reservationId, csrf: newCsrf, status: 200 };
