function createOrder(jar, cartId, csrf, reservationId, etag, idempotencyKey) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey
  };
  if (etag) headers['If-Match'] = etag;
  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    jar,
    redirects: 0,
    headers
  });
  if (res.status === 401) {
    const errorType = res.body && res.body.includes('denied') ? 'denied' :
                      res.body && res.body.includes('session') ? 'session' :
                      res.body && res.body.includes('expired') ? 'expired' : 'unknown';
    return { success: false, orderId: null, csrf: null, status: res.status, errorType, body: res.body };
  }
  if (res.status !== 201) {
    return { success: false, orderId: null, csrf: null, status: res.status, body: res.body };
  }
  const accepted = getAccepted(res.body);
  if (!accepted) {
    return { success: false, orderId: null, csrf: null, status: 200, accepted: false, body: res.body };
  }
  const orderId = getOrderId(res.body);
  const newCsrf = getCsrfFromBody(res.body) || csrf;
  orderCreateCount.add(1);
  return { success: true, orderId, csrf: newCsrf, status: res.status, body: res.body };
}

function doWork(jar, csrf) {
  const startTime = Date.now();
  const res = http.post(`${BASE_URL}/v2/work`, '{}', {
    jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }
  });
  const endTime = Date.now();
  businessResponses.add(1);
  if (res.status === 429) {
    work429s.add(1);
    const retryAfter = getRetryAfter(res.headers);
    return { success: false, status: 429, retryAfter, startTime, endTime, body: res.body };
  }
  if (res.status >= 500) {
    work500s.add(1);
    unexpectedFailures.add(1);
    workFailures.add(1);
    return { success: false, status: res.status, retryAfter: 0, startTime, endTime, body: res.body };
  }
  if (res.status >= 400) {
    unexpectedFailures.add(1);
    workFailures.add(1);
    return { success: false, status: res.status, retryAfter: 0, startTime, endTime, body: res.body };
  }
  const ok = getWorkOk(res.body);
  if (!ok) {
    unexpectedFailures.add(1);
    workFailures.add(1);
    return { success: false, status: res.status, retryAfter: 0, startTime, endTime, body: res.body };
  }
  workCompletions.add(1);
  workStarts.add(startTime);
  workStartTimestamps.push(startTime);
  workEventLog.push({ type: 'work_success', startTime, endTime, status: res.status, vu: __VU, iteration: __ITER });
  return { success: true, status: res.status, retryAfter: 0, startTime, endTime, body: res.body };
}

function doWorkWithRetry(jar, csrf) {
  let retries = 0;
  let result = doWork(jar, csrf);
  while (!result.success && result.status === 429 && retries < MAX_RETRIES_429) {
    const waitMs = result.retryAfter || RETRY_AFTER_MS;
    sleep(waitMs / 1000);
    retries++;
    result = doWork(jar, csrf);
  }
  if (!result.success && result.status === 429) {
    droppedWork.add(1);
    workEventLog.push({ type: 'work_dropped_429', startTime: result.startTime, endTime: result.endTime, status: 429, vu: __VU, iteration: __ITER });
