function performCheckoutJourney(jar, username, password, profile, vuId, iterationId) {
  const loginRes = login(jar, username, password);
  if (!loginRes.success) {
    return { success: false, error: loginRes.error, workDone: false, workStartTime: null };
  }
  let csrf = loginRes.csrf;

  const catalogRes = fetchCatalogWithPages(jar, profile.reverse_catalog || false);
  if (!catalogRes.success || !catalogRes.product) {
    return { success: false, error: catalogRes.error || 'no product', workDone: false, workStartTime: null };
  }
  const product = catalogRes.product;
  const variant = getVariantFromProduct(product);
  if (!variant) {
    return { success: false, error: 'no variant', workDone: false, workStartTime: null };
  }

  let grantId = null;
  const challengeFormRes = getChallengeForm(jar);
  if (challengeFormRes.success && challengeFormRes.action) {
    const challengeRes = postChallenge(jar, csrf, challengeFormRes.action);
    if (challengeRes.success) {
