      csrf = challengeRes.csrf;
    }
  }

  const cartRes = createCart(jar, csrf, product.id, variant.id, grantId);
  if (!cartRes.success) {
    return { success: false, error: `cart create failed ${cartRes.status}`, workDone: false, workStartTime: null };
  }
  let cartId = cartRes.cartId;
  csrf = cartRes.csrf;
  let etag = cartRes.etag;

  const patchRes = patchCart(jar, cartId, csrf, etag, 1);
  if (!patchRes.success) {
    return { success: false, error: `patch failed ${patchRes.status}`, workDone: false, workStartTime: null };
  }
  csrf = patchRes.csrf;
  etag = patchRes.etag;

  const reservationRes = createReservation(jar, cartId, csrf);
  if (!reservationRes.success) {
    return { success: false, error: `reservation failed ${reservationRes.status}`, workDone: false, workStartTime: null };
  }
  csrf = reservationRes.csrf;
  const reservationId = reservationRes.reservationId;

  const idempotencyKey = `cart-${cartId}-${vuId}-${iterationId}`;
  checkoutStarts.add(1);
  const orderStartTime = Date.now();
  let orderRes = createOrder(jar, cartId, csrf, reservationId, etag, idempotencyKey);
  let recoveryAttempted = false;

  if (!orderRes.success && orderRes.status === 401 && orderRes.errorType === 'expired' && !recoveryAttempted) {
    recoveryAttempted = true;
    const recoveryRes = handle401Expired(jar, csrf, cartId, 'order', (newCsrf) => {
      return createOrder(jar, cartId, newCsrf, reservationId, etag, idempotencyKey);
    });
    orderRes = recoveryRes;
  }
  if (!orderRes.success && orderRes.status === 401 && orderRes.errorType === 'session' && !recoveryAttempted) {
    recoveryAttempted = true;
    const recoveryRes = handle401Session(jar, csrf, cartId, username, password, (newCsrf) => {
      return createOrder(jar, cartId, newCsrf, reservationId, etag, idempotencyKey);
    });
    orderRes = recoveryRes;
  }
  if (!orderRes.success && orderRes.status === 401 && orderRes.errorType === 'denied') {
    checkoutFailures.add(1);
    return { success: false, error: 'denied 401', workDone: false, workStartTime: null };
  }

  if (!orderRes.success) {
    checkoutFailures.add(1);
    return { success: false, error: `order failed ${orderRes.status}`, workDone: false, workStartTime: null };
  }

  checkoutCompletions.add(1);
  csrf = orderRes.csrf;

  const workRes = doWorkWithRetry(jar, csrf);
  if (workRes.success) {
    return { success: true, error: null, workDone: true, workStartTime: workRes.startTime };
  }
  return { success: false, error: `work failed ${workRes.status}`, workDone: false, workStartTime: workRes.startTime };
}

