  const response = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    redirects: 0,
  });
  parseCookies(response);
  if (response.status === 401) {
    const errorJson = JSON.parse(response.body);
    return handle401(errorJson.error, () => createOrder(cartId, reservationId));
  }
  if (response.status !== 201) {
    fail(`Order creation failed: ${response.status}`);
  }
  const orderJson = JSON.parse(response.body);
  if (orderJson.accepted !== true) {
    fail('Order not accepted - business failure');
  }
  state.csrf = extractCsrfFromJson(orderJson) || state.csrf;
  return orderJson;
}

function doWork() {
  const state = getVUState();
  const now = Date.now() / 1000;

  // Check if we're in slow mode
  if (state.slowMode && now - state.slowModeStartTime >= 0) {
    // Already in slow mode
  } else if (!state.slowMode && now >= SLOW_AFTER_SECONDS) {
    state.slowMode = true;
    state.slowModeStartTime = now;
  }

  const delay = state.slowMode ? SLOW_DELAY : FAST_DELAY;

  // Record work start timestamp
  const startTime = Date.now() / 1000;
  workStarts.add(1);
  workStartTimestamps.push(startTime);

  // Simulate service latency
  sleep(delay);

  // Make the actual work request
  const response = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
      'Cookie': getCookieHeader(),
    },
    redirects: 0,
  });
  parseCookies(response);

  const endTime = Date.now() / 1000;
  workLatency.add(endTime - startTime);

  businessResponses.add(1);

  if (response.status === 200) {
    const workJson = JSON.parse(response.body);
    if (workJson.ok === true) {
      workCompletions.add(1);
      workCompletionTimestamps.push(endTime);
      state.csrf = extractCsrfFromJson(workJson) || state.csrf;
      state.work429RetryCount = 0;
      return true;
    } else {
      businessFailures.add(1);
      unexpectedErrorCount++;
      workUnexpectedErrors.add(1);
      return false;
    }
  } else if (response.status === 429) {
    workScheduled429.add(1);
    scheduled429Count++;
    const retryAfter = response.headers['Retry-After'];
    const retrySeconds = retryAfter ? parseInt(retryAfter) : RETRY_AFTER_SECONDS;
    if (state.work429RetryCount < MAX_RETRY_429) {
      state.work429RetryCount++;
      sleep(retrySeconds);
      // Retry the work
      const retryStartTime = Date.now() / 1000;
      workStarts.add(1);
      workStartTimestamps.push(retryStartTime);
      sleep(delay);
      const retryResponse = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
          'Cookie': getCookieHeader(),
        },
        redirects: 0,
      });
      parseCookies(retryResponse);
      const retryEndTime = Date.now() / 1000;
      workLatency.add(retryEndTime - retryStartTime);
      businessResponses.add(1);
      if (retryResponse.status === 200) {
        const retryJson = JSON.parse(retryResponse.body);
        if (retryJson.ok === true) {
          workCompletions.add(1);
          workCompletionTimestamps.push(retryEndTime);
          state.csrf = extractCsrfFromJson(retryJson) || state.csrf;
          state.work429RetryCount = 0;
          return true;
        }
      } else if (retryResponse.status === 429) {
        workScheduled429.add(1);
        scheduled429Count++;
        state.work429RetryCount++;
        if (state.work429RetryCount >= MAX_RETRY_429) {
          businessFailures.add(1);
          unexpectedErrorCount++;
          workUnexpectedErrors.add(1);
          return false;
        }
      } else if (retryResponse.status === 401) {
        const errorJson = JSON.parse(retryResponse.body);
        const retryResult = handle401(errorJson.error, doWork);
        return retryResult;
      } else if (retryResponse.status >= 500) {
        businessFailures.add(1);
        unexpectedErrorCount++;
        workUnexpectedErrors.add(1);
        return false;
      }
    } else {
      businessFailures.add(1);
      unexpectedErrorCount++;
      workUnexpectedErrors.add(1);
      return false;
    }
  } else if (response.status === 401) {
    const errorJson = JSON.parse(response.body);
    const retryResult = handle401(errorJson.error, doWork);
    return retryResult;
  } else if (response.status >= 500) {
    businessFailures.add(1);
    unexpectedErrorCount++;
    workUnexpectedErrors.add(1);
    return false;
  } else {
    businessFailures.add(1);
    unexpectedErrorCount++;
    workUnexpectedErrors.add(1);
    return false;
  }
  return false;
}

function fullJourney() {
  const state = getVUState();

  // Fresh login
  login();

  // Get catalog
  const catalog = getCatalog();
  if (!catalog.data || !catalog.data.products || catalog.data.products.length === 0) {
    fail('Catalog has no products');
  }

  // Pick a random product
  const product = randomItem(catalog.data.products);
  if (!product.variants || product.variants.length === 0) {
    fail('Product has no variants');
  }
  const variant = randomItem(product.variants);

  // Try to get a grant via challenge
  let grantId = null;
  try {
    const challengeForm = getChallengeForm();
    if (challengeForm && challengeForm.action && challengeForm.challenge) {
      const grantResult = submitChallenge(challengeForm.action, challengeForm.challenge);
      if (grantResult && grantResult.grant_id) {
        grantId = grantResult.grant_id;
      }
    }
  } catch (e) {
    // Challenge may fail, continue without grant
  }

  // Create cart
  const cart = createCart(product.id, variant.id, grantId);
  if (!cart || !cart.id) {
    fail('Cart creation failed');
  }

  // Update cart quantity
  const quantity = randomIntBetween(1, 20);
  updateCart(cart.id, quantity, state.cartEtag);

  // Create reservation
  let reservationId = null;
  try {
    const reservation = createReservation(cart.id);
    if (reservation && reservation.status_url) {
      const pollResult = pollReservation(reservation.status_url);
      if (pollResult && pollResult.status === 'ready') {
        reservationId = pollResult.reservation_id;
      }
    }
  } catch (e) {
    // Reservation may fail, continue without it
  }

  // Create order
  const order = createOrder(cart.id, reservationId);
  if (!order || order.accepted !== true) {
    fail('Order not accepted');
  }

  // Do work
  const workResult = doWork();
  if (!workResult) {
    droppedIterations.add(1);
    droppedIterationCount++;
  }

  // Reset cart state for next iteration
  state.cartId = null;
  state.cartEtag = null;
  state.grantId = null;
  state.reservationId = null;
  state.idempotencyKey = null;
  state.challengeId = null;
  state.challengeFormAction = null;
  state.challengeGrantId = null;
  state.challengeCsrf = null;
  state.challengeExpiresAt = 0;
  state.cartRecovered = false;
}

export function setup() {
  // Initialize global state
  T0 = null;
  workStartTimestamps = [];
  workCompletionTimestamps = [];
  currentVUs = 0;
  maxConcurrentVUs = 0;
  totalIterations = 0;
  droppedIterationCount = 0;
  scheduled429Count = 0;
  unexpectedErrorCount = 0;
  businessResponseCount = 0;
  businessFailureCount = 0;
  return {};
}

export default function () {
  const now = Date.now() / 1000;

  // Track VU concurrency
  currentVUs++;
  if (currentVUs > maxConcurrentVUs) {
    maxConcurrentVUs = currentVUs;
  }
  activeVUs.add(currentVUs);

  try {
    // Set T0 on first eligible work start
    if (T0 === null) {
      T0 = now;
    }

    totalIterations++;
    fullJourney();
  } catch (e) {
    droppedIterations.add(1);
    droppedIterationCount++;
    console.error(`Iteration error: ${e.message}`);
  } finally {
    currentVUs--;
    activeVUs.add(currentVUs);
  }
}

export function teardown(data) {
  // Calculate final metrics
  const endTime = Date.now() / 1000;
  const totalDuration = endTime - (T0 || endTime);

  // Calculate rate
  const scoredStart = T0 !== null ? T0 + WARMUP_SECONDS : null;
  const scoredEnd = T0 !== null ? T0 + WARMUP_SECONDS + SCORED_SECONDS : null;

  let scoredWorkStarts = 0;
  let scoredWorkCompletions = 0;
  if (scoredStart !== null && scoredEnd !== null) {
    scoredWorkStarts = workStartTimestamps.filter(t => t >= scoredStart && t < scoredEnd).length;
    scoredWorkCompletions = workCompletionTimestamps.filter(t => t >= scoredStart && t < scoredEnd).length;
  }

  const actualRate = scoredWorkStarts / SCORED_SECONDS;
  const completionRate = scoredWorkCompletions / SCORED_SECONDS;

  console.log(`=== Performance Test Results ===`);
  console.log(`T0: ${T0}`);
  console.log(`Total duration: ${totalDuration.toFixed(2)}s`);
  console.log(`Total iterations: ${totalIterations}`);
  console.log(`Dropped iterations: ${droppedIterationCount}`);
  console.log(`Scheduled 429s: ${scheduled429Count}`);
  console.log(`Unexpected errors: ${unexpectedErrorCount}`);
  console.log(`Business responses: ${businessResponseCount}`);
  console.log(`Business failures: ${businessFailureCount}`);
  console.log(`Max concurrent VUs: ${maxConcurrentVUs}`);
  console.log(`Scored work starts: ${scoredWorkStarts}`);
  console.log(`Scored work completions: ${scoredWorkCompletions}`);
  console.log(`Actual rate: ${actualRate.toFixed(2)} starts/s (target: ${TARGET_RATE})`);
  console.log(`Completion rate: ${completionRate.toFixed(2)} completions/s`);
  console.log(`Work latency (ms): avg=${workLatency.avg ? workLatency.avg.toFixed(2) : 'N/A'}, p95=${workLatency.p95 ? workLatency.p95.toFixed(2) : 'N/A'}`);

  // Check gates
  const rateError = Math.abs(actualRate - TARGET_RATE) / TARGET_RATE;
  const rateAllowance = Math.max(0.1 * TARGET_RATE, 1) / TARGET_RATE;
  const rateFraction = rateError <= rateAllowance ? 1 : Math.max(0, 1 - (rateError - rateAllowance) / (0.4 - rateAllowance));

  const droppedFraction = totalIterations > 0 ? droppedIterationCount / totalIterations : 0;
  const droppedGate = droppedFraction <= 0.01 ? 1 : 0;

  const errorFraction = businessResponseCount > 0 ? businessFailureCount / businessResponseCount : 0;
  const errorGate = errorFraction <= 0.01 ? 1 : 0;

  const vusGate = maxConcurrentVUs <= MAX_VUS ? 1 : 0;

  console.log(`Rate fraction: ${rateFraction.toFixed(3)}`);
  console.log(`Dropped gate: ${droppedGate}`);
  console.log(`Error gate: ${errorGate}`);
  console.log(`VUs gate: ${vusGate}`);
  console.log(`=== End Results ===`);
}

export const options = {
  scenarios: {
    constant_rate: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: '45s',
      preAllocatedVUs: 2,
      maxVUs: MAX_VUS,
      exec: 'default',
      startTime: '0s',
