import os
import time
import random
import string
from urllib.parse import urljoin, urlparse, parse_qs

from locust import HttpUser, task, between, LoadTestShape, constant
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ACCOUNTS = [f"bench-{i}" for i in range(1, 17)] + ["bench"]
PASSWORD = "bench"


def generate_idempotency_key():
    return "".join(random.choices(string.ascii_letters + string.digits, k=32))


class ShopUser(HttpUser):
    wait_time = constant(0)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.username = None
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = None
        self.iteration_count = 0
        self.max_iterations = 2
        self.login_nonce = None
        self.session_cookie = None

    def on_start(self):
        self.username = random.choice(ACCOUNTS)
        self.login()

    def login(self):
        # GET login form
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code >= 400:
                resp.failure(f"login-form failed: {resp.status_code}")
                return False
            # Extract csrf from input[name=csrf]
            import re
            match = re.search(r'name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not match:
                match = re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\']', resp.text)
            if not match:
                resp.failure("no csrf in login form")
                return False
            self.csrf = match.group(1)
            # Extract login_nonce if present
            nonce_match = re.search(r'name=["\']login_nonce["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if nonce_match:
                self.login_nonce = nonce_match.group(1)

        # POST login
        payload = {"username": self.username, "password": PASSWORD, "csrf": self.csrf}
        with self.client.post(
            "/v2/login",
            json=payload,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        catch_response=True,
                        allow_redirects=False,
                    ) as resp2:
                        if resp2.status_code >= 400:
                            resp2.failure(f"login redirect failed: {resp2.status_code}")
                            return False
                        self._extract_login_response(resp2)
                else:
                    resp.failure("302 without Location")
                    return False
            elif resp.status_code >= 400:
                resp.failure(f"login failed: {resp.status_code}")
                return False
            else:
                self._extract_login_response(resp)
        return True

    def _extract_login_response(self, resp):
        try:
            data = resp.json()
            self.csrf = data.get("csrf", self.csrf)
        except Exception:
            pass
        # Session cookie is automatically stored by self.client

    def ensure_csrf(self):
        return self.csrf

    def get_headers(self, extra=None):
        headers = {"X-CSRF-Token": self.csrf}
        if extra:
            headers.update(extra)
        return headers

    def handle_401(self, resp, operation_desc):
        """Handle 401 expiry/revocation. Returns True if retry should be attempted."""
        try:
            body = resp.json()
        except Exception:
            body = {}
        error_type = body.get("error", "")
        if error_type == "expired":
            # Renew session
            with self.client.post(
                "/v2/session/renew",
                json={},
                headers=self.get_headers(),
                catch_response=True,
                allow_redirects=False,
            ) as renew_resp:
                if renew_resp.status_code >= 400:
                    renew_resp.failure(f"session renew failed: {renew_resp.status_code}")
                    return False
                try:
                    renew_data = renew_resp.json()
                    self.csrf = renew_data.get("csrf", self.csrf)
                except Exception:
                    pass
            # Recover cart if exists
            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers=self.get_headers(),
                    catch_response=True,
                    allow_redirects=False,
                ) as recover_resp:
                    if recover_resp.status_code >= 400:
                        recover_resp.failure(f"cart recover failed: {recover_resp.status_code}")
                        return False
                    try:
                        recover_data = recover_resp.json()
                        self.csrf = recover_data.get("csrf", self.csrf)
                    except Exception:
                        pass
            return True
        elif error_type == "session":
            # Revoked: re-login and recover cart
            if self.login():
                if self.cart_id:
                    with self.client.post(
                        f"/v2/carts/{self.cart_id}/recover",
                        json={},
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as recover_resp:
                        if recover_resp.status_code >= 400:
                            recover_resp.failure(f"cart recover after re-login failed: {recover_resp.status_code}")
                            return False
                        try:
                            recover_data = recover_resp.json()
                            self.csrf = recover_data.get("csrf", self.csrf)
                        except Exception:
                            pass
                return True
            return False
        elif error_type == "denied":
            resp.failure("401 denied - assertion failure")
            return False
        else:
            resp.failure(f"401 unknown error: {error_type}")
            return False

    def browse_operation(self):
        """POST /v2/browse - counts as browse pool operation."""
        with self.client.post(
            "/v2/browse",
            json={},
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "browse"):
                    # Retry once
                    with self.client.post(
                        "/v2/browse",
                        json={},
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"browse retry failed: {retry_resp.status_code}")
                            return False
                        return True
                return False
            elif resp.status_code >= 400:
                resp.failure(f"browse failed: {resp.status_code}")
                return False
            return True

    def get_catalog(self):
        """Get catalog, return list of products."""
        with self.client.get(
            "/v2/catalog",
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "catalog"):
                    with self.client.get(
                        "/v2/catalog",
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"catalog retry failed: {retry_resp.status_code}")
                            return None
                        resp = retry_resp
                    else:
                        return None
            elif resp.status_code >= 400:
                resp.failure(f"catalog failed: {resp.status_code}")
                return None
            try:
                data = resp.json()
                return data.get("data", {}).get("products", [])
            except Exception:
                resp.failure("catalog parse failed")
                return None

    def get_catalog_page(self, page_url):
        """Get a catalog page, return (product, next_url)."""
        with self.client.get(
            page_url,
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "catalog page"):
                    with self.client.get(
                        page_url,
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"catalog page retry failed: {retry_resp.status_code}")
                            return None, None
                        resp = retry_resp
                    else:
                        return None, None
            elif resp.status_code >= 400:
                resp.failure(f"catalog page failed: {resp.status_code}")
                return None, None
            try:
                data = resp.json()
                product = data.get("data", {}).get("product")
                next_url = data.get("data", {}).get("next")
                return product, next_url
            except Exception:
                resp.failure("catalog page parse failed")
                return None, None

    def create_cart(self, product_id, variant_id):
        """Create cart, return cart_id and etag."""
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "cart create"):
                    with self.client.post(
                        "/v2/carts",
                        json=payload,
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"cart create retry failed: {retry_resp.status_code}")
                            return None, None
                        resp = retry_resp
                    else:
                        return None, None
            elif resp.status_code >= 400:
                resp.failure(f"cart create failed: {resp.status_code}")
                return None, None
            try:
                data = resp.json()
                self.cart_id = data.get("id")
                self.csrf = data.get("csrf", self.csrf)
                etag = resp.headers.get("ETag")
                return self.cart_id, etag
            except Exception:
                resp.failure("cart create parse failed")
                return None, None

    def get_cart(self, cart_id):
        """Get cart, return etag."""
        with self.client.get(
            f"/v2/carts/{cart_id}",
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "cart get"):
                    with self.client.get(
                        f"/v2/carts/{cart_id}",
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"cart get retry failed: {retry_resp.status_code}")
                            return None
                        resp = retry_resp
                    else:
                        return None
            elif resp.status_code >= 400:
                resp.failure(f"cart get failed: {resp.status_code}")
                return None
            return resp.headers.get("ETag")

    def update_cart(self, cart_id, etag, quantity):
        """Update cart quantity, return new etag."""
        payload = {"quantity": quantity}
        headers = self.get_headers({"If-Match": etag})
        with self.client.patch(
            f"/v2/carts/{cart_id}",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 412:
                # Re-read and retry once
                new_etag = self.get_cart(cart_id)
                if new_etag:
                    headers = self.get_headers({"If-Match": new_etag})
                    with self.client.patch(
                        f"/v2/carts/{cart_id}",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"cart update retry failed: {retry_resp.status_code}")
                            return None
                        return retry_resp.headers.get("ETag")
                return None
            elif resp.status_code == 401:
                if self.handle_401(resp, "cart update"):
                    new_etag = self.get_cart(cart_id)
                    if new_etag:
                        headers = self.get_headers({"If-Match": new_etag})
                        with self.client.patch(
                            f"/v2/carts/{cart_id}",
                            json=payload,
                            headers=headers,
                            catch_response=True,
                            allow_redirects=False,
                        ) as retry_resp:
                            if retry_resp.status_code >= 400:
                                retry_resp.failure(f"cart update retry after 401 failed: {retry_resp.status_code}")
                                return None
                            return retry_resp.headers.get("ETag")
                return None
            elif resp.status_code >= 400:
                resp.failure(f"cart update failed: {resp.status_code}")
                return None
            return resp.headers.get("ETag")

    def get_challenge(self):
        """Get challenge form and complete challenge, return grant_id."""
        with self.client.get(
            "/v2/challenge-form",
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "challenge form"):
                    with self.client.get(
                        "/v2/challenge-form",
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"challenge form retry failed: {retry_resp.status_code}")
                            return None
                        resp = retry_resp
                    else:
                        return None
            elif resp.status_code >= 400:
                resp.failure(f"challenge form failed: {resp.status_code}")
                return None
            import re
            action_match = re.search(r'action=["\']([^"\']*challenges[^"\']*)["\']', resp.text)
            challenge_match = re.search(r'name=["\']challenge["\'][^>]*value=["\']([^"\']+)["\']', resp.text)
            if not action_match or not challenge_match:
                resp.failure("challenge form parse failed")
                return None
            action = action_match.group(1)
            challenge_value = challenge_match.group(1)
            if not action.startswith("http"):
                action = urljoin(BASE_URL, action)

        with self.client.post(
            action,
            json={"challenge": challenge_value},
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "challenge submit"):
                    with self.client.post(
                        action,
                        json={"challenge": challenge_value},
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"challenge submit retry failed: {retry_resp.status_code}")
                            return None
                        resp = retry_resp
                    else:
                        return None
            elif resp.status_code >= 400:
                resp.failure(f"challenge submit failed: {resp.status_code}")
                return None
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location:
                    with self.client.get(
                        location,
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as resp2:
                        if resp2.status_code >= 400:
                            resp2.failure(f"challenge redirect failed: {resp2.status_code}")
                            return None
                        try:
                            data = resp2.json()
                            self.grant_id = data.get("grant_id")
                            self.csrf = data.get("csrf", self.csrf)
                            return self.grant_id
                        except Exception:
                            resp2.failure("challenge redirect parse failed")
                            return None
                else:
                    resp.failure("challenge 302 without Location")
                    return None
            else:
                try:
                    data = resp.json()
                    self.grant_id = data.get("grant_id")
                    self.csrf = data.get("csrf", self.csrf)
                    return self.grant_id
                except Exception:
                    resp.failure("challenge parse failed")
                    return None

    def create_reservation(self, cart_id):
        """Create reservation, return reservation_id."""
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": cart_id},
            headers=self.get_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "reservation create"):
                    with self.client.post(
                        "/v2/reservations",
                        json={"cart_id": cart_id},
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"reservation create retry failed: {retry_resp.status_code}")
                            return None
                        resp = retry_resp
                    else:
                        return None
            elif resp.status_code >= 400:
                resp.failure(f"reservation create failed: {resp.status_code}")
                return None
            try:
                data = resp.json()
                status_url = data.get("status_url")
                self.csrf = data.get("csrf", self.csrf)
                if not status_url:
                    resp.failure("no status_url in reservation")
                    return None
                if not status_url.startswith("http"):
                    status_url = urljoin(BASE_URL, status_url)
                # Poll at least 50ms apart, at most 5 times
                for i in range(5):
                    time.sleep(0.05)
                    with self.client.get(
                        status_url,
                        headers=self.get_headers(),
                        catch_response=True,
                        allow_redirects=False,
                    ) as poll_resp:
                        if poll_resp.status_code == 401:
                            if self.handle_401(poll_resp, "reservation poll"):
                                continue
                            return None
                        elif poll_resp.status_code >= 400:
                            poll_resp.failure(f"reservation poll failed: {poll_resp.status_code}")
                            return None
                        try:
                            poll_data = poll_resp.json()
                            status = poll_data.get("status")
                            self.csrf = poll_data.get("csrf", self.csrf)
                            if status == "ready":
                                return poll_data.get("reservation_id")
                            elif status == "failed":
                                return None
                            # pending - continue polling
                        except Exception:
                            poll_resp.failure("reservation poll parse failed")
                            return None
                return None
            except Exception:
                resp.failure("reservation create parse failed")
                return None

    def checkout_operation(self):
        """Complete checkout journey. Returns True if order committed."""
        # Fresh login/cart for each journey
        if not self.login():
            return False
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idempotency_key = generate_idempotency_key()

        # Get catalog
        products = self.get_catalog()
        if not products:
            return False

        # Select a product with in-stock variant
        selected_product = None
        selected_variant = None
        for product in products:
            for variant in product.get("variants", []):
                if variant.get("in_stock"):
                    selected_product = product
                    selected_variant = variant
                    break
            if selected_product:
                break

        if not selected_product:
            # Try catalog pages
            next_url = "/v2/catalog/page"
            for _ in range(3):
                product, next_url = self.get_catalog_page(next_url)
                if product:
                    for variant in product.get("variants", []):
                        if variant.get("in_stock"):
                            selected_product = product
                            selected_variant = variant
                            break
                if selected_product:
                    break
                if not next_url:
                    break

        if not selected_product:
            return False

        # Create cart
        cart_id, etag = self.create_cart(selected_product["id"], selected_variant["id"])
        if not cart_id:
            return False
        self.cart_id = cart_id
        self.cart_etag = etag

        # Update cart quantity
        new_etag = self.update_cart(cart_id, etag, 1)
        if new_etag:
            self.cart_etag = new_etag

        # Get challenge
        grant_id = self.get_challenge()
        if grant_id:
            self.grant_id = grant_id

        # Create reservation
        reservation_id = self.create_reservation(cart_id)
        if reservation_id:
            self.reservation_id = reservation_id

        # Create order
        payload = {"cart_id": cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        headers = self.get_headers({
            "Idempotency-Key": self.idempotency_key,
        })
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 401:
                if self.handle_401(resp, "order create"):
                    # Retry once with same idempotency key
                    headers = self.get_headers({
                        "Idempotency-Key": self.idempotency_key,
                    })
                    if self.cart_etag:
                        headers["If-Match"] = self.cart_etag
                    with self.client.post(
                        "/v2/orders",
                        json=payload,
                        headers=headers,
                        catch_response=True,
                        allow_redirects=False,
                    ) as retry_resp:
                        if retry_resp.status_code >= 400:
                            retry_resp.failure(f"order create retry failed: {retry_resp.status_code}")
                            return False
                        resp = retry_resp
                    else:
                        return False
            elif resp.status_code >= 400:
                resp.failure(f"order create failed: {resp.status_code}")
                return False
            try:
                data = resp.json()
                self.csrf = data.get("csrf", self.csrf)
                if resp.status_code == 201 and data.get("accepted") is True:
                    return True
                elif resp.status_code == 200 and data.get("accepted") is False:
                    # Business failure
                    return False
                else:
                    return False
            except Exception:
                resp.failure("order create parse failed")
                return False

    @task
    def run_iteration(self):
        if self.iteration_count >= self.max_iterations:
            raise StopUser()
        self.iteration_count += 1

        # Determine which pool this user belongs to based on username
        # Users bench-1..bench-8 are browse pool, bench-9..bench-16 and bench are checkout pool
        # But we need to maintain separate rates, so we'll use the shape to control this
        # For now, just do browse or checkout based on a flag set by the shape
        if hasattr(self, "pool_type") and self.pool_type == "checkout":
            self.checkout_operation()
        else:
            self.browse_operation()


class ShopLoadShape(LoadTestShape):
    """
    Shape that maintains separate browse and checkout pools.
    Browse: 8/s, Checkout: 2/s
    """
    def __init__(self):
        super().__init__()
        self.start_time = time.time()
        self.browse_rate = 8.0
        self.checkout_rate = 2.0
        self.total_rate = self.browse_rate + self.checkout_rate
        self.browse_users = 0
        self.checkout_users = 0
        self.last_spawn_time = time.time()
        self.spawn_interval = 0.1  # 100ms between spawns
        self.browse_spawn_accumulator = 0.0
        self.checkout_spawn_accumulator = 0.0
        self.max_users = 64
        self.total_spawned = 0
        self.browse_spawned = 0
        self.checkout_spawned = 0
        self.initialized = False

    def tick(self):
        current_time = time.time()
        elapsed = current_time - self.start_time

        # Run for 45 seconds total (5s warmup + 35s scored + 5s drain)
        if elapsed > 45:
            return None

        if not self.initialized:
            self.initialized = True
            self.last_spawn_time = current_time
            # Spawn initial users
            return self._get_spawn_count(current_time)

        # Calculate spawn counts based on rates
        dt = current_time - self.last_spawn_time
        self.last_spawn_time = current_time

        self.browse_spawn_accumulator += self.browse_rate * dt
        self.checkout_spawn_accumulator += self.checkout_rate * dt

        browse_to_spawn = int(self.browse_spawn_accumulator)
        checkout_to_spawn = int(self.checkout_spawn_accumulator)
        self.browse_spawn_accumulator -= browse_to_spawn
        self.checkout_spawn_accumulator -= checkout_to_spawn

        total_to_spawn = browse_to_spawn + checkout_to_spawn

        if total_to_spawn > 0:
            # Check max users
            if self.total_spawned + total_to_spawn > self.max_users:
                total_to_spawn = self.max_users - self.total_spawned
                if total_to_spawn <= 0:
                    return None

            # Allocate spawns between browse and checkout
            browse_actual = min(browse_to_spawn, total_to_spawn)
            checkout_actual = total_to_spawn - browse_actual

            self.browse_spawned += browse_actual
            self.checkout_spawned += checkout_actual
            self.total_spawned += total_to_spawn

            # Return spawn data
            spawn_data = []
            for i in range(browse_actual):
                spawn_data.append({"user_class": ShopUser.__name__, "pool_type": "browse"})
            for i in range(checkout_actual):
                spawn_data.append({"user_class": ShopUser.__name__, "pool_type": "checkout"})
            return spawn_data

        return None

    def _get_spawn_count(self, current_time):
        """Initial spawn for the first tick."""
        # Spawn a few users immediately to start work
        initial_browse = 4
        initial_checkout = 1
        self.browse_spawned += initial_browse
        self.checkout_spawned += initial_checkout
        self.total_spawned += initial_browse + initial_checkout
        spawn_data = []
        for i in range(initial_browse):
            spawn_data.append({"user_class": ShopUser.__name__, "pool_type": "browse"})
        for i in range(initial_checkout):
            spawn_data.append({"user_class": ShopUser.__name__, "pool_type": "checkout"})
        return spawn_data
